\paragraph{Notation.}
We use bold letters to denote vectors, \eg $\vx = (x_1, \ldots, x_d)$ with $d \in \mathbb{N}_{>0}$.
Given two vectors $\vx$ and $\vy$ of the same dimension $d$ and a scalar $z$, we define the notations
\begin{align*}
    \vx^{\vy}
&:=
    {x_1}^{y_1} \cdots {x_d}^{y_d},
\\
    \vx z^{\vy}
&:=
    (x_1 z^{y_1}, \ldots, x_d z^{y_d}),
\\
    \log(\vx)
&:=
    (\log(x_1), \ldots, \log(x_d)).
\end{align*}
In particular, we write $\vzeta e^{i \vtheta}$
for the vector $(\zeta_1 e^{i \theta_1}, \ldots, \zeta_d e^{i \theta_d})$.
%
The \emph{support} of a multivariate power series $B(\vz)$
is the set
\[
    S_B :=
    \{ \vn,\ [\vz^{\vn}] B(\vz) \neq 0 \}
\]
and we define
\[
    \Delta(S_B) :=
    \{ \vn - \vm,\ \vn, \vm \in S_B \}.
\]
The \emph{cumulant generating function}
associated to the generating function $B(\vz)$
is
\[
    K(\vt) := \log\big(B(e^{\vt})\big)
    = \log\big(B(e^{t_1}, \ldots, e^{t_d})\big).
\]
The gradient of a function $B$ at $\vx$ is denoted by $\nabla_B(\vx)$.

We write $r + q \integers_{\geq 0}$ for the set $\{r + q \ell,\ \ell \in \integers_{\geq 0}\}$.


A \emph{polydisc} is a Cartesian product of discs.
A \emph{torus} is a Cartesian product of circles.


\subsection{Rank and Periodicity of a Multivariate Generating Function}\label{sec_appendix-Elie-preliminaries}


This section presents general results on multivariate formal power series,
defining their \emph{rank} and \emph{period}.
We will use them to prove the existence and uniqueness of the saddle point,
defined in the following section.
In particular, we prove a multivariate version
of the Daffodil lemma \cite[Lemma~IV.1, page~266]{flajolet2009analytic}.


\begin{lemma}
\label{th:smithnormalform}
The kernel of any integer matrix
has a basis composed of integer vectors.
\end{lemma}


\begin{proof}
Let $M$ denote our matrix and let its Smith normal form be
\[
    M = U D V,
\]
where $U$ and $V$ are unimodular integer matrices
and $D$ is an integer diagonal matrix.
The dimension of the kernel of $M$
is equal to the number of zero elements
on the diagonal of $D$.
Consider such an element of index $j$
and let $\ve^{(j)}$, denote the vector with a $1$
in position $j$ and $0$'s everywhere else.
Set $\vp^{(j)} = V^{-1} \ve^{(j)}$.
Since $V$ is unimodular,
$\vp^{(j)}$ has integer coefficients and is nonzero.
We have
\[
    M \vp^{(j)} = U D V \vp^{(j)} = U D \ve^{(j)} = \vzero,
\]
so $\vp^{(j)}$ belongs to the kernel of $M$.
The invertibility of $V$ ensures
that the vectors $\vp^{(j)}$ are linearly independent,
hence they form a basis of the kernel.
\end{proof}



\begin{definition}
\label{def:rank}
We define the \emph{rank}
of a formal power series $B(\vz)$
as the dimension of the real vector space generated by $\Delta(S_B)$.
% Fanfan: inutile de rappeler la def, elle est vraiment juste au-dessus.
% \[
%     \Delta(S_B)
%     =
%     \{\vn - \vm,\ 
%     [\vz^{\vn}] B(\vz) \neq 0 \land
%     [\vz^{\vm}] B(\vz) \neq 0 \}.
% \]
We say that $B(\vz)$ has \emph{full rank}
if its rank is equal to its number of variables.
\end{definition}



In particular, a formal power series
on at least one variable
and that has full rank cannot be a monomial.



\begin{lemma}
\label{th:rank_characterization}
If the formal power series $B(z_1, \ldots, z_d)$
has rank $k$,
then there exist $d-k$ integer vectors
$\vp^{(1)}, \ldots, \vp^{(d-k)}$
generating a real vector space of dimension $d-k$
and integers $r_1, \ldots, r_{d-k}$
such that for all $j \in [1, d-k]$
\[
    B(\vz y^{\vp^{(j)}})
    =
    y^{r_j}
    B(\vz).
\]
%
Reciprocally, if such vectors $\vp^{(j)}$
and integers $r_j$ exist,
then $B(\vz)$ has rank at most $k$.
\end{lemma}


\begin{proof}
% Fanfan: idem, superflu car la def est juste au-dessus.
% Recall that
% \[
%     S_B = \{\vn,\ [\vz^{\vn}] B(\vz) \neq 0\}
% \]
% denotes the support of $B(\vz)$
% and $\Delta(S_B)$ is defined as
% \[
%     \Delta(S_B) =
%     \{\vn - \vm,\ \vn, \vm \in S_B\}.
% \]
If $B(z_1, \ldots, z_d)$ has rank $k$,
by \cref{th:smithnormalform},
the vector space orthogonal to $\Delta(S_B)$
has a basis of $d-k$ integer vectors
$(\vp^{(1)}, \ldots, \vp^{(d-k)})$.
Fix $\vm$ in the support $S_B$ of $B(\vz)$
and define $r_j = \vm^T \vp^{(j)}$,
then for all $\vn$ in $S_B$,
we have
\[
    \vn^T \vp^{(j)} = r_j,
\]
so
\[
    B(\vz y^{\vp^{(j)}})
    =
    y^{r_j}
    B(\vz).
\]

Reciprocally, if there are $d-k$ linearly independent
integer vectors $(\vp^{(1)}, \ldots, \vp^{(d-k)})$
and integers $r_1, \ldots, r_{d-k}$ such that
\[
    B(\vz y^{\vp^{(j)}})
    =
    y^{r_j}
    B(\vz),
\]
then each $\vp^{(j)}$ is in the vector space orthogonal to
$\Delta(S_B)$,
so this vector space has dimension at most $k$.
\end{proof}


In the current article, we will consider a polynomial $P$
having full rank.
It is however worth noticing that coefficient extraction
in a power series that does not have full rank
can be simplified as follows.
%
Say we are interested in the coefficient extraction
$[\vz^{\vn}] B(\vz)$ of a power series $B(\vz)$
that does not have full rank.
Let $\vp$ and $r$ denote
a nonzero integer vector and an integer such that
\[
    B(\vz y^{\vp}) = y^r B(\vz).
\]
Since $\vp$ is nonzero, there exists $j$
such that $p_j \neq 0$.
Then for any $\vn \in S_B$, we have
\[
    n_j = \frac{r - \sum_{\ell \neq j} p_{\ell} n_{\ell}}{p_j},
\]
so $n_j$ is uniquely determined by $(n_{\ell})_{\ell \neq j}$
and
\[
    [\vz^{\vn}] B(\vz) =
    \begin{cases}
    0 & \text{if $\vn^T \vp \neq r$},
    \\
    [z_1^{n_1} \cdots z_{j-1}^{n_{j-1}}
    z_{j+1}^{n_{j+1}} \cdots z_d^{n_d}]
    B(z_1, \ldots, z_{j-1}, 1, z_{j+1}, \ldots, z_d)
    & \text{otherwise}.
    \end{cases}
\]
Thus, coefficient extraction in a power series
that does not have full rank
reduces to a coefficient extraction
in a power series with fewer variables.



\begin{lemma}[Convexity of the cumulant generating function]
\label{th_convexity-cumulant-gf}
Consider a series $B(\vz)$
with nonnegative coefficients,
full rank,
and analytic on a neighborhood $\Omega$ of $\vzero$.
%
Then its cumulant generating function
\[
    K : \vt \mapsto
    \log\big(B(e^{\vt})\big)
\]
is strictly convex
on $\{\vt \in \reals^d,\ e^{\vt} \in \Omega\}$.
\end{lemma}


\begin{proof}
Let $\vX$ denote the vector of random variables
parametrized by $\vx \in \reals_{> 0}^d \cap \Omega$
with distribution
\[
    \proba(\vX = \vn) =
    \frac{[\vz^{\vn}] B(\vz) \vx^{\vn}}{B(\vx)}.
\]
By construction, those probabilities sum to $1$.
This is the so-called \emph{Boltzmann distribution}
associated to the generating function $B(\vz)$
(see \cite{DFLS04}).
We now follow the classical proof of convexity
of the cumulant generating function
of a multivariate random variable,
then prove that the assumption that $B(\vz)$ has full rank
implies strict convexity.

The moment generating function of $\vX$ is
\[
    \mean(e^{\vt^T \vX}) =
    \frac{B(\vx e^{\vt})}{B(\vx)}.
\]
Observe that the cumulant generating function of $\vX$
is equal to
\[
    \log\big(\mean(e^{\vt^T \vX})\big)
%
    =
    \log\big(B(\vx e^{\vt})\big)
    - \log\big(B(\vx)\big)
%
    =
    K\big(\vt + \log(\vx)\big) - \log\big(B(\vx)\big).
\]
%
The vector of the means is
\[
    \mean(\vX) =
    \frac{\diag(\vx) \nabla_B(\vx)}{B(\vx)}.
\]
It is equal to the gradient of $K(\vt)$ at $\vt = \log(\vx)$.
%
The covariance matrix is
\[
    \var(\vX)
%
    =
    \mean\big((\vX - \mean(\vX))^T (\vX - \mean(\vX))\big)
%
    =
    \mean\big(\vX \vX^T\big)
    - \mean(\vX) \mean(\vX)^T.
\]
%
It is equal to the Hessian of $K(\vt)$ at $\vt = \log(\vx)$.

For any vector $\vu \in \reals^d$,
\[
    \vu^T \var(\vX) \vu =
    \mean\Big(\big((\vX - \mean(\vX))^T \vu\big)^2\Big),
\]
so $\var(\vX)$ is positive semi-definite.
Consider a vector $\vu$ such that
\[
    0
%
    =
    \vu^T \var(\vX) \vu
%
    =
    \mean\Big(\big((\vX - \mean(\vX))^T \vu\big)^2\Big).
\]
This implies $(\vX - \mean(\vX))^T \vu = \vzero$
so, for any $\vn$, $\vm$ in the support of $B(\vx)$,
\[
    (\vn - \vm)^T \vu = 0.
\]
Our assumption that $B(\vz)$ has full rank
implies $\vu = \vzero$,
which proves that $\var(\vX)$ is positive definite.
Since $\var(\vX)$ is equal to the Hessian of $K(\vt)$
at $\log(\vx)$,
we deduce that $K(\vt)$ is strictly convex
on $\{\vt \in \reals^d,\ e^{\vt} \in \Omega\}$.
\end{proof}



We recall below the definition of $q$-periodicity
from \cite[Section 4.2]{flajolet1991automatic}
for univariate formal power series.



\begin{definition}
\label{def:periodicity_univariate}
A univariate generating function $B(z)$
is said to be \emph{$q$-periodic}
if there exist an integer $r$ and a formal power series $C(z)$
such that
\[
    B(z) = z^r C(z^q).
\]
Equivalently, the support $S_B$ of $B(z)$ satisfies
\[
    S_B \subseteq r + q \integers_{\geq 0}. %= \{r + q \ell,\ \ell \in \integers_{\geq 0}\}.
\]
%\[
%    \{n - r,\ n \in S_B\} \subseteq q \integers_{\geq 0}.
%\]
%\fanfan{1. J'imagine que c'est $\subseteq$ (moins ambigu). 2. Perso, je trouve plus parlante la notation $S_B \subseteq r + q \integers_{\geq 0}$, qui montre bien que c'est une espèce de sous-réseau affine.}
The series $B(z)$ is said to be \emph{aperiodic}
if it is not $q$-periodic for any $q \geq 2$.
\end{definition}


Let us now extend this definition
to multivariate formal power series.


\begin{definition}
\label{def:periodicity}
A multivariate generating function $B(z_1, \ldots, z_d)$
is said to be \emph{$q$-periodic} if there exist
nonnegative integers $p_1, \ldots, p_d$,
not all divisible by $q$,
such that $B(y^{p_1}, \ldots, y^{p_d})$
is a $q$-periodic univariate formal power series.
%
An equivalent formulation on the support $S_B$ of $B(\vz)$
is that there exists a nonnegative integer $r$ such that
\begin{equation}
\label{eq:multivariate_periodicity_support}
    \{\vp^T \vn,\ \vn \in S_B\} \subseteq r + q \integers_{\geq 0}.
\end{equation}
%
Yet another equivalent formulation is that
there exists a formal power series $E(\vz, y)$,
integers $p_1, \ldots, p_d$ not all divisible by $q$
and an integer $r$ such that
\[
    B(z_1 y^{p_1}, \ldots, z_d y^{p_d}) =
    y^r E(\vz, y^q).
\]
%
We say that $B(\vz)$ is \emph{aperiodic}
if it is not $q$-periodic for any $q \geq 2$.
\end{definition}


Our next result presents a simple sufficient condition
for a formal multivariate power series to have full rank
and be aperiodic.


\begin{proposition}
\label{th_full_rank_aperiodic}
Let $\ve_j$ denote the vector with a $1$ at position $j$,
and $0$s everywhere else.
Consider a formal power series $B(z_1, \ldots, z_d)$
whose support contains $\vzero, \ve_1, \ldots, \ve_d$.
They $B(\vz)$ has full rank and is aperiodic.
\end{proposition}

\begin{proof}
Since the support of $B(\vz)$ contains $\vzero$,
we have $S_B \subseteq \Delta(S_B)$.
Thus, $\Delta(S_B)$ contains $d$ independent vectors
$\ve_1, \ldots, \ve_d$, so it has rank $d$ and $B(\vz)$ has full rank.
%
Consider an integer vector $\vp$ and integers $r$ and $q \geq 2$.
Assume
\[
    \{ \vp^T \vn,\ \vn \in S_B\}
    \subseteq
    r + q \integers_{\geq 0}.
\]
For $\vn = \vzero$, we deduce that $q$ divides $r$.
For $\vn = \ve_j$, we deduce that $q$ divides $p_j - r$,
so $p_j$ is a multiple of $q$.
Thus, $\vp$ is necessarily a multiple of $q$
and $B(\vz)$ cannot be $q$-periodic, so $B(\vz)$ is aperiodic.
\end{proof}


The Daffodil lemma \cite[Lemma~IV.1, page~266]{flajolet2009analytic}
states that the absolute value of a univariate generating function
with nonnegative coefficients
reaches its maximum at a unique point
on any disk contained in its domain of convergence
if and only if it is aperiodic.
Our following lemma extends this result to the multivariate setting.



\begin{lemma}[Multivariate daffodil lemma]
\label{th:multivariate_daffodil}
Consider a multivariate power series $B(z_1, \ldots, z_d)$
with nonnegative coefficients
and a vector $\vzeta \in \reals_{> 0}^d$
such that the domain of convergence of $B(\vz)$ contains
the closed polydisc of radius $\vzeta$
\[
    D(\vzeta) :=
    \{ \vz,
    |z_1| \leq \zeta_1 \land \ldots \land |z_d| \leq \zeta_d \}.
\]
Then for all $\vz \in D(\vzeta)$, we have
$|B(\vz)| \leq B(\vzeta)$.

Assume furthermore that $B(\vz)$ has full rank.
Then $|B(\vz)|$ has a unique maximum on $D(\vzeta)$
if and only if it is aperiodic.
\end{lemma}


\begin{proof}
Using the positivity of the coefficients of $B(\vz)$,
triangular inequality yields for any $\vx \in D(\vzeta)$
\[
    |B(\vx)|
%
    =
    \left|
    \sum_{\vn}
    b_{\vn}
    \vx^{\vn}
    \right|
%
    \leq
    \sum_{\vn}
    b_{\vn}
    |\vx|^{\vn}
%
    \leq
    \sum_{\vn}
    b_{\vn}
    \vzeta^{\vn}
%
    =
    B(\vzeta).
\]
Assume $|B(\vx)| = B(\vzeta)$,
then $(|x_1|, \ldots, |x_d|) = \vzeta$,
so there exists a vector $\vt \in [0, 1)^d$
such that for all $j$, we have $x_j = \zeta_j e^{2 i \pi t_j}$.
The case $\vt = \vzero$ corresponds to $\vx = \vzeta$.
Let us assume first $\vt \neq \vzero$, and prove that there exists $q \geq $
such that $B(\vz)$ is $q$-periodic.
%
The equality $|B(\vx)| = B(\vzeta)$ implies
\[
    \left|
    \sum_{\vn}
    b_{\vn}
    \vzeta^{\vn}
    e^{2 i \pi \vn^T \vt}
    \right|
%
    =
    \sum_{\vn}
    b_{\vn}
    \vzeta^{\vn},
\]
so by the triangular inequality,
for all $\vn$ in the support $S_B$ of $B(\vz)$,
the complex numbers $e^{2 i \pi \vn^T \vt}$ are aligned.
This is equivalent with the existence of $t_0 \in [0,1)$ such that
for all $\vn \in S$, we have
\[
    \vn^T \vt = t_0 \mod 1.
\]
% Fanfan removed this
% Let $\Delta(S_B)$ denote the set
% \[
%     \Delta(S_B) =
%     \{
%     \vn - \vm,\ 
%     \vn, \vm \in S_B
%     \},
% \]
Then for all $\vn \in \Delta(S_B)$, we have
\[
    \vn^T \vt = 0 \mod 1.
\]
Thus, for all $\vn \in \Delta(S_B)$, there exist integers $k_{\vn}$ such that
\[
    \vn^T \vt = k_{\vn}.
\]
%
Let $\Delta(S_B)'$ denote the set
of vectors $\vn$ from $\Delta(S_B)$
with an additional element $- k_{\vn}$ at the bottom,
and let $\vt'$ denote the vector $\vt$
with an additional element $1$ at the bottom,
then the previous equality is equivalent with
\[
    \vn^T \vt' = 0
\]
for all $\vn \in \Delta(S_B)'$.
%
Since $B(\vz)$ has full rank,
$\Delta(S_B)$ generates a vector space of dimension $d$,
so the vector space orthogonal to $\Delta'(S_B)$ has dimension at most $1$.
It contains a nonzero vector, so the dimension is exactly $1$.
By \cref{th:smithnormalform},
there exists a nonzero integer vector $\vu$
orthogonal to $\Delta(S_B)'$.
We have $t'_{d+1} = 1$ and $\vt'$ proportional to the integer vector $\vu$,
so $\vt$ is a vector of rational values.
Recall that $\vt \in [0,1)^d$ and is nonzero.
%
Thus, there exist
$q \in \integers_{\geq 2}$
and $\vp \in \integers_{\geq 0}^d$
with $q$ that does not divide all $p_j$,
such that $\vt = \vp / q$, so for all $\vn \in \Delta(S_B)$,
\[
    \vn^T \vp = q\, k_{\vn}.
\]
Fix $r = \min_{\vn \in S_B} (\vn^T \vp)$, then
for all $\vn \in S_B$,
\[
    \vn^T \vp - r = q\, k_{\vn}.
\]
Thus, $q$ divides $\vn^T \vp - r$.
This implies the existence of a formal univariate power series $C(y)$
such that
\begin{equation}
\label{eq:BpyrC}
    B(y^{p_1}, \ldots, y^{p_d}) = y^r C(y^q),
\end{equation}
so $B(\vz)$ is $q$-periodic.

Reciprocally, if $B(\vz)$ is $q$-periodic for some $q \geq 2$,
there exist nonnegative integers $r, p_1, \ldots, p_d$,
with $q$ not dividing all $p_j$,
and a formal power series $C(y)$
such that \cref{eq:BpyrC} holds.
Then for all $\vn \in S_B$, the integer $q$ divides $\vn^T \vp - r$, so $e^{2 i \pi \vn^T \vp / q} = e^{2 i \pi r / q}$.
For any $\vzeta \in \reals_{> 0}^d$ such that the domain of convergence of $B(\vz)$ contains the polydisc of radius $\vzeta$, setting $\vx = \vzeta e^{2 i \pi \vp / q}$, we have
\[
    |B(\vx)|
%
    =
    \left|
    \sum_{\vn \in S_B}
    b_{\vn}
    \vzeta^{\vn}
    e^{2 i \pi \vp^T \vn / q}
    \right|
%
    =
    \left|
    \sum_{\vn \in S_B}
    b_{\vn}
    \vzeta^{\vn}
    e^{2 i \pi r}
    \right|
%
    =
    \left|
    \sum_{\vn \in S_B}
    b_{\vn}
    \vzeta^{\vn}
    \right|
%
    =
    B(\vzeta),
\]
where the last equality comes from the fact
that the coefficients of $B(\vz)$ are nonnegative.
Thus, on the torus of radius $\vzeta$,
at the point $\vx$, which is distinct from $\vzeta$,
we have $|B(\vx)| = B(\vzeta)$.
\end{proof}


In the current article, we will consider a polynomial $P$
that is aperiodic.
It is however worth noticing that coefficient extraction
in a periodic power series
can be simplified as follows.
%
Suppose we are interested in the coefficient extraction
$[\vz^{\vn}] B(\vz)$.
If $B(\vz)$ does not have full rank,
we saw after \cref{th:rank_characterization}
how to simplify the coefficient extraction.
Assume now $B(\vz)$ has full rank,
is analytic at $\vzero$,
and is $q$-periodic for some $q \geq 2$.
Then there exist nonnegative integers
$r, p_1, \ldots, p_d$,
with $q$ not dividing all $p_j$,
and a power series $E(\vz, y)$ such that
\[
    B(\vz y^{\vp}) =
    y^r E(\vz, y^q).
\]
We have
\[
    [\vz^{\vn}] B(\vz)
%
    =
    [\vz^{\vn} y^{\vp^T \vn}]
    B(z_1 y^{p_1}, \ldots, z_d y^{p_d})
%
    =
    [\vz^{\vn} y^{\vp^T \vn}]
    y^r E(\vz,y^q).
\]
%
Let $j$ be such that $p_j \neq 0$
(which must exist, otherwise $q$ would divide all $p_i$).
Let $\vn_{\setminus j}$ denote the vector
$(n_1, \ldots, n_{j-1}, n_{j+1}, \ldots, n_d)$
and similarly for $\vz_{\setminus j}$.
Then $B(\vz)$ having full rank implies
\[
    [\vz^{\vn} y^{\vp^T \vn}]
    B(\vz y^{\vp})
%
    =
    [\vz_{\setminus j}^{\vn_{\setminus j}} y^{\vp^T \vn}]
    B(z_1 y^{p_1}, \ldots, z_{j-1} y^{p_{j-1}}, y^{p_j}, z_{j+1} y^{p_{j+1}}, \ldots z_d y^{p_d}).
\]
Define
\[
    D(\vz_{\setminus j}, y) :=
    E(z_1, \ldots, z_{j-1}, 1, z_{j+1}, \ldots, z_d, y),
\]
then
\[
    [\vz^{\vn}] B(\vz)
%
    =
    \begin{cases}
    0 & \text{if $q$ does not divide $\vp^T \vn - r$},
    \\
    [\vz_{\setminus j}^{\vn_{\setminus j}} y^{(\vp^T \vn - r) / q}]
    D(\vz_{\setminus j}, y)
    & \text{otherwise.}
    \end{cases}
\]
Thus, when $|B(\vz)|$ reaches its maximum on a polydisc
at several points, the coefficient extraction
$[\vz^{\vn}] B(\vz)$ can be simplified.



\begin{corollary}
Consider a power series $B(\vz)$
and two complex torii $T_1$, $T_2$
centered at the origin
and contained in the domain of convergence of $B(\vz)$.
If $|B(\vz)|$ reaches its maximum on $T_1$ at a unique point,
then it reaches its maximum on $T_2$ at a unique point as well.
\end{corollary}
%\fanfan{Là c'est des torii, mais plus haut c'est appelé des polydiscs si je ne m'abuse.}


    \subsection{Large Powers}\label{sec_appendix-large-powers}


\Cref{th_large-powers-limit} is the key result used in \Cref{sec_subcritical-case}, which corresponds to the case where the saddle point has all coordinates subcritical. Consequently, the contour of integration can pass through the saddle point without intersecting the singularity at \(1\).  

We first present a preliminary theorem, which corresponds to extracting the coefficient of index \(\vlambda n\) for some fixed vector \(\vlambda\) of rational values. Then, we state the theorem in its more general form, considering a sequence of vectors of real values \(\vkappa_n = \vlambda n + \bigO(n^{\delta})\).


\begin{theorem}[Multivariate large powers theorem]
\label{th:multivariate_large_powers}
Consider a power series $B(z_1, \ldots, z_d)$
with nonnegative coefficients,
full rank (\cref{def:rank}), aperiodic (\cref{def:periodicity})
and convergent on a neighborhood $\Omega$ of $0$.
%
Let $K(\vt) = \log\big(B(e^{\vt})\big)$ denote
its cumulant generating function.
%
Let $\vlambda$ denote a vector of positive rational numbers
such that the function $K(\vt) - \vlambda^T \vt$
does not tend to its infimum on the boundary
of $\Psi = \{ \vt \in \reals^d,\ e^{\vt} \in \Omega \}$.
%
Let $\vtau$ denote the unique point of $\Psi$
where $K(\vt) - \vlambda^T \vt$ reaches its minimum
and $\mH$ denote the Hessian matrix of $K(\vt)$ at $\vtau$.
Set $\vzeta = e^{\vtau}$.
%
Consider a power series $A(\vz)$
analytic on the torus of radius $\vzeta$
and satisfying $A(\vzeta) \neq 0$.
Then, considering large values of $n$ such that $\vlambda n$ is a vector of integers,
\[
    [\vz^{\vlambda n}]
    A(\vz)
    B(\vz)^n
%
    \sim
    \frac{A(\vzeta)}
        {\sqrt{(2 \pi n)^d \det(\mH)}}
    \frac{B(\vzeta)^n}{\vzeta^{\vlambda n}}.
\]
\end{theorem}


\begin{proof}
\cref{th_convexity-cumulant-gf} ensures
that $K(\vt)$ is strictly convex,
so $K(\vt) - \vlambda^T \vt$ is strictly convex as well.
Since it does not reach its minimum on the boundary of $\Psi$,
there exists a unique point $\vtau$ in $\Psi$
where $K(\vt) - \vlambda^T \vt$ reaches its minimum.
%
We write the coefficient extraction as a Cauchy integral.
\[
    [\vz^{\vlambda n}]
    A(\vz)
    B(\vz)^n
%
    =
    \frac{1}{(2 i \pi)^d}
    \oint
    A(\vz)
    B(\vz)^n
    \frac{d \vz}{\vz^{\vlambda n + \vone}}.
\]
The analycity of $B(\vz)$ at $\vzeta$
and its nonnegative coefficients
ensure that $B(\vz)$ is analytic on the torus of radius~$\vzeta$.
We choose for the integration domain
the torus of radius $\vzeta$
\[
    [\vz^{\vlambda n}]
    A(\vz)
    B(\vz)^n
%
    =
    \frac{1}{(2 \pi)^d}
    \int_{\vtheta \in [-\pi, \pi]^d}
    A(\vzeta e^{i \vtheta})
    B(\vzeta e^{i \vtheta})^n
    \frac{d \vtheta}
    {\vzeta^{\vlambda n} e^{i n \vlambda^T \vtheta}}.
\]
Introducing
\[
    \phi(\vtheta) :=
    i \vlambda^T \vtheta -
    \log \left(
    \frac{B(\vzeta e^{i \vtheta})}
    {B(\vzeta)}
    \right),
\]
we have
\[
    [\vz^{\vlambda n}]
    A(\vz)
    B(\vz)^n
%
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vlambda n}}
    \frac{1}{(2 \pi)^d}
    \int_{\vtheta \in [-\pi, \pi]^d}
    A(\vzeta e^{i \vtheta})
    e^{- n \phi(\vtheta)}
    d \vtheta.
\]
Since $|B(\vzeta e^{i \vtheta})|$
reaches its maximal value $B(\vzeta)$ only at $\vtheta = 0$,
the real part of $\phi(\vtheta)$
is positive except at $\vtheta = \vzero$.
The Hessian matrix of $\phi(\vtheta)$ at $\vtheta = \vzero$
is equal to the Hessian matrix $\mH$
of $K(\vt)$ at $\vt = \log(\vzeta)$,
and is nonsingular
according to \cref{th_convexity-cumulant-gf}.
The result of the theorem
follows by application of the Laplace method,
recalled in \cref{th:multivariate_laplace_method}.
\end{proof}



Applications often require more flexibility
than provided by our previous result.
Instead of extracting the coefficient of index $\vlambda n$
for some fixed vector $\vlambda$ of rational values,
we might consider an index $\vkappa_n \sim \vlambda n$,
which allows us to cover the case where $\vlambda$
contains irrational values.
To achieve this result,
we follow and modify slightly
the proof of \cref{th:multivariate_laplace_method}.



\begin{theorem}
\label{th_large-powers-limit}
Consider $\delta < 1/2$
and a sequence of vectors of real values
\[
    \vkappa_n = \vlambda n + \bigO(n^{\delta}).
\]
Under the assumptions of \cref{th:multivariate_large_powers},
with $\vtau$ defined as the minimum
of $K(\vt) - \vlambda^T \vt$
and $\vzeta = e^{\vtau}$,
we have
\[
    [\vz^{\vkappa_n}]
    A(\vz)
    B(\vz)^n
%
    \sim
    \frac{A(\vzeta)}
        {\sqrt{(2 \pi n)^d \det(\mH)}}
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}.
\]
\end{theorem}


\begin{proof}
We write again the coefficient extraction
as a Cauchy integral on the torus of radius $\vzeta$
\[
    [\vz^{\vkappa_n}]
    A(\vz)
    B(\vz)^n
%
    =
    \frac{1}{(2 \pi)^d}
    \int_{(-\pi, \pi]^d}
    A(\vzeta e^{i \vtheta})
    B(\vzeta e^{i \vtheta})^n
    \frac{d \theta}
    {\vzeta^{\vkappa_n} e^{i \vkappa_n^T \vtheta}}
\]
and introduce
\begin{equation}
\label{eq:phi}
    \phi(\vtheta) :=
    i \vlambda^T \vtheta
    - \log \left(
    \frac{B(\vzeta e^{i \vtheta})}{B(\vzeta)}
    \right)
\end{equation}
to rewrite it as
\begin{equation}
\label{eq:central_part_large_powers_limit}
    [\vz^{\vkappa_n}]
    A(\vz)
    B(\vz)^n
%
    =
    \frac{B(\vzeta)^n}
    {\vzeta^{\vkappa_n}}
    \frac{1}{(2 \pi)^d}
    \int_{(-\pi, \pi]^d}
    A(\vzeta e^{i \vtheta})
    e^{- n \phi(\vtheta)}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}.
\end{equation}

\paragraphproof{Central part.}
We introduce a positive sequence $\varepsilon_n$
converging to $0$ and specified later.
The central part of the integral is defined as
\[
    C_n :=
    \frac{1}{(2 \pi)^d}
    \int_{(-\varepsilon_n, \varepsilon_n)^d}
    A(\vzeta e^{i \vtheta})
    e^{- n \phi(\vtheta)}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}.
\]
Since $\phi(\vzero) = \vzero$
and, by definition of $\vzeta$,
the gradient of $\phi(\vtheta)$ also vanishes at $\vzero$,
the Taylor expansion of $\phi(\vtheta)$ is
\begin{equation}
\label{eq:phi_gaussian}
    \phi(\vtheta) =
    - \frac{1}{2}
    \vtheta^T \mH \vtheta
    + \bigO(\| \vtheta \|^3).
\end{equation}
For $\vtheta \in (-\varepsilon_n, \varepsilon_n)$, we have
\[
    n \phi(\vtheta) =
    - \frac{n}{2}
    \vtheta^T \mH \vtheta
    + \bigO(n {\varepsilon_n}^3).
\]
We will choose $\varepsilon_n$ to ensure $n {\varepsilon_n}^3 \to 0$.
We will also ensure $n^{\delta} \varepsilon_n \to 0$,
so $e^{i (\vkappa_n - \vlambda n)^T \vtheta} \sim 1$
uniformly for $\theta \in (-\varepsilon_n, \varepsilon_n)$.
%
The change of variable $\vt = \sqrt{n} \vtheta$ is applied
\[
    C_n =
    \frac{n^{-d/2}}{(2 \pi)^d}
    \int_{(- \sqrt{n} \varepsilon_n, \sqrt{n} \varepsilon_n)^d}
    A(\vzeta e^{i n^{-1/2} \vt})
    e^{- \vt^T \mH \vt / 2 + \bigO(n {\varepsilon_n}^3)}
    d \vt.
\]
We have $A(\vzeta e^{i n^{-1/2} \vt}) \to A(\vzeta)$
and $n {\varepsilon_n}^3 \to 0$, so
\[
    C_n \sim
    A(\vzeta)
    \frac{n^{-d/2}}{(2 \pi)^d}
    \int_{(- \sqrt{n} \varepsilon_n, \sqrt{n} \varepsilon_n)^d}
    e^{- \vt^T \mH \vt / 2}
    d \vt.
\]
We recognise a Cauchy integral
and choose $\varepsilon_n$ such that $\sqrt{n} \varepsilon_n \to +\infty$,
so
\[
    C_n
%
    \sim
    A(\vzeta)
    \frac{n^{-d/2}}{(2 \pi)^d}
    \int_{(-\infty, +\infty)^d}
    e^{- \vt^T \mH \vt / 2}
    d \vt
%
    \sim
    \frac{A(\vzeta)}{\sqrt{(2 \pi n)^d \det(\mH)}}.
\]
The three constraints on $\varepsilon_n$ are satisfied
by choosing, for example, $\varepsilon_n = n^{- \beta}$
with $\beta \in (\max(\delta, 1/3), 1/2)$.

\paragraphproof{Tail.}
The tail corresponds to
$(-\pi, \pi]^d \setminus (-\varepsilon_n, \varepsilon_n)^d$.
The tail part of the integral~\eqref{eq:central_part_large_powers_limit}
is bounded by
\[
    \int_{(-\pi, \pi]^d \setminus (-\varepsilon_n, \varepsilon_n)^d}
    \left|
    A(\vzeta e^{i \vtheta})
    e^{- n \phi(\vtheta)}
    \right|
    d \vtheta
%
    \leq
    \left(
    \sup_{\vtheta \in (-\pi, \pi)^d} |A(\vzeta e^{i \vtheta})| 
    \right)
    \int_{(-\pi, \pi]^d \setminus (-\varepsilon_n, \varepsilon_n)^d}
    e^{- n \Real(\phi(\vtheta))}
    d \vtheta.
\]
We will prove in the next paragraph
that for all large enough $n$,
the minimum of $\Real(\phi(\vtheta))$
on the tail is reached at some points from
$[-\varepsilon_n, \varepsilon_n]^d \setminus (-\varepsilon_n, \varepsilon_n)^d$.
Thus, the tail is bounded by
\[
    \bigO(1)
    \sup_{\vtheta \in [-\varepsilon_n, \varepsilon_n]^d \setminus (-\varepsilon_n, \varepsilon_n)^d}
    e^{- n \Real(\phi(\vtheta))}.
\]
We replace $\phi(\vtheta)$ with its Taylor expansion
\[
    - n \Real(\phi(\vtheta)) =
    - \frac{n}{2} \vtheta^T \mH \vtheta
    + \bigO(n {\varepsilon_n}^3).
\]
Our choice of $\varepsilon_n$ ensures the $\bigO$ tends to $0$.
We divide $\vtheta$ by $\varepsilon_n$
to bound the tail by
\[
    \bigO(1)
    \sup_{\vtheta \in [-\varepsilon_n, \varepsilon_n]^d \setminus (-\varepsilon_n, \varepsilon_n)^d}
    \exp \left(
    - \frac{n {\varepsilon_n}^2}{2}
    ({\varepsilon_n}^{-1} \vtheta)^T \mH ({\varepsilon_n}^{-1} \vtheta)
    \right).
\]
The vector ${\varepsilon_n}^{-1} \vtheta$ has
at least one coefficient equal to $-1$ or $1$,
so it stays bounded away from $\vzero$.
Since $\mH$ is positive definite,
there exist a positive constant $c$
such that
$({\varepsilon_n}^{-1} \vtheta)^T \mH ({\varepsilon_n}^{-1} \vtheta) \geq c$,
so the tail is bounded by
\[
    \bigO(1)
    \exp \left(- c \frac{n {\varepsilon_n}^2}{2} \right).
\]
Since $n {\varepsilon_n}^2 \to +\infty$,
this converges exponentially fast to $0$,
so the tail is negligible compared to
the central part of the integral.

\paragraph{Locating the minimum of $\Real(\phi(\vtheta))$ on the tail.}
By definition of $\phi(\vtheta)$, we have
\begin{align*}
    \Real(\phi(\vtheta))
%
    &=
    \Real \left(
    i \vlambda^T \vtheta
    - \log \left(
        \frac{B(\vzeta e^{i \vtheta})}
            {B(\vzeta)}
    \right)
    \right)
%
    \\&=
    \log(B(\vzeta))
    - \log \left( \left|
    B(\vzeta e^{i \vtheta})
    \right| \right).
\end{align*}
Thus, the minima of $\Real(\phi(\vtheta))$
correspond to maxima of $|B(\vzeta e^{i \vtheta})|$.
By assumption, on the polydisc of radius $\vzeta$,
the maximum of $|B(\vz)|$
is reached only at $\vz = \vzeta$,
so the minimum of $\Real(\phi(\vtheta))$
is reached only at $\vtheta = \vzero$.
As all points of the central part tend to $\vzeta$ with $n$,
this minimum tends to $\Real(\phi(\vzero)) = 0$.
%
By contradiction, let us assume that
there is an infinite set of indices $n$
for which there exists a point in
$(-\pi, \pi)^d \setminus [-\varepsilon_n, \varepsilon_n]^d$
where $\Real(\phi(\vtheta))$ reaches its minimum
on the tail $(-\pi, \pi)^d \setminus (-\varepsilon_n, \varepsilon_n)^d$.
We extract a converging subsequence $\vu_n$.
%
The limit $\vv$ must be $\vzero$,
otherwise $\lim_n \Real(\phi(\vu_n)) = \Real(\phi(\vv)) > 0$,
which contradicts the fact that the minimum on the tail
tends to $0$.
%
The gradient of $\Real(\phi(\vtheta))$ vanishes
at each $\vtheta = \vu_n$.
From \cref{eq:phi_gaussian}, we deduce
that the gradient of $\Real(\phi(\vtheta))$
at $\vtheta = \vu_n$ is proportional
to $\mH \vu_n + \bigO(\|\vu_n\|^2)$.
Let $q_n$ denote the minimum of the absolute value
of all coefficients of $\vu_n$,
then for all $n$
\[
    \mH \frac{\vu_n}{q_n} + \bigO(\|\vu_n\|) = \vzero.
\]
Left-multiplying by $\mH^{-1}$,
we deduce that $\vu_n / q_n$ converges to $\vzero$,
which is impossible as at least
one of its coefficients is equal to $1$.
This concludes the proof that
for all large enough $n$,
the minima of $\Real(\phi(\vtheta))$
on $(-\pi, \pi]^d \setminus (-\varepsilon_n, \varepsilon_n)^d$
belongs to $[-\varepsilon_n, \varepsilon_n]^d \setminus (-\varepsilon_n, \varepsilon_n)^d$.
\end{proof}



    \subsection{Combining Large Powers and Singularity Analysis}\label{sec_appendix-Elie-singularity}
The following result generalizes \cref{th_large-powers-limit}
to the case where the saddle point meets singularities.
It is the analytic result behind \Cref{th_critical,th_mixed-case,th_proba-X-Y}.
This is a multivariate combination of the large powers theorem \cite[Theorem VIII.8]{flajolet2009analytic} and singularity analysis \cite[Section VI]{flajolet2009analytic}.
The presence of large powers simplifies the singularity analysis part
and we avoid the complications related to multivariate singularity analysis
\cite{pemantle2024analytic}.
We will derive a more precise version of it (asymptotic expansion)
in \Cref{sec_asymptotic_expansion}.


\begin{theorem}
\label{th_large-powers-singularity}
Consider a power series $B(z_1, \ldots, z_d)$
with nonnegative coefficients,
full rank, aperiodic
and convergent on a neighborhood $\Omega$ of $0$.
%
Let $K(\vt) = \log(B(e^{\vt}))$ denote
its cumulant generating function.
%
Let $\vlambda$ denote a vector of positive real values
such that the function $K(\vt) - \vlambda^T \vt$
does not tend to its infimum on the boundary
of $\Psi = \{ \vt \in \reals^d,\ e^{\vt} \in \Omega \}$.
%
Let $\vtau$ denote the unique point of $\Psi$
where $K(\vt) - \vlambda^T \vt$ reaches its minimum.
Set $\vzeta = e^{\vtau}$.

We assume $\zeta_j \leq 1$ for all $j$ and denote by $\mS$
the set of indices such that $\zeta_j < 1$,
and by $\mC$ the corresponding set for $\zeta_j = 1$.
Note that by assumption, we have $\mS \cup \mC = \{1, \ldots, d\}$.
%
Let $\mH$ denote the Hessian matrix of $K(\vt)$ at $\vtau$
and $\mM$ the submatrix of $\mH^{-1}$ corresponding to the rows and column in $\mC$.
%
Consider a power series $A(\vz)$
analytic on the torus of radius $\vzeta$
and satisfying $A(\vzeta) \neq 0$.
%
Consider a real value $\delta < 1/2$
and a sequence of vectors of real values
\[
    \vkappa_n = \vlambda n + \bigO(n^{\delta}).
\]
Then
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
%
    \sim
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{A(\vzeta)}
        {\prod_{j \in \mS} (1 - \zeta_j)}
    \frac{1}
        {\sqrt{ (2 \pi)^d n^{|\mS|} \det(\mH)}}
    \int_{(0, +\infty)^{|\mC|}}
    e^{- \vu^T \mM \vu / 2}
    d \vu.
\]
\end{theorem}


\begin{proof}
We write the coefficient extraction as a Cauchy integral
and apply again the change of variable $\vz = \vzeta e^{i \vtheta}$.
However, for $j \in \mC$, as $\zeta_j = 1$ and $z_j = 1$
is a singularity of the integrand, we cannot let $\theta_j$ go through $0$.
So in that case, fixing $\varepsilon_n = n^{- \beta}$
with $\beta \in (\max(\delta, 1/3), 1/2)$,
as in the proof of \cref{th_large-powers-limit},
we define the path of integration for $\theta_j$
as $(-\pi, -\varepsilon_n)$, then a half-circle centered at $0$,
starting at $- \varepsilon_n$, going through $i \varepsilon_n$
and stopping at $\varepsilon_n$, then $(\varepsilon_n, \pi]$.
For $j \in \mS$, we have $\zeta_j < 1$ so we choose
the integration path $\theta_j \in (-\pi, \pi]$.
%
The function $\phi(\vt)$ is defined as in \eqref{eq:phi}
and \cref{eq:central_part_large_powers_limit} becomes
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
%
    =
    \frac{B(\vzeta)^n}
    {\vzeta^{\vkappa_n}}
    \frac{1}{(2 \pi)^d}
    \int
    \frac{A(\vzeta e^{i \vtheta}) e^{- n \phi(\vtheta)}}
    {\prod_{j \in \mS \cup \mC} (1 - \zeta_j e^{i \theta_j})}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}.
\]

\paragraphproof{Central part.}
It corresponds to the following part of the domain of integration,
denoted by $\gamma_n$.
For $j \in \mC$, we choose $\theta_j$ on the half-circle described above.
For $j \in \mS$, we choose $\theta_j \in (-\varepsilon_n, \varepsilon_n)$.
%
On this domain, we apply a Taylor expansion of the integrand.
Note that for $j \in \mC$, as $\zeta_j = 1$,
we have $1 - \zeta_j e^{i \theta_j} \sim - i \theta_j$,
while for $j \in \mS$,
we have $1 - \zeta_j e^{i \theta_j} \sim 1 -\zeta_j$.
\begin{equation}
\label{eq:asympt_one}
    \frac{1}{(2 \pi)^d}
    \int_{\gamma_n}
    \frac{A(\vzeta e^{i \vtheta}) e^{- n \phi(\vtheta)}}
    {\prod_{j \in \mS \cup \mC} (1 - \zeta_j e^{i \theta_j})}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}
%
    \sim
    \frac{1}{(2 \pi)^d}
    \int_{\gamma_n}
    \frac{A(\vzeta)
        e^{- n \vtheta^T \mH \vtheta / 2 + \bigO(n \|\vtheta\|^3)}}
    {\prod_{j \in \mC} (- i \theta_j)
    \prod_{j \in \mS} (1 - \zeta_j)}
    d \theta.
\end{equation}
Note that our choice of $\varepsilon_n$ ensures
that $\bigO(n \|\vtheta\|^3)$ tends to $0$.
The change of variable $\vt = \sqrt{n} \vtheta$ is applied.
The integral is now equivalent with
\[
    \frac{A(\vzeta)}
        {\prod_{j \in \mS} (1 - \zeta_j)}
    \frac{i^{|\mC|}}
        {(2 \pi)^d n^{|\mS|/2}}
    \int
    \frac{e^{- \vt^T \mH \vt / 2}}
        {\prod_{j \in \mC} t_j}
    d \vt,
\]
where the domain of integration is the following.
For $j \in \mC$,
$t_j$ is on the line from $-\sqrt{n} \varepsilon_n$ to $i$,
then on the line from $i$ to $\sqrt{n} \varepsilon_n$.
For $j \in \mS$,
$t_j \in (\sqrt{n} -\varepsilon_n, \sqrt{n} \varepsilon_n)$.
The tails of this integral are exponentially small,
so we add them to simplify the expression.
The central asymptotics becomes
\[
    \frac{A(\vzeta)}
        {\prod_{j \in \mS} (1 - \zeta_j)}
    \frac{i^{|\mC|}}
        {(2 \pi)^d n^{|\mS|/2}}
    \int_{(i - \infty, i + \infty)^{|\mC|} \times (-\infty, +\infty)^{|\mS|}}
    \frac{e^{- \vt^T \mH \vt / 2}}
        {\prod_{j \in \mC} t_j}
    d \vt.
\]
To further simplify the expression,
we inject the following identity,
valid for any $t$ with positive imaginary part
\[
    \frac{1}{t} =
    - i
    \int_0^{+\infty}
    e^{i t u}
    d u.
\]
Applying this identity for $t = t_j$ and $j \in \mC$ yields
\[
    \frac{A(\vzeta)}
        {(2 \pi)^d n^{|\mS|/2} \prod_{j \in \mS} (1 - \zeta_j)}
    \int_{(i - \infty, i + \infty)^{|\mC|} \times (-\infty, +\infty)^{|\mS|}}
    \int_{(0, +\infty)^{|\mC|}}
    \exp \bigg(
        - \frac{1}{2} \vt^T \mH \vt
        + i \sum_{j \in \mC} u_j t_j
    \bigg)
    d \vu
    d \vt.
\]
Let $(\vu_{\mC}, \vzero_{\mS})$ denote the vector of dimension $d$
with $u_j$ at any index $j \in \mC$
and $0$ at any index $j \in \mS$.
The matrix $\mH$ is definite positive,
so its inverse and square root are well defined.
We interchange the integrals and
apply the change of variable $\vs = \sqrt{\mH} \vt$
\begin{align*}
    \frac{A(\vzeta)}
        {\prod_{j \in \mS} (1 - \zeta_j)}
&
    \frac{1}
        {(2 \pi)^d \sqrt{n^{|\mS|} \det(\mH)}}
\\&\times
    \int_{(0, +\infty)^{|\mC|}}
    \int_{(i - \infty, i + \infty)^{|\mC|} \times (-\infty, +\infty)^{|\mS|}}
    \exp \left(
        - \frac{1}{2} \vs^T \vs
        + i (\vu_{\mC}, \vzero_{\mS})^T \mH^{-1/2} \vs
    \right)
    d \vs
    d \vu.
\end{align*}
The argument of the exponential is factorized
\begin{align*}
    \frac{A(\vzeta)}
        {\prod_{j \in \mS} (1 - \zeta_j)}
&
    \frac{1}
        {(2 \pi)^d \sqrt{n^{|\mS|} \det(\mH)}}
    \iint
\\
&    \exp \left(
        - \frac{1}{2}
        \left(\vs - i \mH^{-1/2} (\vu_{\mC}, \vzero_{\mS}) \right)^T
        \left(\vs - i \mH^{-1/2} (\vu_{\mC}, \vzero_{\mS}) \right)
        - \frac{1}{2} (\vu_{\mC}, \vzero_{\mS})^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \right)
    d \vs
    d \vu.
\end{align*}
The integrals with respect to each $s_j$ are now separated,
each a Gaussian integral with value $\sqrt{2 \pi}$.
We deduce that the central part has asymptotics
\[
    \frac{A(\vzeta)}{\prod_{j \in \mS} (1 - \zeta_j)}
    \frac{1}{ \sqrt{ (2 \pi)^d n^{|\mS|} \det(\mH)} }
    \int_{(0, +\infty)^{|\mC|}}
    \exp \left(
        - \frac{1}{2} (\vu_{\mC}, \vzero_{\mS})^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \right)
    d \vu.
\]

\paragraphproof{Tail.}
The proof that the tail is
exponentially small compared to the central part
is the same as in the proof of \cref{th_large-powers-limit}.
\end{proof}



    \subsection{Asymptotic Expansion}
    \label{sec_asymptotic_expansion}


We now explain how to obtain more precise asymptotic results,
applied in \Cref{sec_error-terms}.
%In the subcritical case presented in \cref{th_large-powers-limit},
%it is well known that the asymptotic expansion
%consists of terms in increasing powers of $1/n$.
Since \cref{th_large-powers-limit} is a particular case
of \cref{th_large-powers-singularity},
we focus on the latter.
%
%\fanfan{Je dirais: In the fully subcritical case, the asymptotic expansion consists of terms in powers of $1/n$, which is usual since [blabla]. But in the critical and mixed case, [blabla c'est surprenant].}
% In the fully subcritical
In the critical and mixed cases,
we find an asymptotic expansion where each term corresponds to a power of $1/\sqrt{n}$.
This is somewhat surprising, as for singularity analysis \cite[Section VI]{flajolet2009analytic}
and large powers \cite[Theorem VIII.8]{flajolet2009analytic},
the terms of the asymptotic expansion correspond to powers of $1/n$.


\begin{theorem}
\label{th:asympt_expansion}
We keep the notations of \cref{th_large-powers-singularity}
and replace our assumption
$\vkappa_n = \vlambda n + \bigO(n^{\delta})$
for some $\delta < 1/2$
with
\[
    \vkappa_n = \vlambda n + \bigO(1).
\]
Then for any $r \geq 1$,
there exist functions $a_{k,n}$ of $\vkappa_n - \vlambda n$
(which are bounded with respect to $n$) such that
\begin{equation}
\label{eq:asympt_expansion}
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{n^{|\mS|/2}}
    \left(
    \sum_{k=0}^{r-1}
    a_{k,n}
    n^{-k/2}
    + \bigO(n^{-r/2})
    \right).
\end{equation}
An algorithm computing them is provided in the proof.
In particular, $a_0 := a_{0,n}$ is independent of $n$ and equal to
\begin{align*}
    a_0
%
%    &=
%    \frac{A(\vzeta)}{\prod_{j = c+1}^d (1 - \zeta_j)}
%    \frac{i^c}{(2 \pi)^d}
%    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
%    \frac{e^{-\vt^T \mH \vt / 2}}{\prod_{j=1}^c t_j}
%    d \vt
%
%\\
    &=
    \frac{1}{\sqrt{(2 \pi)^d \det(\mH)}}
    \int_{(0, +\infty)^{|\mC|}}
    e^{- \vu^T \mM \vu}
    d \vu
\end{align*}
and we will express $a_{1,n}$ in \cref{th:compute_a1}.
%
Furthermore, in the particular case $\mC = \emptyset$,
then $a_{k,n} = 0$ for all odd $k$.
\end{theorem}


\begin{proof}
We fix some $r \geq 1$.
%
Let us say that a sequence $u_n$
\emph{tends superpolynomially fast} to $0$
if for any integer $k$, the sequence $n^k u_n$ tends to $0$.
For example, $e^{-\sqrt{n}}$ tends superpolynomially fast to $0$.
%
We proved that the tails tends superpolynomially fast to $0$,
so its contribution to \cref{eq:asympt_expansion}
is negligible.
%
We apply the change of variable $\vt = \sqrt{n} \vtheta$
in the left-hand side of \cref{eq:asympt_one}
and deduce
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{(2 \pi)^d n^{d/2}}
    \int
    \frac{A(\vzeta e^{i \vt / \sqrt{n}}) e^{- n \phi(\vt / \sqrt{n})}}
    {\prod_{j \in \mS \cup \mC} (1 - \zeta_j e^{i t_j / \sqrt{n}})}
    \frac{d \vt}
    {e^{i (\vkappa_n - \vlambda n)^T \vt / \sqrt{n}}}
    \left(1 + \bigO(n^{-r/2}) \right)
\]
where the domain of integration is the following.
For $j \in \mC$,
$t_j$ is on the line from $-\sqrt{n} \varepsilon_n$ to $i$,
then on the line from $i$ to $\sqrt{n} \varepsilon_n$.
For $j \in \mS$,
$t_j \in (- \sqrt{n} \varepsilon_n, \sqrt{n} \varepsilon_n)$.
%
Let us set
\begin{equation}
\label{eq:Fvty}
    F(\vt, y) :=
    \frac{A(\vzeta e^{i \vt y})
    \exp \left( \frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2} \right)}
    {\left(\prod_{j \in \mC} \frac{1 - e^{i t_j y}}{- i t_j y} \right)
    \prod_{j \in \mS} (1 - \zeta_j e^{i t_j y}) }
    \frac{1}{e^{i (\vkappa_n - \vlambda n)^T \vt y}}.
\end{equation}
%
Recalling that $\vzeta_j = 1$ for $j \in \mC$
and injecting $F(\vt, y)$ in our previous expression leads to
\begin{equation}
\label{eq:FFF}
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{i^{|\mC|}}{(2 \pi)^d n^{|\mS|/2}}
    \int
    \frac{F(\vt, n^{-1/2})}{\prod_{j \in \mC} t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
    \left(1 + \bigO(n^{-r/2}) \right).
\end{equation}
The term
$\frac{1 - e^{i t_j y}}{- i t_j y}$ has a Taylor expansion at $y=0$.
Observe also that the valuation of
$\frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2}$
in $y$ is at least $1$,
and that in the series expansion at $(\vt, y) = (\vzero, 0)$,
each monomial where the sum of the exponents of the $t_j$
is $p$ has $y$ at the power $p-2$.
This implies that $F(\vt, y)$ has a Taylor expansion at $y = 0$,
denoted by
\[
    F(\vt, y) =
    \sum_{k = 0}^{r-1}
    F_k(\vt) y^k
    + \bigO \left( (t_1 \cdots t_d)^{\beta_r} y^{r} \right)
\]
where $\beta_r$ is some sequence depending on $r$
(we could prove $\beta_r \leq 3 r$ but will not need it)
and each $F_k(\vt)$ is a polynomial in $\vt$
and in $\vkappa_n - \vlambda n$,
which is a bounded sequence in $n$.
\begin{comment}
Furthermore, for $k$ odd,
in each of the monomials of $F_k(\vt)$,
the sum of the exponents of the $t_j$ is odd
(a fact we will use later in the proof).
\end{comment}
%
With our domain of integration,
we have for any $\beta_r$
\[
    \int
    \frac{\bigO \left( (t_1 \cdots t_d)^{\beta_r} n^{-r/2} \right)}{\prod_{j \in \mC} t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
%
    =
    \bigO(n^{-r/2})
\]
so, injecting in \cref{eq:FFF}
the Taylor expansion of $F(\vt, \vy)$
at $\vy = n^{-1/2}$, we obtain
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j \in \mS \cup \mC} (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{n^{|\mS|/2}}
    \left(
    \sum_{k=0}^{r-1}
    \left[
    \frac{i^{|\mC|}}{(2 \pi)^d}
    \int
    \frac{F_k(\vt)}{\prod_{j \in \mC} t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
    \right] 
    n^{-k/2}
    + \bigO(n^{-r/2})
    \right).
\]
The tails of the integrals are exponentially small,
so we add them to simplify the expression.
After deformation, the domain of integration becomes
$(i - \infty, i + \infty)^{|\mC|} \times (-\infty, +\infty)^{|\mS|}$.
Defining
\[
    a_{k,n} :=
    \frac{i^{|\mC|}}{(2 \pi)^d}
    \int_{(i - \infty, i + \infty)^{|\mC|} \times (-\infty, +\infty)^{|\mS|}}
    \frac{F_k(\vt)}{\prod_{j \in \mC} t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt,
\]
we obtain \cref{eq:asympt_expansion}.

The expression of $a_0$ was obtained and simplified
in the proof of \cref{th_large-powers-singularity}.
Let us now show how to apply the same ideas to the other coefficients.
Write for any complex $t$ with positive imaginary part
\[
    \frac{i}{t}
%
    =
    \int_0^{+\infty}
    e^{i t u}
    d u,
\]
then
\[
    a_{k,n} =
    \frac{1}{(2 \pi)^d}
    \iint_{(0,+\infty)^{|\mC|}}
    \vt^{\vp}
    F_k(\vt)
    e^{- \vt^T \mH \vt / 2 + i (\vu_{\mC}, \vzero_{\mS})^T \vt}
    d \vu
    d \vt.
\]
We apply the change of variable $\vs = \sqrt{\mH} \vt$
and factorize the argument of the exponential
as in the proof of \cref{th_large-powers-singularity}
\begin{align*}
    a_{k,n}
%
    &=
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \iint_{(0,+\infty)^{|\mC|}}
    F_k(\mH^{-1/2} \vs)
    e^{- \vs^T \vs / 2 + i (\vu_{\mC}, \vzero_{\mS})^T \mH^{-1/2} \vs}
    d \vu
    d \vs
\\
    &=
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \iint_{(0,+\infty)^{|\mC|}}
    F_k(\mH^{-1/2} \vs)
%\\&
    e^{- (\vs - i \mH^{-1/2} (\vu_{\mC}, \vzero_{\mS})^T (\vs - i \mH^{-1/2} (\vu_{\mC}, \vzero_{\mS})) / 2 - \vu^T \mM \vu / 2}
    d \vu
    d \vs.
\end{align*}
We interchange the integrals and shift
the vector $\vs$ by $i \mH^{-1/2} (\vx, \vzero)$
\[
    a_{k,n}
%
    =
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \int_{(0,+\infty)^{|\mC|}}
    \int
    F_k\left( \mH^{-1/2} \vs + i \mH^{-1} (\vu_{\mC}, \vzero_{\mS}) \right)
    e^{- \vs^T \vs / 2 - \vu^T \mM \vu / 2}
    d \vs
    d \vu.
\]
Recall that $F_k(\vt)$ is a polynomial,
so there exist polynomials $G_{k, \vp}(\vu)$
(which are also polynomials in $\vkappa_n - \vlambda n$)
and a finite set $S_k \subset \integers_{\geq 0}^d$ such that
\[
    F_k\left( \mH^{-1/2} \vs + i \mH^{-1} (\vu_{\mC}, \vzero_{\mS}) \right)
    =
    \sum_{\vp \in S_k}
    \vs^{\vp}
    G_{k, \vp}(\vu).
\]
We deduce
\[
    a_{k,n} =
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \sum_{\vp \in S_k}
    \int_{(0,+\infty)^{|\mC|}}
    \int
    \vs^{\vp}
    G_{k, \vp}(\vu)
    e^{- \vs^T \vs / 2 - \vu^T \mM \vu / 2}
    d \vs
    d \vu.
\]
Each integral with respect to $s_j$, for $j \in \mS \cup \mC$,
is simplified using the formula
\[
    \int_{(i - \infty, i + \infty)}
    s^p e^{- s^2 / 2} d s
%
    =
    \begin{cases}
    0 & \text{if $p$ is odd,}\\
    \sqrt{2 \pi}
    \frac{(2 q)!}{2^q q!}
    & \text{if $p = 2 q$.}
    \end{cases}
\]
We observe that in the expression of $a_{k,n}$,
only vectors $\vp$ where all coefficients are even may contribute.
Let us define
\[
    S_k^{\star} =
    \{ \vq,\ 2 \vq \in S_k \},
\]
then
\begin{equation}
\label{eq:ak}
    a_{k,n} =
    \frac{1}{ \sqrt{(2 \pi)^d \det(\mH)} }
    \sum_{\vq \in S_k^{\star}}
    \bigg(
        \prod_{j \in \mS \cup \mC}
        \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    \int_{(0,+\infty)^{|\mC|}}
    G_{k, 2 \vq}(\vu)
    e^{ - \vu^T \mM \vu / 2}
    d \vu.
\end{equation}

In the particular case $\mC = \emptyset$, the function $F_k$
is simply composed with $\mH^{-1/2} \vs$.
If $k$ is odd, by construction, the sum of the exponents
in each monomial of $F_k(\vt)$ is odd.
This implies that each monomial of $F_k(\mH^{-1/2} \vs)$
contains some $s_j$ at an odd power,
so $a_{k,n} = 0$.

An alternative approach to compute the coefficients $a_{k,n}$
is to apply the change of variable $- \vt^T \vt / 2 = \phi(\vtheta)$
in the left-hand side of \cref{eq:asympt_one}.
We refer the interested reader to \cite[Chapter 5]{analytic2013pemantle}.
\end{proof}


Our next result provides an explicit expression
for the term $a_{1,n}$ of the asymptotic expansion
from \cref{th:asympt_expansion}.


\begin{lemma}
\label{th:compute_a1}
With $\vzeta$ defined as in \cref{th:asympt_expansion},
define the polynomial
\[
    \phi_3(\vt) :=
    [y^3]
    \log \left( \frac{B(\vzeta e^{\vt y})}{B(\vzeta)} \right).
\]
Observe that the sum of the exponents of each of its monomials is $3$.
Let $\phi_3^{\star}(\vu)$ denote the polynomial
obtained by replacing each monomial $t_j t_k t_{\ell}$
(with $j$, $k$, $\ell$ in $\mS \cup \mC$ not necessarily distinct) with
\begin{align}
    \label{eq:replace_in_phi3t}
    &- \ve_j^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \ve_k^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \ve_{\ell}^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \\&
    + \left(
    (\mH^{-1})_{k,\ell} \ve_j
    + (\mH^{-1})_{j,\ell} \ve_k
    + (\mH^{-1})_{j,k} \ve_{\ell}
    \right)^T
    \mH^{-1} (\vu_{\mC}, \vzero_{\mS}). \nonumber
\end{align}
Let $\vb$ denote the vector of size $d$ with $b_j = -1/2$ for $j \in \mC$
and $b_j = \frac{\zeta_j}{1 - \zeta_j}$ for $j \in \mS$.
%
Then the term $a_{1,n}$ in the asymptotic expansion from \cref{th:asympt_expansion}
is equal to
\begin{align*}
    a_{1,n} =&
    \frac{A(\vzeta)}{\prod_{j \in \mS} (1 - \zeta_j)}
    \frac{1}{ \sqrt{ (2 \pi)^d \det(\mH) }}
\\& \times
    \int_{(0,+\infty)^{|\mC|}}
    \left(
    \phi_3^{\star}(\vu)
    -
    \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \right)
    e^{- \vu \mM \vu / 2}
    d \vu.
\end{align*}
\end{lemma}


\begin{proof}
Our first step is to compute $F_1(\vt) = [y^1] F(\vt, y)$,
where $F(\vt, y)$ is defined in \cref{eq:Fvty}.
Using the expression of $\phi_3(\vt)$ from the lemma,
we have the following Taylor expansions
\begin{align*}
    A(\vzeta e^{i \vt y}) &=
    A(\vzeta) + i \nabla_A(\vzeta) \vt y + \bigO(y^2),
\\
    \exp \left(
    \frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2}
    \right)
    &=
    1 - i \phi_3(\vt) y + \bigO(y^2),
\\
    \frac{1}{\frac{1 - e^{i t_j y}}{-i t_j y}}
    &=
    1 - \frac{i}{2} t_j y + \bigO(y^2),
\\
    \frac{1}{1 - \zeta_j e^{i t_j y}} &=
    \frac{1}{1 - \zeta_j} + \frac{\zeta_j}{(1 - \zeta_j)^2} i t_j y + \bigO(y^2),
\\
    \frac{1}{e^{i (\vkappa_n - \vlambda n)^T \vt y}} &=
    1 - i (\vkappa_n - \vlambda n)^T \vt y + \bigO(y^2).
\end{align*}
Using the vector $\vb$ from the current lemma,
we obtain the following Taylor expansion for the products
\[
    \frac{1}{\prod_{j \in \mC} \frac{1 - e^{i t_j y}}{- i t_j y}}
    \frac{1}{\prod_{j \in \mS} (1 - \zeta_j e^{i t_j y})}
    =
    1 + i \vb^T \vt y + \bigO(y^2).
\]
We deduce
\[
    F_1(\vt) =
    \frac{- i A(\vzeta)}{\prod_{j \in \mS} (1 - \zeta_j)}
    \left(
    \phi_3(\vt)
    - \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T \vt
    \right).
\]

Following the proof of \cref{th:asympt_expansion},
our next step is to compute
\[
    \sum_{\vq \in S_1^{\star}}
    \bigg(
    \prod_{j \in \mS \cup \mC}
    \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    G_{1, 2 \vq}(\vu).
\]
It is obtained by the following transformation of $F_1(\vt)$.
Replace $\vt$ with $\mH^{-1/2} \vs + i \mH^{-1} (\vu_{\mC}, \vzero_{\mS})$,
then for each $j$ and $k$, replace $s_j^k$ with $0$ if $k$ is odd,
and with $\frac{(2q)!}{2^q q!}$ if $k = 2q$.
%
Clearly, any $t_j$ at the power $1$ will be transformed into $i \mH^{-1} (\vu_{\mC}, \vzero_{\mS})$. By construction, $\phi_3(\vt)$ is a polynomial where the sum of exponents in each momonial is $3$.
Consider three integers $j, k, \ell$ in $\mS \cup \mC$.
The monomial $t_j t_k t_{\ell}$ will be transformed into
\[
    \left( \ve_j^T \mH^{-1/2} \vs + i \ve_j^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS}) \right)
    \left( \ve_k^T \mH^{-1/2} \vs + i \ve_k^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS}) \right)
    \left( \ve_{\ell}^T \mH^{-1/2} \vs + i \ve_{\ell}^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS}) \right)
\]
where each $s_h$ at an odd power is replaced by $0$
and each $s_h^2$ is replaced by $1$, for all $h \in \mS \cup \mC$.
The expression becomes
\begin{align*}
    - i
    \ve_j^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \ve_k^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \ve_{\ell}^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    &+ i \ve_j^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \sum_{h=1}^d \ve_k^T \mH^{-1/2} \ve_h \ve_{\ell}^T \mH^{-1/2} \ve_h
    \\&+ i \ve_k^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \sum_{h=1}^d \ve_j^T \mH^{-1/2} \ve_h \ve_{\ell}^T \mH^{-1/2} \ve_h
    \\&+ i \ve_{\ell}^T \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \sum_{h=1}^d \ve_j^T \mH^{-1/2} \ve_h \ve_k^T \mH^{-1/2} \ve_h
\end{align*}
which, given the symmetry of $\mH^{-1/2}$,
is equal to \eqref{eq:replace_in_phi3t}.
%
With $\phi_3^{\star}(\vu)$ defined as in the lemma,
we deduce that after evaluating $F_1(\vt)$ at $\vt = \mH^{-1/2} \vs + i \mH^{-1} (\vu_{\mC}, \vzero_{\mS})$, then replacing for each $j$ any odd power of $s_j$ with $0$ and $s_j^2$ with $1$, we obtain
\[
    \sum_{\vq \in S_1^{\star}}
    \bigg(
    \prod_{j \in \mS \cup \mC}
    \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    G_{1, 2 \vq}(\vu)
=
    \frac{A(\vzeta)}{\prod_{j \in \mS} (1 - \zeta_j)}
    \left(
    \phi_3^{\star}(\vu)
    - \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T
    \mH^{-1} (\vu_{\mC}, \vzero_{\mS})
    \right).
\]
Injecting this in \cref{eq:ak} for $k=1$
yields the expression of $a_{1,n}$ from the current lemma.
\end{proof}

\begin{comment} commented the 25/02/10 at 16:00
Our following result generalize \cref{th_large-powers-limit}
to the case where the saddle point meets singularities.
It is the analytic result behind \Cref{th_critical,th_mixed-case,th_proba-X-Y}.
This is a multivariate combination of the large powers theorem \cite[Theorem VIII.8]{flajolet2009analytic} and singularity analysis \cite[Section VI]{flajolet2009analytic}.
The presence of a large powers simplifies the singularity analysis part
and we avoid the complications related to multivariate singularity analysis
\cite{pemantle2024analytic}.
We will derive a more precise version of it (asymptotic expansion)
in \Cref{sec_asymptotic_expansion}.


\fanfan{C'est peut-être un peu short niveau temps, mais: dans le papier, on n'a pas supposé que les coordonnées critiques (resp. sous-critiques)  étaient consécutives. On a considéré des ensembles d'indices $\mathcal{S}$ et $\mC$. Au final, c'est plutôt plus agréable.}

\begin{theorem}
\label{th_large-powers-singularity}
Consider a power series $B(z_1, \ldots, z_d)$
with nonnegative coefficients,
full rank, aperiodic
and convergent on a neighborhood $\Omega$ of $0$.
%
Let $K(\vt) = \log(B(e^{\vt}))$ denote
its cumulant generating function.
%
Let $\vlambda$ denote a vector of positive real values
such that the function $K(\vt) - \vlambda^T \vt$
does not tend to its infimum on the boundary
of $\Psi = \{ \vt \in \reals^d,\ e^{\vt} \in \Omega \}$.
%
Set $\vzeta = e^{\vtau}$
where $\vtau$ denotes the unique point of $\Psi$
where $K(\vt) - \vlambda^T \vt$ reaches its minimum.
We assume
\begin{align*}
    \zeta_j = 1 & \text{ for } j \in [1, c],\\
    \zeta_j \in (0, 1) & \text{ for } j \in [c+1, d].
\end{align*}
%
Let $\mH$ denote the Hessian matrix of $K(\vt)$ at $\vtau$
and $\mM$ the top-left $c \times c$ block of $\mH^{-1}$.
%
Consider a power series $A(\vz)$
analytic on the torus of radius $\vzeta$
and satisfying $A(\vzeta) \neq 0$.
%
Consider a real value $\delta < 1/2$
and a sequence of vectors of real values
\[
    \vkappa_n = \vlambda n + \bigO(n^{\delta}).
\]
Then
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
%
    \sim
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{A(\vzeta)}
        {\prod_{j = c+1}^d (1 - \zeta_j)}
    \frac{1}
        {\sqrt{ (2 \pi)^d n^{d-c} \det(\mH)}}
    \int_{(0, +\infty)^c}
    e^{- \vu^T \mM \vu / 2}
    d \vu.
\]
\end{theorem}


\begin{proof}
We write the coefficient extraction as a Cauchy integral
and apply again the change of variable $\vz = \vzeta e^{i \vtheta}$.
However, for $j \in [1, c]$, as $\zeta_j = 1$ and $z_j = 1$
is a singularity of the integrand, we cannot let $\theta_j$ go through $0$.
So in that case, fixing $\varepsilon_n = n^{- \beta}$
with $\beta \in (\max(\delta, 1/3), 1/2)$,
as in the proof of \cref{th_large-powers-limit},
we define the path of integration for $\theta_j$
as $(-\pi, -\varepsilon_n)$, then a half-circle centered at $0$,
starting at $- \varepsilon_n$, going through $i \varepsilon_n$
and stopping at $\varepsilon_n$, then $(\varepsilon_n, \pi]$.
For $j \in [c+1, d]$, we have $\zeta_j < 1$ so we choose
the integration path $\theta_j \in (-\pi, \pi]$.
%
The function $\phi(\vt)$ is defined as in \eqref{eq:phi}
and \cref{eq:central_part_large_powers_limit} becomes
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
%
    =
    \frac{B(\vzeta)^n}
    {\vzeta^{\vkappa_n}}
    \frac{1}{(2 \pi)^d}
    \int
    \frac{A(\vzeta e^{i \vtheta}) e^{- n \phi(\vtheta)}}
    {\prod_{j=1}^d (1 - \zeta_j e^{i \theta_j})}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}.
\]

\paragraphproof{Central part.}
It corresponds to the following part of the domain of integration,
denoted by $\gamma_n$.
For $j \in [1,c]$, we choose $\theta_j$ on the half-circle described above.
For $j \in [c+1, d]$, we choose $\theta_j \in (-\varepsilon_n, \varepsilon_n)$.
%
On this domain, we apply a Taylor expansion of the integrand.
Note that for $j \in [1,c]$, as $\zeta_j = 1$,
we have $1 - \zeta_j e^{i \theta_j} \sim - i \theta_j$,
while for $j \in [c+1, d]$,
we have $1 - \zeta_j e^{i \theta_j} \sim 1 -\zeta_j$.
\begin{equation}
\label{eq:asympt_one}
    \frac{1}{(2 \pi)^d}
    \int_{\gamma_n}
    \frac{A(\vzeta e^{i \vtheta}) e^{- n \phi(\vtheta)}}
    {\prod_{j=1}^d (1 - \zeta_j e^{i \theta_j})}
    \frac{d \theta}
    {e^{i (\vkappa_n - \vlambda n)^T \vtheta}}
%
    \sim
    \frac{1}{(2 \pi)^d}
    \int_{\gamma_n}
    \frac{A(\vzeta)
        e^{- n \vtheta^T \mH \vtheta / 2 + \bigO(n \|\vtheta\|^3)}}
    {\prod_{j = 1}^c (- i \theta_j)
    \prod_{j = c+1}^d (1 - \zeta_j)}
    d \theta.
\end{equation}
Note that our choice of $\varepsilon_n$ ensures
that $\bigO(n \|\vtheta\|^3)$ tends to $0$.
The change of variable $\vt = \sqrt{n} \vtheta$ is applied.
The integral is now equivalent with
\[
    \frac{A(\vzeta)}
        {\prod_{j = c+1}^d (1 - \zeta_j)}
    \frac{i^c}
        {(2 \pi)^d n^{(d-c)/2}}
    \int
    \frac{e^{- \vt^T \mH \vt / 2}}
        {\prod_{j = 1}^c t_j}
    d \vt,
\]
where the domain of integration is the following.
For $j \in [1, c]$,
$t_j$ is on the line from $-\sqrt{n} \varepsilon_n$ to $i$,
then on the line from $i$ to $\sqrt{n} \varepsilon_n$.
For $j \in [c+1, d]$,
$t_j \in (\sqrt{n} -\varepsilon_n, \sqrt{n} \varepsilon_n)$.
The tails of this integral are exponentially small,
so we add them to simplify the expression.
The central asymptotics becomes
\[
    \frac{A(\vzeta)}
        {\prod_{j = c+1}^d (1 - \zeta_j)}
    \frac{i^c}
        {(2 \pi)^d n^{(d-c)/2}}
    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
    \frac{e^{- \vt^T \mH \vt / 2}}
        {\prod_{j = 1}^c t_j}
    d \vt.
\]
To further simplify the expression,
we inject the following identity,
valid for any $t$ with positive imaginary part
\[
    \frac{1}{t} =
    - i
    \int_0^{+\infty}
    e^{i t u}
    d u.
\]
Applying this identity for $t = t_j$ and $j \in [1, c]$ yields
\[
    \frac{A(\vzeta)}
        {(2 \pi)^d n^{(d-c)/2} \prod_{j = c+1}^d (1 - \zeta_j)}
    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
    \int_{(0, +\infty)^c}
    \exp \left(
        - \frac{1}{2} \vt^T \mH \vt
        + i (u_1 t_1 + \cdots + u_c t_c)
    \right)
    d \vu
    d \vt.
\]
Let $(\vu, \vzero)$ denote the vector
$(u_1, \ldots, u_c, 0, \ldots, 0)$ of dimension $d$.
The matrix $\mH$ is definite positive,
so its inverse and square root are well defined.
We interchange the integrals and
apply the change of variable $\vs = \sqrt{\mH} \vt$
\[
    \frac{A(\vzeta)}
        {\prod_{j = c+1}^d (1 - \zeta_j)}
    \frac{1}
        {(2 \pi)^d \sqrt{n^{d-c} \det(\mH)}}
    \int_{(0, +\infty)^c}
    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
    \exp \left(
        - \frac{1}{2} \vs^T \vs
        + i (\vu, \vzero)^T \mH^{-1/2} \vs
    \right)
    d \vs
    d \vu.
\]
The argument of the exponential is factorized
\begin{align*}
    \frac{A(\vzeta)}
        {\prod_{j=c+1}^d (1 - \zeta_j)}
&
    \frac{1}
        {(2 \pi)^d \sqrt{n^{d-c} \det(\mH)}}
    \iint
\\
&    \exp \left(
        - \frac{1}{2}
        \left(\vs - i \mH^{-1/2} (\vu, \vzero) \right)^T
        \left(\vs - i \mH^{-1/2} (\vu, \vzero) \right)
        - \frac{1}{2} (\vu, \vzero)^T \mH^{-1} (\vu, \vzero)
    \right)
    d \vs
    d \vu.
\end{align*}
The integrals with respect to each $s_j$ are now separated,
each a Gaussian integral with value $\sqrt{2 \pi}$.
We deduce that the central part has asymptotics
\[
    \frac{A(\vzeta)}{\prod_{j = c+1}^d (1 - \zeta_j)}
    \frac{1}{ \sqrt{ (2 \pi)^d n^{d-c} \det(\mH)} }
    \int_{(0, +\infty)^c}
    \exp \left(
        - \frac{1}{2} (\vu, \vzero)^T \mH^{-1} (\vu, \vzero)
    \right)
    d \vu.
\]

\paragraphproof{Tail.}
The proof that the tail is
exponentially small compared to the central part
is the same as in the proof of \cref{th_large-powers-limit}.
\end{proof}



    \subsection{Asymptotic Expansion \fanfan{Higher-Order Asymptotic Expansion? Higher-Order Terms in the Asymptotic Expansion? Ou garder tel quel?}}
    \label{sec_asymptotic_expansion}


We now explain how to obtain more precise asymptotic results,
a result we applied in \Cref{sec_error-terms}.
%In the subcritical case presented in \cref{th_large-powers-limit},
%it is well known that the asymptotic expansion
%consists of terms in increasing powers of $1/n$.
Since \cref{th_large-powers-limit} is a particular case
of \cref{th_large-powers-singularity},
we focus on the latter.
