\begin{theorem}
\label{th:asympt_expansion}
We keep the notations of \cref{th_large-powers-singularity}
and replace our assumption
$\vkappa_n = \vlambda n + \bigO(n^{\delta})$
for some $\delta < 1/2$
with
\[
    \vkappa_n = \vlambda n + \bigO(1).
\]
Then for any $r \geq 1$,
there exist functions $a_k$ of $\vkappa_n - \vlambda n$
(which are bounded with respect to $n$) such that
\begin{equation}
\label{eq:asympt_expansion}
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{n^{(d-c)/2}}
    \left(
    \sum_{k=0}^{r-1}
    a_k
    n^{-k/2}
    + \bigO(n^{-r/2})
    \right).
\end{equation}
An algorithm computing them is provided in the proof.
In particular, we have
\begin{align*}
    a_0
%
%    &=
%    \frac{A(\vzeta)}{\prod_{j = c+1}^d (1 - \zeta_j)}
%    \frac{i^c}{(2 \pi)^d}
%    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
%    \frac{e^{-\vt^T \mH \vt / 2}}{\prod_{j=1}^c t_j}
%    d \vt
%
%\\
    &=
    \frac{1}{\sqrt{(2 \pi)^d \det(\mH)}}
    \int_{(0, +\infty)^c}
    e^{- (\vu, \vzero)^T \mH^{-1} (\vu, \vzero)}
    d \vu
\end{align*}
and we will express $a_1$ in \cref{th:compute_a1}.
%
Furthermore, in the particular case $c=0$ and $k$ odd,
then $a_k = 0$.
\end{theorem}


\begin{proof}
We fix some $r \geq 1$.
%
Let us say that a sequence $u_n$
\emph{tends superpolynomially fast} to $0$
if for any integer $k$, the sequence $n^k u_n$ tends to $0$.
For example, $e^{-\sqrt{n}}$ tends superpolynomially fast to $0$.
%
We proved that the tails tends superpolynomially fast to $0$,
so its contribution to \cref{eq:asympt_expansion}
is negligible.
%
We apply the change of variable $\vt = \sqrt{n} \vtheta$
in the left-hand side of \cref{eq:asympt_one}
and deduce
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{(2 \pi)^d n^{d/2}}
    \int
    \frac{A(\vzeta e^{i \vt / \sqrt{n}}) e^{- n \phi(\vt / \sqrt{n})}}
    {\prod_{j=1}^d (1 - \zeta_j e^{i t_j / \sqrt{n}})}
    \frac{d \vt}
    {e^{i (\vkappa_n - \vlambda n)^T \vt / \sqrt{n}}}
    \left(1 + \bigO(n^{-r/2}) \right)
\]
where the domain of integration is the following.
For $j \in [1,c]$,
$t_j$ is on the line from $-\sqrt{n} \varepsilon_n$ to $i$,
then on the line from $i$ to $\sqrt{n} \varepsilon_n$.
For $j \in [c+1, d]$,
$t_j \in (- \sqrt{n} \varepsilon_n, \sqrt{n} \varepsilon_n)$.
%
Let us set
\begin{equation}
\label{eq:Fvty}
    F(\vt, y) :=
    \frac{A(\vzeta e^{i \vt y})
    \exp \left( \frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2} \right)}
    {\left(\prod_{j=1}^c \frac{1 - e^{i t_j y}}{- i t_j y} \right)
    \prod_{j=c+1}^d (1 - \zeta_j e^{i t_j y}) }
    \frac{1}{e^{i (\vkappa_n - \vlambda n)^T \vt y}}.
\end{equation}
%
Recalling that $\vzeta_j = 1$ for $j \in [1, c]$
and injecting $F(\vt, y)$ in our previous expression leads to
\begin{equation}
\label{eq:FFF}
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{i^c}{(2 \pi)^d n^{(d-c)/2}}
    \int
    \frac{F(\vt, n^{-1/2})}{\prod_{j=1}^c t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
    \left(1 + \bigO(n^{-r/2}) \right).
\end{equation}
The term
$\frac{1 - e^{i t_j y}}{- i t_j y}$ has a Taylor expansion at $y=0$.
Observe also that the valuation of
$\frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2}$
in $y$ is at least $1$,
and that in the series expansion at $(\vt, y) = (\vzero, 0)$,
each monomial where the sum of the exponents of the $t_j$
is $p$ has $y$ at the power $p-2$.
This implies that $F(\vt, y)$ has a Taylor expansion at $y = 0$,
denoted by
\[
    F(\vt, y) =
    \sum_{k = 0}^{r-1}
    F_k(\vt) y^k
    + \bigO \left( (t_1 \cdots t_d)^{\beta_r} y^{r} \right)
\]
where $\beta_r$ is some sequence depending on $r$
(we could prove $\beta_r \leq 3 r$ but will not need it)
and each $F_k(\vt)$ is a polynomial in $\vt$
and in $\vkappa_n - \vlambda n$,
which is a bounded sequence in $n$.
%
With our domain of integration,
we have for any $\beta_r$
\[
    \int
    \frac{\bigO \left( (t_1 \cdots t_d)^{\beta_r} n^{-r/2} \right)}{\prod_{j=1}^c t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
%
    =
    \bigO(n^{-r/2})
\]
so, injecting in \cref{eq:FFF}
the Taylor expansion of $F(\vt, \vy)$
at $\vy = n^{-1/2}$, we obtain
\[
    [\vz^{\vkappa_n}]
    \frac{A(\vz) B(\vz)^n}
    {\prod_{j=1}^d (1 - z_j)}
    =
    \frac{B(\vzeta)^n}{\vzeta^{\vkappa_n}}
    \frac{1}{n^{(d-c)/2}}
    \left(
    \sum_{k=0}^{r - 1}
    \left[
    \frac{i^c}{(2 \pi)^d}
    \int
    \frac{F_k(\vt)}{\prod_{j=1}^c t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt
    \right] 
    n^{-k/2}
    + \bigO(n^{-r/2})
    \right).
\]
The tails of the integrals are exponentially small,
so we add them to simplify the expression.
After deformation, the domain of integration becomes
$(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}$.
Defining
\[
    a_k :=
    \frac{i^c}{(2 \pi)^d}
    \int_{(i - \infty, i + \infty)^c \times (-\infty, +\infty)^{d-c}}
    \frac{F_k(\vt)}{\prod_{j=1}^c t_j}
    e^{- \vt^T \mH \vt / 2}
    d \vt,
\]
we obtain \cref{eq:asympt_expansion}.

The expression of $a_0$ was obtained and simplified
in the proof of \cref{th_large-powers-singularity}.
Let us now show how to apply the same ideas to the other coefficients.
Write for any complex $t$ with positive imaginary part
\[
    \frac{i}{t}
%
    =
    \int_0^{+\infty}
    e^{i t u}
    d u,
\]
then
\[
    a_k =
    \frac{1}{(2 \pi)^d}
    \int
    \int_{(0,+\infty)^c}
    \vt^{\vp}
    F_k(\vt)
    e^{- \vt^T \mH \vt / 2 + i (\vu, 0)^T \vt}
    d \vu
    d \vt.
\]
We apply the change of variable $\vs = \sqrt{\mH} \vt$
and factorize the argument of the exponential
as in the proof of \cref{th_large-powers-singularity}
\begin{align*}
    a_k
%
    &=
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \int
    \int_{(0,+\infty)^c}
    F_k(\mH^{-1/2} \vs)
    e^{- \vs^T \vs / 2 + i (\vu, \vzero)^T \mH^{-1/2} \vs}
    d \vu
    d \vs
\\
    &=
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \int
    \int_{(0,+\infty)^c}
    F_k(\mH^{-1/2} \vs)
    e^{- (\vs - i \mH^{-1/2} (\vu, \vzero))^T (\vs - i \mH^{-1/2} (\vu, \vzero)) / 2 - (\vu, \vzero)^T \mH^{-1} (\vu, \vzero) / 2}
    d \vu
    d \vs.
\end{align*}
We interchange the integrals and shift
the vector $\vs$ by $i \mH^{-1/2} (\vx, \vzero)$
\[
    a_k
%
    =
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \int_{(0,+\infty)^c}
    \int
    F_k\left( \mH^{-1/2} \vs + i \mH^{-1} (\vu, \vzero) \right)
    e^{- \vs^T \vs / 2 - (\vu, \vzero)^T \mH^{-1} (\vu, \vzero) / 2}
    d \vs
    d \vu.
\]
Recall that $F_k(\vt)$ is a polynomial,
so there exist polynomials $G_{k, \vp}(\vu)$
(which are also polynomials in $\vkappa_n - \vlambda n$)
and a finite set $S_k \subset \integers_{\geq 0}^d$ such that
\[
    F_k\left( \mH^{-1/2} \vs + i \mH^{-1} (\vu, \vzero) \right)
    =
    \sum_{\vp \in S_k}
    \vs^{\vp}
    G_{k, \vp}(\vu).
\]
We deduce
\[
    a_k =
    \frac{1}{(2 \pi)^d \sqrt{\det(\mH)}}
    \sum_{\vp \in S_k}
    \int_{(0,+\infty)^c}
    \int
    \vs^{\vp}
    G_{k, \vp}(\vu)
    e^{- \vs^T \vs / 2 - (\vu, \vzero)^T \mH^{-1} (\vu, \vzero) / 2}
    d \vs
    d \vu.
\]
Each integral with respect to $s_j$, for $j \in [1, d]$,
is simplified using the formula
\[
    \int_{(i - \infty, i + \infty)}
    s^p e^{- s^2 / 2} d s
%
    =
    \begin{cases}
    0 & \text{if $p$ is odd,}\\
    \sqrt{2 \pi}
    \frac{(2 q)!}{2^q q!}
    & \text{if $p = 2 q$.}
    \end{cases}
\]
We observe that in the expression of $a_k$,
only vectors $\vp$ where all coefficients are even may contribute.
Let us define
\[
    S_k^{\star} =
    \{ \vq,\ 2 \vq \in S_k \},
\]
then
\begin{equation}
\label{eq:ak}
    a_k =
    \frac{1}{ \sqrt{(2 \pi)^d \det(\mH)} }
    \sum_{\vq \in S_k^{\star}}
    \bigg(
        \prod_{j=1}^d
        \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    \int_{(0,+\infty)^c}
    G_{k, 2 \vq}(\vu)
    e^{ - (\vu, \vzero)^T \mH^{-1} (\vu, \vzero) / 2}
    d \vu.
\end{equation}

In the particular case $c = 0$, the function $F_k$
is simply composed with $\mH^{-1/2} \vs$.
If $k$ is odd, by construction, the sum of the exponents
in each monomial of $F_k(\vt)$ is odd.
This implies that each monomial of $F_k(\mH^{-1/2} \vs)$
contains some $s_j$ at an odd power,
so $a_k = 0$.

An alternative approach to compute the coefficients $a_k$
is to apply the change of variable $- \vt^T \vt / 2 = \phi(\vtheta)$
in the left-hand side of \cref{eq:asympt_one}.
We refer the interested reader to \cite[Chapter 5]{analytic2013pemantle}.
\end{proof}


Our next result provides an explicit expression
for the term $a_1$ of the asymptotic expansion
from \cref{th:asympt_expansion}.


\begin{lemma}
\label{th:compute_a1}
With $\vzeta$ defined as in \cref{th:asympt_expansion},
define the polynomial
\[
    \phi_3(\vt) :=
    [y^3]
    \log \left( \frac{B(\vzeta e^{\vt y})}{B(\vzeta)} \right).
\]
Observe that the sum of the exponents of each of its monomials is $3$.
Let $\phi_3^{\star}(\vu)$ denote the polynomial
obtained by replacing each monomial $t_j t_k t_{\ell}$
(with $j$, $k$, $\ell$ in $[1,d]$ not necessarily distinct) with
\begin{equation}
    \label{eq:replace_in_phi3t}
    - \ve_j^T \mH^{-1} (\vu, \vzero)
    \ve_k^T \mH^{-1} (\vu, \vzero)
    \ve_{\ell}^T \mH^{-1} (\vu, \vzero)
    + \left(
    (\mH^{-1})_{k,\ell} \ve_j
    + (\mH^{-1})_{j,\ell} \ve_k
    + (\mH^{-1})_{j,k} \ve_{\ell}
    \right)^T
    \mH^{-1} (\vu, \vzero).
\end{equation}
Let $\vb$ denote the vector of size $d$
\[
    \vb := \left( -\frac{1}{2}, \ldots, -\frac{1}{2}, \frac{\zeta_{c+1}}{1 - \zeta_{c+1}}, \ldots, \frac{\zeta_{d}}{1 - \zeta_{d}} \right).
\]
Then the term $a_1$ in the asymptotic expansion from \cref{th:asympt_expansion}
is equal to
\begin{align*}
    a_1 =&
    \frac{A(\vzeta)}{\prod_{j=c+1}^d (1 - \zeta_j)}
    \frac{1}{ \sqrt{ (2 \pi)^d \det(\mH) }}
\\& \times
    \int_{(0,+\infty)^c}
    \left(
    \phi_3^{\star}(\vu)
    -
    \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T \mH^{-1} (\vu, \vzero)
    \right)
    e^{- (\vu, \vzero)^T \mH^{-1} (\vu, \vzero) / 2}
    d \vu.
\end{align*}
\end{lemma}


\begin{proof}
Our first step is to compute $F_1(\vt) = [y^1] F(\vt, y)$,
where $F(\vt, y)$ is defined in \cref{eq:Fvty}.
Using the expression of $\phi_3(\vt)$ from the lemma,
we have the following Taylor expansions
\begin{align*}
    A(\vzeta e^{i \vt y}) &=
    A(\vzeta) + i \nabla_A(\vzeta) \vt y + \bigO(y^2),
\\
    \exp \left(
    \frac{1}{2} \vt^T \mH \vt - \phi(\vt y) y^{-2}
    \right)
    &=
    1 - i \phi_3(\vt) y + \bigO(y^2),
\\
    \frac{1}{\frac{1 - e^{i t_j y}}{-i t_j y}}
    &=
    1 - \frac{i}{2} t_j y + \bigO(y^2),
\\
    \frac{1}{1 - \zeta_j e^{i t_j y}} &=
    \frac{1}{1 - \zeta_j} + \frac{\zeta_j}{(1 - \zeta_j)^2} i t_j y + \bigO(y^2),
\\
    \frac{1}{e^{i (\vkappa_n - \vlambda n)^T \vt y}} &=
    1 - i (\vkappa_n - \vlambda n)^T \vt y + \bigO(y^2).
\end{align*}
Using the vector $\vb$ from the current lemma,
we obtain the following Taylor expansion for the products
\[
    \frac{1}{\prod_{j=1}^c \frac{1 - e^{i t_j y}}{- i t_j y}}
    \frac{1}{\prod_{j = c+1}^d (1 - \zeta_j e^{i t_j y})}
    =
    1 + i \vb^T \vt y + \bigO(y^2).
\]
We deduce
\[
    F_1(\vt) =
    \frac{- i A(\vzeta)}{\prod_{j=c+1}^d (1 - \zeta_j)}
    \left(
    \phi_3(\vt)
    - \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T \vt
    \right).
\]

Following the proof of \cref{th:asympt_expansion},
our next step is to compute
\[
    \sum_{\vq \in S_1^{\star}}
    \bigg(
    \prod_{j=1}^d
    \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    G_{1, 2 \vq}(\vu).
\]
It is obtained by the following transformation of $F_1(\vt)$.
Replace $\vt$ with $\mH^{-1/2} \vs + i \mH^{-1} (\vu, \vzero)$,
then for each $j$ and $k$, replace $s_j^k$ with $0$ if $k$ is odd,
and with $\frac{(2q)!}{2^q q!}$ if $k = 2q$.
%
Clearly, any $t_j$ at the power $1$ will be transformed into $i \mH^{-1} (\vu, \vzero)$. By construction, $\phi_3(\vt)$ is a polynomial where the sum of exponents in each momonial is $3$.
Consider three integers $j, k, \ell$ in $[1, d]$.
The monomial $t_j t_k t_{\ell}$ will be transformed into
\[
    \left( \ve_j^T \mH^{-1/2} \vs + i \ve_j^T \mH^{-1} (\vu, \vzero) \right)
    \left( \ve_k^T \mH^{-1/2} \vs + i \ve_k^T \mH^{-1} (\vu, \vzero) \right)
    \left( \ve_{\ell}^T \mH^{-1/2} \vs + i \ve_{\ell}^T \mH^{-1} (\vu, \vzero) \right)
\]
where each $s_h$ at an odd power is replaced by $0$
and each $s_h^2$ is replaced by $1$, for all $h \in [1, d]$.
The expression becomes
\begin{align*}
    - i
    \ve_j^T \mH^{-1} (\vu, \vzero)
    \ve_k^T \mH^{-1} (\vu, \vzero)
    \ve_{\ell}^T \mH^{-1} (\vu, \vzero)
    &+ i \ve_j^T \mH^{-1} (\vu, \vzero)
    \sum_{h=1}^d \ve_k^T \mH^{-1/2} \ve_h \ve_{\ell}^T \mH^{-1/2} \ve_h
    \\&+ i \ve_k^T \mH^{-1} (\vu, \vzero)
    \sum_{h=1}^d \ve_j^T \mH^{-1/2} \ve_h \ve_{\ell}^T \mH^{-1/2} \ve_h
    \\&+ i \ve_{\ell}^T \mH^{-1} (\vu, \vzero)
    \sum_{h=1}^d \ve_j^T \mH^{-1/2} \ve_h \ve_k^T \mH^{-1/2} \ve_h
\end{align*}
which, given the symmetry of $\mH^{-1/2}$,
is equal to \eqref{eq:replace_in_phi3t}.
%
With $\phi_3^{\star}(\vu)$ defined as in the lemma,
we deduce that after evaluating $F_1(\vt)$ at $\vt = \mH^{-1/2} \vs + i \mH^{-1} (\vu, \vzero)$, then replacing for each $j$ any odd power of $s_j$ with $0$ and $s_j^2$ with $1$, we obtain
\[
    \sum_{\vq \in S_1^{\star}}
    \bigg(
    \prod_{j=1}^d
    \frac{(2 q_j)!}{2^{q_j} q_j!}
    \bigg)
    G_{1, 2 \vq}(\vu)
=
    \frac{A(\vzeta)}{\prod_{j=c+1}^d (1 - \zeta_j)}
    \left(
    \phi_3^{\star}(\vu)
    - \left[
    \frac{\nabla_A(\vzeta)}{A(\vzeta)}
    + \vb
    - (\vkappa_n - \vlambda n)
    \right]^T
    \mH^{-1} (\vu, \vzero)
    \right).
\]
Injecting this in \cref{eq:ak} for $k=1$
yields the expression of $a_1$ from the current lemma.
\end{proof}
\end{comment}
