\section{Properties and Proofs for the General Independent Culture (GIC)}\label{sec_appendix-gic}

\subsection{Satisfying the Conditions of the Asymptotic Theorems in \Cref{sec_appendix-Elie}}
\label{sec_P_theorem_conditions}

In this paper, the characteristic polynomial \( P(\vx) \) encodes a probability distribution over the preference rankings of a voter. This guarantees its convergence on a neighborhood \( \Omega \) of \( 0 \).  
Since we assume that the distribution of voter preferences over rankings is generic, \ie every ranking \( r \) has a positive probability, it follows that all coefficients of the characteristic polynomial \( P(\vx) \) from \Cref{def_def-of-P} are positive.  
The following result establishes that this assumption ensures that the remaining conditions required for the application of our asymptotic theorems (\Cref{th_large-powers-limit,th_large-powers-singularity,th:asympt_expansion}) are satisfied.

\begin{lemma}
\label{th_conditions-P-satisfied}
Consider a polynomial $P(x_1, \ldots, x_d)$
where for any $\mX \subseteq \{1, \ldots, d\}$,
the monomial $\prod_{j \in \mX} x_j$ has a positive coefficient,
while any other monomial has a zero coefficient.
%
As usual, define its cumulant generating function as
\[
    K : \vt \mapsto \log(P(e^{\vt})).
\]
Then $P(\vx)$ has full rank (\Cref{def:rank})
and is aperiodic (\Cref{def:periodicity}).
%
Furthermore, for any $\vlambda \in (0, 1)^d$
and $\vl$ on the boundary of $[-\infty, +\infty]^d$,
the function $t \mapsto K(\vt) - \vlambda^T \vt$
tends to infinity as $\vt$ tends to $\vl$.
%
Thus, there exists a unique vector $\vtau \in \reals^d$
where the gradient of $K$ vanishes.
\end{lemma}

\begin{proof}
By assumption, the support of $P(\vx)$
contains $\vzero$ and $\ve_j$ for each $j \in \{1, \ldots, d\}$.
\Cref{th_full_rank_aperiodic} then implies
that $P(\vx)$ has full rank and is aperiodic.

Now, consider $\vt$ converging to $\vl$.
Let $\mX$ denote the sets of indices $j$
such that $\vl_j = +\infty$.
Let $p_{\mX}$ denote the coefficient of $P(\vx)$
corresponding to the monomial of exponents in $\mX$.
Let $\vone_{\mX}$ denote the vector of dimension $d$
with value $1$ at indices from $\mX$,
and $0$ otherwise.
Then
\[
    P(e^{\vt})
    \geq
    p_{\mX} \exp \left(\vone_{\mX}^T \vt \right),
\]
so
\[
    K(\vt) - \vlambda^T \vt
    \geq
    \log(p_{\mX})
    + \vone_{\mX}^T \vt
    - \vlambda^T \vt
    \geq
    \log(p_{\mX})
    + (\vone_{\mX} - \vlambda)^T \vt.
\]
The vector $\vone_{\mX} - \vlambda$
has positive coefficients at the indices where $\vt$ tends to $+\infty$,
and negative coefficients at the indices where $\vt$ tends to a constant or $-\infty$.
Since $\vl$ is on the boundary of $[-\infty, +\infty]^d$,
it has at least one element equal to $-\infty$ or $+\infty$,
so $(\vone_{\mX} - \vlambda)^T \vt$ tends to infinity.
This implies that $K(\vt) - \vlambda^T \vt$
converges to $+\infty$ as well.

According to \Cref{th_convexity-cumulant-gf},
$K$ is strictly convex.
If its minimum is not reached
on the boundary of its domain of definition,
it must be reached in its interior and is unique.
Thus, there exists a unique point $\vtau$
where the gradient of $K$ vanishes.
\end{proof}



\subsection{Connection Between the Hessian Matrix and the Correlation Matrix}
\label{sec_link-matrices}


This section demonstrate the connection discussed in \Cref{sec_critical-case} between our Hessian matrix $\mH_{K}(\vtau)$ and the correlation matrix $R_m$ of \cite{niemi1968paradox} and \cite{krishnamoorthy2005condorcet}.

For each $j \in \mA$, let $X_j$ denote the random variable
taking value $1$ if candidate $j$ is ranked higher than candidate $m$,
and $0$ otherwise.
% Let $\vX$ be defined as in \Cref{sec_constants_IC} {\color{cyan} lien a la section d'apres aie}
Set $\vY = 2 \vX - \vone$.
In this paper, we consider the covariance matrix $\mH_K(\vtau)$ of $\vX$,
whose coefficient $(j,k)$ is
\[
     \mean(X_j X_k) - \mean(X_j) \mean(X_k),
\]
while \cite{niemi1968paradox} and \cite{krishnamoorthy2005condorcet}
consider the correlation matrix $R_m$ of $\vY$,
whose coefficient $(j,k)$ is
\[
    \frac{\mean(Y_j Y_k) - \mean(Y_j) \mean(Y_k)}
    {\sqrt{(1 - \mean(Y_j)^2) (1 - \mean(Y_k)^2}}.
\]
Observe that
\begin{align*}
    \mean(Y_j Y_k) - \mean(Y_j) \mean(Y_k)
    &=
    \mean((2 X_j - 1) (2 X_k - 1)) - \mean(2 X_j - 1) \mean(2 X_k - 1)
    \\&=
    4 \left(
    \mean(X_j X_k) - \mean(X_j) \mean(X_k)
    \right).
\end{align*}
Let $D$ denote the invertible diagonal matrix
whose $j$th element is $(1 - \mean(Y_j)^2)^{-1/2}$,
then
\[
    R_m = 4 D \mH_K(\vtau) D.
\]
Thus, the change of variable $\vu = 2 D \vv$ links the two formulas
\[
    \frac{1}{\sqrt{\det(R_m)}}
    \int_{(0, +\infty)^{m-1}}
    e^{-\vv^T {R_m}^{-1} \vv / 2}
    d \vv
    =
    \frac{1}{\sqrt{\det(\mH_{K}(\vtau))}}
    \int_{(0, +\infty)^{m-1}}
    e^{-\vu^T {\mH_K(\vtau)}^{-1} \vu / 2}
    d \vu.   
\]




\subsection{Inversion Lemma for a Saddle Point Coordinate}\label{sec_appendix-flip-flop}

This section consists in proving \Cref{th_supercritical-becomes-subcritical}, rewritten below.
\begin{lemmastar}
Let $\mX$ and $\mY$ be two disjoint sets of adversaries. Let $\tilde{\vzeta}$ be the saddle point associated with $\proba\big(m \succ_{\valpha} \mathcal{X} \land m \preccurlyeq_{\valpha} \mathcal{Y} \big)$ . Let $j \in \mX$, $\mX' = \mX \setminus \{j\}$, and $\mY' = \mY \cup \{j\}$. 
Then the saddle point associated with $\proba\big(m \succ_{\valpha} \mathcal{X}' \land m \preccurlyeq_{\valpha} \mathcal{Y}' \big)$ has its $k$-th coordinate equal to $\tilde{\zeta}_k$ if $k \neq j$ and $\frac{1}{\tilde{\zeta}_j}$ if $k=j$.
\end{lemmastar}

\begin{proof}
Transferring a candidate from $\mX$ to $\mY$ corresponds to the following algebraic operation:
\begin{equation}\label{eq_polynomials-flip-flap}
P_{\mY'}^{\mX'}\big(\vx_{{}_{\mX'}},\vy_{{}_{\mY'}}\big) = 
 y_j P_{\mY}^{\mX}\big(\vx_{{}_{\mX'}}, \frac{1}{y_j},\vy_{{}_{\mY}}\big),  
\end{equation}
where $y_j$ encodes when $m$ is preferred to $j$, whereas $x_j$ encoded the opposite.

Now, Let us denote $(\vbeta,\valpha)$ the threshold vector associated with $\proba\big(m \succ_{\valpha} \mX \land m \preccurlyeq_{\valpha} \mY\big)$, and $(\hat{\vbeta},\hat{\valpha})$ the threshold vector associated with  $\proba\big(m \succ_{\valpha} \mX'\land m \preccurlyeq_{\valpha} \mY'\big)$. Remark that $\hat{\vbeta}$ is the vector $\vbeta$ where the coordinate $\beta_j$ has been removed, and $\hat{\valpha}$ is the vector $\valpha$ where the coordinate $\alpha_j$ has been added.
Finally, let us denote $\hat{\vzeta}$ the saddle point associated with $\proba\big(m \succ_{\valpha} \mX'\land m \preccurlyeq_{\valpha} \mY'\big)$. By definition of $\hat{\vzeta}$, extending the remark in \Cref{sec_saddle-point-method}, we have
\[\hat{\vzeta} = \argmin_{(\reals_{> 0})^{|\mX' \cup \mY'|}} \frac{P_{\mY'}^{\mX'}\big(\vx_{{}_{\mX'}},\vy_{{}_{\mY'}}\big)}{{\vx_{{}_{\mX'}}}^{\hat{\vbeta}} {\vy_{{}_{\mY'}}}^{\hat{\valpha}} }.\ \]
So injecting \Cref{eq_polynomials-flip-flap} we get
\[\hat{\vzeta} = \argmin_{(\reals_{> 0})^{|\mX' \cup \mY'|}} \frac{P_{\mY}^{\mX}\big(\vx_{{}_{\mX'}}, \frac{1}{y_j},\vy_{{}_{\mY'}}\big)}{{\vx_{{}_{\mX'}}}^{\hat{\vbeta}} {y_j}^{-\beta_j}{\vy_{{}_{\mY}}}^{\valpha} }.\]
Since the minimum of a function over a positive orthant remains unchanged under the inversion of a coordinate, setting \( x_j = \frac{1}{y_j} \) yields
\[\min_{(\reals_{> 0})^{|\mX' \cup \mY'|}} \frac{P_{\mY}^{\mX}\big(\vx_{{}_{\mX'}}, \frac{1}{y_j},\vy_{{}_{\mY'}}\big)}{{\vx_{{}_{\mX'}}}^{\hat{\vbeta}} {y_j}^{-\beta_j}{\vy_{{}_{\mY}}}^{\valpha} } = \min_{(\reals_{> 0})^{|\mX \cup \mY|} }\frac{P_{\mY}^{\mX}\big(\vx_{{}_{\mX}},\vy_{{}_{\mY}}\big)}{{\vx_{{}_{\mX}}}^{\vbeta} {\vy_{{}_{\mY}}}^{\valpha} }, \]
and more importantly, the transformation \( x_j = \frac{1}{y_j} \) yields
\[\hat{\vzeta}=(\tilde{\zeta}_1,\dots,\tilde{\zeta}_{j-1}, \frac{1}{\tilde{\zeta}_j}, \tilde{\zeta}_{j+1},\dots,\tilde{\zeta}_{m-1}).\]
\end{proof}







