\begin{lem}[basis in $\Z^n$ $\Leftrightarrow$ $n$ invariant factors equal $1$]
\label{lem:basis=factors1}
The columns of any $n\times m$ matrix $A$ form a basis of $\Z^n$ if and only if $A$ has $n$ invariant factors equal to 1.
\end{lem}
\begin{proof}
Let $I_n$ be the identity $n\times n$ matrix whose columns $\vb*{w_1},\dots,\vb*{w_n}$ form the standard orthonormal basis of $\Z^n$.
If the columns $\vb*{u_1},\dots,\vb*{u_m}$ of $A$ form a basis of $\Z^n$, then $\vb*{w_i}=\sum\limits_{j=1}^m \vb*{u_j}r_{ij}$, $i=1\dots,n$, for some $r_{ij}\in\Z$.
These $n\times m$ values $r_{ij}$ complemented by the $m-n$ zero columns
form the $m\times m$ matrix $R$ such that by Definition~\ref{dfn:SNF} the product $I_n A R$ is the Smith Normal Form of $A$ with all invariant factors equal to $1$.
Conversely, if the Smith Normal Form $LAR$ from Definition~\ref{dfn:SNF} has all invariant factors equal to 1, the $m$ columns of the $n\times m$ matrix $AR$  and hence the $m$ columns of the matrix $A$ form a basis of $\Z^n$.
Indeed, transforming these $m$ columns by the invertible $n\times n$ matrix $L$ gives the standard orthonormal basis $\vb*{w_1},\dots,\vb*{w_n}$ of $\Z^n$.
\end{proof}

\begin{lem}[connected $G$ $\Rightarrow$ $n$ invariant factors equal $1$]
\label{lem:factors1}
In Algorithm~\ref{alg:bridge_length}, if the lifted periodic graph $G\subset\R^n$ becomes connected, then the translational matrix $A$ has $n$ invariant factors equal to 1.  
\end{lem}
\begin{proof}
\begin{comment}
