\[e^{Qt}Q(0) = e^{Q}=e^{\bigoplus_{i=1}^{H} Q_{i}^{(i)} + Q_{D}} = e^{\bigoplus_{i=1}^{H}Q_{i}^{(i)}}e^{Q_{D}}=e^{Q_{D}}\bigotimes_{h=1}^{H}e^{Q_{i}^{(i)}} = e^{Q_{D}}\bigotimes_{h=1}^{H}P_{i}^{(i)}\]
