% #mark a 1 at all of those indexes
% #mark a 0 at all z2, complementing out those in zdif
\begin{algorithm}[H]
\renewcommand\thealgorithm{}
\caption{ad-mult(s1,s2)}
\begin{algorithmic}[]
\STATE $\text{res} = \text{s1.copy()}$
\STATE $\text{z1, z2} = \text{where(s1 = 0), where(s2 = 0)}$
% \STATE $\text{z2} = \text{where(s2 = 0)}$
\STATE $\text{difs} = [\text{abs}(i[0] - i[1]) \text{ for i in }  \text{z1}\varprod_{}^{}\text{z2}]$ 
\STATE $\text{zdif, odif} = \text{where(difs = 0), where(difs = 1)}$
% \STATE $\text{odif} = \text{where(difs = 1)}$
\STATE $\text{marks} = \text{zdif} \cup \text{odif}$
\FOR{$i$ in \text{marks}}
\STATE $\text{res}[i] = 1$
\ENDFOR
\FOR{$i$ in \text{z2 }$\setminus$\text{ zdif}}
\STATE $\text{res}[i] = 0$
\ENDFOR

\RETURN \text{res}
\end{algorithmic}
% \caption{ad-mult(s1,s2)} 
%\fcolorbox{black}{green}{\rule{0pt}{4pt}\rule{4pt}{0pt}}}
% \label{alg:seq3}
\end{algorithm}
\vspace{-0.5cm} 
\begin{algorithm}[H]
\renewcommand\thealgorithm{}
\caption{reduce-factors(x, lists)} 
\begin{algorithmic}[]

\STATE $\text{lists} = [[1],[0]]$
\FOR{$i=0$ to \text{x}} %x[0] here or [x] in input
\STATE $\text{sub} = \text{{[ ]}}$
\FOR{$j$ in \text{lists}}

 \IF{$j[-1] == 1$}
     \STATE $\text{sub.insert}(j+[0])$
\ENDIF

\STATE $\text{sub.insert}(j+[1])$

\ENDFOR
\STATE $\text{lists} = \text{sub}$
\ENDFOR

\RETURN $\text{lists}$
\end{algorithmic}
% \caption{reduce-factors(x, lists)} 
%\fcolorbox{black}{blue}{\rule{0pt}{4pt}\rule{4pt}{0pt}}}
% \label{alg:seq3}
\end{algorithm}
