\subsubsection*{Solver}
\vspace{-0.5cm} 
\begin{algorithm}[H]
\renewcommand\thealgorithm{}
\caption{$\lambda$ solver}
\begin{algorithmic}
\STATE $\text{A, symbols, batchsize, base, stagger} = \hdots$
\STATE $\text{precision, extractionparams (midpoint, midpointvalue), digits} = \hdots$
% \STATE $\text{digits} \gets \text{batch size} * (\text{stagger} + 1)$
%assign A, batch size, stagger, precision (batch size + 10)
\STATE $.\text{indicatorvars} = \begin{bmatrix}\text{base}^{\ceil{\frac{\text{digits}}{2}} - \text{stagger}} & \text{base}^{\ceil{\frac{\text{digits}}{2}} - 2*\text{stagger}} & \hdots & \text{base}^{-\floor{\frac{\text{digits}} {2}}}\end{bmatrix}$
\STATE $.\text{realvals} = \begin{bmatrix} \hdots \end{bmatrix}$
\STATE $\text{map} = \text{\{symbols} \rightarrow \text{randomreals\}}$
\STATE $\text{coeffs} = \text{{[ ]}}$

\FOR{$i=0$ to \text{numbatches}}
\STATE $\text{mapcurr} = \text{map.copy()}$
\STATE $\text{mapcurr{[}}i*\text{batchsize}, \min{\text{(n}, (i+1)*\text{batchsize)}}\text{{]}} \mathrel{+}= \text{expvars}$
\STATE $\text{A}_{i} = \text{mapcurr(A)}$
\STATE $\sigma = \text{eig\color{red}*\color{black}}(\text{A}_{i}) + \text{midpoint}$
%need to modify here or switch to vectorizing by rows
\STATE $\text{coeffs.insert({[} digitsof}(\sigma_{j}\text{)} - \text{midpointvalue for j in range(n){]})}$
\ENDFOR
% %rows is batch, columns is eigenvalue. concatenate eigenvalues across batches
%rewrite as mapping vec on entries?
\STATE $\text{coeffs} = \begin{bmatrix} \text{vec(coeffs[:},0\text{{]})} \\ \hdots \\ \text{vec(coeffs[:},n-1\text{{]})} \end{bmatrix}$
% calculate eigenvalues for each batch
%     -assign variables for given batch
%     -compute numeric eigenvalues
%     -midpoint_normalized_eigens = [mp.im(i)+midpoint for i in eigenvalues]
%     -return [int(i) - midpoint_value for i in val]

\end{algorithmic}
% \caption{$\lambda$ solver}
% \label{alg:seq}
\end{algorithm}
