  $\mathbf{restock}$ $\mathbf{refines}$ $\mathbf{restock}$ $\triangleq$  $\mathbf{when}$
    soda + water = 0
  $\mathbf{then}$
    soda :=  2 ||
    water :=  1 
  $\mathbf{end}$
\end{lstlisting}
\end{minipage}
\end{figure}

\subsubsection{Formalization}
\label{subsec:formalization}
A B machine induces a state space, as formalized in \Cref{def:machine}, similar to Zhu et al.~\cite{Zhu2019}.
\begin{definition}
\label{def:machine} (State Space of a machine)
    The state space of an Event-B machine M is a quadruple (S, E, $\delta$, $I$) where
    S is the % finite
    set of all possible states, $I \subseteq S$ the initial states,
    E is the set of events, 
    and $\delta \in E \tfun (S \rel S)$ describes the transitions. %\todo{Note Sebastian: I think this is cleaner as it forces E to be finite. I added a sentence to the limitation section explaining the effect}
    To denote an individual transition, we write $s \overset{e}{\rightarrow}_{M} s' $ if $(s \mapsto s') \in \delta(e)$.
\end{definition}

A state itself consists of a mapping from variables and constants to values.

Note that later some propositions will require finite state spaces.\footnote{\Cref{def:prop:convergence_induces_stable_states,def:prop:mainProp} will rely on this.}

%\todo{remove finiteness from definition above and only require later when needed; more formally define S and notation used for state;
%we also need to make clear the notation to get one of the 4 components from a machine M}

%For the moment we will ignore parameters. With parameters $E$ can be infinite.

% Note that the set of states is meant to be finite; therefore, we only cater to a certain group of machines, namely those with a finite state space. This becomes important later as we want to implement an algorithm. An infinite state space would lead to non-terminating computations. 

\begin{example*}
    For our machine in \Cref{lst:vending}, the state space is the
    quadruple (S, E, $\delta$, I) with
    S = $\{ \{soda = 3, coin = 0 \} , \{soda = 3, coin = 1 \},...\}$,\\
    I = $\{ \{soda = 3, coin = 0 \} \}$,
    %E = $\{INITIALISATION, insert\_coin, vend, restock \}$, 
    % INITIALISATION should not be in E, unless we chanage Def.1 !
    E = $\{ insert\_coin, vend, restock \}$, and \\
    $\delta = \{ insert\_coin \mapsto \{(\{soda = 3, c = 0 \}, \{soda = 3, coin = 1 \}),... \},... \} $. \\
    We have, e.g., 
   % $(\{soda = 3, coin = 0 \} \mapsto \{soda = 3, coin = 1 \}) \in \delta(insert\_coin)$.
    $\{soda = 3, coin = 0 \} \overset{insert\_coin}{\rightarrow}_{M} \{soda = 3, coin = 1 \}$.
\end{example*}

\begin{definition} (Event-B refinement)
\label{def:ref}
    Let ($S_A$, $E_A$, $\delta_A$, $I_A$\footnote{For the following we assume $|I_A|=1$. }) and ($S_C$, $E_C$, $\delta_C$, $I_C$) be the state space of two machines $A$ and $C$.
    We write A $\sqsubseteq_{ref}$ C if C is an Event-B refinement \cite{Abrial2010} of A.
    During refinement, new events can be introduced in $C$, which refines the invisible \texttt{skip}. 
    We denote the set of these events as $\mathcal{N}_C$. 
    If no new events are introduced, $\mathcal{N}_C = \emptyset$.
    Event-B also allows renaming events.
 We capture this renaming in the
     mapping  $\psi_{C,A} \in E_C \setminus \mathcal{N_C} \tsur E_A$ from concrete to abstract events.%
\footnote{$\tsur$ is the total surjection.}
    This means that every event, minus the events introduced via \texttt{skip}, is assigned to an abstract event.
\end{definition}

Note that the definition of $\psi_{C,A}$ as a function above has subtle consequences.
If an abstract event has parameters that do not exist at the concrete level, Event-B stipulates the definition of a witness predicate (see Section 5.1.7 of \cite{Abrial2010}).
To make $\psi_{C,A}$ unambiguous (i.e., a function), we require that the witness predicate
 is {\em deterministic}, i.e., it has a single solution for every concrete event.
This requirement will play an important role later in our main Proposition~\ref{def:prop:mainProp}.
In practice, most witnesses are deterministic, so our requirement is reasonable.

    We can use the relational image operator [~]  to apply $\psi_{C,A}$ to sets, i.e, $ \psi_{C,A}[E] = \{e_c\in E \mid \psi_{C,A}(e_c)\}$.



\subsubsection{Traces in Event-B}
\label{subsec:tracesEventB}
Another view on Event-B machines is from the perspective of traces, which consist of states and events.
\Cref{eq:trace} is aligned with the definition of Zhu et al.~\cite{Zhu2019}.  

\begin{definition}
\label{eq:trace} (Finite trace)
Let the state space of a machine M be ($S_M$, $E_M$, $\delta_M$, $I_M$).
We define the transitive closure of  $s \overset{e}{\rightarrow} s' $  as follows:
$s_0 \overset{e_0, e_1,...,e_n}{\implies} s_n$ if $s_0 \overset{e_0}{\rightarrow} s_1 \overset{e_1}{\rightarrow} ..\overset{e_n}{\rightarrow} s_n $. 
Let $E^{*}_{M}$ be the set of finite sequences over $E_M$.
%A trace is an element $\sigma \in E^{*}_{M}$ 
% such that $s_0 \overset{\sigma}{\implies} s_n$ for some $s_0\in I_M$ and $s_n\in S_M$. 
We denote the set of all traces of M as follows:
$traces(M) = \{\sigma \in  E^{*}_{M} \mid s_0\in I_M \wedge s_n \in S_M\}$.
%Two traces can be concatenated with the $^\frown$ operator, e.g., $\sigma^\frown\pi$ if the last state of $\sigma$ and the first state of $\pi$ are equal.
Finally, we denote the last state reached by a trace $\sigma$ by $last(\sigma)$.
\end{definition}

\begin{example*}
   Consider \Cref{fig:trace1}, where we see a visualization of the beginning of the state space of \Cref{lst:vending}.
   This part of the state space has the following traces: 
$\langle  \rangle $, $\langle  insert\_coin \rangle, \langle insert\_coin, insert\_coin \rangle,  \langle insert\_coin, vend \rangle $, etc. 
Note that we do not explicitly write the \texttt{INITIALISATION} event, rather assuming it has been performed implicitly at the beginning of a trace to reach the initial state. % But what about concatenation then? 
\end{example*}

