% V = a -> b -> STOP  [] a -> STOP
% W = a -> STOP
%
%assert V [FD= W -- W is an FD refinement of V
%assert W [T= V -- FALSE: but not all traces of V are traces of W
%\end{verbatim}
\end{example*}


