\section{Proof of Lemma 3}\label{sec:belief}

\begin{IEEEproof}
Let $i\neq j$. Consider the following conditional probability:
\begin{align}\label{eq:pi_low}
\mathbf{P}(Y_j=\ell & \mid Y_i=y)   =  \int_0^\infty \mathbf{P}(Y_j = \ell , X=x \mid Y_i=y)dx  \nonumber \\  & \stackrel{(a)}{=} 
\int_0^\infty \mathbf{P}(Y_j = \ell \mid X=x) f_{X\mid Y_i=y}(x)dx, 
\end{align}
where $(a)$ follows from the conditional independence of $Y_i$ and $Y_j$ given $X=x$. Since:
\begin{equation}\label{eq:conditional_poisson}
\mathbf{P}(Y_j = \ell\mid X=x) = \frac{(\lambda x)^\ell}{\ell!}e^{-\lambda x},
\end{equation}
the result follows by using \cref{lem:conditional_distribution} and \cref{eq:conditional_poisson} in \cref{eq:pi_low}.



\end{IEEEproof}


\section{Proof of Lemma 5}\label{sec:monotonicity}

\begin{IEEEproof}
Let us define the first-order difference
\begin{equation}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j) \Equaldef \pi_{ij}^{\mathrm{low}}(y\mid \tau_j) - \pi_{ij}^{\mathrm{low}}(y+1\mid \tau_j).
\end{equation}
From the definition of $\pi^{\mathrm{low}}_{ij}$, we have
\begin{multline}\label{eq:Delta_Low}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j) = \sum_{\ell=0}^{\tau_j}\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell \left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{k+y} \times \\ \Bigg\{\binom{\ell+k+y-1}{\ell} - \binom{\ell+k+y}{\ell}\left(\frac{\lambda +\theta}{2\lambda+\theta}\right) \Bigg\}.
\end{multline}
From the Pascal Triangle identity, we have
\begin{equation}\label{eq:pascal_triangle}
\binom{\ell+k+y}{\ell} = \binom{\ell+k+y-1}{\ell -1} + \binom{\ell+k+y-1}{\ell},
\end{equation}
and after using \cref{eq:pascal_triangle} into \cref{eq:Delta_Low}, we obtain
\begin{multline}\label{eq:first_order}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j) = \left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{k+y} \sum_{\ell=0}^{\tau_j}\Bigg\{\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell \times \\ \binom{\ell+k+y}{k+y}   \left(\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)} \right)\Bigg\}.
\end{multline}

The first step in the proof is to decompose the summation in \cref{eq:first_order} into two terms: the positive and the nonpositive part. Based on the inequality
\begin{equation}
(k+y-\ell)\lambda-\ell \theta>0 \Longleftrightarrow
\ell < \frac{k+y}{\lambda+\theta},
\end{equation}
we obtain \cref{eq:long_first_order}, in which the first term is  positive, whereas the second is nonpositive.
\begin{figure*}[!t]
\begin{multline}
\label{eq:long_first_order}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)  = \left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{k+y}  \Bigg[ \sum_{\ell=0}^{\min\{\lfloor \frac{k+y}{\lambda+\theta} \rfloor,\tau_j\}}\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell  \binom{\ell+k+y}{k+y}   \Bigg(\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)}\Bigg) \\ + \sum_{\min\{\lfloor \frac{k+y}{\lambda+\theta} \rfloor,\tau_j\}+1}^{\tau_j}\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell  \binom{\ell+k+y}{k+y}   \left(\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)}
\right) \Bigg].
%\hline
\end{multline}
\centering --------------------------------------------------------------------------------------------------------------------------------------------------------

\end{figure*}


There are two possible regimes in \cref{eq:long_first_order} depending on the value of $\tau_j$.

\subsubsection*{Case 1}
\begin{equation}
\tau_j \leq \left\lfloor \frac{k+y}{\lambda +\theta} \right\rfloor \ \ \Longrightarrow \ \ \Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)  >0.
\end{equation}

\subsubsection*{Case 2}
If $\tau_j$ satisfies
\begin{equation}
\tau_j \geq \left\lfloor \frac{k+y}{\lambda +\theta} \right\rfloor +1,
\end{equation}
then define the following function
\begin{multline}
A_{\tau_j}(y) \Equaldef \sum_{\left\lfloor \frac{k+y}{\lambda+\theta} \right\rfloor+1}^{\tau_j}\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell  \times \\ \binom{\ell+k+y}{k+y}   \left(\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)}
\right).
\end{multline}
In this regime, all the terms in \cref{eq:negative} are strictly negative. Therefore,
\begin{equation}\label{eq:bound_A_tau}
A_{\tau_j}(y) > A_{\infty}(y).
\end{equation}
From \cref{eq:bound_A_tau}, we obtain the following lower bound
\begin{multline}\label{eq:lower_bound_first_order}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)  > \left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{k+y}  \sum_{\ell=0}^{\infty}\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell  \times \\ \binom{\ell+k+y}{k+y}   \Bigg(\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)}\Bigg).
\end{multline}

The last step in the proof is to show that the right hand side of \cref{eq:lower_bound_first_order} is exactly equal to zero. We start by writing the identity below
\begin{equation}
\frac{(k+y-\ell)\lambda -\ell\theta}{(2\lambda+\theta)(\ell+k+y)} = \frac{\lambda}{2\lambda +\theta} - \left(\frac{\ell}{\ell +k+y} \right)
\end{equation}
From \cref{lem:identity}, we can obtain a combinatorial identity given by
\begin{equation}\label{eq:identity}
\sum_{\ell=0}^\infty \binom{\ell+k+y}{\ell} \Big(\frac{\lambda}{\theta+2\lambda} \Big)^\ell = \Big(\frac{\theta+\lambda}{\theta+2\lambda} \Big)^{-(k+y)}.
\end{equation}


Using \cref{eq:identity} in \cref{eq:lower_bound_first_order}, we have
\begin{multline}
\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)  > \frac{\lambda}{2\lambda +\theta} 
- \textbf{}\left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{k+y} \times \\  \underbrace{\sum_{\ell=0}^{\infty} \binom{\ell+k+y}{k+y}\left(\frac{\ell}{\ell+k+y} \right)\left(\frac{\lambda}{2\lambda+\theta}\right)^\ell}_{\Equaldef \circledast} .   
\end{multline}

Then,
\begin{equation}
\circledast =  \sum_{\ell=1}^{\infty}  \binom{\ell+k+y-1}{\ell-1}   \left(\frac{\lambda}{2\lambda+\theta}\right)^\ell \stackrel{(a)}{=}\left(\frac{\lambda +\theta}{2\lambda+\theta}\right)^{-(k+y)},
\end{equation}
where $(a)$ follows from the change of variables $\ell'=\ell-1$, and using the identity in \cref{eq:identity}. Therefore, $\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)  > 0.$





Since the first order difference $\Delta_{ij}^{\mathrm{low}}(y\mid \tau_j)$ is strictly positive for all $y$, it implies that $\pi^{\mathrm{low}}_{ij}(y \mid \tau_j)$ is strictly monotone decreasing. Moreover, $\pi^{\mathrm{low}}_{ij}(y \mid \tau_j) \rightarrow 0$. Consequently, from the relationship between $\pi^{\mathrm{low}}_{ij}(y \mid \tau_j)$ and $\pi^{\mathrm{high}}_{ij}(y \mid \tau_j)$, we have
\begin{equation}
\pi^{\mathrm{high}}_{ij}(y+1 \mid \tau_j) - \pi^{\mathrm{high}}_{ij}(y\mid \tau_j) = \Delta_{ij}^{\mathrm{low}}(y\mid \tau_j) > 0,
\end{equation}
which implies that $\pi^{\mathrm{high}}_{ij}(y\mid \tau_j)$ is strictly monotone increasing. Moreover, $\pi^{\mathrm{high}}_{ij}(y \mid \tau_j) \rightarrow 1$.

\end{IEEEproof}


