\subsection{Adapting \ours for other Adjacency Notions}
The notion of adjacency used is central to the interpretation of the obtained privacy guarantees, as well as to the sensitivity analysis. We use \textit{replace-by-null} adjacency to derive the privacy guarantees for \ours in \Cref{prop:ourclip-sensitivity} and \Cref{thm:accounting}; refer to \S\ref{sec:review} for a full discussion of other adjacency notions and on how they have been used in previous work. 

We also state the sensitivity of $f_\OurClip$ under \textit{zero-out} adjacency in \Cref{prop:our-sens-zeroout}.
\begin{property} \label{prop:our-sens-zeroout}
    Let the dataset set $\bsz = |\bfR|$ be fixed.
    Then the sensitivity of the map $f_{\OurClip}:(\bfr_1, \ldots, \bfr_\bsz) \mapsto \frac{1}{\bsz} \sum_{i=1}^\bsz \OurClip_\clipnorm(\bfphi_i, \bfphi_\public)$ defined in \Cref{prop:ourclip-sensitivity}, under zero-out adjacency, is
    \[
    \sens(f_\OurClip) = \frac{2\clipnorm}{\bsz}\,.
    \]
\end{property}
%
%
%
%
%
%
%
%
%
%
%
%
%

%
%
%
%
%
%

\begin{proof}
For zero-out adjacency, consider adjacent datasets
$\bfR=\{\bfr_1, \ldots, \bfr_\bsz\}$ and $\bfR'=\{\bfr_1', \ldots, \bfr_\bsz'\}$ that differ in their first element where $\bfr_1'=\perp$ is the empty string. We need to bound the sensitivity of the map $f_{\OurClip}$ from \cref{eq:our-clip}.
%
%
%
%
As in the proof of \Cref{prop:ourclip-sensitivity}, we use shorthand $\bfphi_\public := \phi(\,\cdot\, |\, \bfq, \bfxlt)$ and $\bfphi_i := \phi(\,\cdot \, | \, \bfq, \bfr_i, \bfxlt)$ are public and private logits respectively for $\bfR$ and $\bfphi_i' := \phi(\,\cdot \, | \, \bfq, \bfr_i', \bfxlt)$ are private logits for $\bfR'$.
Noting that (a) $\bfphi_i = \bfphi_i'$ for $i \neq 1$ by assumption, and (b) $\bfphi_1' = \bm{0}$ under the zero-out adjacency,
we upper bound the sensitivity as
\begin{align*}
    \sens(f_{\OurClip})
    &=
    \norm{f_{\OurClip}(\bfR) - f_{\OurClip}(\bfR')}_\infty \\
    &= \norm{\frac{1}{\bsz}  \sum_{i=1}^\bsz \clip_\clipnorm\big(\bfphi_i - \bfphi_\public\big) - \frac{1}{\bsz}  \sum_{i=1}^\bsz \clip_\clipnorm\big(\bfphi_i' - \bfphi_\public\big)}_\infty\\
    &\stackrel{(a)}{=} \frac{1}{\bsz} \norm{\clip_\clipnorm\big(\bfphi_1 - \bfphi_\public\big)- \clip_\clipnorm\big(\bfphi_1' - \bfphi_\public\big)}_\infty\\
    %
    %
    &\stackrel{(b)}{\le}\frac{1}{\bsz} \norm{\clip_\clipnorm\big(\bfphi_1 - \bfphi_\public\big) -\clip_\clipnorm\big(- \bfphi_\public\big)}_\infty\\
    &\stackrel{(c)}{\le}\frac{1}{\bsz} \norm{\clip_\clipnorm\big(\bfphi_1 - \bfphi_\public\big)}_\infty + \frac{1}{\bsz} \norm{\clip_\clipnorm\big(- \bfphi_\public\big)}_\infty\\
    &\le\frac{2C}{\bsz}\,,
\end{align*}
where (c) follows from the triangle inequality on the $\ell_\infty$ norm and the last line follows because the $\ell_\infty$ norm of any logits clipped using $\clip_C(\cdot)$ is upper bounded by $C$.
\end{proof}

The $2\times$ increase in the sensitivity of $f_\OurClip$ under \textit{zero-out} adjacency causes a $4\times$ increase in the $\rho$-zCDP guarantee of \Cref{alg:main} for the same parameters and settings as under the \textit{replace-by-null} adjacency. This highlights the need for careful definition of adjacency notions in DP.


\subsection{Technical Lemmas}
We recall some technical results that are useful for other proofs.


\begin{lemma}[Adaptive Composition of zCDP~\cite{bun16concentrated}]
\label{lem:adaptive-comp-zcdp}
For any fixed sets $\calX, \calY$, let $\calA_1 : \calX^* \to \calY_1$ be $\rho_1$-zCDP, and $\calA_2: \calX^* \times \calY_1 \to \calY_2$ be $\rho_2$-zCDP mechanism with respect to its first argument for any fixed second argument. Then, we have the following adaptive composition results: 
\begin{enumerate}[label=(\alph*)]
\item \textbf{Sequential}:
\label{part:sequential}
the mechanism $\calA(D) = \big(Y_1, \calA_2(D, Y_1)\big)$ for $Y_1 = \calA_1(D)$ is $(\rho_1 + \rho_2)$-zCDP. 
\item \textbf{Parallel}: 
\label{part:parallel}
the mechanism $\calA(D) = \big(Y_1, \calA_2(D_2, Y_1)\big)$ for $Y_1 = \calA_1(D_1)$ and any fixed data-independent partition $D_1, D_2$ of $D$
%
is $\max\{\rho_1, \rho_2\}$-zCDP.
\end{enumerate}
This result can be extended to an arbitrary number of mechanisms by induction.
\end{lemma}


