\section{Bayes Error and Statistical Similarity}

\label{sec:Bayes-error}

A \emph{binary prediction problem} is a distribution ${P}$ of $X\times \{0,1\}$ where ${X}$ is a (finite) feature space.
A \emph{classifier} is a deterministic function $g : X \to \{0,1\}$.
The \emph{$0$-$1$ error of the predictor $g$} is $\Prob_{(x, y)\sim P}\csqbra{g(x) \neq y}$.

The \emph{Bayes optimal classifier} is the classifier that outputs $1$ if and only if $P(x|1) \geq P(x|0)$.
The error of Bayes optimal classifier denoted as $R^*$ is called the {\em Bayes error}.
Bayes error is the minimum error possible in the sense that the error of any classifier is at least Bayes error.
It is known that for a prediction problem $P$, its Bayes error $R^*$ is given by the following marginal expectation:
\[
R^* = \cexptq{\min(P(0|X), P(1|X))}{X}.
\]
Let the prior probabilities $P(0)$ and $P(1)$ be denoted by $\alpha_0$ and $\alpha_1$ respectively.
Note that $\alpha_0$ and $\alpha_1$ are constants that sum up to $1$.
We call $P$ \emph{balanced} if $P(0) = P(1) = 1/2$.
For simplifying notation, we will also denote the likelihood distributions $P(X|0)$ and $P(X|1)$ as $P_0$ and $P_1$ respectively.

\begin{theorem}
\label{thm:Bayes-error}
For a prediction problem $P$, its Bayes error is given by
\[
R^* = \SIM(\alpha_0 P_0, \alpha_1 P_1).
\]
In particular, for a balanced prediction problem $P$, its Bayes error is given by $R^* = {\SIM(P_0, P_1)} / {2}$.
\end{theorem}

\begin{proof}
The proof is a simple application of the Bayes theorem.
That is,
\begin{align*}
R^*
& = \cexptq{\min(P(0|X), P(1|X)}{X} \\
& = \sum_{x \in X} P(x) \cdot \min(P(0|x), P(1|x)) \\
& = \sum_{x} P(x) \cdot \min\!\left(\frac{P(x|0)P(0)}{P(x)}, \frac{P(x|1)P(1)}{P(x)}\right ) \\
& = \sum_{x} \min\cprn{{P(x|0)P(0)}, {P(x|1)P(1)}}
= \SIM(\alpha_0 P_0, \alpha_1 P_1).
\end{align*}
The balanced case follows from the fact that $\alpha_0 = \alpha_1 = \frac{1}{2}$.
\end{proof}

\section{Total Variation Distance and Statistical Similarity}

\label{sec:dtv_stv}

Statistical similarity can be proved to be equal to the complement of statistical distance, which is commonly called total variation distance (denoted by $\dtv$).
See below.

\begin{definition}
For distributions $P, Q$ over a sample space $D$, the \emph{total variation (TV) distance between $P$ and $Q$} is
\begin{align*}
\dtv(P,Q)
& := \sum_{x \in D} \max\cprn{0, P(x) - Q(x)}.
\end{align*}
\end{definition}

\begin{proposition}[Scheff\'{e}'s identity, see also \citep{tsybakov2009introduction}]
\label{prop:TV-complement-min}
Let $P, Q$ be distributions over a sample space $D$.
Then $\stv\cprn{P, Q} = 1 - \dtv\cprn{P, Q}$.
\end{proposition}

\begin{proof}
We have that
\begin{align*}
\stv\cprn{P, Q}
& = \sum_{x \in D} \min\cprn{P\cprn{x}, Q\cprn{x}} \\
& = \sum_{x \in D} \min\cprn{P\cprn{x}, P\cprn{x} + Q\cprn{x} - P\cprn{x}} \\
& = \sum_{x \in D} P\cprn{x} + \sum_{x \in D} \min\cprn{0, Q\cprn{x} - P\cprn{x}} \\
& = 1 - \sum_{x \in D} \max\cprn{0, P\cprn{x} - Q\cprn{x}}
= 1 - \dtv\cprn{P, Q}.
\qedhere
\end{align*}
\end{proof}

\section{Proof of \texorpdfstring{\Cref{clm:help}}{}}

\label{sec:help}

We have
\begin{align*}
\SIM\cprn{Y_i \cdot Z_i}
& = \cexptq{\min\cprn{Y_i \cdot Z_i, 1}}{} \\
& = \cexptq{\sum_{j = 0}^m \min\cprn{Y_i \cdot Z_i, 1} \mathbbm{1}\csqbra{Y_i \in I_j}}{} \\
& = \cexptq{\sum_{j = 1}^m \min\cprn{Y_i \cdot Z_i, 1} \mathbbm{1}\csqbra{Y_i \in I_j}}{} + \cexptq{\min\cprn{Y_i \cdot Z_i, 1} \mathbbm{1}\csqbra{Y_i \in I_0}}{} \\
& \leq \sum_{j = 1}^m \cexptq{\min\cprn{Y_i \cdot Z_i, 1} \mathbbm{1}\csqbra{Y_i \in I_j}}{}  + \gamma B\\
& \leq \sum_{j = 1}^m \cexptq{\prn{\prn{1 + \delta} \min\cprn{\widetilde{Y}_i \cdot Z_i, 1}} \mathbbm{1}\csqbra{Y_i \in I_j}}{} +\gamma B\\
& = \sum_{j = 1}^m \prn{1 + \delta} \cexptq{\min\cprn{\widetilde{Y}_i \cdot Z_i, 1} \mathbbm{1}\csqbra{{Y}_i \in I_j}}{} + \gamma B \\
& = \prn{1 + \delta} \sum_{j = 1}^m \cexptq{\min\cprn{\widetilde{Y}_i \cdot Z_i, 1} \mathbbm{1}\csqbra{{Y}_i \in I_j}}{} + \gamma B\\
& \leq \prn{1 + \delta} \sum_{j = 0}^m \cexptq{\min\cprn{\widetilde{Y}_i \cdot Z_i, 1} \mathbbm{1}\csqbra{{Y}_i \in I_j}}{} + \gamma B \\
& = \prn{1 + \delta} \cexptq{\min\cprn{\widetilde{Y}_i \cdot Z_i, 1}}{} + \gamma B
= \prn{1 + \delta} \SIM\cprn{\widetilde{Y}_i \cdot Z_i} + \gamma B,
\end{align*}
The first part of the first inequality follows from the linearity of the expectation.
For the second part, note that since $I_0= (0, \gamma]$, the maximum value $Y_i$ can take in $I_0$ is at most $\gamma$.
The maximum value of $Z_i$ is $B$, thus $\cexptq{\min\cprn{Y_i \cdot Z_i, 1} \mathbbm{1}\csqbra{Y_i \in I_0}}{} \leq \gamma B$.
For the second inequality, suppose that $Y_i \in I_j = (\gamma(1+\delta)^{j-2}, \gamma(1+\delta)^{j-1}]$.
The maximum value $Y_i$ can take is $\gamma(1+\delta)^{j-1}$ and the $\widetilde{Y}_i$ is larger than $\gamma(1+\delta)^{j-2}$.
Thus $Y_i \leq \prn{1 + \delta} \widetilde{Y}_i$.

