\section{Method}
\label{sec:method}
% We denote the input sequence as $\longsequnce = \{\token_\tokenIndex\}_{1}^{\contxtLen}.$

At test (inference) time, given a prompt consists of instruction $\question$~and long context $\llminput$, \ourmodelacronym~finetune the pretrained model with parameter $\parameter_0$ on the long context $\llminput$  and implicitly memorize the  sequence in the model parameters. To address the quadratic computation overhead and memory footprint of transformer based models, \ourmodelacronym~chunks long context $\llminput = (\token_0, \token_1,\dots,\token_L)$ into  subsequences $\{\longsequnce_0 = \token_{0:\chunklen}, \longsequnce_1=\token_{\chunklen:2\chunklen}, ... \}$, with fixed length $\chunklen$ tokens. The subsequences are randomly grouped into batches, batch $i$ denotes as $\batch_\batchi$, and fine-tuned using a next-word prediction objective function to edit model implicit knowledge.

% Knowledge editing is done  done by maximizing the probabilities of the next tokens given the subsequence \cite{qiu2024empirical}.

The pretrained model parameters are used to compute the log probability of the first batch $\sum_{{\longsequnce_\batchi \in \batch_0}} \log p(\longsequnce_\batchi|\theta_0)$.  This probability is then employed to calculate the cross-entropy loss $L(\batch_0)$ and  the corresponding gradient $\nabla L(\batch_0)$. The gradient $\nabla L(\batch_0)$ is subsequently used to update the model, resulting in the adapted parameters 
$\theta_1$. This process is repeated for the second batch, where the probability 
$p(\batch_1|\theta_1)$ is evaluated, and the  procedure is carried out iteratively for all batches (See Algorithm \ref{al:1}).

\begin{algorithm}
\caption{\ourmodelacronym~Algorithm}
\begin{algorithmic}[1]
\State \textbf{Input:} Pretrained model $\mathcal{M}$ with parameters $\parameter_0$, Context $\llminput$, Instruction $\question$, number  of TTT epochs \T.
% \State \textbf{Output:} Fine-tuned model
\State Decompose $\llminput$ into subsequences: 
$\{\longsequnce_0 = \token_{0:\chunklen}, \longsequnce_1=\token_{\chunklen:2\chunklen}, ... \}$
\For{each epoch e $\in [1\dots \T]$}
\State Randomly group subsequences  into batches,   batch $i$ denotes as $\batch_\batchi$
\For{each batch $\batch_\batchi$}
    \State $\mathcal{M}_{{\theta}_{e}}=$ Fine-tuned model $\mathcal{M}_{{\theta}_{e-1}}$ using a next-word prediction objective function on the current batch
\EndFor
\EndFor
\State Sample answer $A$ from $p_{{\theta}_\T}(.|\question)$
\State Reset to the original parameters $\parameter_0$
\State \Return $A$
\end{algorithmic}
\label{al:1}
\end{algorithm}

