\section{Preliminaries}
\label{secpreliminaries}
In this section, we will review the necessary preliminary results and notations for Boolean functions $h:\{-1,1\}^n\to\{-1,1\}$ of $n\in\mathbb N$ variables needed for the formulation and proof of this papers results.

\subsection{Boolean functions}
For any $A\subseteq\mathbb Z$ we define:
\begin{equation*}
    A_\textup{abs}\coloneqq\{\lvert a\rvert\colon a\in A\},\quad-A\coloneqq\{-a\colon a\in A\},\quad\pm A\coloneqq A\cup(-A),
\end{equation*}
and $\lvert A\rvert$ for the number of elements in $A$. For $n\in\mathbb N$ we use the notation
\begin{equation*}
    [n]\coloneqq\{ 1,2,\dots,n\}.
\end{equation*}

We let $\SAT$ denote the set of all functions $h:B\to\{-1,1\}$ with the element~$1$ contained in the range of~$h$, where $B$ is a non-empty subset of $\{-1,1\}^n$ for any~$n$, called the \emph{satisfiable} functions. If $x\in B$ is such that $h(x)=1$, then $h$ is said to be \emph{satisfied} at~$x$. The collection of such~$x$ is called the \emph{solution space} for~$h$ and is denoted
\begin{equation*}
    \mathsf{SOL}(h)\coloneqq h^{-1}(\{ 1\})=\{ x\in B\colon h(x)=1\}\subseteq\{-1,1\}^n.
\end{equation*}

If $\mathcal B$ is a set of Boolean functions of $n$ variables, then we will say that $\mathcal B$ is \emph{consistent} if it is possible to satisfy all functions in $\mathcal B$ simultaneously, i.e.\ if there exists an $x\in\{-1,1\}^n$ such that $h(x)=1$ for all $h\in\mathcal B$. If we define a new Boolean function $\min(\mathcal B):\{-1,1\}^n\to\{-1,1\}$ by
\begin{equation}
\label{literalstocnf}
    \min(\mathcal B)(x)\coloneqq\min_{h\in\mathcal B}h(x),\quad (x\in\{-1,1\}^n),
\end{equation}
then $\mathcal B$ is consistent if and only if $\min(\mathcal B)\in\SAT$.


\subsection{Literals and fixing variables}
A function $l:\{-1,1\}^n\to\{-1,1\}$ is called a \emph{literal} if, for some $v\in[n]$,
\begin{equation*}
    l(x)=x_v\text{ for all $x$},\quad\text{or}\quad l(x)=-x_v\text{ for all $x$}.
\end{equation*}
Each literal (of $n$ variables) corresponds to an element of $\pm[n]$ in the following way: the literal $x\mapsto x_v$ corresponds to~$v$ and $x\mapsto-x_v$ corresponds to~$-v$. This correspondence is bijective since taking an element $l\in\pm[n]$ to the literal $x\mapsto\sgn(l)x_{\lvert l\rvert}$ is the inverse operation. Thus, the space of literals in $n$ variables is identified with the set $\pm[n]$, and we shall use these two sets interchangeably in the following. So considering e.g.\ the number~$-5$ as a literal we have $-5(x)=-x_5$.

Notice that a literal~$l$ is satisfied at~$x$ (i.e.\ $l(x)=1$) exactly when $x_{\lvert l\rvert}=\sgn(l)$. It follows for a set of literals $\mathcal L\subseteq\pm[n]$ that, for all $x\in\{-1,1\}^n$,
\begin{equation*}
    l(x)=1\text{ for all }l\in\mathcal L\iff x_{\lvert l\rvert}=\sgn(l)\text{ for all }l\in\mathcal L,
\end{equation*}
and hence that $\mathcal L$ is consistent if and only if either $v\notin\mathcal L$ or $-v\notin\mathcal L$ for every $v\in[n]$, or equivalently if at most one of~$v$ and~$-v$ is a member of $\mathcal L$ for every $v\in[n]$. We see from this that for a consistent set of literals $\mathcal L$, satisfying $\min(\mathcal L)$ (at~$x$) amounts to fixing certain of the variables~$x_v$; more precisely fixing $x_{\lvert l\rvert}$ to~$\sgn(l)$ for every~$l\in\mathcal L$. Motivated by this we define for every consistent set of literals $\mathcal L\subseteq\pm[n]$ and every $v\in[n]$ the set
\begin{equation}
\label{Bdefn}
    B_v(\mathcal L)\coloneqq
    \begin{cases}
        \{ 1\},&\text{if $v\in\mathcal L$,} \\
        \{-1\},&\text{if $-v\in\mathcal L$,} \\
        \{-1,1\},&\text{if $v,-v\notin\mathcal L$,}
    \end{cases}
    \quad\text{and we define}\quad B(\mathcal L)\coloneqq\bigtimes_{v=1}^n B_v(\mathcal L).
\end{equation}
Then we exactly get $\mathsf{SOL}(\min(\mathcal L))=B(\mathcal L)$ by the preceding discussion (this identity will also hold for contradicting $\mathcal L$ if we extend the definition of $B_v(\mathcal L)$ to~$\emptyset$ when both $v,-v\in\mathcal L$). This again implies that for any Boolean function $h:\{-1,1\}^n\to\{-1,1\}$ it holds that
\begin{equation*}
    h\land\min(\mathcal L)\in\SAT\iff h\vert_{B(\mathcal L)}\in\SAT,
\end{equation*}
where $h\vert_{B(\mathcal L)}$ is the restriction of~$h$ to the set $B(\mathcal L)\subseteq\{-1,1\}^n$. Motivated by this, we define for any Boolean function $h:\{-1,1\}^n\to\{-1,1\}$ and any consistent set of literals $\mathcal L\subseteq\pm[n]$,
\begin{equation}
\label{fixvardefn}
    h_\mathcal L\coloneqq h\vert_{B(\mathcal L)}.
\end{equation}
Thus, $h_\mathcal L$ is the function~$h$ but with the variables dictated by $\mathcal L$ fixed. More generally we get for $\mathcal L\subseteq\pm[n]$ (not necessarily consistent) that
\begin{equation}
\label{splitoffunitclauses}
h\land\min(\mathcal L)\in\SAT\iff\min(\mathcal L)\in\SAT\quad\text{and}\quad h_\mathcal L\in\SAT.
\end{equation}

\begin{example}
    If $h:\{-1,1\}^n\to\{-1,1\}$ ($n\geq 5$ for this example) is again any Boolean function, and $\mathcal L=\{ 1,-2,4\}$, we see that $\mathcal L$ is dictating $x_1=1$, $x_2=-1$, and $x_4=1$, i.e.\
    \begin{equation*}
        B(\mathcal L)=\{ 1\}\times\{-1\}\times\{-1,1\}\times\{ 1\}\times\{-1,1\}^{n-4},
    \end{equation*}
    giving us
    \begin{equation*}
        h_\mathcal L(x)=h(1,-1,x_3,1,x_5,\dots,x_n),\quad (x\in B(\mathcal L)).
    \end{equation*}
\end{example}


\subsection{Clauses and CNF formulas}
A function $C:\{-1,1\}^n\to\{-1,1\}$ is called a \emph{(disjunctive) clause} if there exists $k\in\mathbb N$ and literals $l_1,l_2,\dots,l_k\in\pm[n]$ such that
\begin{equation*}
    C(x)=l_1(x)\lor l_2(x)\lor\dots\lor l_k(x)=\max_{i\in[k]}l_i(x),\quad (x\in\{-1,1\}^n).
\end{equation*}
The minimum such~$k$ is called the \emph{length} of~$C$, and we call~$C$ a $k$-clause. A $1$-clause is just a literal and is also called a \emph{unit clause}. Further, by convention we call the constant function $C\equiv-1$ a $0$-clause, i.e.\ a clause that is always unsatisfied, and the constant function $C\equiv 1$ a $\star$-clause, i.e.\ a clause that is always satisfied.

If \(C_1,C_2,\dots,C_m\) are clauses, then the function $\varphi:\{-1,1\}^n\to\{-1,1\}$ defined by
\begin{equation}
\label{cnfdef}
\varphi(x)=C_1(x)\land C_2(x)\land\dots\land C_m(x)=\min_{j\in[m]}C_j(x),\quad (x\in\{-1,1\}^n),
\end{equation}
is said to be a \emph{CNF formula}, and the form in~\eqref{cnfdef} is called a \emph{CNF representation} for~$\varphi$ (CNF is short for \emph{conjunctive normal form}). We allow $m=0$ which by convention gives $\varphi\equiv1$. If each of the clauses $C_1,C_2,\dots,C_m$ has length~$k$ (ignoring any $\star$-clauses), then $\varphi$ is called a $k$-CNF formula, and~\eqref{cnfdef} is called a $k$-CNF representation.

A $1$-CNF formula is just a conjunction/minimum of literals, and from any set of literals $\mathcal L$ it is of course possible to define a $1$-CNF formula~$\lambda$ by taking $\lambda=\min(\mathcal L)$ as defined in~\eqref{literalstocnf}. This operation sends all sets with contradicting literals to the same $1$-CNF formula (the constant function $x\mapsto -1$), but when restricted to the consistent sets of literals, it is one-to-one. Indeed, in this case $\mathsf{SOL}(\lambda)=B(\mathcal L)$, and $B(\mathcal L)$ determines~$\mathcal L$. Thus, for any \emph{satisfiable} $1$-CNF formula~$\lambda$ with corresponding set of literals~$\mathcal L$ (i.e.\ $\lambda=\min(\mathcal L)$) we may and do write~$h_\lambda$ instead of~$h_\mathcal L$ for any $h:\{-1,1\}^n\to\{-1,1\}$.


\subsection{Fixing variables in CNF formulas}
Consider first a $2$-CNF formula
\begin{equation*}
    \varphi=C_1\land C_2\land\dots\land C_m,
\end{equation*}
each clause given by the disjunction of two literals: $C_j=l_{j,1}\lor l_{j,2}$, where $l_{j,i}\in\pm[n]$ for all $j\in[m]$ and $i=1,2$, and consider in addition a consistent set of literals $\mathcal L\subseteq\pm[n]$. In the formula~$\varphi_\mathcal L$, each literal $l_{j,i}$ has a possibility of being fixed, and this happens exactly when $l_{j,i}\in\pm\mathcal L$. More precisely, if $l_{j,i}\in\mathcal L$, then $(l_{j,i})_\mathcal L\equiv 1$, and if $l_{j,i}\in -\mathcal L$, then $(l_{j,i})_\mathcal L\equiv-1$, and lastly if $l_{j,i}\notin\pm\mathcal L$, then $(l_{j,i})_\mathcal L=l_{j,i}$. This yields the following cases for $(C_j)_\mathcal L$ for each $j\in[m]$:
\begin{enumerate}
    \item[0.] If both literals get fixed to~$-1$, i.e.\ $l_{j,1},l_{j,2}\in-\mathcal L$, then $(C_j)_\mathcal L\equiv-1$ can never be satisfied.
    \item If one literal gets fixed to~$-1$, say $l_{j,1}\in-\mathcal L$, but the other is not fixed, i.e.\ $l_{j,2}\notin\pm\mathcal L$, then $(C_j)_\mathcal L=-1\lor l_{j,2}=l_{j,2}$, so $(C_j)_\mathcal L$ is the unit clause $l_{j,2}$. Similarly if $l_{j,2}\in-\mathcal L$ and $l_{j,1}\notin\pm\mathcal L$, then $(C_j)_\mathcal L=l_{j,1}$.
    \item If no literal gets fixed, i.e.\ both $l_{j,1},l_{j,2}\notin\pm\mathcal L$, then $(C_j)_\mathcal L=C_j$.
    \item[$\star$.] If one or both literals gets fixed to~$1$, i.e.\ $l_{j,1}\in\mathcal L$ or $l_{j,2}\in\mathcal L$, then $(C_j)_\mathcal L\equiv1$ is always satisfied.
\end{enumerate}
We see that each of the clauses $(C_j)_\mathcal L$ either becomes unsatisfiable (case~0), is transformed to a unit clause (case~1), remains intact (case~2), or is immediately satisfied (case~$\star$). Let for $k\in\{ 0,1,2,\star\}$
\begin{equation}
\label{defnmk}
    \mathcal C_k\coloneqq\{ j\in[m]\colon\text{$j$ is in case $k$}\},
\end{equation}
where we suppress the dependence on the~$l_{j,i}$'s and~$\mathcal L$ in the notation. That is, $\mathcal C_k$ consists of exactly those $j\in[m]$ where $C_j$ becomes a $k$-clause when fixing the variables dictated by~$\mathcal L$, i.e.\
\begin{equation*}
    j\in\mathcal C_k\iff\text{$(C_j)_\mathcal L$ is a $k$-clause}.
\end{equation*}
We can now split~$\varphi_\mathcal L$ into parts by defining for each $k\in\{ 0,1,2,\star\}$:
\begin{equation}
\label{defnpsik}
    \varphi_k\coloneqq\min_{j\in\mathcal C_k}(C_j)_\mathcal L,
\end{equation}
where $\min\emptyset=1$, so that $\varphi_k$ is a $k$-CNF formula, and $\varphi_\mathcal L=\varphi_0\land\varphi_1\land\varphi_2$. Using the latter and~\eqref{splitoffunitclauses}, we find that
\begin{equation}
\label{phiLsatiff}
    \varphi_\mathcal L\in\SAT\iff\lvert\mathcal C_0\rvert=0,\quad\varphi_1\in\SAT,\quad\text{and}\quad(\varphi_2)_{\varphi_1}\in\SAT.
\end{equation}
This method of ``splitting'' $\varphi_\mathcal L$ into its $0$-, $1$-, and $2$-CNF sub-formulas $\varphi_0,\varphi_1,\varphi_2$, along with the corresponding sets $\mathcal C_0,\mathcal C_1,\mathcal C_2$, will play a major role in the proof of the main theorem of this paper.

Consider now a $3$-CNF formula $\varphi=C_1\land\dots\land C_m$. By completely analogous considerations to the above, we see that each clause falls into one of of the following five cases when fixing the variables dictated by $\mathcal L$: becomes unsatisfiable (case~0), is transformed to a unit clause (case~1), is transformed to a binary clause (case~2), remains intact (case~3), or is immediately satisfied (case~$\star$). Again we may define $\mathcal C_k$ and $\varphi_k$ for $k\in\{ 0,1,2,3,\star\}$ as in~\eqref{defnmk} and~\eqref{defnpsik}, where then $\varphi_\mathcal L=\varphi_0\land\varphi_1\land\varphi_2\land\varphi_3$, and we get that
\begin{equation}
\label{phiLsatiff3}
    \varphi_\mathcal L\in\SAT\iff\lvert\mathcal C_0\rvert=0,\quad\varphi_1\in\SAT,\quad\text{and}\quad(\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT.
\end{equation}


\subsection{Random CNF formulas}
A random $k$-CNF formula $\varphi$ with $m$~clauses and $n$~variables is obtained by sampling $m$ i.i.d.\ random $k$-clauses $C_1,\dots,C_m$ and taking their conjunction:
\begin{equation*}
    \varphi\coloneqq C_1\land\dots\land C_m=\min_{j\in[m]}C_j.
\end{equation*}
Each of the $C_j$ is obtained by sampling $V_j=(V_{j,1},\dots,V_{j,k})$ uniformly at random among all sequences of $k$ \emph{pairwise distinct} variables from $[n]$, and then sampling fair random signs (i.e.\ equal to $-1$ or $1$, each with probability $1/2$) $S_j=(S_{j,1},\dots,S_{j,k})$ independently of~$V_j$. This gives random literals $L_{j,i}\coloneqq S_{j,i}V_{j,i}$ and the random $k$-clause
\begin{equation*}
    C_j\coloneqq L_{j,1}\lor\dots\lor L_{j,k}=\max_{i\in [k]}L_{j,i}.
\end{equation*}
If the lengths of the clauses $C_1,\dots,C_j$ are not all chosen to be equal, we say that $\varphi$ is a random \emph{mixed} CNF formula.


