\section{The proof}
\label{sectheproof}

\subsection{Lemmas}
In this section, we establish a few technical lemmas needed for the proof of Theorem~\ref{mainthm}. We will first show that for a random $k$-CNF formula~$\varphi$ and consistent set of literals $\mathcal L\subseteq\pm[n]$, the probability that $\varphi_\mathcal L\in\SAT$ only depends on $\mathcal L$ through $\lvert\mathcal L\rvert$, the number of variables being fixed, and in a non-increasing way.

\begin{lemma}
\label{probdecreaseinc}
    Let $\varphi$ be a random (possibly mixed) CNF formula with $m$~clauses and $n$~variables, and let $\mathcal L,\mathcal L^\prime\subseteq\pm[n]$ be two consistent sets of literals.
    \begin{enumerate}[label=(\roman*)]
        \item If $\lvert\mathcal L\rvert=\lvert\mathcal L^\prime\rvert$, then $\prob(\varphi_\mathcal L\in\SAT)=\prob(\varphi_{\mathcal L^\prime}\in\SAT)$.
        \item If $\lvert\mathcal L\rvert\geq\lvert\mathcal L^\prime\rvert$, then $\prob(\varphi_\mathcal L\in\SAT)\leq\prob(\varphi_{\mathcal L^\prime}\in\SAT)$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Let $L_{j,i}=S_{j,i}V_{j,i}$ for $j\in[m]$ and $i\in[k_j]$ be the literals defining~$\varphi$. Assume that $\lvert\mathcal L\rvert=\lvert\mathcal L^\prime\rvert$ and let $\pi:[n]\to[n]$ be a permutation such that $\pi(\mathcal L_\textup{abs})=\mathcal L^\prime_\textup{abs}$. Define $\theta,\theta^\prime:[n]\to\{-1,1\}^n$ by putting
    \begin{equation*}
        \theta(v)\coloneqq
        \begin{cases}
            -1,&\text{if $-v\in\mathcal L$,} \\
            1,&\text{otherwise},
        \end{cases}
        \quad\text{and similarly}\quad\theta^\prime(v)\coloneqq
        \begin{cases}
            -1,&\text{if $-v\in\mathcal L^\prime$,} \\
            1,&\text{otherwise}.
        \end{cases}
    \end{equation*}
    This definition is such that if $l\in\mathcal L$ then $\theta(\lvert l\rvert)=\sgn(l)$ and similarly for~$\theta^\prime$. Now define
    \begin{equation*}
        V^\prime_{j,i}\coloneqq\pi(V_{j,i}),\quad S^\prime_{j,i}\coloneqq S_{j,i}\theta(V_{j,i})\theta^\prime(V^\prime_{j,i}),\quad\text{and}\quad L^\prime_{j,i}\coloneqq S^\prime_{j,i}V^\prime_{j,i}
    \end{equation*}
    for all $j\in[m]$ and $i\in[k]$. Then by direct calculation we find that the random vectors $(L^\prime_{j,i})_{j,i}$ and $(L_{j,i})_{j,i}$ have the same distribution, so $\varphi$ and $\varphi^\prime$ have the same distribution, where $\varphi^\prime$ is the random CNF formula defined from the random literals $L^\prime_{j,i}$ for $j\in[m]$ and $i\in[k_j]$. This implies
    \begin{equation*}
        \prob(\varphi_{\mathcal L^\prime}\in\SAT)=\prob(\varphi^\prime_{\mathcal L^\prime}\in\SAT).
    \end{equation*}
    We now show that
    \begin{equation*}
        \varphi^\prime_{\mathcal L^\prime}\in\SAT\iff\varphi_\mathcal L\in\SAT.
    \end{equation*}
    This will follow from the fact that $(L_{j,i})_\mathcal L(x)=(L^\prime_{j,i})_{\mathcal L^\prime}(x^\prime)$ for all $j\in[m]$, $i\in[k]$, and $x\in\{-1,1\}^n$, where $x^\prime\in\{-1,1\}^n$ is given by $x^\prime_v=x_{\pi^{-1}(v)}$. There are two cases:
    \begin{enumerate}[label=(\arabic*)]
        \item If $V_{j,i}\notin\mathcal L_\textup{abs}$, then $V^\prime_{j,i}\notin\mathcal L^\prime_\textup{abs}$, and in this case $\theta(V_{j,i})=\theta^\prime(V^\prime_{j,i})=1$, yielding
        \begin{equation*}
            (L^\prime_{j,i})_{\mathcal L^\prime}(x^\prime)=S^\prime_{j,i}x^\prime_{V^\prime_{j,i}}=S_{j,i}x_{\pi^{-1}(V^\prime_{j,i})}=S_{j,i}x_{V_{j,i}}=(L_{j,i})_\mathcal L(x).
        \end{equation*}
        \item If $V_{j,i}\in\mathcal L_\textup{abs}$, then $V^\prime_{j,i}\in\mathcal L^\prime_\textup{abs}$, and by construction we get $B_{V_{j,i}}(\mathcal L)=\{\theta(V_{j,i})\}$ and $B_{V^\prime_{j,i}}(\mathcal L^\prime)=\{\theta^\prime(V^\prime_{j,i})\}$ (see~\eqref{Bdefn}). This yields (see~\eqref{fixvardefn})
        \begin{equation*}
            (L^\prime_{j,i})_{\mathcal L^\prime}(x^\prime)=S^\prime_{j,i}\theta^\prime(V^\prime_{j,i})=S_{j,i}\theta(V_{j,i})\theta^\prime(V^\prime_{j,i})^2=S_{j,i}\theta(V_{j,i})=(L_{j,i})_\mathcal L(x).
        \end{equation*}
    \end{enumerate}
    All together we find that
    \begin{equation*}
        \prob(\varphi_{\mathcal L^\prime}\in\SAT)=\prob(\varphi^\prime_{\mathcal L^\prime}\in\SAT)=\prob(\varphi_\mathcal L\in\SAT),
    \end{equation*}
    proving (i).

    Now for (ii), if $\lvert\mathcal L\rvert\geq\lvert\mathcal L^\prime\rvert$, we consider an injection $\iota:\mathcal L^\prime\to\mathcal L$. Then it is clear that $\varphi_\mathcal L\in\SAT$ implies $\varphi_{\iota(\mathcal L^\prime)}\in\SAT$ (since $\iota(\mathcal L^\prime)\subseteq\mathcal L$), and the result follows from (i) since $\lvert\iota(\mathcal L^\prime)\rvert=\lvert\mathcal L^\prime\rvert$.
\end{proof}

The next lemma shows that adding more clauses to~$\varphi$ only decreases the probability of satisfiability for~$\varphi_\mathcal L$.

\begin{lemma}
\label{probdecreaseinm}
    Let $\varphi$ and $\varphi^\prime$ be random (possibly mixed) CNF formulas with $m_k$ resp.\ $m_k^\prime$ $k$-clauses for each~$k$ and $n$~variables, and let $\mathcal L\subseteq\pm[n]$ be a consistent set of literals. If $m_k\geq m^\prime_k$ for each $k$, then
    \begin{equation*}
        \prob(\varphi_\mathcal L\in\SAT)\leq\prob(\varphi^\prime_\mathcal L\in\SAT),
    \end{equation*}
    and in particular $\prob(\varphi\in\SAT)\leq\prob(\varphi^\prime\in\SAT)$.
\end{lemma}
\begin{proof}
    The result follows from a straightforward coupling argument; let $C^{(k)}_j$ be independent random $k$-clauses for $j,k\in\mathbb N$ (also independent across different values of~$k$), and define
    \begin{equation*}
        \psi\coloneqq\min_{k\in\mathbb N}\min_{j\in[m_k]}C^{(k)}_j,\quad\text{and}\quad\psi^\prime\coloneqq\min_{k\in\mathbb N}\min_{j\in[m^\prime_k]}C^{(k)}_j.
    \end{equation*}
    Then $\psi$ has the same distribution as~$\varphi$ and $\psi^\prime$ has the same distribution as~$\varphi^\prime$, but it holds by construction that, for every $x\in\{-1,1\}^n$, if $\psi(x)=1$, then $\psi^\prime(x)=1$, and thus also $\psi_\mathcal L(x)=1$ implies $\psi^\prime_\mathcal L(x)=1$. This yields
    \begin{equation*}
        \prob(\varphi_\mathcal L\in\SAT)=\prob(\psi_\mathcal L\in\SAT)\leq\prob(\psi^\prime_\mathcal L\in\SAT)=\prob(\varphi^\prime_\mathcal L\in\SAT).
    \end{equation*}
    The second assertion follows by taking $\mathcal L=\emptyset$.
\end{proof}

This next lemma describes the distribution of $(\varphi_0,\varphi_1,\varphi_2)$ and $(\varphi_0,\varphi_1,\varphi_2,\varphi_3)$, the $0$-, $1$-, $2$-CNF (and $3$-CNF) subformulas of $\varphi_\mathcal L$ defined in~\eqref{defnpsik}, when $\varphi$ is a random $2$- or $3$-CNF formula.

\begin{lemma}
\label{distofphiandm}
    Let $k^\prime=2$ or $k^\prime=3$ and let $K=\{ 0,1,\dots,k^\prime,\star\}$. For $m,n\in\mathbb N$ and $n^\prime\in\mathbb N_0$ with $2\leq n^\prime<n$, let $\varphi$ be a random $k^\prime$-CNF formula with $m$ clauses and $n$ variables, and let $\mathcal L=[n]\setminus[n-n^\prime]$. Let $(\mathcal C_k)_{k\in K}$ and $(\varphi_k)_{k\in K}$ be as defined in~\eqref{defnmk} and~\eqref{defnpsik}, so in particular $\varphi_\mathcal L=\varphi_0\land\dots\land\varphi_{k^\prime}$. Let furthermore $M=(M_k)_{k\in K}$ be a partition of~$[m]$.

    Then $(\lvert\mathcal C_k\rvert)_{k\in K}\sim\mathrm{Multinomial}(m,(p_k)_{k\in K})$, and in the conditional distribution given $(\mathcal C_k)_{k\in K}=M$, it holds that the $\varphi_k$'s are independent and that $\varphi_k$ is a random $k$-CNF formula with $\lvert M_k\rvert$ clauses and $n-n^\prime$ variables for all $k\in K$.

    Furthermore, if $k^\prime=2$, then
    \begin{equation*}
        p_0=\frac{n^\prime(n^\prime-1)}{4n(n-1)},\quad p_1=\frac{n^\prime (n-n^\prime)}{n(n-1)},\quad p_2=\frac{(n-n^\prime)(n-n^\prime-1)}{n(n-1)},
    \end{equation*}
    and if $k^\prime=3$, then
    \begin{align*}
        p_0&=\frac{n^\prime(n^\prime-1)(n^\prime-2)}{8n(n-1)(n-2)},& p_1&=\frac{3n^\prime (n^\prime-1)(n-n^\prime)}{4n(n-1)(n-2)}, \\
        p_2&=\frac{3n^\prime (n-n^\prime)(n-n^\prime-1)}{2n(n-1)(n-2)},& p_3&=\frac{(n-n^\prime)(n-n^\prime-1)(n-n^\prime-2)}{n(n-1)(n-2)}.
    \end{align*}
\end{lemma}
\begin{proof}
    Assume initially that $k^\prime=2$ and let $L=(L_{j,i})_{j\in[m],i\in[2]}$ be the random literals defining~$\varphi$. Notice that $[n]\setminus\mathcal L=[n-n^\prime]$, and define the sets
    \begin{gather*}
        A_0\coloneqq-\mathcal L\times-\mathcal L,\quad A_1\coloneqq(-\mathcal L\times\pm[n-n^\prime])\cup(\pm[n-n^\prime]\times-\mathcal L), \\
        A_2\coloneqq\pm[n-n^\prime]\times\pm[n-n^\prime],\quad A_\star\coloneqq(\mathcal L\times\pm[n])\cup(\pm[n]\times\mathcal L).
    \end{gather*}
    Notice for each $k\in K$ that
    \begin{equation*}
        \mathcal C_k=\big\{\, j\in[m]\colon (L_{j,1},L_{j,2})\in A_k\,\big\},
    \end{equation*}
    where the sets $\mathcal C_k$ are those defined in~\eqref{defnmk}. Since $(A_k)_{k\in K}$ is a partition of $\pm[n]\times\pm[n]$, it is clear that $(\lvert\mathcal C_k\rvert)_{k\in K}$ follows a multinomial distribution. Now,
    \begin{equation*}
        p_k=\frac{1}{m}\mean\bigl[\lvert\mathcal C_k\rvert\bigr]=\frac{1}{m}\mean\biggl[\sum_{j=1}^m 1_{\{ (L_{j,1},L_{j,2})\in A_k\}}\biggr]=\prob\bigl((L_{1,1},L_{1,2})\in A_k\bigr).
    \end{equation*}
    From the known distribution of the random literals $(L_{1,1},L_{1,2})$, we find by direct calculations the values of $p_0,p_1,p_2$ stipulated.

    Put $\mathcal C\coloneqq(\mathcal C_k)_{k\in K}$, and let $M=(M_k)_{k\in K}$ be a partition of $[m]$. For any $l_{j,i}\in\pm[n]$, $j\in[m]$ and $i=1,2$, we immediately find by independence of the $(L_{j,1},L_{j,2})$ pairs that
    \begin{equation*}
        \prob\bigl(L=(l_{j,i})_{j\in[m],i\in[2]}\bigm\vert\mathcal C=M\bigr)=\prod_{k\in K}\prod_{j\in M_k}\prob\bigl((L_{j,1},L_{j,2})=(l_{j,1},l_{j,2})\bigm\vert (L_{j,1},L_{j,2})\in A_k\bigr),
    \end{equation*}
    so the pairs $(L_{j,1},L_{j,2})$ for $j\in[m]$ are conditionally independent given $\mathcal C=M$. We further find by direct calculation that for $j\in M_2$ and $(l_{j,1},l_{j,2})\in A_2$ with $\lvert l_{j,1}\rvert\neq\lvert l_{j,2}\rvert$,
    \begin{equation*}
        \prob\bigl((L_{j,1},L_{j,2})=(l_{j,1},l_{j,2})\bigm\vert (L_{j,1},L_{j,2})\in A_2\bigr)=\frac{1}{4n(n-1)p_2}=\frac{1}{4(n-n^\prime)(n-n^\prime-1)},
    \end{equation*}
    showing that $(L_{j,1},L_{j,2})$ is uniformly distributed over all pairs of strictly distinct literals from $\pm[n-n^\prime]$ given $\mathcal C=M$. Also, $(L_{j,1},L_{j,2})\in A_2$ is ``case 2'' described above~\eqref{defnmk}, so $(L_{j,i})_\mathcal L=L_{j,i}$ for $i=1,2$ almost surely given $\mathcal C=M$. Recalling that
    \begin{equation*}
        \varphi_k(x)=\min_{j\in\mathcal C_k}\bigl((L_{j,1})_\mathcal L(x)\lor (L_{j,2})_\mathcal L(x)\bigr),\quad (x\in\{-1,1\}^n),
    \end{equation*}
    for $k=0,1,2$, it follows that in the conditional distribution given $\mathcal C=M$, $\varphi_2$ is indeed a random $2$-CNF formula (defined from the random literals $(L_{j,i})_{j\in M_k,i\in[2]}$). An analogous argument shows that given $\mathcal C=M$, $\varphi_1$ is a random $1$-CNF formula. By independence of the $(L_{j,1},L_{j,2})$ pairs in the conditional distribution, $\varphi_0$, $\varphi_1$ and $\varphi_2$ are independent given $\mathcal C=M$.

    Completely analogous considerations establish the result for $k^\prime=3$.
\end{proof}

The final lemma in this section concerns the amount of duplicate literals in a random $1$-CNF formula. We show that there are loosely speaking very few duplicates if the number of clauses/literals is proportional to the square root of the number of variables.

\begin{lemma}
\label{fewduplicateliterals}
    Let $n_0=n_0(n)$ and $f=f(n)$ be such that $f/\sqrt{n_0}\to\beta$, where $0\leq\beta<\infty$. Consider i.i.d.\ random literals $L_1,L_2,\dots,L_f$ uniformly distributed on $\pm[n_0]$. Put $\Lambda\coloneqq\{ L_1,\dots,L_f\}$. Then
    \begin{equation*}
        \prob\bigl(\lvert\Lambda\rvert<f-w\bigr)\leq\frac{4\beta^2}{w}
    \end{equation*}
    for all $w=w(n)$ when $n$ is large enough.
\end{lemma}
\begin{proof}
    Let $V_j\coloneqq\lvert L_j\rvert$ for each $j\in[f]$, so that $\Lambda_\textup{abs}=\{ V_1,\dots,V_f\}$. Define for each $v\in[n_0]$
    \begin{equation*}
        N_v\coloneqq\bigl\lvert\bigl\{ j\in[f]\colon V_j=v\bigr\}\bigr\rvert.
    \end{equation*}
    Then $(N_1,\dots,N_{n_0})\sim\mathrm{Multinomial}(f,(1/n_0,\dots,1/n_0))$, and we see that
    \begin{equation*}
        \lvert\Lambda_\textup{abs}\rvert=f-\sum_{v\in[n_0]}(N_v-1)1_{\{ N_v\geq 2\}}.
    \end{equation*}
    We split the sum as follows:
    \begin{equation*}
        \sum_{v\in[n_0]}(N_v-1)1_{\{ N_v\geq 2\}}=\sum_{v\in[n_0]}(N_v-1)1_{\{ N_v\geq 3\}}+\sum_{v\in[n_0]}1_{\{ N_v=2\}}.
    \end{equation*}
    Cauchy-Schwarz yields
    \begin{equation*}
        \mean[(N_v-1)1_{\{ N_v\geq 3\}}]\leq\mean[N_v 1_{\{ N_v\geq 3\}}]\leq\mean[N_v^2]^{1/2}\prob(N_v\geq 3)^{1/2},
    \end{equation*}
    where
    \begin{equation*}
        \mean[N_v^2]=\frac{f(f-1)}{n_0^2}+\frac{f}{n_0}\leq\frac{f^2}{n_0^2}+\frac{f}{n_0}\leq 2\frac{f}{n_0},
    \end{equation*}
    where we in the end use that $f/n_0\to 0$ as $n\to\infty$, so $f/n_0\leq 1$ when $n$ is large enough, and thus $\mean[N_v^2]^{1/2}\leq\sqrt{2f}/\sqrt{n_0}$ when $n$ is large enough. For the second factor we notice that $N_v\geq 3$ if and only if there exists $j_1<j_2<j_3$ such that $V_{j_1}=V_{j_2}=V_{j_3}=v$, so that
    \begin{equation*}
        \prob(N_v\geq 3)=\sum_{j_1<j_2<j_3}\prob(V_{j_1}=V_{j_2}=V_{j_3}=v)=\binom{f}{3}\frac{1}{n_0^3}\leq\frac{f^3}{n_0^3},
    \end{equation*}
    since the $V_1,\dots,V_f$ are i.i.d.\ uniformly distributed on $[n_0]$. We note for later that, in particular,
    \begin{equation}
    \label{drawatmosttwo}
        \prob(N_v\geq 3\text{ for some $v\in[n_0]$})\leq\sum_{v\in[n_0]}\prob(N_v\geq 3)\leq\frac{f^3}{n_0^2}=\biggl(\frac{f}{\sqrt{n_0}}\biggr)^3\frac{1}{\sqrt{n_0}}\longrightarrow 0
    \end{equation}
    as $n\to\infty$, so that $N_v\leq 2$ for all $v\in[n_0]$ w.h.p. Together this shows that
    \begin{equation*}
        \sum_{v\in[n_0]}\mean[(N_v-1)1_{\{ N_v\geq 3\}}]\leq\sqrt{2}\frac{f^2}{n_0}=\sqrt{2}\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\longrightarrow\sqrt{2}\beta^2\quad\text{as $n\to\infty$},
    \end{equation*}
    so this sum is smaller than~$2\beta^2$ when $n$ is large enough. For the other sum we note that, as before, $N_v\geq 2$ if and only if there exists $j_1<j_2$ such that $V_{j_1}=V_{j_2}=v$, so by a similar argument,
    \begin{equation*}
        \mean\biggl[\sum_{v\in[n_0]}1_{\{ N_v=2\}}\biggr]=\sum_{v\in[n_0]}\prob(N_v\geq 2)\leq\frac{f^2}{n_0}=\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\longrightarrow\beta^2\quad\text{as $n\to\infty$}
    \end{equation*}
    so this sum is also smaller than~$2\beta^2$ when $n$ is large enough. Taken together:
    \begin{equation*}
        \mean\biggl[\sum_{v\in[n_0]}(N_v-1)1_{\{ N_v\geq 2\}}\biggr]\leq 4\beta^2
    \end{equation*}
    when $n$ is large enough, and thus by Markov's inequality:
    \begin{equation*}
        \prob\bigl(\lvert\Lambda_\textup{abs}\rvert<f-w\bigr)=\prob\biggl(\sum_{v\in[n_0]}(N_v-1)1_{\{ N_v\geq 2\}}>w\biggr)\leq\frac{4\beta^2}{w}
    \end{equation*}
    when $n$ is large enough. As $\lvert\Lambda\rvert\geq\lvert\Lambda_\textup{abs}\rvert$, we are done.
\end{proof}


\subsection{Special cases}
We need to prove two special cases of our main result, which we will need for the proof itself. Now, we will actually prove our main result in a more general form than stated in Theorem~\ref{mainthm}. Namely, we let our random $2$- or $3$-CNF formula $\varphi$ have any number of variables $n_0=n_0(n)$, as long as $n_0(n)\to\infty$ when $n\to\infty$, as opposed to $\varphi$ having exactly $n$ variables. The assumption on the number of clauses~$m$ then becomes $m/n_0\to\alpha$ and the number of variables fixed~$f$ becomes $f\sqrt{m}/n_0\to\gamma$ or $fm^{1/3}/n_0\to\gamma$ respectively. We shall for convenience also employ this small increase in generality for the results of this section (as we have already done in Lemma~\ref{fewduplicateliterals}), but it does not in any way change the proofs (it simply amounts to exchanging some $n$'s for~$n_0$'s), and for this reason we shall abuse notation by writing $n\coloneqq n_0$.

The characterization of the random $1$-SAT problem~\eqref{1satproblem} is the first special case which shall actually play an important role in the proof of Theorem~\ref{mainthm}.

\begin{lemma}[The random $1$-SAT problem]
\label{random1sat}
    For $0\leq\beta\leq\infty$, let $\lambda$ be a random $1$-CNF formula with $f=f(n)$ clauses and $n_0=n_0(n)$ variables, where $n_0\to\infty$ and $f/\sqrt{n_0}\to\beta$. Then
    \begin{equation*}
        \lim_{n\to\infty}\prob(\lambda\in\SAT)=e^{-(\beta/2)^2}.
    \end{equation*}
\end{lemma}
\begin{proof}
    Assume initially that $\beta<\infty$. We abuse notation by writing $n\coloneqq n_0$. Let the random literals corresponding to $\lambda$ be $L_1,L_2,\dots,L_f$, where $S_j=\sgn(L_j)$ and $V_j=\lvert L_j\rvert$. For each $v\in[n]$ we put
    \begin{equation*}
        N_v\coloneqq\bigl\lvert\bigl\{ j\in[f]\colon V_j=v\bigr\}\bigr\rvert.
    \end{equation*}
    Then $N\coloneqq (N_1,\dots,N_n)\sim\mathrm{Multinomial}(f,(1/n,\dots,1/n))$. From~\eqref{drawatmosttwo} we have that $N_v\leq 2$ for all $v\in[n]$ w.h.p., so when writing
    \begin{equation*}
        \prob(\lambda\in\SAT)=\prob(\lambda\in\SAT,N_v\geq 3\text{ for some $v\in[n]$})+\prob(\lambda\in\SAT,N_v\leq 2\text{ for all $v\in[n]$}),
    \end{equation*}
    we see that the first term vanishes as $n\to\infty$, and in regards to the second term we have:
    \begin{equation*}
        \{ N_v\leq 2\text{ for all $v\in[n]$}\}=\bigcup_{\substack{\eta\in\{0,1,2\}^n\colon \\ \eta_1+\dots+\eta_n=f}}\{ N=\eta\}=\bigcup_{k=0}^{\lfloor f/2\rfloor}\bigcup_{\eta\in H_k}\{ N=\eta\},
    \end{equation*}
    where 
    \begin{equation*}
        H_k\coloneqq\bigl\{\,\eta\in\{0,1,2\}^n\colon\eta_1+\dots+\eta_n=f,\lvert\{ v\in[n]\colon\eta_v=2\}\rvert=k\,\bigr\},
    \end{equation*} 
    i.e.\ we have divided the union into sub-unions depending on how many entries of $\eta$ are equal to~$2$, so that $\eta\in H_k$ when there are $k$ entries of $\eta$ equal to~$2$. Since the events on the right-hand side are disjoint, we may write
    \begin{equation}
    \label{probphisatunit}
        \prob(\lambda\in\SAT,N_v\leq 2\text{ for all $v\in[n]$})=\sum_{k=0}^{\lfloor f/2\rfloor}\sum_{\eta\in H_k}\prob(\lambda\in\SAT,N=\eta).
    \end{equation}
    Notice that $\lvert H_k\rvert=\binom{n-k}{f-2k}\binom{n}{k}$, corresponding to firstly choosing $k$ entries of $\eta$ to equal~$2$ and then choosing $f-2k$ of the remaining $n-k$ entries to equal~$1$ (the remaining entries will equal~$0$).

    Now, for fixed $k\in\{ 0,1,\dots,\lfloor f/2\rfloor\}$ and $\eta\in H_k$ we find by definition of $N$ that $N=\eta$ if and only if $(V_1,\dots,V_f)=\underline v$ for some $\underline v\in[n]^f$ satisfying $\lvert\{ j\in[f]\colon\underline v_j=v\}\rvert=\eta_v$ for all $v\in[n]$. Hence,
    \begin{equation}
    \label{decompphisatx}
        \prob(\lambda\in\SAT,N=\eta)=\sum_{\substack{\underline v\in[n]^f\colon \\ \lvert\{ j\in[f]\colon\underline v_j=v\}\rvert=\eta_v \\ \text{for all $v\in[n]$}}}\prob(\lambda\in\SAT,V=\underline v),
    \end{equation}
    where $V\coloneqq (V_1,\dots,V_f)$. Notice now that $\lambda\in\SAT$ if and only if there are no contradictions in the literals $L_1,\dots,L_f$, i.e.\ we don't have $L_{j_1}=-L_{j_2}$ for any $j_1<j_2$, which is to say that $\lambda\in\SAT$ if and only if $V_{j_1}=V_{j_2}$ implies $S_{j_1}=S_{j_2}$. But since $V$ and $S\coloneqq (S_1,\dots,S_f)$ are independent, we find that:
    \begin{equation*}
        \prob(\lambda\in\SAT,V=\underline v)=\prob(\text{$S_{j_1}=S_{j_2}$ for all $j_1<j_2$ with $\underline v_{j_1}=\underline v_{j_2}$})\prob(V=\underline v)=\frac{1}{2^k}\prob(V=\underline v),
    \end{equation*}
    since there are exactly $k$ pairs $(j_1,j_2)$ satisfying $j_1<j_2$ and $\underline v_{j_1}=\underline v_{j_2}$ by choice of~$\eta$. Inserting this into~\eqref{decompphisatx} and using the known distribution of~$N$ together with the fact that exactly $k$ entries of $\eta$ are~$2$ and the rest are $1$ or~$0$, we get:
    \begin{equation*}
        \prob(\lambda\in\SAT,N=\eta)=\frac{1}{2^k}\prob(N=\eta)=\frac{f!}{4^k n^f},
    \end{equation*}
    and inserting this further into~\eqref{probphisatunit} yields:
    \begin{align}
        \MoveEqLeft\prob(\lambda\in\SAT,N_v\leq 2\text{ for all $v\in[n]$})=\sum_{k=0}^{\lfloor f/2\rfloor}\binom{n-k}{f-2k}\binom{n}{k}\frac{f!}{4^k n^f}\label{needforlater1sat} \\
        &=\sum_{k=0}^\infty\biggl(\prod_{d=0}^{2k-1}\frac{f-d}{\sqrt{n}}\biggr)\biggl(\prod_{d=0}^{f-k-1}\frac{n-d}{n}\biggr)\frac{1}{4^k k!}1_{[0,\lfloor f/2\rfloor]}(k),\label{finalsum1sat}
    \end{align}
    where we in the second equality simply have rearranged the factors in each term. For fixed~$k$ we see that
    \begin{equation*}
        \lim_{n\to\infty}\prod_{d=0}^{2k-1}\frac{f-d}{\sqrt{n}}=\prod_{d=0}^{2k-1}\lim_{n\to\infty}\biggl(\frac{f}{\sqrt{n}}-\frac{d}{\sqrt{n}}\biggr)=\beta^{2k},
    \end{equation*}
    and also for large enough~$n$ (independent of $k$) we have $f/\sqrt{n}\leq\beta+1$, so:
    \begin{equation}
    \label{boundfirstprod}
        \prod_{d=0}^{2k-1}\frac{f-d}{\sqrt{n}}\leq (\beta+1)^{2k}.
    \end{equation}
    In regards to the other product we use that $\log(1+t)/t\to 1$ as $t\to 0$, so that for any $0<\epsilon<1$ we have $(1-\epsilon)t\leq\log(1+t)\leq(1+\epsilon)t$ whenever $t$ is close enough to $0$. This yields
    \begin{equation*}
        (1-\epsilon)\sum_{d=0}^{f-k-1}\frac{-d}{n}\leq\sum_{d=0}^{f-k-1}\log\bigl(1-\tfrac{d}{n}\bigr)\leq(1+\epsilon)\sum_{d=0}^{f-k-1}\frac{-d}{n}
    \end{equation*}
    whenever $n$ is large enough, and since
    \begin{equation*}
        \sum_{d=0}^{f-k-1}\frac{-d}{n}=\frac{-1}{2}\cdot\frac{f-k-1}{\sqrt{n}}\cdot\frac{f-k}{\sqrt{n}}\longrightarrow\frac{-\beta^2}{2}\quad\text{as $n\to\infty$},
    \end{equation*}
    we get by taking $\epsilon\to 0$ that
    \begin{equation*}
        \lim_{n\to\infty}\prod_{d=0}^{f-k-1}\frac{n-d}{n}=\lim_{n\to\infty}\exp\biggl[\sum_{d=0}^{f-k-1}\log\bigl(1-\tfrac{d}{n}\bigr)\biggr]=e^{-\tfrac{1}{2}\beta^2}.
    \end{equation*}
    Of course, we also have for all $n\in\mathbb N$
    \begin{equation}
    \label{boundsecondprod}
        \prod_{d=0}^{f-k-1}\frac{n-d}{n}\leq 1
    \end{equation}
    Thus, by~\eqref{boundfirstprod} and~\eqref{boundsecondprod}, the $k$'th term in~\eqref{finalsum1sat} is bounded by $(\beta+1)^{2k}/(4^k k!)$ when $n$ is large enough (independent of $k$), so by appealing to dominated convergence we get
    \begin{equation*}
        \lim_{n\to\infty}\prob(\lambda\in\SAT)=e^{-\tfrac{1}{2}\beta^2}\sum_{k=0}^\infty\frac{\beta^{2k}}{4^k k!}=e^{-\tfrac{1}{4}\beta^2},
    \end{equation*}
    as claimed.

    Now, if $\beta=\infty$, we consider for an arbitrary $T>0$ a $1$-CNF formula $\psi$ with $\lfloor T\sqrt{n}\rfloor$ clauses and $n$ variables. Since $f/\sqrt{n}\to\infty$ as $n\to\infty$, we have for large enough~$n$ that $f\geq\lfloor T\sqrt{n}\rfloor$, so for such large~$n$ we also have by Lemma~\ref{probdecreaseinm}
    \begin{equation*}
        \prob(\lambda\in\SAT)\leq\prob(\psi\in\SAT),
    \end{equation*}
    and $\prob(\psi\in\SAT)\to e^{-(T/2)^2}$ as $n\to\infty$ by what we have proved thus far. Taking then $T\to\infty$ yields
    \begin{equation*}
        \lim_{n\to\infty}\prob(\lambda\in\SAT)=0
    \end{equation*}
    as desired.
\end{proof}

The second special case which we need to prove separately is the subcritical case $\beta=0$ in Theorem~\ref{mainthm} case $k=2$. To prove this, we employ a new variation of the classical ``snakes and snares'' proof of the sharp satisfiability threshold in the random $2$-SAT problem. In this variation, we show that a $2$-CNF formula that has its satisfiability spoiled by fixing some amount of variables must contain a ``cobra'', which we define shortly. We then show that the mean number of cobras in a random $2$-CNF formula vanishes if we fix asymptotically fewer variables than the square root of the total number of variables, i.e.\ if $\beta=0$.

Let $m,n,N\in\mathbb N$ and $\mathcal L\subseteq\pm[n]$ be a set of literals. Then an \emph{$\mathcal L$-cobra} (of size $N$) is a sequence $l_0,l_1,\dots,l_N\in\pm[n]$ of literals such that
\begin{enumerate}[label=(c\arabic*)]
    \item\label{c1} The variables $\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{N-1}\rvert$ are pairwise distinct,
    \item\label{c2} $\lvert l_0\rvert\in\mathcal L_\textup{abs}$,
    \item\label{c3} $\lvert l_N\rvert\in\mathcal L_\textup{abs}\cup\{\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{N-1}\rvert\}$.
\end{enumerate}

Let $\varphi$ be a (non-random) $2$-CNF formula with $n$ variables and $m$ clauses of the form $\ell_{j,1}\lor\ell_{j,2}$, $j\in[m]$. We say that $\varphi$ \emph{contains} the sequence $(l_0,l_1,\dots,l_N)$ if there for all $t\in[N]$ exists some $j\in[m]$ such that $\{-l_{t-1},l_t\}=\{\ell_{j,1},\ell_{j,2}\}$.

\begin{lemma}
\label{alphaisnull}
    For $0\leq\alpha<1$, let $\varphi$ be a random $2$-CNF formula with $m=m(n)$ clauses and $n_0=n_0(n)$ variables, where $n_0\to\infty$ and $m/n_0\to\alpha$, and let $\mathcal L\subseteq\pm[n_0]$ be a consistent set of literals with $\lvert\mathcal L\rvert=f=f(n)$, where $f/\sqrt{n_0}\to 0$ as $n\to\infty$. Then it holds that
    \begin{equation*}
        \lim_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)=1.
    \end{equation*}
\end{lemma}
\begin{proof}
    As before we abuse notation by suppressing the dependence on $n$, and we then abbreviate $n$ for $n_0$.

    Let $(L_{j,i})_{j\in[m],i\in[2]}$ denote the random literals defining $\varphi$, and let $C_1,C_2,\dots,C_m$ denote the random clauses of $\varphi$, i.e.\ $C_j=L_{j,1}\lor L_{j,2}$, and let $\mathcal C^{(1)}_k$ denote the set defined in~\eqref{defnmk} for each $k\in\{ 0,1,2,\star\}$. Define the corresponding random CNF formulas (cf.~\eqref{defnpsik})
    \begin{equation*}
        \lambda^{(1)}\coloneqq\min_{j\in\mathcal C^{(1)}_1}(C_j)_\mathcal L,\quad\text{and}\quad\varphi^{(1)}\coloneqq\min_{j\in\mathcal C^{(1)}_2}(C_j)_\mathcal L=\min_{j\in\mathcal C^{(1)}_2}C_j.
    \end{equation*}
    Define also $\Lambda_1\coloneqq\bigl\{ (C_j)_\mathcal L\colon j\in\mathcal C^{(1)}_1\bigr\}$, the set of random literals in $\lambda^{(1)}$, i.e.\ $\lambda^{(1)}=\min(\Lambda_1)$. Then by~\eqref{phiLsatiff},
    \begin{equation*}
        \varphi_\mathcal L\in\SAT\iff\lvert\mathcal C^{(1)}_0\rvert=0,\quad\lambda^{(1)}\in\SAT,\quad\text{and}\quad\varphi^{(1)}_{\Lambda_1}\in\SAT.
    \end{equation*}
    We now repeat this with $\varphi^{(1)}_{\Lambda_1}$ in place of $\varphi_\mathcal L$, giving us for each $r\in\mathbb N$ sets $\mathcal C^{(r)}_k$ for $k\in\{ 0,1,2,\star\}$ stemming from $\varphi^{(r-1)}_{\Lambda_{r-1}}$, and random CNF formulas
    \begin{equation*}
        \lambda^{(r)}\coloneqq\min_{j\in\mathcal C^{(r)}_1}(C_j)_{\Lambda_{r-1}},\quad\text{and}\quad\varphi^{(r)}\coloneqq\min_{j\in\mathcal C^{(r)}_2}(C_j)_{\Lambda_{r-1}}=\min_{j\in\mathcal C^{(r)}_2}C_j,
    \end{equation*}
    and we finally also define $\Lambda_r\coloneqq\bigl\{ (C_j)_{\Lambda_{r-1}}\colon j\in\mathcal C^{(r)}_1\bigr\}$ so that $\lambda^{(r)}=\min(\Lambda_r)$. We here take $\varphi^{(0)}\coloneqq\varphi$ and $\Lambda^{(0)}\coloneqq\mathcal L$. Now, notice that
    \begin{equation*}
        \mathcal C^{(r)}_2=\bigcup_{k\in\{ 0,1,2,\star\}}\mathcal C^{(r+1)}_k
    \end{equation*}
    for each $r\in\mathbb N$, and of course the sets $\mathcal C^{(r)}_0,\mathcal C^{(r)}_1,\mathcal C^{(r)}_2,\mathcal C^{(r)}_\star$ are pairwise disjoint. In particular, $\mathcal C^{(1)}_2,\mathcal C^{(2)}_2,\mathcal C^{(3)}_2,\dots$ is a decreasing sequence of finite sets, and thus it must at some point become constant, i.e.\ there exists an $R\in\mathbb N$ such that $\mathcal C^{(r)}_2=\mathcal C^{(r+1)}_2$ for all $r\geq R$ (this happens precisely the first time $\mathcal C^{(r)}_1=\emptyset$, but this is irrelevant). In particular we get for $r\geq R$ that $\varphi^{(r)}=\varphi^{(r+1)}$ and $\mathcal C^{(r+1)}_k=\emptyset$ for $k\in\{ 0,1,\star\}$, and thus also $\Lambda_{r+1}=\emptyset$. We are thus able to define
    \begin{equation*}
        \varphi^{(\infty)}(x)\coloneqq\lim_{r\to\infty}\varphi^{(r)}(x)=\min\Bigl\{ C_j(x)\colon j\in\bigcap_{r\in\mathbb N}\mathcal C^{(r)}_2\Bigr\},\quad (x\in\{-1,1\}^n),
    \end{equation*}
    which we immediately see has the property $\varphi^{(\infty)}(x)\geq\varphi(x)$ for all $x$, so $\varphi\in\SAT$ implies $\varphi^{(\infty)}\in\SAT$. Further, we see that when $r>R$,
    \begin{equation*}
        \varphi^{(r)}_{\Lambda_r}=\varphi^{(\infty)}_\emptyset=\varphi^{(\infty)},
    \end{equation*}
    so using~\eqref{phiLsatiff} iteratively on $\varphi^{(r)}_{\Lambda_r}$ for each $r\in\mathbb N$ yields
    \begin{equation*}
        \varphi_\mathcal L\in\SAT\iff\text{$\lvert\mathcal C^{(r)}_0\rvert=0$ and $\lambda^{(r)}\in\SAT$ for all $r\in\mathbb N$},\quad\text{and}\quad\varphi^{(\infty)}\in\SAT.
    \end{equation*}
    Now define the event
    \begin{equation*}
        F\coloneqq\bigcup_{r\in\mathbb N}\Bigl(\bigl\{\lvert\mathcal C^{(r)}_0\rvert>0\bigr\}\cup\bigl\{\lambda^{(r)}\notin\SAT\bigr\}\Bigr),
    \end{equation*}
    so that, by the above,
    \begin{equation}
    \label{checkpointsubcrit}
        \prob(\varphi_\mathcal L\in\SAT)=\prob\bigl(F^c\cap\{\varphi^{(\infty)}\in\SAT\}\bigr).
    \end{equation}
    Since $\varphi$ is satisfiable w.h.p.~\cite{CR92,goerdt96}, so is~$\varphi^{(\infty)}$, and it thus only remains to prove that $F^c$ also occurs w.h.p., which is the same as proving that $\prob(F)\to 0$ as $n\to\infty$.

    We first prove that, if $F$ occurs, then $\varphi$ contains an $\mathcal L$-cobra. We introduce the ``flipping'' map $\rho:[2]\to[2]$ given by
    \begin{equation*}
        \rho(i)=3-i=
        \begin{cases}
            2,&\text{if $i=1$,} \\
            1,&\text{if $i=2$,}
        \end{cases}
        \quad (i\in[2]),
    \end{equation*}
    so that for any $j\in[m]$ and $i\in[2]$ we have $C_j=L_{j,i}\lor L_{j,\rho(i)}$. Assume then that $F$ occurs, meaning there exists an $r\in\mathbb N$ such that $\lvert\mathcal C^{(r)}_0\rvert>0$ or $\lambda^{(r)}\notin\SAT$. Let $N^\prime$ be the smallest such $r$.

    Assume first that $\lambda^{(N^\prime)}\notin\SAT$. This means that there exists two clauses $C_j$ and $C_{j^\prime}$, which at ``timepoint'' $N^\prime-1$ are still $2$-clauses, but when fixing the variables dictated by $\Lambda^{(N^\prime-1)}$, they each become $1$-clauses that contradict each other. That is to say, there exists $j(1),j^\prime(1)\in[m]$ and $i(1),i^\prime(1)\in[2]$ such that
    \begin{equation}
    \label{recurvbegin}
        L_{j(1),i(1)}=-L_{j^\prime(1),i^\prime(1)},\quad\text{and}\quad -L_{j(1),\rho(i(1))},-L_{j^\prime(1),\rho(i^\prime(1))}\in\Lambda^{(N^\prime-1)}.
    \end{equation}
    Now, $-L_{j(1),\rho(i(1))}$ being an element in $\Lambda^{(N^\prime-1)}$ means that there exists $j(2)\in[m]$ and $i(2)\in[2]$ such that
    \begin{equation*}
        -L_{j(1),\rho(i(1))}=L_{j(2),i(2)},\quad\text{and}\quad -L_{j(2),\rho(i(2))}\in\Lambda^{(N^\prime-2)}.
    \end{equation*}
    We continue this recursively, giving sequences $j(1),j(2),\dots,j(N^\prime)\in[m]$ and $i(1),i(2),\dots,i(N^\prime)\in[2]$ such that
    \begin{equation}
    \label{recurvL}
        -L_{j(t),\rho(i(t))}=L_{j(t+1),i(t+1)},\quad\text{and}\quad -L_{j(t+1),\rho(i(t+1))}\in\Lambda^{(N^\prime-(t+1))}
    \end{equation}
    for all $t\in[N^\prime-1]$. In the same way we also get sequences $j^\prime(1),j^\prime(2),\dots,j^\prime(N^\prime)\in[m]$ and $i^\prime(1),i^\prime(2),\dots,i^\prime(N^\prime)\in[2]$ such that
    \begin{equation}
    \label{recurvLprime}
        -L_{j^\prime(t),\rho(i^\prime(t))}=L_{j^\prime(t+1),i^\prime(t+1)},\quad\text{and}\quad -L_{j^\prime(t+1),\rho(i^\prime(t+1))}\in\Lambda^{(N^\prime-(t+1))}
    \end{equation}
    for all $t\in[N^\prime-1]$. We now define for each $t\in\{ 0,1,\dots,N^\prime-1\}$:
    \begin{equation*}
        l_t\coloneqq -L_{j(N^\prime-t),\rho(i(N^\prime-t))}.
    \end{equation*}
    Then $l_0=-L_{j(N^\prime),\rho(i(N^\prime))}\in\Lambda^{(0)}=\mathcal L$ by~\eqref{recurvL}, so condition~\ref{c2} in the definition of an $\mathcal L$-cobra is satisfied. Now define further for $t\in\{ 0,1,\dots,N^\prime-1\}$:
    \begin{equation*}
        l_{N^\prime+t}\coloneqq -L_{j^\prime(t+1),i^\prime(t+1)}.
    \end{equation*}
    We now verify that the sequence $(l_0,l_1,\dots,l_{2N^\prime-1})$ is ``contained'' in $\varphi$ in the sense defined above the formulation of Lemma~\ref{alphaisnull}. For $t\in[N^\prime-1]$ we have
    \begin{align*}
        (-l_{t-1},l_t)&=\bigl(L_{j(N^\prime-t+1),\rho(i(N^\prime-t+1))},-L_{j(N^\prime-t),\rho(i(N^\prime-t))}\bigr) \\
        &=\bigl(L_{j(N^\prime-t+1),\rho(i(N^\prime-t+1))},L_{j(N^\prime-t+1),i(N^\prime-t+1)}\bigr),
    \end{align*}
    using~\eqref{recurvL} in the second equality, as desired. From~\eqref{recurvbegin} we get
    \begin{equation*}
        (-l_{N^\prime-1},l_{N^\prime})=\bigl(L_{j(1),\rho(i(1))},-L_{j^\prime(1),i^\prime(1)}\bigr)=\bigl(L_{j(1),\rho(i(1))},L_{j(1),i(1)}\bigr),
    \end{equation*}
    and lastly for $t\in[N^\prime-1]$:
    \begin{align*}
        (-l_{N^\prime+t-1},l_{N^\prime+t})&=\bigl(L_{j^\prime(t),i^\prime(t)},-L_{j^\prime(t+1),i^\prime(t+1)}\bigr) \\
        &=\bigl(L_{j^\prime(t),i^\prime(t)},L_{j^\prime(t),\rho(i^\prime(t))}\bigr),
    \end{align*}
    using this time~\eqref{recurvLprime}. Hence, $(l_0,l_1,\dots,l_{2N^\prime-1})$ is contained in~$\varphi$. Now, if there exists a $t\in[2N^\prime-1]$ such that $\lvert l_t\rvert\in\{\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{t-1}\rvert\}$, then let $N$ be the smallest such~$t$. Then $(l_0,l_1,\dots,l_N)$ is clearly an $\mathcal L$-cobra contained in~$\varphi$ as desired. If not, then the variables $\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{2N^\prime-1}\rvert$ are pairwise distinct, and we take $N\coloneqq 2N^\prime$ and define finally
    \begin{equation*}
        l_N\coloneqq L_{j^\prime(N^\prime),\rho(i^\prime(N^\prime))}.
    \end{equation*}
    It follows immediately from~\eqref{recurvLprime} that $-l_N\in\Lambda^{(0)}=\mathcal L$, so of course $\lvert l_N\rvert\in\mathcal L_\textup{abs}$, and the sequence $(l_0,l_1,\dots,l_N)$ is thus an $\mathcal L$-cobra. It is also contained in~$\varphi$ since
    \begin{equation*}
        (-l_{N-1},l_N)=\bigl(L_{j^\prime(N^\prime),i^\prime(N^\prime)},L_{j^\prime(N^\prime),\rho(i^\prime(N^\prime))}\bigr).
    \end{equation*}
    This concludes the case where $\lambda^{(N^\prime)}\notin\SAT$.

    Assume now instead that $\lvert\mathcal C^{(N^\prime)}_0\rvert>0$. That is, there exists an element in $\mathcal C^{(N^\prime)}_0$, meaning that there exists a clause~$C_j$ that at ``timepoint'' $N^\prime-1$ is still a $2$-clause, but when fixing the variables dictated by $\Lambda^{(N^\prime-1)}$, it becomes a $0$-clause. More precisely, there exists a $j\in[m]$ such that
    \begin{equation*}
        -L_{j,1},-L_{j,2}\in\Lambda^{(N^\prime-1)}.
    \end{equation*}
    Taking $j(1)\coloneqq j^\prime(1)\coloneqq j$ and $i(1)\coloneqq 1$, $i^\prime(1)\coloneqq 2$, this is the second statement in~\eqref{recurvbegin}, so again we can find $j(2),j^\prime(2),\dots,j(N^\prime),j^\prime(N^\prime)\in[m]$ and $i(2),i^\prime(2),\dots,i(N^\prime),i^\prime(N^\prime)\in[2]$ such that~\eqref{recurvL} and~\eqref{recurvLprime} hold. We then define for $t\in\{ 0,1,\dots,N^\prime-1\}$:
    \begin{equation*}
        l_t\coloneqq -L_{j(N^\prime-t),\rho(i(N^\prime-t))},\quad\text{and}\quad l_{N^\prime+t}\coloneqq L_{j^\prime(t+1),\rho(i^\prime(t+1))},
    \end{equation*}
    where we see that the first of the two definitions coincides with what we had in the case $\lambda^{(N^\prime)}\notin\SAT$, so we need only verify that
    \begin{equation*}
        (-l_{N^\prime-1},l_{N^\prime})=\bigl(L_{j(1),\rho(i(1))},L_{j^\prime(1),\rho(i^\prime(1))}\bigr)=(L_{j,2},L_{j,1}),
    \end{equation*}
    and, using~\eqref{recurvLprime},
    \begin{align*}
        (-l_{N^\prime+t-1},l_{N^\prime+t})&=\bigl(-L_{j^\prime(t),\rho(i^\prime(t))},L_{j^\prime(t+1),\rho(i^\prime(t+1))}\bigr) \\
        &=\bigl(L_{j^\prime(t+1),i^\prime(t+1)},L_{j^\prime(t+1),\rho(i^\prime(t+1))}\bigr),
    \end{align*}
    for all $t\in[N^\prime-1]$, so that $(l_0,l_1,\dots,l_{2N^\prime-1})$ is indeed contained in~$\varphi$. As before we also have $\lvert l_0\rvert\in\mathcal L_\textup{abs}$, so if there exists a $t\in[2N^\prime-1]$ such that $\lvert l_t\rvert\in\{\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{t-1}\rvert\}$, then we take $N$ to be the smallest such~$t$, and $(l_0,l_1,\dots,l_N)$ is an $\mathcal L$-cobra contained in~$\varphi$. If there does not exist such a~$t$, then $(l_0,l_1,\dots,l_{2N^\prime-1})$ is does the trick; indeed, we are only missing a verification of~\ref{c3}, but
    \begin{equation*}
        -l_{2N^\prime-1}=-L_{j^\prime(N^\prime),\rho(i^\prime(N^\prime))}\in\Lambda^{(0)}=\mathcal L
    \end{equation*}
    by~\eqref{recurvLprime}, so indeed $\lvert l_{2N^\prime-1}\rvert\in\mathcal L_\textup{abs}$ as required.

    Now let $\mathfrak C_N$ denote the set of $\mathcal L$-cobras of size~$N$ for each $N\in\mathbb N$, and put
    \begin{equation*}
        Z\coloneqq\sum_{N\in\mathbb N}\sum_{l\in\mathfrak C_N}1_{\{\varphi\text{ contains }l\}},
    \end{equation*}
    i.e.\ $Z$ is the number of $\mathcal L$-cobras contained in~$\varphi$. We have just shown that $F\subseteq\{ Z>0\}$, so if we can only show that $\mean[Z]\to 0$ as $n\to\infty$, then the first moment method (Markov's inequality) asserts that
    \begin{equation*}
        \prob(F)\leq\prob(Z>0)\leq\mean[Z]\longrightarrow 0\quad\text{as $n\to\infty$},
    \end{equation*}
    thus finishing the proof of Lemma~\ref{alphaisnull}. To calculate the large $n$ limit of $\mean[Z]$, we first give an upper bound on $\lvert\mathfrak C_N\rvert$, i.e.\ the number of $\mathcal L$-cobras of size~$N$. Since $\mathcal L$ is consistent, $\lvert\mathcal L_\textup{abs}\rvert=\lvert\mathcal L\rvert=f$, and so there are $f$ possible choices for~$\lvert l_0\rvert$ by~\ref{c2}, and taking the sign into consideration gives $2f$ possible choices for~$l_0$. Then each of $l_1,l_2,\dots,l_{N-1}$ can be chosen freely as long as $\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{N-1}\rvert$ are pairwise distinct by~\ref{c1}, so choosing them one after the other gives $2(n-t)$ choices for~$l_t$, where $t\in[N-1]$. Finally, $\lvert l_N\rvert$ must be chosen from $\mathcal L_\textup{abs}\cup\{\lvert l_0\rvert,\lvert l_1\rvert,\dots,\lvert l_{N-1}\rvert\}$ by~\ref{c3}, so this gives at the most $2(f+N)$ possible choices for~$l_N$. All in all, we have
    \begin{equation}
    \label{sizeofCN}
        \lvert\mathfrak C_N\rvert\leq 2^{N+1}f(n-1)(n-2)\dots (n-(N-1))(f+N)\leq 2^{N+1}n^{N-1}f(f+N).
    \end{equation}
    Now, given some $l\in\mathfrak C_N$, what is the probability that $\varphi$ contains~$l$? Notice that the sets
    \begin{equation*}
        \{-l_0,l_1\},\{-l_1,l_2\},\dots,\{-l_{N-1},l_N\}
    \end{equation*}
    are pairwise different by property~\ref{c1}, and again by~\ref{c1}, each of the sets contain exactly two elements (literals), \emph{except} for possibly the last set $\{-l_{N-1},l_N\}$, where we might have $-l_{N-1}=l_N$. For any $l,l^\prime\in\pm[n]$ and $j\in[m]$ we have
    \begin{equation*}
        \prob\bigl(\{ L_{j,1},L_{j,2}\}=\{ l,l^\prime\}\bigr)=
        \begin{cases}
            2/(2n)^2=1/(2n^2),&\text{if $l\neq l^\prime$,} \\
            1/(2n)^2=1/(4n^2),&\text{if $l=l^\prime$,}
        \end{cases}
    \end{equation*}
    but in all cases $\prob\bigl(\{ L_{j,1},L_{j,2}\}=\{ l,l^\prime\}\bigr)\leq 1/(2n^2)$. Next we note that, for pairwise different $j_1,j_2,\dots,j_N\in[m]$,
    \begin{equation*}
        \prob\bigl(\{ L_{j_t,1},L_{j_t,2}\}=\{-l_{t-1},l_t\}\text{ for all $t\in[N]$}\bigr)=\prod_{t\in[N]}\prob\bigl(\{ L_{j_t,1},L_{j_t,2}\}=\{-l_{t-1},l_t\}\bigr)\leq\frac{1}{(2n^2)^N},
    \end{equation*}
    and since there are $\binom{m}{N}$ choices for $j_1,j_2,\dots,j_N$ and $N!$ ways to arrange these, we get the following bound for the probability that $\varphi$ contains~$l$:
    \begin{equation}
    \label{proboflinphi}
        \prob(\text{$\varphi$ contains $l$})\leq\binom{m}{N}\frac{N!}{2^Nn^{2N}}.
    \end{equation}
    Putting~\eqref{sizeofCN} and~\eqref{proboflinphi} together yields
    \begin{equation*}
        \mean[Z]=\sum_{N\in\mathbb N}\sum_{l\in\mathfrak C_N}\prob(\text{$\varphi$ contains $l$})\leq\sum_{N\in\mathbb N}\frac{m!2f(f+N)}{(m-N)!n^{N+1}}\leq\frac{f}{\sqrt{n}}\sum_{N\in\mathbb N}2\bigg(\frac{m}{n}\bigg)^N\frac{f+N}{\sqrt{n}}.
    \end{equation*}
    We now choose $\epsilon>0$ small enough that $\alpha+\epsilon<1$, and since $m/n\to\alpha$ as $n\to\infty$, we get for large enough $n$ that $m/n\leq\alpha+\epsilon$. On the other hand, $f/\sqrt{n}\to 0$ as $n\to\infty$, so for $n$ large enough we have $f/\sqrt{n}\leq 1\leq N$ for all $N\in\mathbb N$, so
    \begin{equation*}
        \sum_{N\in\mathbb N}2\bigg(\frac{m}{n}\bigg)^N\frac{f+N}{\sqrt{n}}\leq\sum_{N\in\mathbb N}4(\alpha+\epsilon)^N N\eqqcolon\kappa<\infty,
    \end{equation*}
    where the first inequality holds when $n$ is large enough, and $\kappa$ is a fixed number which does not depend on~$n$, and thus
    \begin{equation*}
        \mean[Z]\leq\frac{f}{\sqrt{n}}\kappa\longrightarrow 0\quad\text{as $n\to\infty$},
    \end{equation*}
    which was the final thing missing.
\end{proof}

We now have all necessary results in place and are thus equipped to prove Theorem~\ref{mainthm}. We prove initially the case $k=2$ when $\alpha>0$, which is the most difficult part of the theorem. We proceed by showing that the claimed limit is both an asymptotic upper- and lower bound on the quantity under consideration.

\subsection{Lower bound}
We now begin our proof of Theorem~\ref{mainthm} in the case $k=2$ when $\alpha>0$. Just as with the special cases, we will prove the result in a slightly more general form, where $\varphi$ is a random $2$-CNF formula with $m=m(n)$ clauses and $n_0=n_0(n)$ variables, where $n_0\to\infty$ and $m/n_0\to\alpha$, $0<\alpha<1$. Also, $\mathcal L\subseteq\pm[n_0]$ has $\lvert\mathcal L\rvert=f=f(n)$, where $f/\sqrt{n_0}\to\beta$, $0\leq\beta\leq\infty$. The goal is to compute $\lim_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)$. In this section we give a proof of the lower bound
\begin{equation*}
    \liminf_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\geq\exp\biggl(\frac{-\beta^2\alpha}{4(1-\alpha)}\biggr).
\end{equation*}

In the case that $\beta=\infty$, the lower bound $\liminf_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\geq 0$ is trivial, so assume without loss of generality that $\beta<\infty$. The case $\beta=0$ is Lemma~\ref{alphaisnull}, so assume also that $\beta>0$. We will prove that
\begin{equation*}
    \liminf_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\geq\exp\biggl(\frac{-\beta^2(1+\epsilon)\alpha}{4[1-(1+\epsilon)\alpha]}\biggr)
\end{equation*}
for all $\epsilon>0$ small enough so that $(1+\epsilon)\alpha<1$. Taking $\epsilon\to 0$ will then yield the correct lower bound. Thus, let $\epsilon>0$ be such that $(1+\epsilon)\alpha<1$, and define for convenience $\alpha_\epsilon\coloneqq (1+\epsilon)\alpha$.

Let $C_1,\dots,C_m$ be the random $2$-clauses defining~$\varphi$. By Lemma~\ref{probdecreaseinc} we may assume without loss of generality that $\mathcal L=[n_0]\setminus[n_0-f]$. Let as before $K\coloneqq\{ 0,1,2,\star\}$, and let for each $k\in K$ $\mathcal C^{(1)}_k$ denote the set $\mathcal C_k$ from~\eqref{defnmk}, i.e.\ $\mathcal C^{(1)}_k$ is the set of $j\in[m]$ for which the $j$'th clause of $\varphi$ has become a $k$-clause (a $\star$-clause meaning a satisfied clause) when fixing the variables dictated by $\mathcal L$. Put $\mathcal C\coloneqq (\mathcal C^{(1)}_k)_{k\in K}$. Let further $\varphi_1$ and $\varphi_2$ be the random functions defined in~\eqref{defnpsik}, i.e.\
\begin{equation*}
    \varphi_k\coloneqq\min_{j\in\mathcal C^{(1)}_k}(C_j)_\mathcal L,\quad (k=1,2).
\end{equation*}
Define finally
\begin{equation*}
    n_1\coloneqq n_0-f,\quad f_1\coloneqq\bigl\lfloor\alpha_\epsilon f+\alpha_\epsilon n_0^{3/8}\bigr\rfloor,\quad\mathcal L_1\coloneqq [n_1]\setminus[n_1-f_1],
\end{equation*}
(and note that all of $n_1$, $f_1$, and $\mathcal L_1$ depend on $n$), and let $\lambda^{(1)}$ denote a random $1$-CNF formula with $f_1$ clauses and $n_1$ variables, and let $\varphi^{(1)}$ denote a random $2$-CNF formula with $m$ clauses and $n_1$ variables. The exponent $3/8$ in the definition of $f_1$ could be any number strictly between $1/4$ and $1/2$, as the proof will show.

With all this in place, we get from~\eqref{phiLsatiff} that
\begin{align*}
    \prob(\varphi_\mathcal L\in\SAT)&=\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    &\geq\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\leq f_1,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    &=\sum_{M\in\mathfrak M}\prob\bigr(\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)\prob(\mathcal C=M),
\end{align*}
where $\mathfrak M$ is the set of partitions $(M_k)_{k\in K}$ of $[m]$ such that $\lvert M_0\rvert=0$ and $\lvert M_1\rvert\leq f_1$. For any $M\in\mathfrak M$ we now consider for $k=1,2$ an auxiliary random $k$-CNF formula $\psi_k$ with $\lvert M_k\rvert$ clauses and $n_1$ variables, such that $\psi_1$ and $\psi_2$ are independent. Then by Lemma~\ref{distofphiandm} the distribution of $(\psi_1,\psi_2)$ (under~$\prob$) is the same as that of $(\varphi_1,\varphi_2)$ in the conditional distribution given $\mathcal C=M$. Hence, letting $\mathcal B$ denote the set of all satisfiable $1$-CNF formulas with $\lvert M_1\rvert$ clauses and $n_1$ variables, we get
\begin{equation}
\label{transfermethod}
\begin{aligned}
    \prob\bigl(\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)&=\prob\bigl(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT\bigr) \\
    &=\sum_{h\in\mathcal B}\prob\bigl(\psi_1=h,\, (\psi_2)_h\in\SAT\bigr) \\
    &=\sum_{h\in\mathcal B}\prob(\psi_1=h)\prob\bigl((\psi_2)_h\in\SAT\bigr) \\
    &\geq\prob\bigl(\psi_1\in\SAT\bigr)\prob\bigl((\psi_2)_{\mathcal L_1}\in\SAT\bigr) \\
    &\geq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr),
\end{aligned}
\end{equation}
where we in the first inequality have used Lemma~\ref{probdecreaseinc}(ii) (since $\lvert\mathcal L_1\rvert=f_1\geq\lvert M_1\rvert$), and in the final inequality used Lemma~\ref{probdecreaseinm} with the fact that $\lambda^{(1)}$ has more clauses than~$\psi_1$ and $\varphi^{(1)}$ has more clauses than~$\psi_2$. Using this, we get
\begin{align*}
    \MoveEqLeft[2.5]\smash{\sum_{M\in\mathfrak M}}\prob\bigl(\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)\prob(\mathcal C=M) \\
    &\geq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\leq f_1\bigr) \\
    &=\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0\bigr)\prob\bigl(\lvert\mathcal C^{(1)}_1\rvert\leq f_1\bigm\vert\lvert\mathcal C^{(1)}_0\rvert=0\bigr),
\end{align*}
where the final factor should read: the probability that $\lvert\mathcal C^{(1)}_1\rvert\leq f_1$ given $\lvert\mathcal C^{(1)}_0\rvert=0$. All together we conclude that
\begin{equation}
\label{lowerbdfirst}
    \prob(\varphi_\mathcal L\in\SAT)\geq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0\bigr)\prob\bigl(\lvert\mathcal C^{(1)}_1\rvert\leq f_1\bigm\vert\lvert\mathcal C^{(1)}_0\rvert=0\bigr).
\end{equation}

Notice now that we are in the same situation with $\varphi^{(1)}_{\mathcal L_1}$ as we were with~$\varphi_\mathcal L$, so we can repeat the above procedure. Put
\begin{equation*}
    R\coloneqq\bigl\lfloor c\log(n_0)\bigr\rfloor,\quad\text{where}\quad c\coloneqq\frac{1}{16\log(1/\alpha_\epsilon)}>0.
\end{equation*}
and define for all $r\in\mathbb N$ (where we take $f_0\coloneqq f$):
\begin{equation*}
    n_r\coloneqq n_{r-1}-f_{r-1}=n_0-\sum_{k=0}^{r-1}f_k,\quad f_r\coloneqq\bigl\lfloor\alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}\bigr\rfloor,\quad\mathcal L_r\coloneqq[n_r]\setminus[n_r-f_r],
\end{equation*}
and let $\mathcal C^{(r)}_k$ denote the set $\mathcal C_k$ from~\eqref{defnmk} with $\varphi^{(r-1)}$ in place of~$\varphi$ and $\mathcal L_{r-1}$ in place of~$\mathcal L$ for each $k\in K$, and denote finally by $\lambda^{(r)}$ a random $1$-CNF formula with $f_r$ clauses and $n_r$ variables, and by $\varphi^{(r)}$ a random $2$-CNF formula with $m$ clauses and $n_r$ variables. Redoing the argument above, we get for each $r\in\mathbb N$ the following:
\begin{equation*}
    \prob\bigl(\varphi^{(r-1)}_{\mathcal L_{r-1}}\in\SAT\bigr)\geq\prob\bigl(\lambda^{(r)}\in\SAT\bigr)\prob\bigl(\varphi^{(r)}_{\mathcal L_r}\in\SAT\bigr)\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert\leq f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr),
\end{equation*}
and by successively applying this inequality $R$ times we obtain:
\begin{equation}
\begin{aligned}
    \prob(\varphi_\mathcal L\in\SAT)\geq{}&\prob\bigl(\varphi^{(R)}_{\mathcal L_R}\in\SAT\bigr)\prod_{r=1}^R\prob\bigl(\lambda^{(r)}\in\SAT\bigr) \\
    &\times\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert\leq f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr).
\end{aligned}
\label{maindecomp}
\end{equation}
Hence, the stipulated asymptotic lower bound will follow if we establish the following points:
\begin{enumerate}[label=(L\arabic*)]
    \item\label{L1} $\lim_{n\to\infty}\prob\bigl(\varphi^{(R)}_{\mathcal L_R}\in\SAT\bigr)=1$,
    \item\label{L2} $\lim_{n\to\infty}\prod_{r=1}^R\prob\bigl(\lambda^{(r)}\in\SAT\bigr)=\exp\biggl(\frac{-\beta^2}{4}\sum_{r=1}^\infty\alpha_\epsilon^{2r}\biggr)$,
    \item\label{L3} $\lim_{n\to\infty}\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)\geq\exp\biggl(\frac{-\beta^2}{4}\sum_{r=1}^\infty\alpha_\epsilon^{2r-1}\biggr)$,
    \item\label{L4} $\lim_{n\to\infty}\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert\leq f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=1$.
\end{enumerate}
It will be useful to note that, according to Lemma~\ref{distofphiandm}, it holds for each $n,r\in\mathbb N$ that
\begin{equation}
\label{distofmr}
    \bigl(\lvert\mathcal C^{(r)}_0\rvert,\lvert\mathcal C^{(r)}_1\rvert,\lvert\mathcal C^{(r)}_2\rvert,\lvert\mathcal C^{(r)}_\star\rvert\bigr)\sim\mathrm{Multinomial}\bigl(m,(p^{(r)}_0,p^{(r)}_1,p^{(r)}_2,p^{(r)}_\star)\bigr),
\end{equation}
where
\begin{equation*}
    p^{(r)}_0=\frac{f_{r-1}(f_{r-1}-1)}{4n_{r-1}(n_{r-1}-1)},\quad p^{(r)}_1\coloneqq\frac{f_{r-1}n_r}{n_{r-1}(n_{r-1}-1)},\quad p^{(r)}_2\coloneqq\frac{n_r(n_r-1)}{n_{r-1}(n_{r-1}-1)},
\end{equation*}
and lastly $p^{(r)}_\star=1-p^{(r)}_0-p^{(r)}_1-p^{(r)}_2$. It will further be useful to note that, for any fixed $r\in\mathbb N$,
\begin{equation}
\label{computelimfr}
    \lim_{n\to\infty}\frac{f_r}{\sqrt{n_0}}=\alpha_\epsilon^r\beta.
\end{equation}
Putting then $S\coloneqq\sup_{n\in\mathbb N}(n_0^{3/8}/f)<\infty$, we get the upper bound
\begin{equation}
\label{boundfr}
    f_r\leq\alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}\leq\alpha_\epsilon^r f+Sr\alpha_\epsilon^r f=(1+Sr)\alpha_\epsilon^r f
\end{equation}
for all $r\in\mathbb N$. This yields further the following bound:
\begin{equation}
\label{boundsumfk}
    \sum_{k=0}^\infty f_k\leq\biggl[\sum_{k=0}^\infty\alpha_\epsilon^k+S\sum_{k=0}^\infty k\alpha_\epsilon^k\biggr]f=Cf,
\end{equation}
where $C=(1+(S-1)\alpha_\epsilon)/(1-\alpha_\epsilon)^2<\infty$. We get from the definition of $n_r$ and~\eqref{boundsumfk} that
\begin{equation}
\label{boundur}
    n_0-Cf\leq n_r\leq n_0
\end{equation}
for all $r\in\mathbb N$ and $n\in\mathbb N$, yielding in particular (noticing that also $R$ depends on~$n$)
\begin{equation}
\label{computelimuranduR}
    \lim_{n\to\infty}\frac{n_r}{n_0}=1,\quad\text{and}\quad\lim_{n\to\infty}\frac{n_R}{n_0}=1.
\end{equation}
Since $c\log(n_0)\leq R+1$, $\alpha_\epsilon<1$ and $c=1/(16\log(1/\alpha_\epsilon))$, we get the following bounds on~$\alpha_\epsilon^R$:
\begin{equation}
\label{betapowerR}
    \frac{1}{n_0^{1/16}}=\alpha_\epsilon^{c\log(n_0)}\leq\alpha_\epsilon^R\leq\alpha_\epsilon^{c\log(n_0)-1}=\frac{1}{\alpha_\epsilon n_0^{1/16}}.
\end{equation}
Using the lower bound, we find for $r\in[R]$ that $r\alpha_\epsilon^r n_0^{3/8}\geq\alpha_\epsilon^R n_0^{3/8}\geq n_0^{5/16}\geq 1$, so
\begin{equation}
\label{lowerboundfr}
    f_r=\bigl\lfloor\alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}\bigr\rfloor\geq\alpha_\epsilon^r f\geq\alpha_\epsilon^R f\geq\frac{f}{n_0^{1/16}}
\end{equation}
for all $r\in[R]$ and $n\in\mathbb N$.

Using now the upper bound on $\alpha_\epsilon^{R(n)}$ from~\eqref{betapowerR}, we conclude using initially~\eqref{boundfr} that
\begin{equation*}
    f_R\leq (1+SR)\alpha_\epsilon^R f\leq\frac{1+Sc\log(n_0)}{n_0^{1/16}}\cdot\frac{f}{\alpha_\epsilon},
\end{equation*}
so that $f_R/\sqrt{n_0}\to 0$. Hence, since $\lvert\mathcal L_R\rvert=f_R$ and since $\varphi^{(R)}$ is a random $2$-CNF formula with $m$ clauses and $n_R$ variables, where we have seen that $n_R/n_0\to 1$, we see that~\ref{L1} follows from Lemma~\ref{alphaisnull}.

We now establish~\ref{L2}. Since $\lambda^{(r)}$ is a random $1$-CNF formula with $f_r$ clauses and $n_r$ variables for every $r\in\mathbb N$, Lemma~\ref{random1sat} together with~\eqref{computelimfr} and~\eqref{computelimuranduR} shows that
\begin{equation*}
    \lim_{n\to\infty}\prob\bigl(\lambda^{(r)}\in\SAT\bigr)=e^{-\tfrac{1}{4}\beta^2\alpha_\epsilon^{2r}}.
\end{equation*}
Taking the logarithm, we want to conclude that
\begin{equation*}
    \lim_{n\to\infty}\sum_{r=1}^\infty\log\prob\bigl(\lambda^{(r)}\in\SAT\bigr)1_{[R]}(r)=-\frac{1}{4}\beta^2\sum_{r=1}^\infty\alpha_\epsilon^{2r},
\end{equation*}
which we will do by arguing that dominated convergence applies. This requires a uniform (over large enough~$n$) summable (in~$r$) lower bound on $\log\prob(\lambda^{(r)}\in\SAT)$. It follows from~\eqref{needforlater1sat} in the proof of Lemma~\ref{random1sat} that
\begin{equation*}
    \prob\bigl(\lambda^{(r)}\in\SAT\bigr)\geq\sum_{k=0}^{\lfloor f_r/2\rfloor}\binom{n_r-k}{f_r-2k}\binom{n_r}{k}\frac{f_r!}{4^k n_r^{f_r}}\geq\binom{n_r}{f_r}\frac{f_r!}{n_r^{f_r}}=\prod_{d=0}^{f_r-1}\frac{n_r-d}{n_r},
\end{equation*}
where we in the second inequality simply remove all but the first term. Now, from the classical inequality $\log(t)\leq t-1$ for all $t>0$, we multiply by~$-1$ and evaluate at $t=1/(1-s)$, yielding
\begin{equation}
\label{canonlogbound}
    \log(1-s)\geq\frac{s}{s-1}\quad\text{for all $s<1$}.
\end{equation}
Using this and our inequalities above, we get
\begin{equation*}
    \log\prob\bigl(\lambda^{(r)}\in\SAT\bigr)\geq\sum_{d=0}^{f_r-1}\log\bigl(1-\tfrac{d}{n_r}\bigr)\geq\sum_{d=0}^{f_r-1}\frac{d}{d-n_r}\geq\frac{1}{f_r-n_r}\sum_{d=0}^{f_r-1}d=\frac{(f_r-1)f_r}{2(f_r-n_r)}\geq\frac{-f_r^2}{2n_{r+1}},
\end{equation*}
where we have used $n_r-f_r=n_{r+1}$. From here we apply~\eqref{boundfr} and~\eqref{boundur} to get
\begin{equation*}
    \frac{f_r^2}{2n_{r+1}}\leq (1+Sr)^2\alpha_\epsilon^{2r}\frac{f^2}{2(n_0-Cf)}.
\end{equation*}
Now, since
\begin{equation*}
    \frac{f^2}{2(n_0-Cf)}=\frac{1}{2}\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\biggl(\frac{n_0}{n_0-Cf}\biggr)\longrightarrow\frac{\beta^2}{2}
\end{equation*}
as $n\to\infty$, we conclude that, when $n$ is large enough, it holds for all $r\in\mathbb N$ that
\begin{equation*}
    \log\prob\bigl(\lambda^{(r)}\in\SAT\bigr)\geq-\beta^2(1+Sr)^2\alpha_\epsilon^{2r},
\end{equation*}
and of course $(1+Sr)^2\alpha_\epsilon^r\to 0$ as $r\to\infty$, so $S^\prime\coloneqq\sup_{r\in\mathbb N}(1+Sr)^2\alpha_\epsilon^r<\infty$, thus
\begin{equation}
\label{lowerboundsummable}
    \sum_{r=1}^\infty (1+Sr)^2\alpha_\epsilon^{2r}\leq S^\prime\sum_{r=1}^\infty\alpha_\epsilon^r=S^\prime\frac{\alpha_\epsilon}{1-\alpha_\epsilon}<\infty,
\end{equation}
as required.

We now establish~\ref{L3}. From~\eqref{distofmr} it follows that $\lvert\mathcal C^{(r)}_0\rvert\sim\mathrm{Binomial}(m,p^{(r)}_0)$ for all $r\in\mathbb N$. Writing
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=\bigl(1-p^{(r)}_0\bigr)^m=\biggl(\biggl(1-\biggl(\frac{f_{r-1}(f_{r-1}-1)}{n_0}\biggr)\biggl(\frac{n_0^2}{n_{r-1}(n_{r-1}-1)}\bigg)\frac{1}{4n_0}\biggr)^{n_0}\biggr)^{m/n_0},
\end{equation*}
we find, using \eqref{computelimfr}, \eqref{computelimuranduR}, and $m/n_0\to\alpha$, that $\prob(\lvert\mathcal C^{(r)}_0\rvert=0)\to e^{-\tfrac{1}{4}\beta^2\alpha_\epsilon^{2(r-1)}\alpha}$ as $n\to\infty$. Taking the logarithm, we want to conclude that
\begin{equation*}
    \lim_{n\to\infty}\sum_{r=1}^\infty\log\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)1_{[R]}(r)=-\frac{1}{4}\beta^2\alpha\sum_{r=1}^\infty\alpha_\epsilon^{2(r-1)}\geq -\frac{1}{4}\beta^2\sum_{r=1}^\infty\alpha_\epsilon^{2r-1},
\end{equation*}
where the inequality follows from $\alpha\leq (1+\epsilon)\alpha=\alpha_\epsilon$, and the equality will again follow from an application of dominated convergence, once we give a uniform (over large enough~$n$) summable (in~$r$) lower bound on the terms $\log\prob(\lvert\mathcal C^{(r)}_0\rvert=0)$. Notice first of all that, using~\eqref{boundsumfk} and~\eqref{boundur},
\begin{equation*}
    p^{(r)}_0\leq\frac{C^2}{4}\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\biggl(\frac{n_0}{n_0-Cf-1}\biggr)^2\frac{1}{n_0}\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
where the convergence is uniform in~$r$ (since the upper bound does not depend on~$r$). Thus, when $n$ is large enough, $p^{(r)}_0\leq 1/2$ for all $r\in\mathbb N$. Next, using now~\eqref{boundfr} and~\eqref{boundur}, we find that
\begin{equation*}
    mp^{(r)}_0\leq\frac{(1+Sr)^2\alpha_\epsilon^{2r}}{4}\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\biggl(\frac{n_0}{n_0-Cf-1}\biggr)^2\frac{m}{n_0},
\end{equation*}
where of course
\begin{equation*}
    \lim_{n\to\infty}\biggl(\frac{f}{\sqrt{n_0}}\biggr)^2\biggl(\frac{n_0}{n_0-Cf-1}\biggr)^2\frac{m}{n_0}=\beta^2\alpha\leq\beta^2\alpha_\epsilon,
\end{equation*}
so it follows that when $n$ is large enough, it holds for all $r\in\mathbb N$ that
\begin{equation}
\label{boundmpr0}
    mp^{(r)}_0\leq\tfrac{1}{2}\beta^2(1+Sr)^2\alpha_\epsilon^{2r-1}.
\end{equation}
Thus, when $n$ is large enough to satisfy both~\eqref{boundmpr0} and $p^{(r)}_0\leq\tfrac{1}{2}$ for all $r\in\mathbb N$, we get by using~\eqref{canonlogbound} that
\begin{equation*}
    \log\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=m\log\bigl(1-p^{(r)}_0\bigr)\geq\frac{mp^{(r)}_0}{p^{(r)}_0-1}\geq -\beta^2(1+Sr)^2\alpha_\epsilon^{2r-1}
\end{equation*}
holds for all $r\in\mathbb N$, where we used $p^{(r)}_0\leq\tfrac{1}{2}$ in the denominator and~\eqref{boundmpr0} in the numerator, and~\eqref{lowerboundsummable} shows that this lower bound is summable, proving~\ref{L3}.

We now establish~\ref{L4}. Here we will not be able to apply dominated convergence, and it is for this reason that we stop the ``splitting'' process in~\eqref{maindecomp} after $R$ steps/rounds. If we were able to establish~\ref{L4} with (symbolically) $R=\infty$, then we could have completely bypassed a verification of~\ref{L1} and thus the need for Lemma~\ref{alphaisnull}. But alas, we proceed without the comfort of dominated convergence and with the need for a verification of~\ref{L1} and Lemma~\ref{alphaisnull}. Also, points~\ref{L1} through~\ref{L3} could all have been verified with $\alpha$ in place of~$\alpha_\epsilon$, and it is only for this point~\ref{L4} that we need the ``$\epsilon$-breathing room'' that $\alpha_\epsilon$ provides us over a more direct calculation using~$\alpha$. Finally, it is at this point that we need the exponent~$3/8$ in the definition of~$f_r$ to be greater than~$1/4$, and actually the precise definition of~$f_r$ comes into play, where only the first order asymptotics of~$f_r$ mattered for the other points. Thus, point~\ref{L4} is by far the most delicate out of the four.

First of all, if we define
\begin{equation*}
    \xi\coloneqq\max_{r\in [R]}\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert>f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr),
\end{equation*}
then taking the logarithm gives
\begin{align*}
    \sum_{r=1}^R\log\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert\leq f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr)&\geq R\min_{r\in [R]}\log\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert\leq f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr) \\
    &=R\log(1-\xi)\geq R\frac{\xi}{\xi-1}\geq\frac{c\log(n_0)\xi}{\xi-1},
\end{align*}
where we in the second to last inequality use~\eqref{canonlogbound}. Hence, if we can show that $\log(n_0)\xi\to 0$ as $n\to\infty$, then certainly $\xi\to 0$ as well, and thus
\begin{equation*}
    \lim_{n\to\infty}\frac{c\log(n_0)\xi}{\xi-1}=0,
\end{equation*}
from which~\ref{L4} follows. Now, from~\eqref{distofmr} we get from known results that in the conditional distribution given $\lvert\mathcal C^{(r)}_0\rvert=0$, $\lvert\mathcal C^{(r)}_1\rvert$ follows a Binomial distribution with parameters~$m$ and
\begin{equation*}
    p^{(r)}_{1\mid 0}\coloneqq\frac{p^{(r)}_1}{1-p^{(r)}_0}=\frac{f_{r-1}n_r}{n_{r-1}(n_{r-1}-1)-\tfrac{1}{4}f_{r-1}(f_{r-1}-1)}.
\end{equation*}
Now consider for a moment the expression
\begin{equation}
\label{neededforL4}
    \frac{mn_r}{n_{r-1}(n_{r-1}-1)-\tfrac{1}{4}f_{r-1}(f_{r-1}-1)}\leq\frac{mn_0}{(n_0-Cf-1)^2-\tfrac{1}{4}(Cf)^2}\longrightarrow\alpha\quad\text{as $n\to\infty$},
\end{equation}
where we have used~\eqref{boundsumfk} and~\eqref{boundur}, and the convergence is uniform in~$r$. Letting then $N^{(r)}\sim\mathrm{Binomial}(m,p^{(r)}_{1\mid 0})$ under~$\prob$, we see that
\begin{equation}
\label{meanNrupperbound}
    \mean[N^{(r)}]=mp^{(r)}_{1\mid 0}=f_{r-1}\frac{mn_r}{n_{r-1}(n_{r-1}-1)-\tfrac{1}{4}f_{r-1}(f_{r-1}-1)}\leq (1+\epsilon)\alpha f_{r-1}=\alpha_\epsilon f_{r-1},
\end{equation}
where the last inequality holds for large enough~$n$ independent of~$r$ thanks to~\eqref{neededforL4}. Furthermore, since $f_{r-1}=\lfloor\alpha_\epsilon^{r-1}f+(r-1)\alpha_\epsilon^{r-1}n_0^{3/8}\rfloor$, we get
\begin{equation*}
    \alpha_\epsilon f_{r-1}\leq\alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}-\alpha_\epsilon^r n_0^{3/8},
\end{equation*}
giving all together
\begin{equation}
\label{meannrbound}
    \alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}\geq\mean[N^{(r)}]+\alpha_\epsilon^r n_0^{3/8},
\end{equation}
uniformly in~$r$ for large enough~$n$. Now,
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_1\rvert>f_r\bigm\vert\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=\prob\bigl(N^{(r)}>f_r\bigr),
\end{equation*}
and since $N^{(r)}$ takes only integer values, rounding down makes no difference, i.e.\
\begin{equation*}
    \prob\bigl(N^{(r)}>f_r\bigr)=\prob\bigl(N^{(r)}>\alpha_\epsilon^r f+r\alpha_\epsilon^r n_0^{3/8}\bigr)\leq\prob\bigl(N^{(r)}>\mean[N^{(r)}]+\alpha_\epsilon^r n_0^{3/8}\bigr),
\end{equation*}
where we in the inequality have used~\eqref{meannrbound}, so it holds uniformly in~$r$ for large enough~$n$. We will now apply Chernoff's bound:
\begin{equation}
\label{chernoff}
    \prob\bigl(N>\mean[N]+\delta\mean[N]\bigr)\leq e^{-\tfrac{1}{3}\delta^2\mean[N]},
\end{equation}
when $N$ is binomially distributed and $0<\delta<1$. Taking in our case $N=N^{(r)}$ and
\begin{equation*}
    \delta=\frac{\alpha_\epsilon^r n_0^{3/8}}{\mean[N^{(r)}]},
\end{equation*}
we find that, as long as $r\in[R]$, \eqref{boundur} and~\eqref{lowerboundfr} give us
\begin{equation*}
    \mean[N^{(r)}]=f_{r-1}\frac{mn_r}{n_{r-1}(n_{r-1}-1)-\tfrac{1}{4}f_{r-1}(f_{r-1}-1)}\geq\frac{f}{n_0^{1/16}}\cdot\frac{m(n_0-Cf)}{n_0^2},
\end{equation*}
so using~\eqref{betapowerR} in addition to the above we get for all $r\in[R]$:
\begin{equation*}
    \delta=\frac{\alpha_\epsilon^r n_0^{3/8}}{\mean[N^{(r)}]}\leq\frac{1}{n_0^{1/16}}\cdot\frac{\sqrt{n_0}}{f}\cdot\frac{n_0}{m}\cdot\frac{n_0}{n_0-Cf}\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
so naturally $\delta<1$ for all $r\in [R]$ for large enough~$n$. Hence, Chernoff's bound yields
\begin{equation*}
    \prob\bigl(N^{(r)}>\mean[N^{(r)}]+\alpha_\epsilon^r n_0^{3/8}\bigr)\leq\exp\biggl(\frac{-\alpha_\epsilon^{2r}n_0^{3/4}}{3\mean[N^{(r)}]}\biggr)
\end{equation*}
for all $r\in[R]$ when $n$ is large enough. We saw in~\eqref{meanNrupperbound} that $\mean[N^{(r)}]\leq f_{r-1}$ for all $r\in\mathbb N$ when $n$ is large enough, and $f_{r-1}\leq Cf$ for all $r,n\in\mathbb N$ by~\eqref{boundsumfk}. On the other hand, $\alpha_\epsilon^{2r}\geq\alpha_\epsilon^{2R}\geq n_0^{-1/8}$ for all $r\in[R]$ and $n\in\mathbb N$ by~\eqref{betapowerR}, so taken all together we get when $n$ is large enough:
\begin{equation*}
    \xi=\max_{r\in[R]}\prob\bigl(N^{(r)}>f_r\bigr)\leq\max_{r\in[R]}\exp\biggl(\frac{-\alpha_\epsilon^{2r}n_0^{3/4}}{3\mean[N^{(r)}]}\biggr)\leq\exp\biggl(\frac{-n_0^{5/8}}{3Cf}\biggr),
\end{equation*}
and of course $n_0^{5/8}/(3Cf)$ is asymptotic to $n_0^{1/8}/(3C\beta)$ as $n\to\infty$, readily yielding $\log(n_0)\xi\to 0$, completing the proof of~\ref{L4} and thus the entire proof of the lower bound.

\subsection{Upper bound}
We now give a proof of the upper bound
\begin{equation*}
    \limsup_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\leq\exp\biggl(\frac{-\beta^2\alpha}{4(1-\alpha)}\biggr).
\end{equation*}
Taken together with the lower bound, this will complete the proof of the case $k=2$ in Theorem~\ref{mainthm} when $\alpha>0$. We are still assuming that $\varphi$ is a random $2$-CNF formula with $m=m(n)$ clauses and $n_0=n_0(n)$ variables, where $n_0\to\infty$ and $m/n_0\to\alpha$, and that $\lvert\mathcal L\rvert=f=f(n)$, where $f/\sqrt{n_0}\to\beta$. A priori we have $0<\alpha<1$ and $0\leq\beta\leq\infty$, but the case $\beta=0$ is trivial, so we assume without loss of generality that $\beta>0$. We will also assume that $\beta<\infty$, since the case $\beta=\infty$ follows. Indeed, let for a given $T>0$ $\psi$ denote a random $2$-CNF formula with $n_0$ variables and $\lfloor T\sqrt{n_0}\rfloor$ clauses. Then $f\geq\lfloor T\sqrt{n_0}\rfloor$ for large enough~$n$ if $\beta=\infty$, so by Lemma~\ref{probdecreaseinm} we get
\begin{equation*}
    \limsup_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\leq\limsup_{n\to\infty}\prob(\psi_\mathcal L\in\SAT)\leq\exp\biggl(\frac{-T^2\alpha}{4(1-\alpha)}\biggr).
\end{equation*}
Letting $T\to\infty$ gives the desired result. Hence, assume $0<\beta<\infty$.

The method for proving the upper bound will be similar to the one for the lower bound. We ``reset'' the notation from the lower bound and begin anew. Let $0<\epsilon<1$ be given. We prove the bound
\begin{equation*}
    \limsup_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)\leq\exp\biggl(\frac{-\beta^2(1-\epsilon)\alpha}{4[1-(1-\epsilon)\alpha]}\biggr),
\end{equation*}
from which the desired bound follows by taking $\epsilon\to 0$. Put $\alpha_\epsilon\coloneqq (1-\epsilon)\alpha$.

As in the lower bound we assume without loss of generality that $\mathcal L=[n_0]\setminus[n_0-f]$ by Lemma~\ref{probdecreaseinc}. Let $K=\{ 0,1,2,\star\}$, and decompose $\varphi_\mathcal L$ into $\varphi_1$ and~$\varphi_2$ with corresponding sets $\mathcal C=(\mathcal C^{(1)}_k)_{k\in K}$ according to~\eqref{defnmk}. Define
\begin{gather*}
    n_1\coloneqq n_0-f,\quad f_1\coloneqq\bigl\lfloor\alpha_\epsilon f-\alpha_\epsilon n_0^{3/8}\bigr\rfloor,\quad w\coloneqq\bigl\lfloor n_0^{1/4}\bigr\rfloor, \\
    m_1\coloneqq\bigl\lceil m-3\alpha\bigl(f+n_0^{3/8}\bigr)\bigr\rceil,\quad\mathcal L_1\coloneqq [n_1]\setminus [n_1-(f_1-w)],
\end{gather*}
where $\lceil\cdot\rceil$ denotes the ceiling function (rounding up), and let $\lambda^{(1)}$ denote a random $1$-CNF formula with $f_1$ clauses and $n_1$ variables, and let $\Lambda^{(1)}$ denote the set of $f_1$ random literals defining~$\lambda^{(1)}$, and let finally $\varphi^{(1)}$ denote a random $2$-CNF formula with $m_1$ clauses and $n_1$ variables.

We get from~\eqref{phiLsatiff} that
\begin{align*}
    \prob(\varphi_\mathcal L\in\SAT)={}&\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    \leq{}&\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\geq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\geq m_1,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    &+\prob\bigl(\lvert\mathcal C^{(1)}_1\rvert<f_1\bigr)+\prob\bigl(\lvert\mathcal C^{(1)}_2\rvert<m_1\bigr).
\end{align*}
If $\mathfrak M$ denotes the set of partitions $(M_k)_{k\in K}$ of $[m]$ such that $\lvert M_0\rvert=0$, $\lvert M_1\rvert\geq f_1$, and $\lvert M_2\rvert\geq m_1$, we get
\begin{align*}
    \MoveEqLeft\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\geq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\geq m_1,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    &=\sum_{M\in\mathfrak M}\prob\bigl(\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)\prob(\mathcal C=M).
\end{align*}
For a given $M\in\mathfrak M$ we now consider for $k=1,2$ an auxiliary random $k$-CNF formula~$\psi_k$ with $\lvert M_k\rvert$ clauses and $n_1$ variables, such that $\psi_1$ and $\psi_2$ are independent. Then, by Lemma~\ref{distofphiandm},
\begin{equation*}
    \prob\bigl(\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)=\prob(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT).
\end{equation*}
The next step of this argument is a bit more involved than in the lower bound, since here, the number of \emph{distinct} clauses in~$\psi_1$ might be lower than~$\lvert M_1\rvert$ owing to duplicates, and thus, $\psi_1$ might fix fewer than $\lvert M_1\rvert$ variables in~$\psi_2$. This was of course also the case in the lower bound, but fixing the maximum number of variables only reduced the probability of satisfiability even further; here, we must deal with this issue proper. Let $\Lambda$ denote the set of random literals defining~$\psi_1$, i.e.\ $\psi_1=\min(\Lambda)$. Notice firstly that, since $\lvert M_1\rvert\geq f_1$, $\psi_1$ has more clauses than~$\lambda^{(1)}$, and hence
\begin{equation*}
    \prob\bigl(\lvert\Lambda\rvert<f_1-w\bigr)\leq\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr).
\end{equation*}
Using this, we now write
\begin{align*}
    \prob(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT)\leq{}&\prob\bigl(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT,\,\lvert\Lambda\rvert\geq f_1-w\bigr) \\
    &+\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr).
\end{align*}
Letting $\mathcal B$ denote the set of all satisfiable $1$-CNF formulas with at least $f_1-w$ (distinct) clauses and $n_1$ variables, we find that
\begin{align*}
    \prob\bigl(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT,\,\lvert\Lambda\rvert\geq f_1-w\bigr)&=\sum_{h\in\mathcal B}\prob(\psi_1=h,\, (\psi_2)_h\in\SAT) \\
    &=\sum_{h\in\mathcal B}\prob(\psi_1=h)\prob((\psi_2)_h\in\SAT) \\
    &\leq\prob\bigl(\psi_1\in\SAT,\,\lvert\Lambda\rvert\geq f_1-w\bigr)\prob\bigl((\psi_2)_{\mathcal L_1}\in\SAT\bigr) \\
    &\leq\prob\bigl(\psi_1\in\SAT\bigr)\prob\bigl((\psi_2)_{\mathcal L_1}\in\SAT\bigr) \\
    &\leq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\psi^{(1)}_{\mathcal L_1}\in\SAT\bigr),
\end{align*}
where we in the first inequality use Lemma~\ref{probdecreaseinc} and in the final inequality use Lemma~\ref{probdecreaseinm}. This yields
\begin{equation*}
    \prob\bigl(\psi_1\in\SAT,\, (\psi_2)_{\psi_1}\in\SAT\bigr)\leq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)+\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr),
\end{equation*}
and thus,
\begin{align*}
    \MoveEqLeft[3]\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\geq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\geq m_1,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr) \\
    \leq{}&\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\geq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\geq m_1\bigr) \\
    &\times\bigl[\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)+\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr)\bigr] \\
    \leq{}&\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0\bigr)\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr)+\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr).
\end{align*}
All in all, we get
\begin{align*}
    \prob(\varphi_\mathcal L\in\SAT)\leq{}&\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0\bigr)\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl(\varphi^{(1)}_{\mathcal L_1}\in\SAT\bigr) \\
    &+\prob\bigl(\lvert\mathcal C^{(1)}_1\rvert<f_1\bigr)+\prob\bigl(\lvert\mathcal C^{(1)}_2\rvert<m_1\bigr)+\prob\bigl(\lvert\Lambda^{(1)}\rvert<f_1-w\bigr).
\end{align*}
We now repeat the procedure on~$\varphi^{(1)}_{\mathcal L_1}$. Put again
\begin{equation*}
    R\coloneqq\bigl\lfloor c\log(n_0)\bigr\rfloor,\quad\text{where}\quad c\coloneqq\frac{1}{16\log(1/\alpha_\epsilon)},
\end{equation*}
and define for each $r\in\mathbb N$:
\begin{equation*}
    n_r\coloneqq n_0-f-\sum_{k=1}^{r-1}(f_k-w),\quad f_r\coloneqq\bigl\lfloor\alpha_\epsilon^r f-r\alpha_\epsilon^r n_0^{3/8}\bigr\rfloor,\quad m_r\coloneqq\biggl\lceil m-\frac{3}{1-\epsilon}(f+n_0^{3/8})\sum_{k=1}^r\alpha_\epsilon^k\biggr\rceil,
\end{equation*}
and finally $\mathcal L_r\coloneqq [n_r]\setminus[n_r-(f_r-w)]$, and let $\mathcal C^{(r)}_k$ denote the set~$\mathcal C_k$ from~\eqref{defnmk} with $\varphi^{(r-1)}$ in place of~$\varphi$ and $\mathcal L_{r-1}$ in place of~$\mathcal L$ for each $k\in K$, and denote finally by $\lambda^{(r)}$ a random $1$-CNF formula with $f_r$ clauses and $n_r$ variables, and by $\Lambda^{(r)}$ the set of random literals defining~$\lambda^{(r)}$, and finally by $\varphi^{(r)}$ a random $2$-CNF formula with $m_r$ clauses and $n_r$ variables. Redoing the argument above $R$ times, and finally bounding $\prob(\varphi^{(R)}_{\mathcal L_R}\in\SAT)\leq 1$, we get
\begin{align*}
    \prob(\varphi_\mathcal L\in\SAT)\leq{}&\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)\prod_{r=1}^R\prob\bigl(\lambda^{(r)}\in\SAT\bigr) \\
    &+\sum_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<f_r\bigr)+\sum_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_2\rvert<m_r\bigr)+\sum_{r=1}^R\prob\bigl(\lvert\Lambda^{(r)}\rvert<f_r-w\bigr).
\end{align*}
The upper bound then follows after a verification of the following points:
\begin{enumerate}[label=(U\arabic*)]
    \item\label{U1} $\lim_{n\to\infty}\prod_{r=1}^R\prob\bigl(\lambda^{(r)}\in\SAT\bigr)=\exp\biggl(\frac{-\beta^2}{4}\sum_{r=1}^\infty\alpha_\epsilon^{2r}\biggr)$,
    \item\label{U2} $\lim_{n\to\infty}\prod_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)\leq\exp\biggl(\frac{-\beta^2}{4}\sum_{r=1}^\infty\alpha_\epsilon^{2r-1}\biggr)$,
    \item\label{U3} $\lim_{n\to\infty}\sum_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<f_r\bigr)=0$,
    \item\label{U4} $\lim_{n\to\infty}\sum_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_2\rvert<m_r\bigr)=0$,
    \item\label{U5} $\lim_{n\to\infty}\sum_{r=1}^R\prob\bigl(\lvert\Lambda^{(r)}\rvert<f_r-w\bigr)=0$.
\end{enumerate}

We initially note that, by Lemma~\ref{distofphiandm},
\begin{equation}
\label{distofmrupper}
    \bigl(\lvert\mathcal C^{(r)}_0\rvert,\lvert\mathcal C^{(r)}_1\rvert,\lvert\mathcal C^{(r)}_2\rvert,\lvert\mathcal C^{(r)}_\star\rvert\bigr)\sim\mathrm{Multinomial}\bigl(m_{r-1},(p^{(r)}_0,p^{(r)}_1,p^{(r)}_2,p^{(r)}_\star)\bigr),
\end{equation}
where we now have for $r\geq 2$
\begin{equation*}
    p^{(r)}_0=\frac{(f_{r-1}-w)(f_{r-1}-w-1)}{4n_{r-1}(n_{r-1}-1)},\quad p^{(r)}_1=\frac{(f_{r-1}-w)n_r}{n_{r-1}(n_{r-1}-1)},\quad p^{(r)}_2=\frac{n_r(n_r-1)}{n_{r-1}(n_{r-1}-1)},
\end{equation*}
and lastly $p^{(r)}_\star=1-p^{(r)}_0-p^{(r)}_1-p^{(r)}_2$. The expressions for~$p^{(1)}_k$, $k\in\{ 0,1,2,\star\}$, are the same, except we do not subtract~$w$ from~$f$ in this case.

We of course still have
\begin{equation}
\label{computelimfrupper}
    \lim_{n\to\infty}\frac{f_r}{\sqrt{n_0}}=\alpha_\epsilon^r\beta
\end{equation}
for all $r\in\mathbb N$, so it follows immediately from Lemma~\ref{fewduplicateliterals} that
\begin{equation*}
    \sum_{r=1}^R\prob\bigl(\lvert\Lambda^{(r)}\rvert<f_r-w\bigr)\leq\sum_{r=1}^R\frac{4\alpha_\epsilon^{2r}\beta^2}{w}\leq 4\beta^2\frac{R}{w}\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
proving~\ref{U5}.

Putting $C\coloneqq 1/(1-\alpha_\epsilon)$ and $C^\prime\coloneqq 6C/(1-\epsilon)$, we have
\begin{equation}
    f+\sum_{k=1}^{r-1}(f_k-w)\leq\sum_{k=0}^{r-1}f_k\leq\sum_{k=0}^{r-1}\alpha_\epsilon^k f\leq Cf
\end{equation}
for all $r\in\mathbb N$, and therefore $n_0-Cf\leq n_r\leq n_0$. We also immediately find $m_r\leq m$, and $f/n_0^{3/8}\to\infty$ as $n\to\infty$, so $n_0^{3/8}\leq f$ for large enough~$n$, and after this point
\begin{equation*}
    \frac{3}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\sum_{k=1}^r\alpha_\epsilon^r\leq\frac{3C}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\leq C^\prime f,
\end{equation*}
yielding $m_r\geq m-C^\prime f$ and hence
\begin{equation}
\label{computelimurgr}
    \lim_{n\to\infty}\frac{n_r}{n_0}=1,\quad\text{and}\quad\lim_{n\to\infty}\frac{m_r}{n_0}=\alpha
\end{equation}
for all $r\in\mathbb N$. Of course, we still have
\begin{equation}
\label{betapowerRupper}
    \frac{1}{n_0^{1/16}}\leq\alpha_\epsilon^R\leq\frac{1}{\alpha_\epsilon n_0^{1/16}}
\end{equation}
by the same argument as in~\eqref{betapowerR}. Now, for a lower bound on $f_r$ we notice that when $r\in [R]$ we have $r\alpha_\epsilon^r n_0^{3/8}\leq R\alpha_\epsilon^r n_0^{3/8}$, and
\begin{equation*}
    \frac{\tfrac{1}{2}\alpha_\epsilon^rf}{R\alpha_\epsilon^r n_0^{3/8}}=\frac{f}{2Rn_0^{3/8}}\longrightarrow\infty\quad\text{as $n\to\infty$},
\end{equation*}
where the convergence is uniform in~$r$, so we have $r\alpha_\epsilon^r n_0^{3/8}\leq\tfrac{1}{2}\alpha_\epsilon^rf-1$ for all $r\in[R]$ when $n$ is large enough, and thus
\begin{equation}
\label{lowerboundfrupper}
    f_r=\bigl\lfloor\alpha_\epsilon^r f-r\alpha_\epsilon^r n_0^{3/8}\bigr\rfloor\geq\frac{\alpha_\epsilon^r f}{2}\geq\frac{f}{2n_0^{1/16}}
\end{equation}
for all $r\in[R]$ when $n$ is large enough, where the last inequality comes from~\eqref{betapowerRupper}. Further, since $f/n_0^{1/16}$ is asymptotic to $\beta n_0^{7/16}$ as $n\to\infty$, we see that
\begin{equation*}
    w\leq n_0^{1/4}\leq\frac{f}{4n_0^{1/16}}\leq\frac{f_r}{2}
\end{equation*}
for all $r\in[R]$ when $n$ is large enough, using in the end~\eqref{lowerboundfrupper}, and from these inequalities follows
\begin{equation}
\label{boundfrminusw}
    f_r-w\geq\tfrac{1}{2}f_r.
\end{equation}

For~\ref{U1} we see that, similarly to~\ref{L2}, since $\lambda^{(r)}$ is a random $1$-CNF formula with $f_r$ clauses and $n_r$ variables, Lemma~\ref{random1sat} together with~\eqref{computelimfrupper} and~\eqref{computelimurgr} gives
\begin{equation*}
    \lim_{n\to\infty}\prob\bigl(\lambda^{(r)}\in\SAT\bigr)=e^{-\tfrac{1}{4}\beta^2\alpha_\epsilon^{2r}}
\end{equation*}
for all $r\in\mathbb N$, and to complete the proof of~\ref{U1} we need only give a uniform (in large~$n$) summable (in~$r$) lower bound on $\log\prob(\lambda^{(r)}\in\SAT)$ to be able to apply dominated convergence. By the exact same argument as in the proof of~\ref{L2} we get
\begin{equation*}
    \log\prob\bigl(\lambda^{(r)}\in\SAT\bigr)\geq\frac{-f_r^2}{2n_{r+1}},
\end{equation*}
and we also have
\begin{equation*}
    \lim_{n\to\infty}\frac{f^2}{2(n_0-Cf)}=\frac{\beta^2}{2},
\end{equation*}
so using $f_r\leq\alpha_\epsilon^r f$ and $n_{r+1}\geq n_0-Cf$, we conclude that
\begin{equation*}
    \frac{-f_r^2}{2n_{r+1}}\geq\alpha_\epsilon^{2r}\frac{-f^2}{2(n_0-Cf)}\geq-\alpha_\epsilon^{2r}\beta^2,
\end{equation*}
where the last inequality holds for large enough~$n$ independent of~$r$.

Now for~\ref{U2} we get from~$\eqref{distofmrupper}$ that $\lvert\mathcal C^{(r)}_0\rvert\sim\mathrm{Binomial}(m_{r-1},p^{(r)}_0)$, so similarly to the argument in the proof of~\ref{L3}:
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=\bigl(1-p^{(r)}_0\bigr)^{m_{r-1}}\longrightarrow e^{-\tfrac{1}{4}\beta^2\alpha_\epsilon^{2(r-1)}\alpha}\leq e^{-\tfrac{1}{4}\beta^2\alpha_\epsilon^{2r-1}}
\end{equation*}
for all $r\in\mathbb N$, and to complete the proof of~\ref{U2} we need only give a uniform (in large~$n$) summable (in~$r$) lower bound on $\log\prob(\lvert\mathcal C^{(r)}_0\rvert=0)$. To this end, we again notice that
\begin{equation*}
    p^{(r)}_0\leq\frac{f^2}{4(n_0-Cf-1)^2}\longrightarrow 0
\end{equation*}
uniformly in~$r$, so $p^{(r)}_0\leq\tfrac{1}{2}$ for all $r\in\mathbb N$ when $n$ is large enough, and
\begin{equation*}
    m_{r-1}p^{(r)}_0\leq\alpha_\epsilon^{2(r-1)}\frac{mf^2}{4(u-Cf-1)^2}\longrightarrow\frac{1}{4}\alpha_\epsilon^{2(r-1)}\alpha\beta^2\leq\frac{1}{4}\alpha_\epsilon^{2r-1}\beta^2,
\end{equation*}
so $m_{r-1}p^{(r)}_0\leq\tfrac{1}{2}\alpha_\epsilon^{2r-1}\beta^2$ for all $r\in\mathbb N$ when $n$ is large enough, and hence we conclude using~\eqref{canonlogbound} that
\begin{equation*}
    \log\prob\bigl(\lvert\mathcal C^{(r)}_0\rvert=0\bigr)=m_{r-1}\log\bigl(1-p^{(r)}_0\bigr)\geq\frac{m_{r-1}p^{(r)}_0}{p^{(r)}_0-1}\geq-\alpha_\epsilon^{2r-1}\beta^2
\end{equation*}
for all $r\in\mathbb N$ when $n$ is large enough.

Now for~\ref{U3}. We get from~\eqref{distofmrupper} that $\lvert\mathcal C^{(r)}_1\rvert\sim\mathrm{Binomial}(m_{r-1},p^{(r)}_1)$, so we see that
\begin{equation*}
    \mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]=
    \begin{dcases}
        \frac{m_{r-1}(f_{r-1}-w)n_r}{n_{r-1}(n_{r-1}-1)},&\text{if $r\geq 2$}, \\
        \frac{mfn_1}{n_0(n_0-1)},&\text{if $r=1$},
    \end{dcases}
\end{equation*}
and
\begin{equation*}
    \frac{m_{r-1}n_r}{n_{r-1}(n_{r-1}-1)}\geq\frac{(m-C^\prime f)(n_0-Cf)}{n_0^2}\longrightarrow\alpha,
\end{equation*}
so $m_{r-1}n_r/n_{r-1}(n_{r-1}-1)\geq\alpha_\epsilon$ for all $r\in\mathbb N$ when $n$ is large enough. Hence, since
\begin{equation*}
    f_{r-1}-w=\bigl\lfloor\alpha_\epsilon^{r-1}f-(r-1)\alpha_\epsilon^{r-1}n_0^{3/8}\bigr\rfloor-\bigl\lfloor n_0^{1/4}\bigr\rfloor\geq\alpha_\epsilon^{r-1}f-(r-1)\alpha_\epsilon^{r-1}n_0^{3/8}-2n_0^{1/4},
\end{equation*}
and of course $f\geq f-2n_0^{1/4}$ for the case $r=1$, we get
\begin{equation*}
    \mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]\geq\alpha_\epsilon^r f-r\alpha_\epsilon^r n_0^{3/8}+\alpha_\epsilon^r n_0^{3/8}-2\alpha_\epsilon n_0^{1/4}
\end{equation*}
for all $r\in\mathbb N$ when $n$ is large enough, which is the same as the second inequality in
\begin{equation}
\label{meancr1bound}
    f_r\leq\alpha_\epsilon^r f-r\alpha_\epsilon^r n_0^{3/8}\leq\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]-\alpha_\epsilon^r n_0^{3/8}+2\alpha_\epsilon n_0^{1/4}.
\end{equation}
Now, if $r\in [R]$, then $\alpha_\epsilon^r\geq n_0^{-1/16}$ by~\eqref{betapowerRupper}, and of course $2n_0^{1/4}\leq\tfrac{1}{2}n_0^{5/16}$ for large enough~$n$, so in that case
\begin{equation*}
    -\alpha_\epsilon^r n_0^{3/8}+2\alpha_\epsilon n_0^{1/4}\leq-n_0^{5/16}+2n_0^{1/4}\leq -\tfrac{1}{2}n_0^{5/16}
\end{equation*}
for large enough~$n$. We now get from~\eqref{meancr1bound} and the above that
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<f_r\bigr)\leq\prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]-\tfrac{1}{2}n_0^{5/16}\bigr)
\end{equation*}
for all $r\in[R]$ when $n$ is large enough. Next, we wish to apply the following Chernoff bound:
\begin{equation*}
    \prob\bigl(N<\mean[N]-\delta\mean[N]\bigr)\leq e^{-\tfrac{1}{2}\delta^2\mean[N]}
\end{equation*}
when $N$ is binomially distributed and $0<\delta<1$. Taking in our case $N=\lvert\mathcal C^{(r)}_1\rvert$ and
\begin{equation*}
    \delta=\frac{n_0^{5/16}}{2\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]}\leq\frac{n_0^{5/16}}{2\alpha_\epsilon (f_{r-1}-w)}\leq\frac{n_0^{5/16}}{\alpha_\epsilon f_{r-1}}\leq\frac{2n_0^{3/8}}{\alpha_\epsilon f}\longrightarrow 0,
\end{equation*}
where the first inequality comes from the initial bound on $\mean[\lvert\mathcal C^{(r)}_1\rvert]$ and holds for all $r\in\mathbb N$ when $n$ is large enough, the second comes from~\eqref{boundfrminusw} and holds for all $r\in[R]$ when $n$ is large enough, and the final comes from~\eqref{lowerboundfrupper} and holds for all $r\in[R]$ when $n$ is large enough. Thus, for all $r\in[R]$ it holds for large enough~$n$ that $\delta<1$, so Chernoff's bound gives
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]-\tfrac{1}{2}n_0^{5/16}\bigr)\leq\exp\biggl(\frac{-n_0^{5/8}}{8\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]}\biggr).
\end{equation*}
Lastly, we note that
\begin{equation*}
    \mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]\leq f\frac{mn_0}{(n_0-Cf-1)^2},
\end{equation*}
and $mn_0/(n_0-Cf-1)^2\to\alpha$ as $n\to\infty$, so for large enough~$n$ it holds for all $r\in\mathbb N$ that $\mean[\lvert\mathcal C^{(r)}_1\rvert]\leq 2\alpha f$, and using this yields
\begin{equation*}
    \exp\biggl(\frac{-n_0^{5/8}}{8\mean\bigl[\lvert\mathcal C^{(r)}_1\rvert\bigr]}\biggr)\leq\exp\biggl(\frac{-n_0^{5/8}}{16\alpha f}\biggr).
\end{equation*}
Putting it all together, we get
\begin{equation*}
    \sum_{r=1}^R \prob\bigl(\lvert\mathcal C^{(r)}_1\rvert<f_r\bigr)\leq R\exp\biggl(\frac{-n_0^{5/8}}{16\alpha f}\biggr)\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
as desired.

Now finally for~\ref{U4}. We see for all $r\in\mathbb N$ that, since $\lvert\mathcal C^{(r)}_2\rvert$ can only attain integer values,
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(r)}_2\rvert<m_r\bigr)=\prob\Bigl(\lvert\mathcal C^{(r)}_2\rvert<m-\frac{3}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\sum_{k=1}^r\alpha_\epsilon^k\Bigr),
\end{equation*}
and
\begin{equation*}
    m-\frac{3}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\sum_{k=1}^r\alpha_\epsilon^k\leq m_{r-1}-\frac{3}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\alpha_\epsilon^r,
\end{equation*}
so
\begin{equation*}
    \prob\Bigl(\lvert\mathcal C^{(r)}_2\rvert<m-\frac{3}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\sum_{k=1}^r\alpha_\epsilon^k\Bigr)\leq\prob\Bigl(m_{r-1}-\lvert\mathcal C^{(r)}_2\rvert>\frac{3\alpha_\epsilon^r}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\Bigr).
\end{equation*}
Now, from~\eqref{distofmrupper} we find that $m_{r-1}-\lvert\mathcal C^{(r)}_2\rvert=\lvert\mathcal C^{(r)}_0\rvert+\lvert\mathcal C^{(r)}_1\rvert+\lvert\mathcal C^{(r)}_\star\rvert$, and
\begin{equation*}
    \lvert\mathcal C^{(r)}_0\rvert+\lvert\mathcal C^{(r)}_1\rvert+\lvert\mathcal C^{(r)}_\star\rvert\sim\mathrm{Binomial}\bigl(m_{r-1},1-p^{(r)}_2\bigr).
\end{equation*}
Put for convenience $N^{(r)}\coloneqq\lvert\mathcal C^{(r)}_0\rvert+\lvert\mathcal C^{(r)}_1\rvert+\lvert\mathcal C^{(r)}_\star\rvert$, and notice that for $r\geq 2$, as $n_r=n_{r-1}-(f_{r-1}-w)$,
\begin{equation*}
    p^{(r)}_2=\frac{n_r(n_r-1)}{n_{r-1}(n_{r-1}-1)}=1-(f_{r-1}-w)\frac{2n_{r-1}-(f_{r-1}-w)-1}{n_{r-1}(n_{r-1}-1)},
\end{equation*}
giving us
\begin{equation*}
    1-p^{(r)}_2=(f_{r-1}-w)\frac{2n_{r-1}-(f_{r-1}-w)-1}{n_{r-1}(n_{r-1}-1)}\leq\frac{2}{n_{r-1}-1}f_{r-1}\leq\frac{2}{n_0-Cf-2}f_{r-1},
\end{equation*}
and of course, for $r=1$ this is the last inequality in
\begin{equation*}
    1-p^{(1)}_2=1-\frac{n_1(n_1-1)}{n_0(n_0-1)}=\frac{2n_0-f-1}{n_0(n_0-1)}f\leq\frac{2}{n_0-1}f\leq\frac{2}{n_0-Cf-2}f,
\end{equation*}
which holds, so since $2m/(n_0-Cf-2)\to 2\alpha$, we find that
\begin{equation*}
    \mean[N^{(r)}]=m_{r-1}\bigl(1-p^{(r)}_2\bigr)\leq\frac{2m}{n_0-Cf-2}f_{r-1}\leq 3\alpha f_{r-1}=\frac{3\alpha_\epsilon}{1-\epsilon}f_{r-1}
\end{equation*}
holds for all $r\in\mathbb N$ when $n$ is large enough, and since $f_{r-1}\leq\alpha_\epsilon^{r-1}f-(r-1)\alpha_\epsilon^{r-1}n_0^{3/8}$, we get
\begin{equation}
\label{boundonmeansumm}
    \mean[N^{(r)}]\leq\frac{3\alpha_\epsilon^r}{1-\epsilon}f-(r-1)\frac{3\alpha_\epsilon^r}{1-\epsilon}n_0^{3/8}
\end{equation}
uniformly in~$r$ when $n$ is large enough. Now, continuing our calculations from before and using~\eqref{boundonmeansumm}, we get
\begin{align*}
    \prob\Bigl(m_{r-1}-\lvert\mathcal C^{(r)}_2\rvert>\frac{3\alpha_\epsilon^r}{1-\epsilon}\bigl(f+n_0^{3/8}\bigr)\Bigr)&=\prob\Bigl(N^{(r)}>\frac{3\alpha_\epsilon^r}{1-\epsilon}f+\frac{3\alpha_\epsilon^r}{1-\epsilon}n_0^{3/8}\Bigr) \\
    &\leq\prob\Bigl(N^{(r)}>\mean[N^{(r)}]+r\frac{3\alpha_\epsilon^r}{1-\epsilon}n_0^{3/8}\Bigr)
\end{align*}
for all $r\in\mathbb N$ as long as $n$ is large enough. We are now in a position to apply Chernoff's bound~\eqref{chernoff}, which will require a lower bound on $\mean[N^{(r)}]$. For $r\geq 2$ we find that
\begin{equation*}
    1-p^{(r)}_2=\frac{2n_{r-1}-(f_{r-1}-w)-1}{n_{r-1}(n_{r-1}-1)}(f_{r-1}-w)\geq\frac{2(n_0-Cf)-f-1}{2n_0^2}f_{r-1}\geq\frac{n_0-Cf}{2n_0^2}f_{r-1},
\end{equation*}
where the first inequality holds when $r\in[R]$ and $n$ is large enough due to~\eqref{boundfrminusw}, the last inequality holds for large enough~$n$ since of course $n_0-Cf\geq f+1$ at some point, and by verification the inequality also holds for $r=1$. Further, if $r\in[R]$ and $n$ is large enough we get $f_{r-1}\geq f/(2n_0^{1/16})$ from~\eqref{lowerboundfrupper}, and thus
\begin{equation*}
    \mean[N^{(r)}]=m_{r-1}(1-p^{(r)}_2)\geq\frac{(m-C^\prime f)(n_0-Cf)}{2n_0^2}\cdot\frac{f}{2n_0^{1/16}}\geq\frac{\alpha_\epsilon f}{4n_0^{1/16}}
\end{equation*}
for all $r\in[R]$ when $n$ is large enough, where the last inequality holds because
\begin{equation*}
    \lim_{n\to\infty}\frac{(m-C^\prime f)(n_0-Cf)}{n_0^2}=\alpha.
\end{equation*}
Now, using the above lower bound on $\mean[N^{(r)}]$, we get for the following choice of $\delta$:
\begin{equation*}
    \delta=\frac{3r\alpha_\epsilon^r n_0^{3/8}}{(1-\epsilon)\mean[N^{(r)}]}\leq\frac{12Rn_0^{7/16}}{(1-\epsilon)f}\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
and hence $\delta<1$ for all $r\in[R]$ when $n$ is large enough. Chernoff's bound~\eqref{chernoff} gives
\begin{equation*}
    \prob\Bigl(N^{(r)}>\mean[N^{(r)}]+r\frac{3\alpha_\epsilon^r}{1-\epsilon}n_0^{3/8}\Bigr)\leq\exp\biggl(\frac{-3r^2 \alpha_\epsilon^{2r}n_0^{3/4}}{(1-\epsilon)^2\mean[N^{(r)}]}\biggr).
\end{equation*}
From~\eqref{boundonmeansumm} it follows that $\mean[N^{(r)}]\leq (3\alpha_\epsilon^r f)/(1-\epsilon)$, and inserting this yields the first inequality in:
\begin{equation*}
    \exp\biggl(\frac{-3r^2 \alpha_\epsilon^{2r}n_0^{3/4}}{(1-\epsilon)^2\mean[N^{(r)}]}\biggr)\leq\exp\biggl(\frac{-r^2\alpha_\epsilon^r n_0^{3/4}}{(1-\epsilon)f}\biggr)\leq\exp\biggl(\frac{-n_0^{11/16}}{f}\biggr),
\end{equation*}
and the second inequality follows from~\eqref{betapowerRupper} and the fact that $r\geq 1$ and $1-\epsilon\leq 1$. The above inequality holds for all $r\in[R]$ when $n$ is large enough. Putting it all together, we conclude that
\begin{equation*}
    \sum_{r=1}^R\prob\bigl(\lvert\mathcal C^{(r)}_2\rvert<m_r\bigr)\leq R\exp\biggl(\frac{-n_0^{11/16}}{f}\biggr)\longrightarrow 0\quad\text{as $n\to\infty$},
\end{equation*}
proving~\ref{U4} and hence also finishing the proof of the case $k=2$ in Theorem~\ref{mainthm} when $\alpha>0$.


\subsection{The random mixed 1- and 2-SAT problem}
In this section, we give a proof of Theorem~\ref{mainthm2}, which follows quite readily from the part of Theorem~\ref{mainthm} that we have just proved. Remember that $n_0\to\infty$, $f/\sqrt{n_0}\to\beta$, and $m/n_0\to\alpha$, where $0\leq\beta\leq\infty$ and $0<\alpha<1$. We are considering a random $2$-CNF formula~$\varphi$ with $m$ clauses and $n_0$ variables and a random $1$-CNF formula~$\lambda$ with $f$ clauses and $n_0$ variables, such that $\varphi$ and~$\lambda$ are independent. Let $\Lambda=\{ L_1,L_2,\dots,L_f\}$ denote the set of the random literals defining~$\lambda$. From~\eqref{splitoffunitclauses} we get
\begin{equation*}
    \varphi\land\lambda\in\SAT\iff\lambda\in\SAT\quad\text{and}\quad\varphi_\Lambda\in\SAT.
\end{equation*}
Let $\mathcal L_0\coloneqq [n_0]\setminus [n_0-f]$ so that $\lvert\mathcal L_0\rvert=f\geq\lvert\Lambda\rvert$, and let $\mathcal B$ denote the set of all satisfiable $1$-CNF formulas with $n_0$ variables and at most $f$ clauses. We get from the above and Lemma~\ref{probdecreaseinc} that
\begin{align*}
    \prob(\varphi\land\lambda\in\SAT)&=\prob(\lambda\in\SAT,\varphi_\Lambda\in\SAT) \\
    &=\sum_{h\in\mathcal B}\prob(\varphi_\Lambda\in\SAT\mid\lambda=h)\prob(\lambda=h) \\
    &=\sum_{h\in\mathcal B}\prob(\varphi_h\in\SAT)\prob(\lambda=h) \\
    &\geq\prob(\varphi_{\mathcal L_0}\in\SAT)\prob(\lambda\in\SAT) \\
    &\longrightarrow\exp\biggl(\frac{-\beta^2\alpha}{4(1-\alpha)}\biggr)\exp\biggl(\frac{-\beta^2}{4}\biggr)\quad(\text{as $n\to\infty$}) \\
    &=\exp\biggl(\frac{-\beta^2}{4(1-\alpha)}\biggr),
\end{align*}
where the convergence comes from the first part of Theorem~\ref{mainthm} and Lemma~\ref{random1sat} respectively.

Now, to get a corresponding upper bound on $\prob(\varphi\land\lambda\in\SAT)$ we need a lower bound on~$\lvert\Lambda\rvert$, i.e.\ we need to bound the number of duplicates in the random literals defining~$\lambda$. We get from Lemma~\ref{fewduplicateliterals} that $\lvert\Lambda\rvert\geq f-\lfloor n_0^{1/4}\rfloor$ with probability tending towards~$1$. Now put $\mathcal L_1\coloneqq[n_0]\setminus[n_0-(f-\lfloor n_0^{1/4}\rfloor)]$ so that $\lvert\mathcal L_1\rvert=f-\lfloor n_0^{1/4}\rfloor$, and we repeat the argument from above: let $\mathcal B$ denote the set of all satisfiable $1$-CNF formulas with $n_0$ variables and at least $f-\lfloor n_0^{1/4}\rfloor$ clauses. Then
\begin{align*}
    \prob(\varphi\land\lambda\in\SAT)={}&\prob\bigl(\lambda\in\SAT,\,\varphi_\Lambda\in\SAT,\,\lvert\Lambda\rvert\geq f-\bigl\lfloor n_0^{1/4}\bigr\rfloor\bigr) \\
    &+\prob\bigl(\lambda\in\SAT,\,\varphi_\Lambda\in\SAT,\,\lvert\Lambda\rvert<f-\bigl\lfloor n_0^{1/4}\bigr\rfloor\bigr),
\end{align*}
where of course the second term vanishes, and using Lemma~\ref{probdecreaseinc}:
\begin{align*}
    \prob\bigl(\lambda\in\SAT,\,\varphi_\Lambda\in\SAT,\,\lvert\Lambda\rvert\geq f-\bigl\lfloor u^{1/4}\bigr\rfloor\bigr)&=\sum_{h\in\mathcal B}\prob(\varphi_h\in\SAT)\prob(\lambda=h) \\
    &\leq\prob(\varphi_{\mathcal L_1}\in\SAT)\sum_{h\in\mathcal B}\prob(\lambda=h) \\
    &\leq\prob(\varphi_{\mathcal L_1}\in\SAT)\prob(\lambda\in\SAT) \\
    &\longrightarrow\exp\biggl(\frac{-\beta^2}{4(1-\alpha)}\biggr)\quad\text{as $n\to\infty$},
\end{align*}
using in the end Theorem~\ref{mainthm}, since $\lvert\mathcal L_1\rvert/\sqrt{n_0}\to\beta$, and Lemma~\ref{random1sat}. This completes the proof of Theorem~\ref{mainthm2}, except for the case $\alpha=0$, which may be proved as follows: let $\psi$ be a random $2$-CNF formula with $\lfloor\epsilon n_0\rfloor$ clauses and $n_0$ variables. Then by Lemma~\ref{probdecreaseinm},
\begin{equation*}
    \liminf_{n\to\infty}\prob(\varphi\land\lambda\in\SAT)\geq\liminf_{n\to\infty}\prob(\psi\land\lambda\in\SAT)=\exp\biggl(\frac{-\beta^2}{4(1-\epsilon)}\biggr),
\end{equation*}
and
\begin{equation*}
    \limsup_{n\to\infty}\prob(\varphi\land\lambda\in\SAT)\leq\limsup_{n\to\infty}\prob(\lambda\in\SAT)=\exp\biggl(\frac{-\beta^2}{4}\biggr),
\end{equation*}
so taking $\epsilon\to 0$ yields the desired result.


\subsection{Sublinear number of binary clauses}

The only thing missing from a proof of Theorem~\ref{mainthm} in the case $k=2$ is the verification of
\begin{equation*}
    \lim_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)=e^{-(\gamma/2)^2},
\end{equation*}
where $\varphi$ is a random $2$-CNF formula with $m=m(n)$ clauses and $n_0=n_0(n)$ variables satisfying $m\to\infty$ and $m/n_0\to 0$, and $\mathcal L\subseteq\pm[n_0]$ is a consistent set of literals with $\lvert\mathcal L\rvert=f=f(n)$ such that $f\sqrt{m}/n_0\to\gamma$. We may assume without loss of generality that $0<\gamma<\infty$, as the cases $\gamma=0$ and $\gamma=\infty$ then follow by an application of Lemma~\ref{probdecreaseinm}, as we have shown in similar situations previously.

As usual we assume without loss of generality that $\mathcal L=[n_0]\setminus [n_0-f]$, so we get
\begin{equation*}
    \prob(\varphi_\mathcal L\in\SAT)=\prob\bigl(\lvert\mathcal C_0\rvert=0,\,\varphi_1\in\SAT,\, (\varphi_2)_{\varphi_1}\in\SAT\bigr)
\end{equation*}
from~\eqref{phiLsatiff}, and from Lemma~\ref{distofphiandm}:
\begin{equation*}
    \mean[\lvert\mathcal C_0\rvert]=m\frac{f(f-1)}{4n_0(n_0-1)}=\biggl(\frac{1}{2}\cdot\frac{f\sqrt{m}}{n_0}\biggr)^2\frac{f-1}{f}\cdot\frac{n_0}{n_0-1}\longrightarrow\biggl(\frac{\gamma}{2}\biggr)^2,
\end{equation*}
meaning that $\lvert\mathcal C_0\rvert$ is asymptotically Poisson-distributed with mean $(\gamma/2)^2$, yielding
\begin{equation*}
    \prob(\varphi_\mathcal L\in\SAT)\leq\prob(\lvert\mathcal C_0\rvert=0)\longrightarrow e^{-(\gamma/2)^2}.
\end{equation*}
This leaves the lower bound. By the exact same arguments as those leading up to~\eqref{lowerbdfirst}, we get
\begin{equation*}
    \prob(\varphi_\mathcal L\in\SAT)\geq\prob(\lambda\in\SAT)\prob(\psi_{\mathcal L_1}\in\SAT)\prob(\lvert\mathcal C_0\rvert=0)\prob\bigl(\lvert\mathcal C_1\rvert\leq f_1\bigm\vert\lvert\mathcal C_0\rvert=0\bigr),
\end{equation*}
where
\begin{equation*}
    f_1\coloneqq\bigl\lfloor 2\gamma\sqrt{m}+m^{3/8}\bigr\rfloor,
\end{equation*}
and $\lambda$ is a random $1$-CNF formula with $f_1$ clauses and $n_1\coloneqq n_0-f$ variables, $\psi$ is a random $2$-CNF formula with $m$ clauses and $n_1$ variables, and lastly $\mathcal L_1\coloneqq [n_1]\setminus [n_1-f_1]$. Of course, we still have $\prob(\lvert\mathcal C_0\rvert=0)\to e^{-(\gamma/2)^2}$, so we need to show that the other factors tend towards~$1$. We notice that
\begin{equation*}
    \frac{f}{n_0}=\frac{1}{\sqrt{m}}\cdot\frac{f\sqrt{m}}{n_0}\longrightarrow 0,
\end{equation*}
since $m\to\infty$, so $n_1/n_0\to 1$, and $f_1/\sqrt{m}\to 2\gamma$, thus
\begin{equation*}
    \frac{f_1}{\sqrt{n_1}}=\frac{f_1}{\sqrt{m}}\sqrt{\frac{m}{n_0}}\sqrt{\frac{n_0}{n_1}}\longrightarrow 0,
\end{equation*}
and with this Lemma~\ref{random1sat} gives $\prob(\lambda\in\SAT)\to 1$, and Lemma~\ref{alphaisnull} gives $\prob(\psi_{\mathcal L_1}\in\SAT)\to 1$. Next, $\lvert\mathcal C_1\rvert$ has a binomial distribution with parameters~$m$ and
\begin{equation*}
    p_{1\mid 0}\coloneqq\frac{f(n_0-f)}{n_0(n_0-1)-\tfrac{1}{4}f(f-1)}
\end{equation*}
given $\lvert\mathcal C_0\rvert=0$, again by Lemma~\ref{distofphiandm}. Let $N\sim\mathrm{Binom}(m,p_{1\mid 0})$, and notice that
\begin{equation*}
    \mean[N]=\frac{mf(n_0-f)}{n_0(n_0-1)-\tfrac{1}{4}f(f-1)}=\frac{f\sqrt{m}}{n_0}\cdot\frac{n_0-f}{n_0}\cdot\frac{n_0^2}{n_0(n_0-1)-\frac{1}{4}f(f-1)}\sqrt{m},
\end{equation*}
so since
\begin{equation*}
    \lim_{n\to\infty}\biggl[\frac{f\sqrt{m}}{n_0}\cdot\frac{n_0-f}{n_0}\cdot\frac{n_0^2}{n_0(n_0-1)-\frac{1}{4}f(f-1)}\biggr]=\gamma,
\end{equation*}
we conclude that
\begin{equation*}
    \tfrac{1}{2}\gamma\sqrt{m}\leq\mean[N]\leq 2\gamma\sqrt{m}
\end{equation*}
when $n$ is large enough. In particular we have
\begin{equation*}
    \delta=\frac{m^{3/8}}{\mean[N]}\leq\frac{2}{\gamma m^{1/8}}<1
\end{equation*}
for large enough $n$, so applying Chernoff's bound~\eqref{chernoff} yields:
\begin{align*}
    \prob\bigl(\lvert\mathcal C_1\rvert>f_1\bigm\vert\lvert\mathcal C_0\rvert=0\bigr)&=\prob(N>f_1) \\
    &=\prob\bigl(N>2\gamma\sqrt{m}+m^{3/8}\bigr) \\
    &\leq\prob\bigl(N>\mean[N]+m^{3/8}\bigr) \\
    &\leq\exp\biggl(\frac{-m^{3/4}}{3\mean[N]}\biggr) \\
    &\leq\exp\biggl(\frac{-m^{1/4}}{6\gamma}\biggr)\longrightarrow 0
\end{align*}
as $n\to\infty$, finishing the proof.


\subsection{Random 3-SAT}

We are able to prove Theorem~\ref{mainthm} directly in the case $k=3$ (without assuming $\alpha>0$). The proof in this section will follow along the same lines as before, but it is a bit more notationally heavy than in the case $k=2$, as there are now, in addition to $0$-, $1$-, and $2$-clauses, also $3$-clauses appearing, but it is mathematically more elementary, since the decomposition~\eqref{phiLsatiff3} only occurs three times, so there are no infinite series to deal with. We seek to prove that
\begin{equation*}
    \lim_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)=e^{-(\gamma/2)^3},
\end{equation*}
where $\varphi$ is a random $3$-CNF formula with $m=m(n)$ clauses and $n_0=n_0(n)$ variables, $\mathcal L\subseteq\pm[n_0]$ is a consistent set of literals with $\lvert\mathcal L\rvert=f=f(n)$, and $m\to\infty$, $m/n_0\to\alpha$, and $fm^{1/3}/n_0\to\gamma$ as $n\to\infty$, where $0\leq\alpha<3.145$ and $0\leq\gamma\leq\infty$. Assume without loss of generality that $\mathcal L=[n_0]\setminus [n_0-f]$ and $0<\gamma<\infty$.

From~\eqref{phiLsatiff3} we have
\begin{equation*}
    \prob(\varphi_\mathcal L\in\SAT)=\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\varphi_1\in\SAT,\, (\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT\bigr),
\end{equation*}
and from Lemma~\ref{distofphiandm} it follows that $\lvert\mathcal C^{(1)}_0\rvert$ is Binomially distributed with mean
\begin{equation*}
    \mean\bigl[\lvert\mathcal C^{(1)}_0\rvert\bigr]=m\frac{f(f-1)(f-2)}{8n_0(n_0-1)(n_0-2)}\longrightarrow\frac{\gamma^3}{8},
\end{equation*}
so $\lvert\mathcal C^{(1)}_0\rvert$ is asymptotically Poisson-distributed with mean $(\gamma/2)^3$, and thus
\begin{equation*}
    \lim_{n\to\infty}\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0\bigr)=e^{-(\gamma/2)^3},
\end{equation*}
which immediately yields the correct upper bound for the limit $\lim_{n\to\infty}\prob(\varphi_\mathcal L\in\SAT)$.

For the lower bound we apply the same line of reasoning as in the lower bound in the case $k=2$. Put $K\coloneqq\{ 0,1,2,3,\star\}$ and $\mathcal C\coloneqq (\mathcal C^{(1)}_k)_{k\in K}$. Put further
\begin{equation*}
    f_1\coloneqq\bigl\lfloor\gamma^2 m^{1/3}+m^{1/5}\bigr\rfloor\quad\text{and}\quad m_1\coloneqq\bigl\lfloor 2\gamma m^{2/3}+m^{2/5}\bigr\rfloor.
\end{equation*}
We have
\begin{align*}
    \MoveEqLeft\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\varphi_1\in\SAT,\, (\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT\bigr) \\
    &\geq\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\leq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\leq m_2,\,\varphi_1\in\SAT,\, (\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT\bigr) \\
    &=\sum_{M\in\mathfrak M}\prob\bigl(\varphi_1\in\SAT,\, (\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)\prob(\mathcal C=M),
\end{align*}
where $\mathfrak M$ denotes the collection of all partitions $M=(M_k)_{k\in K}$ of $[m]$ satisfying $\lvert M_0\rvert=0$, $\lvert M_1\rvert\leq f_1$, and $\lvert M_2\rvert\leq m_1$. By the exact same argument as in~\eqref{transfermethod} we get
\begin{equation*}
    \prob\bigl(\varphi_1\in\SAT,\, (\varphi_2\land\varphi_3)_{\varphi_1}\in\SAT\bigm\vert\mathcal C=M\bigr)\geq\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl((\psi^{(1)}\land\varphi^{(1)})_{\mathcal L_1}\in\SAT\bigr),
\end{equation*}
where $\lambda^{(1)}$ is a random $1$-CNF formula with $f_1$ clauses and $n_1\coloneqq n_0-f$ variables, $\psi^{(1)}$ is a random $2$-CNF formula with $m_1$ clauses and $n_1$ variables, and $\varphi^{(1)}$ is a random $3$-CNF formula with $m$ clauses and $n_1$ variables such that (the clauses of) $\psi^{(1)}$ and~$\varphi^{(1)}$ are independent, and finally $\mathcal L_1\coloneqq [n_1]\setminus [n_1-f_1]$. Hence,
\begin{equation}
\label{decomp3}
\begin{aligned}
    \prob(\varphi_\mathcal L\in\SAT)\geq{}&\prob\bigl(\lambda^{(1)}\in\SAT\bigr)\prob\bigl((\psi^{(1)}\land\varphi^{(1)})_{\mathcal L_1}\in\SAT\bigr) \\
    &\times\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\leq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\leq m_1\bigr).
\end{aligned}
\end{equation}
Lemma~\ref{distofphiandm} again tells us that both $\lvert\mathcal C^{(1)}_1\rvert$ and $\lvert\mathcal C^{(1)}_2\rvert$ are binomially distributed with parameters $m$ and $p^{(1)}_1$ or $p^{(1)}_2$ respectively, where
\begin{equation*}
    p^{(1)}_1=\frac{3f(f-1)(n_0-f)}{4n_0(n_0-1)(n_0-2)},\quad\text{and}\quad p^{(1)}_2=\frac{3f(n_0-f)(n_0-f-1)}{2n_0(n_0-1)(n_0-2)}.
\end{equation*}
A quick calculation shows that $\mean[\lvert\mathcal C^{(1)}_1\rvert]$ is asymptotic to $\tfrac{3}{4}\gamma^2 m^{1/3}$ and $\mean[\lvert\mathcal C^{(1)}_2\rvert]$ is asymptotic to $\tfrac{3}{2}\gamma m^{2/3}$ as $n\to\infty$. Thus, we can apply Chernoff's bound~\eqref{chernoff} to receive
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(1)}_1\rvert>f_1\bigr)\leq\prob\bigl(\lvert\mathcal C^{(1)}_1\rvert>\mean\bigl[\lvert\mathcal C^{(1)}_1\rvert\bigr]+m^{1/5}\bigr)\leq\exp\biggl(\frac{-m^{2/5}}{3\mean\bigl[\lvert\mathcal C^{(1)}_1\rvert\bigr]}\biggr)\leq\exp\biggl(\frac{-m^{1/15}}{3\gamma^2}\biggr),
\end{equation*}
where the first and last inequality holds for large enough~$n$, so that $\lvert\mathcal C^{(1)}_1\rvert\leq f_1$ w.h.p. By a similar argument we see that $\lvert\mathcal C^{(1)}_2\rvert\leq m_1$ w.h.p. This means that
\begin{equation*}
    \lim_{n\to\infty}\prob\bigl(\lvert\mathcal C^{(1)}_0\rvert=0,\,\lvert\mathcal C^{(1)}_1\rvert\leq f_1,\,\lvert\mathcal C^{(1)}_2\rvert\leq m_1\bigr)=e^{-(\gamma/2)^3},
\end{equation*}
so it remains only to show that the other factors in~\eqref{decomp3} tend towards~$1$ as $n\to\infty$. We notice that
\begin{equation*}
    \frac{f}{n_0}=\frac{fm^{1/3}}{n_0}\cdot\frac{1}{m^{1/3}}\longrightarrow 0,\quad\text{so}\quad\frac{n_1}{n_0}\longrightarrow 1,\quad\text{and thus}\quad\frac{f_1}{\sqrt{n_1}}=\frac{f_1}{\sqrt{m}}\sqrt{\frac{m}{n_0}}\sqrt{\frac{n_0}{n_1}}\longrightarrow 0.
\end{equation*}
Lemma~\ref{random1sat} thus gives $\prob(\lambda^{(1)}\in\SAT)\to 1$.

Looking at the final factor, let for each $k\in\{0,1,2,\star\}$ $\mathcal C^{(2)}_k(2)$ denote the set of $j\in [m_1]$ for which the $j$'th clause of $\psi^{(1)}$ becomes a $k$-clause when fixing the variables dictated by $\mathcal L_1$ (cf.~\eqref{defnmk}), and let $\mathcal C^{(2)}_k(3)$ denote the corresponding set for $\varphi^{(1)}$. Put
\begin{equation*}
    \lvert\mathcal C^{(2)}_k\rvert\coloneqq\lvert\mathcal C^{(2)}_k(2)\rvert+\lvert\mathcal C^{(2)}_k(3)\rvert,
\end{equation*}
where the two terms are seen to be independent. As before we are able to make the following decomposition:
\begin{align*}
    \prob\bigl((\psi^{(1)}\land\varphi^{(1)})_{\mathcal L_1}\in\SAT\bigr)\geq{}&\prob\bigl(\lambda^{(2)}\in\SAT\bigr)\prob\bigl((\psi^{(2)}\land\varphi^{(2)})_{\mathcal L_2}\in\SAT\bigr) \\
    &\times\prob\bigl(\lvert\mathcal C^{(2)}_0\rvert=0,\,\lvert\mathcal C^{(2)}_1\rvert\leq f_2,\,\lvert\mathcal C^{(2)}_2\rvert\leq m_2\bigr),
\end{align*}
where $n_2\coloneqq n_1-f_1$,
\begin{equation*}
    f_2\coloneqq\bigl\lfloor m^{1/5}\bigr\rfloor,\quad m_2\coloneqq\bigl\lfloor 3\gamma m^{2/3}+m^{2/5}\bigr\rfloor,\quad\text{and}\quad\mathcal L_2\coloneqq [n_2]\setminus [n_2-f_2],
\end{equation*}
and $\lambda^{(2)}$ is a random $1$-CNF formula with $f_2$ clauses and $n_2$ variables, $\psi^{(2)}$ is a random $2$-CNF formula with $m_2$ clauses and $n_2$ variables, and $\varphi^{(2)}$ is a random $3$-CNF formula with $m$ clauses and $n_2$ variables such that (the clauses of) $\psi^{(2)}$ and~$\varphi^{(2)}$ are independent.

As before $f_2/\sqrt{n_2}\to 0$, so Lemma~\ref{random1sat} gives $\mathbb P(\lambda^{(2)}\in\SAT)\to 1$. Looking at Lemmas~\ref{distofphiandm}, a quick calculation shows that $\mean[\lvert\mathcal C^{(2)}_0(2)\rvert]$ is asymptotic to $\tfrac{1}{2}\gamma^5\alpha^{4/3}n_0^{-2/3}\to 0$, and $\mean[\lvert\mathcal C^{(2)}_0(3)\rvert]$ is asymptotic to $\frac{1}{8}\gamma^6\alpha^2 n_0^{-1}\to 0$, and it follows that $\lvert\mathcal C^{(2)}_0\rvert=0$ w.h.p.\ by an application of Markov's inequality:
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(2)}_0\rvert>0\bigr)\leq\mean\bigl[\lvert\mathcal C^{(2)}_0\rvert\bigr]\longrightarrow 0.
\end{equation*}
Next, we find that $\mean[\lvert\mathcal C^{(2)}_1(2)\rvert]\to 2\gamma^3 \alpha$ and $\mean[\lvert\mathcal C^{(2)}_1(3)\rvert]$ is asymptotic to $\tfrac{3}{4}\gamma^4 \alpha^{5/3}n_0^{-1/3}\to 0$, so $\lvert\mathcal C^{(2)}_1\rvert\leq f_2$ w.h.p.\ again by Markov's inequality:
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(2)}_1\rvert>f_2\bigr)\leq\frac{\mean\bigl[\lvert\mathcal C^{(2)}_1\rvert\bigr]}{f_2}\longrightarrow 0.
\end{equation*}
Lastly, $\mean[\lvert\mathcal C^{(2)}_2(2)\rvert]$ is asymptotic to $2\gamma m^{2/3}$ and $\mean[\lvert\mathcal C^{(2)}_2(3)\rvert]$ is asymptotic to $\tfrac{3}{2}\gamma^2 \alpha m^{1/3}$, so $\mean[\lvert\mathcal C^{(2)}_2\rvert]\leq 3\gamma m^{2/3}$ for large enough~$n$, and Chernoff's inequality~\eqref{chernoff} yields
\begin{equation*}
    \prob\bigl(\lvert\mathcal C^{(2)}_2\rvert>m_2\bigr)\leq\prob\bigl(\lvert\mathcal C^{(2)}_2\rvert>\mean\bigl[\lvert\mathcal C^{(2)}_2\rvert\bigr]+m^{2/5}\bigr)\leq\exp\biggl(\frac{-m^{4/5}}{3\mean\bigl[\lvert\mathcal C^{(2)}_2\rvert\bigr]}\biggr)\leq\exp\biggl(\frac{-m^{2/15}}{9\gamma^2}\biggr),
\end{equation*}
and thus $\lvert\mathcal C^{(2)}_2\rvert\leq m_2$ w.h.p. Hence, we are only missing a verification of the fact that $(\psi^{(2)}\land\varphi^{(2)})_{\mathcal L_2}$ is satisfiable w.h.p. We make the final decomposition:
\begin{equation*}
    \prob\bigl((\psi^{(2)}\land\varphi^{(2)})_{\mathcal L_2}\in\SAT\bigr)\geq\prob\bigl(\psi^{(3)}\land\varphi^{(3)}\in\SAT\bigr)\prob\bigl(\lvert\mathcal C^{(3)}_0\rvert=0,\,\lvert\mathcal C^{(3)}_1\rvert=0,\,\lvert\mathcal C^{(3)}_2\rvert\leq m_3\bigr),
\end{equation*}
where $n_3\coloneqq n_2-f_2$ and $m_3\coloneqq\lfloor 4\gamma m^{2/3}+m^{2/5}\rfloor$, $\psi^{(3)}$ is a random $2$-CNF formula with $m_3$ clauses and $n_3$ variables, and $\varphi^{(3)}$ is a random $3$-CNF formula with $m$ clauses and $n_3$ variables such that (the clauses of) $\psi^{(3)}$ and~$\varphi^{(3)}$ are independent (this corresponds to taking $f_3\coloneqq 0$).

We see that $\mean[\lvert\mathcal C^{(3)}_0(2)\rvert]$ is asymptotic to $\tfrac{3}{4}\gamma\alpha^{16/15}n_0^{-14/15}\to 0$, and $\mean[\lvert\mathcal C^{(3)}_0(3)\rvert]$ is asymptotic to $\tfrac{1}{8}\alpha^{8/5}n_0^{-7/5}\to 0$, so $\lvert\mathcal C^{(3)}_0\rvert=0$ w.h.p. Similarly $\mean[\lvert\mathcal C^{(3)}_1(2)\rvert]$ is asymptotic to $3\gamma\alpha^{13/15}n_0^{-2/15}\to 0$, and $\mean[\lvert\mathcal C^{(3)}_1(3)\rvert]$ is asymptotic to $\tfrac{3}{4}\alpha^{7/5}n_0^{-3/5}\to 0$, so again $\lvert\mathcal C^{(3)}_1\rvert=0$ w.h.p. Finally, $\mean[\lvert\mathcal C^{(3)}_2(2)\rvert]$ is asymptotic to $3\gamma m^{2/3}$ and $\mean[\lvert\mathcal C^{(3)}_2(3)\rvert]$ is asymptotic to $\tfrac{3}{2}\alpha m^{1/5}$, so $\mean[\lvert\mathcal C^{(3)}_2\rvert]\leq 4\gamma m^{2/3}$ for large enough~$n$, and by Chernoff's inequality we find that $\lvert\mathcal C^{(3)}_2\rvert\leq m_3$ w.h.p.

The final step in the proof is to show that the mixed formula $\psi^{(3)}\land\varphi^{(3)}$ is satisfiable w.h.p. Since $m/n_0\to\alpha$, $m_3/m^{2/3}\to 4\gamma$, and $n_3/n_0\to 1$, it follows that $m_3\leq\lfloor 10^{-6}n_3\rfloor$ for large enough~$n$. It further holds that $m/n_3\to\alpha<3.145$, so $m\leq\lfloor 3.145 n_3\rfloor$ for large enough~$n$. Let $\Phi$ denote a random mixed CNF formula with $n_3$ variables, $\lfloor 10^{-6}n_3\rfloor$ 2-clauses, and $\lfloor 3.145 n_3\rfloor$ 3-clauses. It follows from Lemma~\ref{probdecreaseinm} that
\begin{equation*}
    \liminf_{n\to\infty}\prob\bigl(\psi^{(3)}\land\varphi^{(3)}\in\SAT\bigr)\geq\liminf_{n\to\infty}\prob(\Phi\in\SAT).
\end{equation*}
From the first lines in the proof of Theorem~1 in~\cite{achlioptas00} it follows that $\liminf_{n\to\infty}\prob(\Phi\in\SAT)>0$, and it then follows from Theorem~2 from~\cite{AKKK01} that $\Phi$ is satisfiable w.h.p., completing the proof of our Theorem~\ref{mainthm}.


\subsection{The random mixed 1- and 3-SAT problem}

The final part is the proof of Theorem~\ref{mainthm2} in the case $k=3$. Thus, we again have $n_0\to\infty$, and we let~$\varphi$ denote a random $3$-CNF formula with $m$ clauses and $n_0$ variables, such that $m/n_0\to\alpha$ for some $0\leq\alpha<3.145$, and let~$\lambda$ denote a random $1$-CNF formula with $f$ clauses and $n_0$ variables, such that $f/\sqrt{n_0}\to\beta$ for some $0\leq\beta\leq\infty$, where $\varphi$ and $\lambda$ are independent. Then we immediately have
\begin{equation*}
    \limsup_{n\to\infty}\prob(\varphi\land\lambda\in\SAT)\leq\limsup_{n\to\infty}\prob(\lambda\in\SAT)=e^{-(\beta/2)^2}
\end{equation*}
from Lemma~\ref{probdecreaseinm} and Lemma~\ref{random1sat}.

To obtain the corresponding lower bound, we first note from~\eqref{splitoffunitclauses} that
\begin{equation*}
    \varphi\land\lambda\in\SAT\iff\lambda\in\SAT\quad\text{and}\quad\varphi_\lambda\in\SAT.
\end{equation*}
Let $\mathcal L\coloneqq [n_0]\setminus [n_0-f]$ and note that $\lambda$ will always have at most $f=\lvert\mathcal L\rvert$ distinct clauses. Thus, letting $\mathcal B$ denote the set of all satisfiable $1$-CNF formulas with $n_0$ variables and at most $f$ (distinct) clauses, we get from the above and Lemma~\ref{probdecreaseinc} that
\begin{align*}
    \prob(\varphi\land\lambda\in\SAT)&=\prob(\lambda\in\SAT,\varphi_\lambda\in\SAT) \\
    &=\sum_{h\in\mathcal B}\prob(\varphi_\lambda\in\SAT\mid\lambda=h)\prob(\lambda=h) \\
    &=\sum_{h\in\mathcal B}\prob(\varphi_h\in\SAT)\prob(\lambda=h) \\
    &\geq\prob(\varphi_\mathcal L\in\SAT)\prob(\lambda\in\SAT) \\
    &\longrightarrow e^{-(\beta/2)^2}\quad\text{as $n\to\infty$},
\end{align*}
where we in the end use Lemma~\ref{random1sat} and Theorem~\ref{mainthm}. This concludes the proof of Theorem~\ref{mainthm2} and thus the entire article.


