\begin{theorem}[$(\epsilon,\delta)$-LDP for the proposed protocol]
\label{thm:agm_CASH}
% Consider client $i$ encoding its local item $\mathbf{u}_i$ with a generator matrix $\mathbf{G}$ then modulated by BPSK to obtain $\mathbf{x}_i$, for $i\in[N]$. 
The protocol is $(\epsilon,\delta)$-LDP with the analytic Gaussian mechanism as the randomized mechanism $\mathcal{R}_i$, such that
$\mathcal{R}_i(\mathbf{u}_i) =q(\mathbf{u}_i)+\mathbf{n}_i= \mathbf{x}_i+\mathbf{n}_i$,
where $\mathbf{n}_i$ is a noise vector sampled from $\mathcal{N}(0,\sigma^2)$, which is a zero-mean Gaussian distribution with variance $\sigma^2=\textsc{AnalyticGaussian}(\epsilon,\delta,\Delta)$, for $i\in[N]$.
\end{theorem}
