% \end{proof}

With Theorem~\ref{thm:agm_CASH}, we summarize our protocol in Algorithm~\ref{alg:LDPCASH}.

% \begin{theorem}[$(\epsilon,\delta)$-LDP]
%     The proposed construction in Algorithm~\ref{alg:LDPCASH} is $(\epsilon,\delta)$-LDP with $\mathcal{R}_i(\mathbf{x}_i,\epsilon)$ adds a Gaussian noise vector that each entry is sampled from $\mathcal{N}(0,\sigma^2)$, where $\sigma^2=$
% \end{theorem}

\begin{algorithm}[t]
    \caption{$(\epsilon,\delta)$-LDP Coding-Assisted Succinct Histogram Protocol for the Unique Heavy Hitter Problem}\label{alg:LDPCASH}
    \begin{algorithmic}[1]
    % \REQUIRE a
    \renewcommand{\algorithmicrequire}{\textbf{Input:}}
    \renewcommand{\algorithmicensure}{\textbf{Output:}}
    \REQUIRE Clients' inputs $\{\mathbf{u}_i\in\mathbf{u}^*\cup\bot:i\in[N]\}$, privacy guarantee $\epsilon$ and $\delta$, sensitivity $\Delta$, and generator matrix $\mathbf{G}$ constructed by an $(n,k)$-polar code
    \ENSURE Succinct histogram $\left(\hat{\mathbf{u}},\hat{f}(\hat{\mathbf{u}})\right)$

% \vspace{0.3em}
%     \textbf{Clients:}
    \FOR{Client $i\in[N]$}
        \STATE If $\mathbf{u}_i\neq\bot$, client $i$ encodes then modulates its item $\mathbf{x}_i=\frac{1}{\sqrt{n}}(2\mathbf{v}_i-\mathbf{1}_n)=\frac{1}{\sqrt{n}}(2\mathbf{u}_i\mathbf{G}-\mathbf{1}_n)$. Else, $\mathbf{x}_i=\mathbf{0}_n$.
        \STATE Client $i$ randomized its private report $\mathbf{z}_i=\mathcal{R}_i\left(\mathbf{x}_i\right)=\mathbf{x}_i+\mathbf{n}_i$, where $\mathbf{n}_i$ is a vector that all entries are sampled from a zero mean Gaussian distribution $\mathcal{N}(0,\sigma^2)$ with $\sigma^2=\mathrm{AnalyticGaussian}(\epsilon,\delta,\Delta).$
        \STATE Client $i$ sends $\mathbf{z}_i$ to the server.
    \ENDFOR
    \STATE Server collects $\mathbf{z}_i$'s from clients $i\in[N]$.
    \STATE Server computes $\mathbf{y}=\frac{1}{N}\sum_{i\in[N]}\mathbf{z}_i$.
    \STATE Server calculates the LLR $\Tilde{\mathbf{y}}=\frac{2}{\sigma^2}\mathbf{y}$.
    \STATE Server decodes $\Tilde{\mathbf{y}}$ into an estimate for the unique item $\hat{\mathbf{u}}=\mathrm{Dec}(\Tilde{\mathbf{y}})$ by an SCL decoder.
    \STATE Server encodes then modulates its decoded item $\hat{\mathbf{x}}=\frac{1}{\sqrt{n}}(2\hat{\mathbf{v}}-\mathbf{1}_n)=\frac{1}{\sqrt{n}}(2\hat{\mathbf{u}}\mathbf{G}-\mathbf{1}_n)$.
    \STATE Server computes a frequency estimate $\hat{f}(\hat{\mathbf{u}})=\langle \hat{\mathbf{x}},\mathbf{y}\rangle$.
    \STATE \textbf{Return} the succinct histogram $\left(\hat{\mathbf{u}},\hat{f}(\hat{\mathbf{u}})\right)$
    \end{algorithmic}
\end{algorithm}
\begin{remark}
The major differences between our proposed protocol Algorithm~\ref{alg:LDPCASH} compared to the most relevant prior work \prot in \cite[Algorithm 2]{bassily2015local} are as follows: 
(1) We formulate the practical code construction for encoding the unique item to the codewords in step 2, which \prot did not specify the construction at all;
(2) The randomizers between our protocol and \prot are fundamentally different. \prot randomly picks the $j$th entry from $\mathbf{x}_i$, which is denoted by $x_{i,j}$, randomizes it to either $c_\epsilon n x_{i,j}$ or $-c_\epsilon n x_{i,j}$ according to the randomized response \cite{Warner01031965} when $\mathbf{x}_i\neq\mathbf{0}_n$, or assigning $c_\epsilon\sqrt{n}$ or $-c_\epsilon\sqrt{n}$ uniformly at random, while other entries are set to zeros. Our proposed protocol randomizes each entry by adding Gaussian noise.
% (1) We formulate the practical transformation of the unique item to the codewords in step 2, by defining the dimension of the unique item $\mathbf{u}_i$, the chosen binary linear block code with a generator matrix $\mathbf{G}$, that encodes the unique item to a codeword $\mathbf{v}_i=\mathbf{u}_i\mathbf{G}$, for $i\in[N]$, which \prot did not at all; 
(3) Our protocol enables flexibility in the soft-decision process by adding perturbations to the queries by the analytic Gaussian mechanism in step 3, that satisfy $(\epsilon,\delta)$-LDP with optimal noise. In \protns, a local randomizer inspired by randomized response was applied to perturb the queries, making it fundamentally binarized to a hard-decision process;
(4) The SCL decoder used in step 9 is a soft decoder, while \prot rounds $\mathbf{y}$ in our step 7 to $(-\frac{1}{\sqrt{n}},\frac{1}{\sqrt{n}})^n$, which is limited to a hard decoder. Section~\ref{sec:sim} demonstrates the significance of the decoder, especially when it comes to a low true frequency.
\end{remark}


\subsection{Error Analysis}
We analyze the error in the frequency estimation of the correctly decoded item, i.e., $\hat{\mathbf{u}}=\mathbf{u}^*$. The following lemma derives the expression of $\mathbf{y}$, which is the mean of collected $\mathbf{z}_i$'s from clients $i\in[N]$.
\begin{lemma}
\label{lem:y}
 The received vector at the server in step 7 in Algorithm~\ref{alg:LDPCASH} is 
 \begin{equation}
     \mathbf{y}=\frac{1}{N}\sum_{i\in[N]}\mathbf{z}_i=f(\mathbf{u}^*)\mathbf{x}^*+\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i,
 \end{equation}
\end{lemma}
\begin{proof}
Given that $\mathbf{z}_i=\mathbf{x}_i+\mathbf{n}_i$ for clients $i\in[N]$, we have 
    \begin{equation}
    \label{eq:y_sub1}
        \begin{aligned}
            \mathbf{y}&=\frac{1}{N}\sum_{i\in[N]}\mathbf{z}_i=\frac{1}{N}\sum_{i\in[N]}\mathbf{x}_i+\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\\
        \end{aligned}.
    \end{equation}
Then, note that $\mathbf{x}_i=\mathbf{x}^*$ for $i\in\mathcal{T}$ and $\mathbf{x}_i=\mathbf{0}_i$ for $i\in[N]\setminus\mathcal{T}$.
    \begin{equation}
    \label{eq:y_sub2}
        \begin{aligned}
            \frac{1}{N}\sum_{i\in[N]}\mathbf{x}_i
            &=\frac{1}{N}\left[\sum_{i\in\mathcal{T}}\mathbf{x}_i+\sum_{i\in[N]\setminus\mathcal{T}}\mathbf{x}_i\right]\\
            &=\frac{1}{N}\left[|\mathcal{T}|\cdot\mathbf{x}^*+\left(N-|\mathcal{T}|\right)\cdot\mathbf{0}_n\right]\\
            &=\frac{|\mathcal{T}|}{N}\mathbf{x}^*= f(\mathbf{u}^*)\mathbf{x}^*.
        \end{aligned}
    \end{equation}
    Combining \eqref{eq:y_sub1} and \eqref{eq:y_sub2} proves the statement.
