\begin{lemma}[Error analysis for the correctly decoded items]
\label{lem:Error Bound}
    Assuming the unique item is correctly decoded, i.e., $\hat{\mathbf{u}}=\mathbf{u}^*$, the frequency estimation error is expressed as follows:
    \begin{equation}
        \mathrm{Err}_{\hat{\mathbf{u}},\mathbf{u}^*}\overset{\mathrm{def}}{=}\left|\hat{f}(\hat{\mathbf{u}})-f(\mathbf{u^*})\right|=\left|\langle\mathbf{x}^*,\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle\right| .
    \end{equation}
    % \begin{equation}
    % \max_{\mathbf{u^*}, \hat{\mathbf{u}}}
    % |\hat{f}(\hat{\mathbf{u}})-f(\mathbf{u^*})| = \left|\frac{1}{2wN}\langle \hat{\mathbf{v}},\sum_{i=1}^{N}\mathbf{n}_i\rangle\right|,
    % \end{equation}
    % and $\hat{\mathbf{v}}=\hat{\mathbf{u}}\mathbf{G}$.
\end{lemma}
\begin{proof}
When we have the correct decoded item, we can substitute $\hat{\mathbf{u}}$ by $\mathbf{u}^*$, thus the problem becomes $\mathrm{Err}_{\hat{\mathbf{u}}=\mathbf{u}^*}=\left|\hat{f}({\mathbf{u}}^*)-f(\mathbf{u^*})\right|$. 
Given the frequency estimate $\hat{f}(\hat{\mathbf{u}})=\langle\hat{\mathbf{x}},\mathbf{y}\rangle$ in the protocol, plugging $\hat{\mathbf{u}}=\mathbf{u}^*$, we obtain that $\hat{f}({\mathbf{u}}^*)=\langle{\mathbf{x}^*},\mathbf{y}\rangle$, where $\hat{\mathbf{x}}=\mathbf{x}^*$, yields $\mathrm{Err}_{\hat{\mathbf{u}},\mathbf{u}^*}=\left|\langle{\mathbf{x}^*},\mathbf{y}\rangle-f(\mathbf{u}^*)\right|$. Then, with Lemma~\ref{lem:y} we have
\begin{equation}
\begin{aligned}   \mathrm{Err}_{\hat{\mathbf{u}}=\mathbf{u}^*} =&\left|\langle{\mathbf{x}^*},f(\mathbf{u}^*)\mathbf{x}^*+\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle-f(\mathbf{u}^*)\right|\\
    =&\left|f(\mathbf{u}^*)\langle{\mathbf{x}^*},\mathbf{x}^*\rangle+\langle{\mathbf{x}^*},\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle-f(\mathbf{u}^*)\right|\\
    =&\left|\langle\mathbf{x}^*,\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle\right|,
    % =&\left|\langle\frac{1}{\sqrt{n}}\left(2\mathbf{v}^*-\mathbf{1}_n\right),\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle\right|\\
    % =&\left|\frac{2}{\sqrt{n}}\langle\mathbf{v}^*,\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle-\frac{1}{\sqrt{n}}\langle\mathbf{1}_n,\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle\right|\\
    % =&\left|\frac{2}{\sqrt{n}}\langle\mathbf{v}^*,\frac{1}{N}\sum_{i\in[N]}\mathbf{n}_i\rangle-\frac{1}{\sqrt{n}N}\sum_{j\in[n]}\sum_{i\in[N]}n_{i,j}\right|
\end{aligned}
\end{equation}
where $\langle\mathbf{x}^*,\mathbf{x}^*\rangle=1$.
\end{proof}


