\section*{Appendix}
\section*{Proof of Lemma 1}

Let $\hat{\theta}$ be the minimum value of the local computation resources $\theta$ that satisfies the condition for a given reward reward $\gamma$ and communication resources $\mu$, i.e., $\hat{\theta} = \min\{\theta\in\Theta:c(\theta,\mu)\le\gamma\}$, and given any $\mu_1, \mu_2 \in [\underline{\tau},\overline{\tau}]$, we can drive the corresponding $\hat{\theta}_1$ and $\hat{\theta}_2$, respectively:
\begin{equation}
	\begin{cases}
		\hat{\theta}_1 = \min \{ \theta\in\Theta:c(\theta,\mu_1) \le \gamma \},\\
		\hat{\theta}_2 = \min \{ \theta\in\Theta:c(\theta,\mu_2) \le \gamma \}.\\
	\end{cases}
\end{equation}
According to the definition of $\hat{\theta}$, the following inequalities hold:
\begin{equation}
	\begin{cases}
		c(\hat{\theta}_1,\mu_1) \le \gamma, \\
		c(\hat{\theta}_2,\mu_2) \le \gamma. \\
	\end{cases}
\end{equation}

According to Assumption 1, where $c(\theta,\tau)$ is a convex function with respect to both $\theta$ and $\tau$, i.e., $c(\lambda\hat{\theta}_1 + (1-\lambda)\hat{\theta}_2,\lambda \mu_1+(1-\lambda)\mu_2)\le\lambda c(\hat{\theta}_1,\mu_1)+(1-\lambda)c(\hat{\theta}_2,\mu_2)$, we can derive the following inequality:
\begin{equation}
	c(\lambda\hat{\theta}_1 + (1-\lambda)\hat{\theta}_2,\lambda \mu_1+(1-\lambda)\mu_2)\le \gamma,
\end{equation}
where $\lambda\in[0,1]$. Therefore, $\lambda\hat{\theta}_1 + (1-\lambda)\hat{\theta}_2$ is a feasible solution to the constraint $c(\theta,\lambda \mu_1+(1-\lambda)\mu_2) \le \gamma$. Since $\hat{\theta}$ is the minimum value that satisfies constraint $\{\theta\in\Theta:c(\theta,\mu)\le\gamma\}$, we have
\begin{equation}
	\begin{split}
		&\min\{\theta\in\Theta: c(\theta,\lambda \mu_1+(1-\lambda)\mu_2)\le\gamma\} \\&
		\hspace{2em} \le \lambda\hat{\theta}_1 + (1-\lambda)\hat{\theta}_2 \\&
		\hspace{2em} \le \lambda \min \{ \theta\in\Theta:c(\theta,\mu_1) \le \gamma \} \\&
		\hspace{2em} + (1-\lambda)\min \{ \theta\in\Theta:c(\theta,\mu_2) \le \gamma \}.
	\end{split}
\end{equation}
Therefore, $\min\{\theta\in\Theta: c(\theta,\lambda \mu_1+(1-\lambda)\mu_2)\le\gamma\}$ is a convex function with respect to $\mu$ [Cui \textit{et al.}, 2023; Boyd, 2004]. Since $s(\hat{\theta})$ is a concave function with respect to $\hat{\theta}$, as defined in Assumption 2, and $\hat{\theta}$ is determined by $\gamma$ and $\mu$. We can conclude that $s(\gamma,\mu)$ is also a concave function with respect to $\mu$. 

With a fixed $\gamma$, we simplify $s(\gamma,\mu)$ as $s(\mu)$, and define $\textit{conv}(s)$ as the convex hull of the graph of $s(\mu)$, and $\underline{s}(\mu)$ is the minimum value in $\textit{conv}(s)$, i.e., $\underline{s}(\mu) = \sup \{ s(\mu) | (\mu, s) \in \textit{conv}(\mu) \}$. For each point in $\textit{conv}(s)$, i.e., $(\mu, s) \in \textit{conv}(\mu)$, there exists a posterior distribution such that $\mu$ and $s$ equal the expected values of the posterior belief, respectively. Given a prior value $\mu$, the minimum value inside the convex hull is $\underline{s}(\mu)$. Therefore, there exist optimal signals $\rho$, and the value of optimal signal lies on  $\underline{s}(\mu)$.

With a fixed $\rho$, there exists an optimal reward $\gamma$ subject to the computation resource threshold $\beta$, based on the monotonicity and continuity properties of the cost function with respect to $\gamma$. As a result, the proof is completed.


\section*{Proof of Theorem 1}

According to Lemma 1, there exists an optimal signal $\rho$ associated with specific posterior beliefs which satisfy Bayesian plausible condition. The signal minimize the server’s cost within the convex hull $\textit{conv}(\mu)$, and the optimal signals lies on $\underline{s}(\mu)$. Any point within the convex hull $\textit{conv}(\mu)$ can be represented as a linear combinations of any set of points within the convex hull. The optimal signal structure can be achieved through the two extreme point. This is because the two extreme points represent the potential boundary cases, and any point within the convex hull can be determined as a convex combination of these boundary cases. According to the second item of Assumption 2, the optimal signals lies at $\underline{\tau}$ and $\overline{\tau}$, where $\tau\in[\underline{\tau}, \overline{\tau}]$.

Based on the Bayesian Consistency and the Bayesian plausible defined in Definitions 2 and 3, respectively, we can derive the following equations from the above analysis of the optimal signals:

\begin{equation}
	\label{eq23}
	\begin{cases}
		\int_0^1\lambda(\underline{\tau}) \rho(\mu|\underline{\tau})\mu + \lambda(\bar{\tau})\rho(\mu|\bar{\tau})\mu d\mu = \lambda(\underline{\tau})\underline{\tau} + \lambda(\bar{\tau})\bar{\tau},\\
		\frac{\lambda(\underline{\tau})\rho(\mu|\underline{\tau})\underline{\tau} + \lambda(\bar{\tau})\rho(\mu|\bar{\tau})\bar{\tau}}{\lambda(\underline{\tau})\rho(\mu|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu|\bar{\tau})}=\mu.\\
	\end{cases}
\end{equation}
Based on the first sub formula in Eq. (\ref{eq23}), we can obtain  $\lambda(\underline{\tau}) \rho(\mu|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu|\bar{\tau}) = \frac{ \lambda(\underline{\tau})\underline{\tau} + \lambda(\bar{\tau})\bar{\tau} }{\mu}$. Then, we define $\rho(\mu) = \lambda(\underline{\tau}) \rho(\mu|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu|\bar{\tau})$ , and derive the optimal signals as follows:
\begin{equation}
	\begin{cases}
		\rho(\mu|\underline{\tau})=\frac{\rho(\mu)(\overline{\tau}-\mu)}{\lambda(\underline{\tau})(\overline{\tau} - \underline{\tau})},\\
		\rho(\mu|\overline{\tau})=\frac{\rho(\mu)(\mu-\underline{\tau})}{\lambda(\overline{\tau})(\overline{\tau} - \underline{\tau})}.
	\end{cases}
\end{equation}

Under the optimal signals, we can derive that the server’s cost function is 

\begin{equation}
	\begin{split}
		&c_s(\gamma, \rho^*) =\gamma [\lambda(\underline{\tau})\int_0^1\rho(\mu|\underline{\tau}) p(\gamma,\mu) d\mu \\& 
		\hspace{2em}+ \lambda(\overline{\tau})\int_0^1\rho(\mu|\overline{\tau}) p(\gamma,\mu) d\mu ]  \\&
		\hspace{2em}= \gamma\int_0^1\rho(\mu)p(\gamma,\mu)d\mu.
	\end{split}
\end{equation}
Based on the monotonicity and continuity properties of the cost function with respect to $\gamma$, we can derive that $\gamma^* =  \arg\min\gamma\int_0^1\rho(\mu)p(\gamma,\mu)d\mu$. As a result, the proof is completed.

\section*{Proof of Lemma 2}

The true reward probability associated with a given computation resources threshold is defined as $p$. This computation resources threshold has been selected for $n$ times, out of which $n_r$ instances have resulted in a reward. Therefore, its predicted reward probability is given by $\tilde{p} = \frac{n_r}{n}$. If $\delta$ can be determined such that $p\le \tilde{p} + \delta$, then $\tilde{p} + \delta$ is the upper confidence bound of the true reward probability $p$. According to Hoeffding’s inequality, $P\{ p-\tilde{p} \le \delta \} \ge 1-e^{-2n\delta^2}$. The inequality $p-\tilde{p} \le \delta$ always holds when $1-e^{-2n\delta^2} = \frac{N-1}{N}$, where  $\delta = \sqrt{\frac{\ln N}{2n}}$. As $n = N_t(\hat{\theta})$, $n_r = \sum_{n\in\mathcal{N}_t(\hat{\theta})}\mathbf{1}(\gamma_n \ge c(\theta_n,\mu_n))$. Then,  we have $\tilde{p} + \delta = \frac{\sum_{n\in\mathcal{N}_t(\hat{\theta})}\mathbf{1}(\gamma_n \ge c(\theta_n,\mu_n))}{{N_t(\hat{\theta})}} + \sqrt{\frac{\ln N}{2N_t(\hat{\theta})}}$. As a result, the proof is completed.


\section*{Proof of Theorem 2}

Let the optimal reward be $\gamma^*$, and the approximate optimal reward in the discrete space $R$ as $\gamma^+$, we have $\gamma^*+\xi \le \gamma^+ \le \gamma^*+2\xi$, where $\gamma^+\in R$. According to the definition of the minimum threshold for a client’s computation resources $\hat{\theta}$ with a fixed $\gamma$ and $\mu$, we can derive the following:
\begin{equation}
	\begin{cases}
		\hat{\theta}^*= \min \{\theta | \mathbf{1}(\gamma^*\ge c(\theta,\mu))\}), \\
		\hat{\theta}^+= \min \{\theta | \mathbf{1}(\gamma^+\ge c(\theta,\mu))\}). \\
	\end{cases}
\end{equation}
Let $(z-1)\xi\le \hat{\theta}^+ \le z\xi$, where $z\in\mathbb{Z}^+$, we have
\begin{equation}
	\begin{cases}
		(z-1)\xi = \min \{\theta | \mathbf{1}(\gamma^+ \ge c(\theta,\mu_r))\}), \\
		z\xi = \min \{\theta | \mathbf{1}(\gamma^+\ge c(\theta,\mu_l))\}), \\
	\end{cases}
\end{equation}
where $\mu_l < \mu < \mu_r$. According to the Bayesian Consistency and Bayesian plausible, the signals for $\mu_l$ and $\mu_r$ are given as follows:
\begin{equation}
	\begin{cases}
		\frac{
			\lambda(\underline{\tau})\rho(\mu_l|\underline{\tau})\underline{\tau} + \lambda(\bar{\tau})\rho(\mu_l|\bar{\tau})\bar{\tau}
		}{
			\lambda(\underline{\tau})\rho(\mu_l|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu_l|\bar{\tau})
		}
		=
		\mu_l,\\

		\frac{
			\lambda(\underline{\tau})\rho(\mu_r|\underline{\tau})\underline{\tau} + \lambda(\bar{\tau})\rho(\mu_r|\bar{\tau})\bar{\tau}
		}{
			\lambda(\underline{\tau})\rho(\mu_r|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu_r|\bar{\tau})
		}
		=
		\mu_r.
	\end{cases}
\end{equation}

Let $\rho(\mu_l) = \lambda(\underline{\tau}) \rho(\mu_l|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu_l|\bar{\tau})$ and $\rho(\mu_r) = \lambda(\underline{\tau}) \rho(\mu_r|\underline{\tau}) + \lambda(\bar{\tau})\rho(\mu_r|\bar{\tau})$, the approximate optimal signal is given by:
\begin{equation}
	\begin{cases}
		\rho(\mu_l|\underline{\tau})=\frac{\rho(\mu_l)(\overline{\tau}-\mu_l)}{\lambda(\underline{\tau})(\overline{\tau} - \underline{\tau})},\\
		\rho(\mu_l|\overline{\tau})=\frac{\rho(\mu_l)(\mu_l-\underline{\tau})}{\lambda(\overline{\tau})(\overline{\tau} - \underline{\tau})},\\
		\rho(\mu_r|\underline{\tau})=\frac{\rho(\mu_r)(\overline{\tau}-\mu_r)}{\lambda(\underline{\tau})(\overline{\tau} - \underline{\tau})},\\
		\rho(\mu_r|\overline{\tau})=\frac{\rho(\mu_r)(\mu_r-\underline{\tau})}{\lambda(\overline{\tau})(\overline{\tau} - \underline{\tau})},\\
	\end{cases}
\end{equation}
As a result, the proof is completed.


\section*{Proof of Theorem 3}

The optimal reward is denoted by $\gamma^*$, and the approximate reward is denoted by $\gamma^+$, where $\gamma^* +\xi \le \gamma^+ \le \gamma^* +2\xi$. Since higher reward leads to lower computation resources threshold in $\hat{\theta} = \min \{\theta | \mathbf{1}(\gamma\ge c(\theta,\mu))\}$ with a fixed $\rho$, it follows that $s(\gamma^*,\mu) \ge s(\gamma^+,\mu)$. Then, the difference in the server’s cost between the approximate optimal signal $\rho^+$ and reward $\gamma^+$, and optimal signal  $\rho^*$ and reward $\gamma^*$, is given by
\begin{equation}
	\begin{split}
		&\gamma^+ \int_0^1 \lambda(\tau)\int_0^1\rho^+(\mu|\tau) s(\gamma^+,\mu) d\mu d\tau
		\\& \hspace{2em} - \gamma^* \int_0^1 \lambda(\tau)\int_0^1\rho^*(\mu|\tau) s(\gamma^*,\mu) d\mu d\tau 
		\\& \hspace{2em} \le  (\gamma^* + 2\xi) \int_0^1 \lambda(\tau)\int_0^1\rho^+(\mu|\tau) s(\gamma^+,\mu) d\mu d\tau 
		\\& \hspace{2em} -  \gamma^* \int_0^1 \lambda(\tau)\int_0^1\rho^*(\mu|\tau) s(\gamma^*,\mu) d\mu d\tau 
		\\& \hspace{2em} \le \gamma^* \int_0^1 \lambda(\tau)\int_0^1\rho^+(\mu|\tau) s(\gamma^+,\mu) d\mu d\tau 
		\\& \hspace{2em} - \gamma^* \int_0^1 \lambda(\tau)\int_0^1\rho^*(\mu|\tau) s(\gamma^*,\mu) d\mu d\tau +2\xi 
		\\& \hspace{2em} \le 2\xi.
	\end{split}
\end{equation}
As a result, the proof is completed.


