\section{Proofs of Main Results}
\label{sec:proofs-main-results}
\subsection{Achievability and Converse Proof of Theorem~\ref{thm:public-time-sharing}}\label{sec:achievabilityproof_PTS}
Under public time-sharing, denote $x_1^{\lambda n}(w_1)$ (resp. $x_2^{\overline{\lambda}n}(w_2)$) the codeword encoding User 1's message $w_1$ (resp. User 2's message $w_2$). The distribution induced at the eavesdropper's channel output becomes
\begin{align}
    \widehat{Q}^n(z^n) &= \widehat{Q}^{\lambda n}_1(z^{\lambda n})\times\widehat{Q}^{\overline{\lambda}n}_2(z^{\lambda n+1:n}),\label{eq:pts_structure}
\end{align}
where
\begin{align}
    \widehat{Q}_1^{\lambda n}(z^{\lambda n}) &= \frac{1}{M_1}\sum_{w_1=1}^{M_1}W_{Z|X_1X_2}^{\otimes n}(z^{\lambda n}|x_1^{\lambda n}(w_1),0^{\lambda n}),\\
    \widehat{Q}_2^{\overline{\lambda} n}(z^{\overline{\lambda} n}) &= \frac{1}{M_2}\sum_{w_2=1}^{M_2}W_{Z|X_1X_2}^{\otimes n}(z^{\overline{\lambda} n}|0^{\overline{\lambda} n},x_2^{\overline{\lambda} n}(w_2)).
\end{align}
Now, considering the structure of the eavesdropper output distribution in~(\ref{eq:pts_structure}), our covertness metric becomes
\begin{align}
    &\D{\widehat{Q}^n}{Q_{00}^{\otimes n}} = \D{\widehat{Q}_1^{\lambda n}}{Q_{00}^{\otimes \lambda n}}+\D{\widehat{Q}_2^{\overline{\lambda} n}}{Q_{00}^{\otimes \overline{\lambda}n}}.
    \label{eq:red_ptp}
\end{align}
We introduce $\delta_1\eqdef\limsup_{n\to\infty}\D{\smash{\widehat{Q}^{\lambda n}_1}}{\smash{Q_{00}^{\otimes \lambda n}}}$ to parametrize the covertness budget allocated to User 1 during the first $\lambda n$ channel uses. Because of~\eqref{eq:red_ptp}, the two-way covert communication under public time-sharing reduces to two independent point-to-point covert communication problems. From~\cite{Bloch2015b}, in order to maximize the throughput in the point-to-point case, we need to use all of the allocated covertness budget. Hence, by incorporating this result with the definition of $\delta_1$, we shall assume that $\limsup_{n\to\infty}\D{\smash{\widehat{Q}_2^{\overline{\lambda} n}}}{\smash{Q_{00}^{\otimes \overline{\lambda} n}}}=\delta-\delta_1$ to satisfy the overall constraint
\begin{equation}
    \limsup_{n\to\infty}\D{\widehat{Q}^n}{Q_{00}^{\otimes n}}=\delta.
\end{equation}

The characterization of the covert capacity under public time sharing implicitly requires the identification of the optimal covertness budget $\delta_1$ in terms of the time-sharing parameter $\lambda$. As in~\cite{Tan2019}, we shall show that $\delta_1(\lambda)=\lambda\delta$ is optimal, though our proof is different because~\cite{Tan2019} follows a different converse argument.
\begin{proposition}
  \label{prop:achiv_pts}
  For any $\mu\in(0,1)$, $\lambda\in[0,1]$, $\delta_1\in(0,\delta)$, there exists a public time-sharing scheme such that
  \begin{align*}
        &\lim_{n\to\infty}\frac{\log M_1}{\sqrt{\lambda n\delta_1}}\geq (1-\mu)\sqrt{\frac{2}{\chi_2\left(Q_{10}\Vert Q_{00}\right)}}\D{P^{(2)}_{10}}{P^{(2)}_{00}},\\
    &\lim_{n\to\infty}\frac{\log M_2}{\sqrt{\overline{\lambda} n(\delta-\delta_1)}}\geq(1-\mu)\sqrt{\frac{2}{\chi_2\left(Q_{01}\Vert Q_{00}\right)}}\D{P^{(1)}_{01}}{P^{(1)}_{00}},\\
    &\lim_{n\to\infty} P_e^{(n)} = 0,
      \qquad \limsup_{n\to\infty} \D{\widehat{Q}^n}{Q_{00}^{\otimes n}} \leq\delta.
  \end{align*}
\end{proposition}
\begin{IEEEproof}
  By~(\ref{eq:red_ptp}), we split the covertness condition across two independent sub-blocks of length $\lambda n$ and $\overline{\lambda}n$, respectively, in which a single user is transmitting an encoded message with covertness constraint $\delta_1$, and $\delta-\delta_1$, respectively. By adapting the point-to-point covert achievability result~\cite[Theorem 2]{Bloch2015b}, there exists a public time-sharing scheme satisfying the conditions of the proposition.
\end{IEEEproof}
\begin{proposition}
  \label{prop:converse_pts}
  if $\lim_{n\to\infty} P_e^{(n)} = 0$ and $\limsup_{n\to\infty} \D{\smash{\widehat{Q}^n}}{Q_{00}^{\otimes n}} \leq\delta$, any public time-sharing scheme allocating a fraction $\lambda\in[0,1]$ of channel uses to User 1 and a covertness constraint $\delta_1\in(0,\delta)$ so that $\D{\smash{\widehat{Q}_1^{\lambda n}}}{Q_{00}^{\otimes \lambda n}}=\delta_1$ must satisfy
  \begin{align*}
        &\lim_{n\to\infty}\frac{\log M_1}{\sqrt{\lambda n\delta_1}}\leq\sqrt{\frac{2}{\chi_2\left(Q_{10}\Vert Q_{00}\right)}}\D{P^{(2)}_{10}}{P^{(2)}_{00}},\\
    &\lim_{n\to\infty}\frac{\log M_2}{\sqrt{\overline{\lambda} n(\delta-\delta_1)}}\leq\sqrt{\frac{2}{\chi_2\left(Q_{01}\Vert Q_{00}\right)}}\D{P^{(1)}_{01}}{P^{(1)}_{00}}.
  \end{align*}
\end{proposition}
\begin{IEEEproof}
  The result follows by applying the point-to-point converse result from~\cite[Theorem 3]{Bloch2015b}.
\end{IEEEproof}
Together, Proposition~\ref{prop:achiv_pts} and Proposition~\ref{prop:converse_pts} show that the public time-sharing covert capacity region is
\begin{align}
\calC_{\textnormal{PTS}} = \bigcup_{\lambda\in[0,1]}\bigcup_{\delta_1\in(0,\delta)}\left\{
  \begin{array}{l}
    (r_1,r_2)\in\bbR^2_+:\\
    r_1 \leq \sqrt{\frac{2\lambda\delta_1}{\delta\chi_2\left(Q_{10}\Vert Q_{00}\right)}}\D{P^{(2)}_{10}}{P^{(2)}_{00}}\\
    r_2\leq \sqrt{\frac{2\overline{\lambda}(\delta-\delta_1)}{\delta\chi_2\left(Q_{01}\Vert Q_{00}\right)}}\D{P^{(1)}_{01}}{P^{(1)}_{00}}
  \end{array}
  \right\}.
  \label{eq:full_charac_cpts}
\end{align}
The boundary of the region $\calC_{\textnormal{PTS}}$ can be further characterized by identifying the relationship between $\delta_1$ and $\lambda$ on the boundary as shown next.

\begin{lemma}\label{lm:opt_param}
    The parameterization of the covertness budget $\delta_1$ that corresponds to the boundary of the covert capacity region in terms of the time-sharing parameter $\lambda$ is $\delta_1(\lambda)=\lambda\delta$.
\end{lemma}
\begin{IEEEproof}
    We parameterize the boundary of the public time-sharing covert capacity region such that our free parameter for covertness is a function of our time-sharing parameter, i.e., $\delta_1=\delta_1(\lambda)$ with boundary conditions, $\delta_1(0)=0,\delta_1(1)=\delta$. These boundary conditions correspond to the maximum throughputs $r_1$ and $r_2$, respectively, that one can achieve. The area of the covert capacity region is a functional of $\delta_1$, $A(\delta_1)$  given by
\begin{align}
    A(\delta_1) &= \int r_2\mathrm{d}r_1 = \int\displaylimits_0^1 r_2(\lambda)\dot{r}_1(\lambda)\mathrm{d}\lambda
\end{align}
where the last equality follows by a change of variables. In this parameterization, we set for simplicity $r_1(\lambda,\delta_1)\eqdef\sqrt{\lambda\delta_1}$ and $r_2(\lambda_1,\delta)\eqdef\sqrt{\overline{\lambda}(\delta-\delta_1)}$, since the multiplicative terms in~(\ref{eq:full_charac_cpts}) are constants independent of the parameterization and we assume that ${\D{\smash{P^{(2)}_{10}}}{\smash{P^{(2)}_{00}}}}\geq \D{Q_{10}}{Q_{00}}$ and ${\D{\smash{P^{(1)}_{01}}}{\smash{P^{(1)}_{00}}}}\geq \D{Q_{01}}{Q_{00}}$. Hence,
\begin{align}
    \dot{r_1}(\lambda,\delta_1,\dot{\delta}_1) &= \frac{\partial r_1}{\partial \lambda}+\frac{\partial r_1}{\partial \delta_1}\dot{\delta}_1= \frac{1}{2}\left(\sqrt{\frac{\delta_1}{\lambda}}+\dot{\delta}_1\sqrt{\frac{\lambda}{\delta_1}}\right).
\end{align}

To maximize our area functional, we use the following fundamental result from calculus of variations, reduced to the one-dimensional case,
\begin{theorem}[{\cite[Theorem 1]{gelfand2012calculus}}] \label{th:EL}
    Let $\calP(a,b,x_a,x_b)$ be the set of smooth paths $q:[a,b]\to\bbR$ for which $q(a)=x_a$, $q(b)=x_b$ and let $\calL(t,q,v)$ be the Lagrangian, a smooth real-valued function. The action functional $S:\calP(a,b,x_a,x_b)\to\bbR$ is defined as
    \begin{align}
        S[q] = \int\displaylimits_a^b\calL(t,q(t),\dot{q}(t))\mathrm{d}t.
    \end{align}
    A path $q\in\calP(a,b,x_a,x_b)$ is a stationary point, extremal, of $S$ if and only if it satisfies the Euler-Lagrange equation,
    \begin{align}
        \frac{\partial\calL}{\partial q}(t,q(t),\dot{q}(t))-\frac{\mathrm{d}}{\mathrm{d}t}\frac{\partial\calL}{\partial \dot{q}}(t,q(t),\dot{q}(t))=0.\label{eq:EL}
    \end{align}
  \end{theorem}

Using the notation of Theorem~\ref{th:EL}, the Lagrangian of the area functional $A(\delta_1)$ is
\begin{align}
    \calL(\lambda,\delta_1,\dot{\delta}_1) = \frac{1}{2}\left(\sqrt{\frac{\delta_1}{\lambda}}+\dot{\delta}_1\sqrt{\frac{\lambda}{\delta_1}}\right)\sqrt{\overline{\lambda}(\delta-\delta_1)}.
\end{align}
The derivatives of the Lagrangian are,
\begin{align}
    \frac{\partial \calL}{\partial \delta_1}(\lambda,\delta_1,\dot{\delta}_1) &= \frac{1}{4}\left(\sqrt{\frac{\overline{\lambda}(\delta-\delta_1)}{\lambda\delta_1}}-\frac{\dot{\delta}_1}{\delta_1}\sqrt{\frac{\lambda\overline{\lambda}(\delta-\delta_1)}{\delta_1}}-\sqrt{\frac{\overline{\lambda}\delta_1}{\lambda(\delta-\delta_1)}}-\dot{\delta}_1\sqrt{\frac{\lambda\overline{\lambda}}{\delta_1(\delta-\delta_1)}}\right),\label{eq:gradL}\\
    \frac{\partial \calL}{\partial\dot{\delta}_1}(\lambda,\delta_1,\dot{\delta}_1) &= \frac{1}{2}\sqrt{\frac{\lambda\overline{\lambda}(\delta-\delta_1)}{\delta_1}},\\
    \frac{\mathrm{d}}{\mathrm{d}\lambda}\frac{\partial \calL}{\partial\dot{\delta}_1}(\lambda,\delta_1,\dot{\delta}_1) &= \frac{1}{4}\left(\sqrt{\frac{\overline{\lambda}(\delta-\delta_1)}{\lambda\delta_1}}-\sqrt{\frac{\lambda(\delta-\delta_1)}{\overline{\lambda}\delta_1}}-\frac{\dot{\delta}_1}{\delta_1}\sqrt{\frac{\lambda\overline{\lambda}(\delta-\delta_1)}{\delta_1}}-\dot{\delta}_1\sqrt{\frac{\lambda\overline{\lambda}}{\delta_1(\delta-\delta_1)}}\right).\label{eq:derL}
\end{align}
By substituting \eqref{eq:gradL} and \eqref{eq:derL} into the Euler-Lagrange equation \eqref{eq:EL}, we obtain after simplification
\begin{align}
    \sqrt{\frac{\overline{\lambda}\delta_1}{\lambda(\delta-\delta_1)}}=\sqrt{\frac{\lambda(\delta-\delta_1)}{\overline{\lambda}\delta_1}},
\end{align}
which reduces to $\delta_1=\lambda\delta$. By Theorem~\ref{th:EL} the parameterization $\delta_1(\lambda)=\lambda\delta$ is the unique extremal of the area functional $A$.
\end{IEEEproof}
Substituting the characterization provided by Lemma~\ref{lm:opt_param} in~(\ref{eq:full_charac_cpts}) yields the result of Theorem~\ref{thm:public-time-sharing}.

\subsection{Achievability Proof of Theorem~\ref{thm:capacity}}\label{sec:achievabilityproof2}
We shall prove the following achievability result.
\begin{proposition}
  \label{prop:achievability_proof2}
  For any $\mu\in(0,1)$ and  $\lambda\in[0,1]$, there exists a sequence of coding schemes such that
  \begin{align*}
    &r_1\geq \left(1-\mu\right)c_\lambda\lambda\D{P^{(2)}_{10}}{P^{(2)}_{00}},\\
    &r_1\leq \left(1+\mu\right)c_\lambda\lambda\D{Q_{10}}{Q_{00}},\\
    &r_2\geq \left(1-\mu\right)c_\lambda\overline{\lambda}\D{P^{(1)}_{01}}{P^{(1)}_{00}},\\
    &r_2\leq \left(1+\mu\right)c_\lambda\overline{\lambda}\D{Q_{01}}{Q_{00}},\\
    &\lim_{n\to\infty} P_e^{(n)} = 0,
      \qquad \limsup_{n\to\infty} \D{\widehat{Q}^n}{Q_{00}^{\otimes n}} \leq\delta,
  \end{align*}
  where $c_\lambda\eqdef \sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}\Vert Q_{00}\right)}}$.
\end{proposition}
\begin{IEEEproof}
  The general approach is inspired by~\cite{Helhal2018a}. We use a block Markov coding scheme with $B$ blocks of length $n$, where $B$ is a constant independent of $n$. In each block $b\in\intseq{1}{B}$, we analyze reliability and covertness assuming the existence of a common secret message $W_0^{(b)}$ that facilitates coordination. To justify the existence of $W_0^{(b)}$, we require each user $i\in\set{1,2}$ to split its message  $W_i^{(b)}$ into a secret part $W_i^{s,(b)}$, to be kept hidden from the eavesdropper, and a public part $W_i^{p,(b)}$. Since both users eventually get to reconstruct both $W_1^{s,(b)}$ and $W_2^{s,(b)}$, the pair $(W_1^{s,(b)},W_2^{s,(b)})$ can serve as the common secret message $W_0^{(b+1)}$ in block $b+1$. This mode of operation creates a dependence across blocks, which is illustrated by the functional dependence graph in Fig.~\ref{fig:cod_dep}. The crux of our proof is to first show how to achieve reliability, covertness, and secrecy in each block $b$ and then show how the dependence across blocks does not compromise reliability and covertness.
\begin{figure}[h]
    \centering
    \includegraphics[width=0.7\linewidth]{Figures/twc_FDG.pdf}
    \caption{Functional dependence graph of the proposed coding scheme. In every block $b$, User $i\in\set{1,2}$ transmits a secret message $W_i^{s,(b)}$ and a public message $W_i^{p,(b)}$ using a common message $W_0^{(b)}$ for coordination. The codewords sent through the channel are $X^{n,(b)}_{1}$ and $X^{n,(b)}_{2}$, respectively, resulting in received signals $Y^{n,(b)}_{1}$ and $Y^{n,(b)}_{2}$ at the users and $Z^{n,(b)}$ at the eavesdropper. The secret messages are used to create the common message $W_0^{(b+1)}$ in the next block.}
    \label{fig:cod_dep}
\end{figure}

\textit{a) Random codebook generation and decoder:} Consider the distributions $P_{UX_1X_2}$ and $Q_Z$ defined in~\eqref{eq:STS_dist} and~(\ref{eq:qz_ts2}). For every block $b\in\intseq{1}{B}$:
\begin{itemize}
    \item Independently generate $M_0$ codewords according to $P_U^{\otimes n}$ and label them $u^n(w_0^{(b)})$ where $w_0^{(b)}\in\intseq{1}{M_0}$.
    \item For every $w_0^{(b)}$, independently generate $M_1^pM_1^s$ codewords according to $\prod_{i=1}^nP_{X_1|U=u^n_i(w_0^{(b)})}$; label them $x_1^n(w_1^{p,(b)},w_1^{s,(b)},w_0^{(b)})$ for $w_1^{p,(b)}\in\intseq{1}{M_1^p}$ and $w_1^{s,(b)}\in\intseq{1}{M_1^s}$. Set $w_1^{(b)}\eqdef(w_1^{p,(b)},w_1^{s,(b)})$.
    \item For every $w_0^{(b)}$, independently generate $M_2^pM_2^s$ codewords according to $\prod_{i=1}^nP_{X_2|U=u^n_i(w_0^{(b)})}$; label them $x_2^n(w_2^{p,(b)},w_2^{s,(b)},w_0^{(b)})$ for $w_2^{p,(b)}\in\intseq{1}{M_2^p}$ and $w_2^{s,(b)}\in\intseq{1}{M_2^s}$. Set $w_2^{(b)}\eqdef(w_2^{p,(b)},w_2^{s,(b)})$.
\end{itemize}
Define the codebook $\calC_n^{(b)}$ for block $b$ as
\begin{multline}
    \calC_n^{(b)} \eqdef \left\{u^n(w_0^{(b)}),x_1^n(w_1^{p,(b)},w_1^{s,(b)},w_0^{(b)}),x_2^n(w_2^{p,(b)},w_2^{s,(b)},w_0^{(b)})):\right.\\ \left.w_0^{(b)}\in\intseq{1}{M_0},w_1^{p,(b)}\in\intseq{1}{M_1^p},w_1^{s,(b)}\in\intseq{1}{M_1^s},w_2^{p,(b)}\in\intseq{1}{M_2^p},w_2^{s,(b)}\in\intseq{1}{M_2^s}\right\}.
\end{multline}
The random codebook is denoted by $C_n^{(b)}$. The transmission of codewords $x_1^n(w_1^{p,(b)},w_1^{s,(b)},w_0^{(b)})$ and $x_2^n(w_2^{p,(b)},w_2^{s,(b)},w_0^{(b)})$ in block $b$ over the discrete memoryless two-way channel results in observations $y_1^{n,(b)}$, $y_2^{n,(b)}, z^{n,(b)}$ at User 1, User 2, and the eavesdropper, respectively.

For a fixed $\mu\in(0,1)$, the decoders in every block rely on threshold decoding with the sets
\begin{align*}
  \calA_{1,\gamma_1}^n &\eqdef \left\{\begin{array}{l}\left(x_1^n,x_2^n,y_2^n,u^n\right)\in\calX_1^n\times\calX_2^n\times\calY_2^n\times\calU^n:\\
  \log\frac{W_{Y_2|X_1X_2}^{\otimes n}(y_2^n|x_1^n,x_2^n)}{P_{Y_2|X_2U}^{\otimes n}(y_2^n|x_2^n,u^n)}\geq \gamma_1\end{array}\right\},\\
  \calA_{2,\gamma_2}^n &\eqdef \left\{\begin{array}{l}\left(x_1^n,x_2^n,y_1^n,u^n\right)\in\calX_1^n\times\calX_2^n\times\calY_1^n\times\calU^n:\\
  \log\frac{W_{Y_1|X_1X_2}^{\otimes n}(y_1^n|x_1^n,x_2^n)}{P_{Y_1|X_2U}^{\otimes n}(y_1^n|x_1^n,u^n)}\geq \gamma_2\end{array}\right\},
\end{align*}
with $\gamma_1\eqdef(1-\mu)n\I{X_1}{Y_2|X_2,U}$ and $\gamma_2\eqdef(1-\mu)n\I{X_2}{Y_1|X_1,U}$. Specifically, knowing $w_0^{(b)}$ and $w_2^{(b)}$, User $2$ decodes $w_1^{(b)}$ as $w_1$ if $w_1$ is the unique message $w_1\in\intseq{1}{M_1}$ such that $(x_1^n(w_1, w_0^{(b)}), x_2^n(w_2^{(b)}, w_0^{(b)}), y_2^n, u^n(w_0^{(b)})) \in \mathcal{A}_{1,\gamma_1}^n$; else, User 2 declares a decoding error. Similarly, knowing $w_0^{(b)}$ qnd $w_1^{(b)}$, User $1$ decodes $w_2^{(b)}$ as $w_2$ if $w_2$ is the unique message $w_2\in\intseq{1}{M_2}$ such that $(x_1^n(w_1^{(b)}, w_0^{(b)}), x_2^n(w_2, w_0^{(b)}), y_1^n, u^n(w_0^{(b)})) \in \mathcal{A}_{2,\gamma_2}^n$; else, User 1 declares a decoding error.

\textit{b) Channel reliability analysis in every block:} The following holds.
\begin{lemma}
    \label{lm:reliability2}
    For any $\mu\in(0,1)$, $n$ large enough, and every block $b\in\intseq{1}{B}$, if the common message $W_0^{(b)}$ is known by legitimate users and if
    \begin{align}
        &\log M_1 < (1-\mu)q_1p_1n^{\frac{1}{2}}\D{P^{(2)}_{10}}{P^{(2)}_{00}},\\
        &\log M_2 < (1-\mu)q_2p_2n^{\frac{1}{2}}\D{P^{(1)}_{01}}{P^{(1)}_{00}},
    \end{align}
    the decoding error probability $P_e^{(b)}\eqdef \P{(\widehat{W}_1^{(b)},\widehat{W}_2^{(b)})\neq (W_1^{(b)},W_2^{(b)})}$ averaged over all random codebooks satisfies  $\E{P_e^{(b)}}\leq\exp(-\zeta n^{\frac{1}{2}})$ for an appropriate constant $\zeta>0$.
\end{lemma}
\begin{IEEEproof}
  The proof follows ideas similar to~\cite{Helhal2018a} but requires a one-shot analysis to properly handle the dependence of distributions with the blocklength. In addition, our choice of threshold decoding, which circumvents the need to characterize entropies and only relies on mutual information is crucial to obtain the result and avoid dealing with the different scaling of entropies with the blocklength. See Appendix~\ref{appendix:proof_reliability2} for details. 
\end{IEEEproof}

\textit{c) Channel resolvability analysis in every block:} The following holds. assuming a common message $W_0^{(b)}$.
\begin{lemma}
    \label{lm:resolvability2}
    For any $\mu\in(0,1)$, $n$ large enough, and every block $b\in\intseq{1}{B}$, if the common message $W_0^{(b)}$ is known by legitimate users and if
    \begin{align}
      &\log M_1^pM_2^pM_0 > (1+\mu)\left(q_1p_1n^{\frac{1}{2}}\D{Q_{10}}{Q_{00}}+q_2p_2n^{\frac{1}{2}}\D{Q_{01}}{Q_{00}}\right),\\
      &\log M_2^pM_0 > (1+\mu)q_2p_2n^{\frac{1}{2}}\D{Q_{01}}{Q_{00}},\\
      &\log M_1^pM_0 > (1+\mu)q_1p_1n^{\frac{1}{2}}\D{Q_{10}}{Q_{00}},\\
      &\log M_0 > \calO\left(n^{\frac{1}{4}}\right).
    \end{align}
    the relative entropy between $P_{Z^n|W_1^{s,(b)}W_2^{s,(b)}}$ and $Q_Z^{\otimes n}$ averaged over secret messages and all random codebooks satisfies
    \begin{align}
        \E{\E[W_1^{s,(b)}W_2^{s,(b)}]{\D{P_{Z^n|W_1^{s,(b)}W_2^{s,(b)}}}{Q_Z^{\otimes n}}}}\leq\exp\left(-\xi n^{\frac{1}{4}}\right),\label{eq:resolve_code}
    \end{align}
    for an appropriate constant $\xi>0$.
\end{lemma}
\begin{IEEEproof}
     The proof follows again ideas similar to~\cite{Helhal2018a} but requires a one-shot analysis to properly handle the dependence of distributions with the blocklength. See Appendix~\ref{appendix:proof_resolvability2} for details.
  \end{IEEEproof}
Ignoring the superscript $(b)$ for clarity, note that we control $\E[W_1^sW_2^s]{\D{P_{Z^n|W_1^sW_2^s}}{Q_Z^{\otimes n}}}$ instead of $\D{P_{Z^n}}{Q_Z^{\otimes n}}$ to ensure that $W_1^{s}$ and $W_2^{s}$ remain secret with respect to the eavesdropper observing $Z^n$. This follows by deriving ``secrecy from resolvability''~\cite{Hayashi2006,Bloch2011e} and observing that $\I{\smash{W_1^{s},W_2^{s}}}{Z^n}\leq \E[W_1^sW_2^s]{\D{P_{Z^n|W_1^sW_2^s}}{Q_Z^{\otimes n}}}$.

\textit{c) Chaining multiple blocks:} While Lemma~\ref{lm:reliability2} and Lemma~\ref{lm:resolvability2} assume far that both users have access to the common message $W_0^{(b)}$ in every block $b\in\intseq{1}{B}$, we now consider the actual operation of the protocol. After each block $b$, each user has access to their own secret message and estimate of the other user's secret message, i.e., User 1 has access to $W_1^{s,(b)}$ and $\widehat{W}_2^{s,(b)}$ and User 2 has access to $W_2^{s,(b)}$ and $\widehat{W}_1^{s,(b)}$, which they use to generate $W_0^{(b+1)}$ and $\widehat{W}_0^{(b+1)}$, respectively. This procedure enforces the additional constraint
\begin{align}
  \log M_1^sM_2^s \geq \log M_0.\label{eq:rate_chaining_constraint}
\end{align}

By the union bound, the overall error rate $P^{(nB)}_e $over all blocks can be upper bounded as
\begin{align}
  P^{(nB)}_e \leq \sum_{b=1}^B P_e^{(b)},\label{eq:union_bound}
\end{align}
Furthermore, the following lemma shows that we can control the relative entropy between the induced distribution and the covert stochastic process by the relative entropy between the induced distribution and the covert stochastic process in each block.
\begin{lemma}
  The relative entropy between the induced distribution $\widehat{Q}^{nB}$ and the covert stochastic process $Q_{Z}^{\otimes nB}$ is upper bounded by
  \begin{align}
    \D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}\leq &2\sum_{b=1}^B\E[W_1^{s,(b)}W_2^{s,(b)}]{\D{P_{Z_b^n|W_1^{s,(b)},W_2^{s,(b)}}}{Q_{Z}^{\otimes n}}}\nonumber\\
    &+\sum_{b=1}^B\left(\He{\widehat{W}_1^{s,(b)}|W_1^{s,(b)}}+\He{\widehat{W}_2^{s,(b)}|W_2^{s,(b)}}\right),\label{eq:chaining_relative_entropy}
  \end{align}
  where $\widehat{W}_i^{s,(b)}$ and $W_i^{s,(b)}$ denote the estimated and the original secret message of User $i$ in block $b$.
  \label{lm:chaining}
\end{lemma}

The proof of Lemma~\ref{lm:chaining} is similar to~\cite{Helhal2018a} and is omitted for brevity. By Fano's inequality, note that
\begin{align}
\forall i\in\set{1,2}\quad  \He{\widehat{W}_i^{s,(b)}|W_i^{s,(b)}} \leq \Hb{P_e^{(b)}}+P_e^{(b)}\log M_i^s,
\end{align}
which ensures that controlling reliability and resolvability in each block shall guarantee reliability and resolvability across the entire chain of blocks. 

\textit{d) Identification of a specific code:} Using the union bound and Markov's inequality, we obtain 
\begin{align}
  \P{P_e^{(nB)}<4\E{P_e^{(nB)}}\cap\D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}<4\E{\D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}}}\geq\frac{1}{2}.
\end{align}
Hence, if one satisfies the constraints of Lemma~\ref{lm:reliability2}, Lemma~\ref{lm:resolvability2}, and~(\ref{eq:rate_chaining_constraint}), we conclude combining~(\ref{eq:union_bound}) and~(\ref{eq:chaining_relative_entropy}) that there must exist at least one codebook that simultaneously achieves \begin{align}
    P^{(nB)}_e &\leq\exp\left(-\zeta_1n^\frac{1}{2}\right)\label{eq:code_rel},\\
    \D{\widehat{Q}^{nB}}{Q_Z^{\otimes nB}} &\leq\exp\left(-\zeta_2n^{\frac{1}{4}}\right).\label{eq:code_res}
\end{align}  
for appropriate constants $\zeta_1,\zeta_2>0$ and an $n$ large enough.

\textit{e) Covertness:} Next, we show that we can indeed ensure covertness.
\begin{lemma}\label{lm:resolv_concentration2}
  For $n$ large enough and an appropriate constant $\zeta_3>0$, the specific code identified earlier satisfies
  \begin{align}
    \abs{\D{\widehat{Q}^{nB}}{Q_{00}^{\otimes nB}}-\D{Q_{Z}^{\otimes nB}}{Q_{00}^{\otimes nB}}} \leq \exp\left(-\zeta_3n^\frac{1}{4}\right)\label{eq:resolv_concentration}.
  \end{align}
    provided that \eqref{eq:resolve_code} is satisfied.
\end{lemma}
\begin{IEEEproof}
    See Appendix~\ref{appendix:resolv_concent_proof}.
\end{IEEEproof}
Combining Lemma~\ref{lm:D_localTS2} and Lemma~\ref{lm:resolv_concentration2}, and defining $\lambda\eqdef \frac{q_1p_1}{q_1p_1+q_2p_2}\in[0;1]$, we obtain
\begin{align}
    \D{\widehat{Q}^{nB}}{Q_{00}^{\otimes nB}} = B\frac{\left(q_1p_1+q_2p_2\right)^2}{2}\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}\Vert Q_{00}\right)+\calO\left(n^{-\frac{1}{2}}\right).\label{eq:D_res_local2}
\end{align}
Note that $\lambda$ is a function of the parameters $q_1,q_2,p_1,p_2$. Since $q_1,q_2,p_1,p_2\in[0,1]$ are free parameters, for each $\lambda$ we can find appropriate values so that 
\begin{align}
    B\frac{\left(q_1p_1+q_2p_2\right)^2}{2}\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}\Vert Q_{00}\right) &= \delta,\label{eq:cov_cons_sat}
\end{align}
and we satisfy the covertness constraint $\limsup_{n\to\infty}\D{\smash{\widehat{Q}^{nB}}}{Q_{00}^{\otimes nB}} = \delta$.


Combining \eqref{eq:code_rel},~\eqref{eq:code_res}, and~(\ref{eq:D_res_local2}), we conclude that there exists one coding scheme that simultaneously satisfies reliability and covertness constraints. In light of the constraints of Lemma~\ref{lm:reliability2}, Lemma~\ref{lm:resolvability2},~(\ref{eq:rate_chaining_constraint}), and~(\ref{eq:cov_cons_sat}), we have shown the existence of a code such that 
\begin{align}
    \lim_{n\to\infty}\frac{\log M_1}{\sqrt{nB\delta}} &\geq (1-\mu)\sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}||Q_{00}\right)}}\lambda\D{P^{(2)}_{10}}{P^{(2)}_{00}},\\
  \lim_{n\to\infty}\frac{\log M_2}{\sqrt{nB\delta}} &\geq (1-\mu)\sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}||Q_{00}\right)}}\Bar{\lambda}\D{P^{(1)}_{01}}{P^{(1)}_{00}},\\
  \lim_{n\to\infty}\frac{\log M_1^pM_0}{\sqrt{nB\delta}} &\leq (1+\mu)\sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}||Q_{00}\right)}}\lambda\D{Q_{10}}{Q_{00}},\\
  \lim_{n\to\infty}\frac{\log M_2^pM_0}{\sqrt{nB\delta}} &\leq (1+\mu)\sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}||Q_{00}\right)}}\Bar{\lambda}\D{Q_{01}}{P^{(2)}_{00}},\\
  \lim_{n\to\infty}\frac{\log M_1^pM_2^pM_0}{\sqrt{nB\delta}} &\leq (1+\mu)\sqrt{\frac{2}{\chi_2\left(\lambda Q_{10}+\Bar{\lambda}Q_{01}||Q_{00}\right)}}\left(\lambda\D{Q_{10}}{Q_{00}}+\Bar{\lambda}\D{Q_{01}}{Q_{00}}\right),\\
  \lim_{n\to\infty}\frac{\log M_0}{\sqrt{nB\delta}} &= 0.
\end{align}
Note that the constraints are now solely parameterized by $\lambda$. In addition, because $\frac{\log M_0}{\sqrt{nB\delta}}$ vanishes, its effect disappears asymptotically resulting in the region stated in Proposition~\ref{prop:achievability_proof2}.
\end{IEEEproof}

\subsection{Converse Proof of Theorem~\ref{thm:capacity}}
The converse proof of Theorem~\ref{thm:capacity} follows from a general converse for covert communication over any discrete memoryless two-way channel we describe next.
\begin{proposition}
  \label{prop:converse}
  The covert capacity region of any discrete memoryless two-way channel is included in
  \begin{align}
    \bigcup_{\substack{
    \bfrho\in[0,1]^4,\rho_{00}=0,\\ \sum_{ij}\rho_{ij}=1}}\left\{\begin{array}{l}
    (r_1,r_2)\in\bbR^2_+:\\
    r_1 \leq \tau_{\bfrho} \left(\sum_{ij}\rho_{ij}\D{P^{(2)}_{ij}}{P^{(2)}_{00}}-\left(\sum_i\rho_{i1}\right)\D{\frac{\sum_j\rho_{j1}P^{(2)}_{j1}}{\sum_k\rho_{k1}}}{P^{(2)}_{00}}\right)\\
    r_2 \leq \tau_{\bfrho} \left(\sum_{ij}\rho_{ij}\D{P^{(1)}_{ij}}{P^{(1)}_{00}}-\left(\sum_i\rho_{1i}\right)\D{\frac{\sum_j\rho_{1j}P^{(1)}_{1j}}{\sum_k\rho_{1k}}}{P^{(1)}_{00}}\right)
    \end{array}\right\},\label{eq:outerbound}
\end{align}
where $\bfrho\eqdef\set{\rho_{00},\rho_{01},\rho_{10},\rho_{11}}$ and $\tau_{\bfrho} = \sqrt{\frac{2}{\chi_2\left(\sum_{ij}\rho_{ij}Q_{ij}\middle\Vert Q_{00}\right)}}$.
\end{proposition}

\begin{remark}
Our converse result does not include lower bounds on the throughputs, which one could expect from other multi-user covert communication results~\cite{Arumugam2018a,Cho2021Treating}. While we were able to obtain single-letterized bounds of the form
\begin{align*}
    \frac{1}{n}\log M_1M_2 \geq \I{X_1X_2}{Z}-\He{Y_1Y_2|X_1X_2Z}-\epsilon,
\end{align*}
such bounds are useless in the context of covert communications because the mutual information term scales as $\calO(1/\sqrt{n})$ while the entropy scales as $\calO(1)$. Intuitively, the challenge is that $\He{Y_1Y_2|X_1X_2Z}$ captures the potential reduction in channel resolvability throughput enabled by secret coordination between the two legitimate users, but without accounting for the communication required to achieve this coordination. Unlike two-way wiretap channels, in which secrecy is an explicit constraint that can be used in the converse, secrecy is not explicitly required in the context of covert communications, suggesting that more sophisticated (and still elusive) arguments are required to develop refined converse bounds. 
\end{remark}
\begin{comment}
\begin{remark}
    In Section~\ref{sec:prel-covert-proc} we described two coordination schemes for achievability, yet we only provided achievability results for Time-Sharing 2 scheme. The reason for this is due to the scaling of $\I{U}{Z}$, in Lemma~\ref{lm:D_localTS1} $\I{U}{Z}$ is $\calO\left(n^{-1}\right)$. Unfortunately, this scaling corresponds to a non-vanishing upper-bound in the random coding argument for the channel resolvability analysis. Detailed explanation of this result is given in Appendix~\ref{appendix:TS1}.
\end{remark}
\end{comment}

\begin{IEEEproof}
  The proof proceeds in two steps, first by showing how the covertness constraint induces a constraint on the average number of non-innocent symbols that can be tolerated at the channel inputs, and then showing how this constraint can be integrated into the single-letterization process. The latter part presents new challenges because of the two-way nature of the channel.

\textit{a) Relative Entropy Analysis:} Let $P_{X_{1i}X_{2i}}$ denote the joint distribution of the $i^{th}$ symbols of the codewords for User 1 and User 2 and $P_{\Tilde{X}_{1}\Tilde{X}_{2}}$ be the average joint distribution of the codewords, i.e.,
\begin{align}
    P_{X_{1i}X_{2i}}(x_1,x_2) &= \frac{1}{M_1M_2}\sum_{w_1=1}^{M_1}\sum_{w_2=1}^{M_2}\indic{x_{1i}(w_1)=x_1,x_{2i}(w_2)=x_2}\eqdef \mu^{(n),i}_{x_1x_2},\\
    P_{\Tilde{X}_1\Tilde{X}_2}(x_1,x_2) &= \frac{1}{n}\sum_{i=1}^nP_{X_{1i}X_{2i}}(x_1,x_2)\eqdef\mu^n_{x_1x_2}.
\end{align}
From the output distribution $\widehat{Q}^n$ of the eavesdropper, the marginal distribution of the $i^{th}$ symbol and time-averaged distribution are
\begin{align*}
  \widehat{Q}^n_i(z_i) &= \sum_{x_1,x_2}P_{X_{1i}X_{2i}}(x_1,x_2)Q_{x_1x_2}(z_i) = \sum_{k,\ell}\mu_{k\ell}^{(n),i}Q_{k\ell}(z_i),\\
  \overline{Q}^n(z) &= \frac{1}{n}\sum_{i=1}^n\widehat{Q}^n_i(z)
                      = \sum_{k,\ell}\mu^n_{k\ell}Q_{k\ell}(z)\quad \forall n\in\bbN^*.
\end{align*}
Since $  \limsup_{n\to\infty}\D{\smash{\widehat{Q}^n}}{Q_{00}^{\otimes n}}\leq \delta$, one can show following by~\cite{Wang2016b} that, for $n$ large enough, 
\begin{align}
  \delta &\geq \sum_{i=1}^n \D{\widehat{Q}_i^n}{Q_{00}}
         \stackrel{(a)}\geq n\D{\overline{Q}^n}{Q_{00}},\label{eq:D_convexity}
\end{align}
where $(a)$ follows from the convexity of relative entropy in the first argument. This also implies that 
\begin{align}
  \lim_{n\to\infty}\overline{Q}^n(z) &= Q_{00}(z)\quad\forall z\in\calZ.
\end{align}
From this result and by our assumptions that $Q_{00}$ cannot be written as a convex combination of $\{Q_{01},Q_{10},Q_{11}\}$ we must have
$\mu^n_{01},\mu^n_{10},\mu^n_{11} \xrightarrow[n\to\infty]{} 0$.

To obtain the scaling of the weights we use the following lemma.
\begin{lemma}\label{lm:D_conv}
  If $\lim_{n\to\infty}\mu_{ij}^n=0$ $\forall(i,j)\neq(0,0)$, the average weight of the codewords satisfies for $n$ large enough
  \begin{align}
    \D{\widehat{Q}^n}{Q_{00}^{\otimes n}} &\geq n\chi_2\left(\sum_{ij}\mu_{ij}^nQ_{ij}\middle\Vert Q_{00}\right)+\calO\left(\mu_n^3\right).\label{eq:D_LB}
  \end{align}
\end{lemma}
\begin{IEEEproof}
    See Appendix~\ref{appendix:D_conv}.
\end{IEEEproof}

\textit{b) Throughput Analysis:} For User 1 we upper bound $\log M_1$ by standard techniques,
\begin{align}
  \log M_1 &\overset{}{\leq} \I{W_1}{W_2Y_2^n}+\Hb{P_e^{(n)}}+P_e^{(n)}\log M_1\\
           &\leq \sum_{i=1}^n\I{X_{1i}}{Y_{2i}|X_{2i}}+n\epsilon_n\label{eq:M1_bound}
\end{align}
with $\epsilon_n\eqdef \frac{1}{n}(\Hb{P_e^{(n)}}+P_e^{(n)}\log M_1)$. To upper bound the first term in \eqref{eq:M1_bound} we use the following lemma.
\begin{lemma}\label{lm:conv_r1r2}
  If $\forall(k,\ell)\neq~(0,0),\quad\forall n\in\bbN^*$ $\lim_{n\to\infty}\mu_{k\ell}^{(n),i}=0$, we have
  \begin{align}
    \sum_{i=1}^n\I{X_{1i}}{Y_{2i}|X_{1i}} \leq& n\mu_n\left(\sum_{ij}\rho_{ij}^n\D{P^{(2)}_{ij}}{P^{(2)}_{00}}-\sum_i\rho_{i1}^n\D{\frac{\sum_j\rho^n_{j1}P^{(2)}_{j1}}{\sum_k\rho^n_{k1}}}{P^{(2)}_{00}}\right)\nonumber\\
    &+\calO\left(n\left(\mu_{10}^n\right)^2\right),\label{eq:I_avg_bound}
  \end{align}
  where $\forall n\in\bbN^*$ $\mu_n\eqdef 1-\mu^n_{00}$ and $\forall(i,j)$ $\rho_{ij}^n\in[0,1]^4$ we have $\rho_{00}^n=~0$, $\sum_{ij}\rho_{ij}^n=1$, $\forall(i,j)\neq~(0,0)~\mu_{ij}^n=\mu_n\rho^n_{ij}$.
\end{lemma}
\begin{IEEEproof}
See Appendix~\ref{appendix:conv_r1r2}. 
\end{IEEEproof}
Hence, by combining \eqref{eq:D_LB}, \eqref{eq:M1_bound} and \eqref{eq:I_avg_bound} we obtain
\begin{align}
  &\liminf_{n\to\infty}\frac{\log M_1}{\sqrt{n\delta}}\leq \tau_{\bfrho} \left(\sum_{ij}\rho_{ij}\D{P^{(2)}_{ij}}{P^{(2)}_{00}}-\sum_i\rho_{i1}\D{\frac{\sum_j\rho_{j1}P^{(2)}_{j1}}{\sum_k\rho_{k1}}}{P^{(2)}_{00}}\right).
\end{align}
The bound for the throughput of User 2 follows similarly.
\end{IEEEproof}

The converse proof of Theorem~\ref{thm:capacity} is the specialization of the general converse of Proposition~\ref{prop:converse} to alarm channels. For the alarm channel, covertness enforces $\rho_{11}=0$, which results in the parameterization $\rho_{10}=\lambda$, $\rho_{01}=\Bar{\lambda}$ and $\tau_{\bfrho}=c_\lambda$. With this parameterization the converse region becomes $r_1\leq c_\lambda\lambda\D{\smash{P^{(2)}_{10}}}{\smash{P^{(2)}_{00}}},r_2\leq c_\lambda\Bar{\lambda}\D{\smash{P^{(2)}_{10}}}{\smash{P^{(2)}_{00}}}$.

