\section{Proof of Lemma ~\ref{lm:resolvability2}}\label{appendix:proof_resolvability2}
For $\bftau\eqdef\set{\tau_i}_{i=1}^4$, we first define the set
\begin{equation}
  \calB^{(n)}_\tau = \bigcap_{i=1}^4\calB^{(n)}_{\tau_i},
\end{equation}
where
\begin{align}
  &\calB^{(n)}_{\tau_1} = \left\{(x_1^n,x_2^n,u^n,z^n):\log\frac{W_{Z|X_1,X_2}^{\otimes n}(z^n|z_1^n,x_2^n)}{Q_Z^{\otimes n}(z^n)}\leq\tau_1\right\},\\
  &\calB^{(n)}_{\tau_2} = \left\{(x_1^n,x_2^n,u^n,z^n):\log\frac{P_{Z|X_1,U}^{\otimes n}(z^n|x_1^n,u^n)}{Q_Z^{\otimes n}(z^n)}\leq\tau_2\right\},\\
  &\calB^{(n)}_{\tau_3} = \left\{(x_1^n,x_2^n,u^n,z^n):\log\frac{P_{Z|X_2,U}^{\otimes n}(z^n|x_2^n,u^n)}{Q_Z^{\otimes n}(z^n)}\leq\tau_3\right\},\\
  &\calB^{(n)}_{\tau_4} = \left\{(x_1^n,x_2^n,u^n,z^n):\log\frac{P_{Z|U}^{\otimes n}(z^n|u^n)}{Q_Z^{\otimes n}(z^n)}\leq\tau_4\right\},
\end{align}
where $\tau_1~\eqdef(1+\mu)n\I{X_1,X_2}{Z}$, $\tau_2~\eqdef(1+\mu)n\I{X_1,U}{Z}$, $\tau_3~\eqdef(1+\mu)n\I{X_2,U}{Z}$, $\tau_4~\eqdef(1+\mu)n\I{U}{Z}$.

Taking the expectation of the relative entropy $\D{P_{Z^n,W_1^s,W_2^s}}{Q_{Z}^{\otimes n}P_{W_1^s}P_{W_2^s}}$ with respect to the random codebook, we obtain
\begin{align}
    &\E[C_n]{\D{P_{Z^n,W_1^s,W_2^s}}{Q_{Z}^{\otimes n}P_{W_1^s}P_{W_2^s}}}\nonumber\\
    &\stackrel{(a)}{=} \sum_{z^n}\mathbb{E}_{U^n(1)X_1^n(1,1,1)X_2^n(1,1,1)}\left[{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(1,1,1)x_2^n(1,1,1))} \right.\nonumber\\
    & \times\left. \E[C_n\setminus\{U^n(1)X_1^n(1,1,1)X_2^n(1,1,1)\}]{\log{\frac{1}{M_1^pM_2^pM_0}\sum_{w_1^{p'},w_2^{p'},w_0'}}\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(w_1^{p'},1,w_0')X_2^n(w_2^{p'},1,w_0'))}{Q_{Z}^{\otimes n}(z^n)}}\right]\\
      & \stackrel{(b)}{\leq}\sum_{z^n}\sum_{u^n(1)}\sum_{x_1^n(1,1,1)}\sum_{x_2^n(1,1,1)}W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^n(1,1,1)x_2^n(1,1,1))\nonumber\\
  &\phantom{==========}P_{U}^{\otimes n}(u^n(1))P_{X_1|U}^{\otimes n}(x_1^n(1,1,1)|u^n(1))P_{X_2|U}^{\otimes n}(x_2^n(1,1,1)|u^n(1))\nonumber\\
    & \times \log{\E[C_n\setminus\{u^n(1)x_1^n(1,1,1)x_2^n(1,1,1)\}]{\frac{1}{M_1^pM_2^pM_0}\sum_{w_1^{p'},w_2^{p'},w_0}\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(w_1^{p'},w_1^s,w_0')X_2^n(w_2^{p'},w_2^s,w_0'))}{Q_{Z}^{\otimes n}(z^n)}}} \label{eq:concavity_bound}
\end{align}
where $(a)$ follows by expanding $P_{Z^n,W_1^s,W_2^s}$ and using the symmetry of the random code construction; $(b)$ follows by explicitly writing $\mathbb{E}_{U^n(1)X_1^n(1,1,1)X_2^n(1,1,1)}$ and from the concavity of $\log\left(\cdot\right)$. The $\log$ term can be expanded and simplified as
\begin{align}
  &  \log{\left[\frac{1}{M_1^pM_2^pM_0}\left(\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^n(1,1,1),x_2(1,1,1))}{Q_{Z}^{\otimes n}(z^n)}\right.\right.}\nonumber\\
  &+\sum_{{w_1^{p'} \neq 1}} \E[X_1^n(w_1^{p'},1,1)]{\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(w_1^{p'},1,1),x_2^n(1,1,1))}{Q_{Z}^{\otimes n}(z^n)}\Bigg|U^n=u^n(1)} \nonumber\\
  &+\sum_{{w_2^{p'} \neq 1}} \E[X_2^n(w_2^{p'},1,1)]{\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^n(1,1,1),X_2^n(w_2^{p'},1,1))}{Q_{Z}^{\otimes n}(z^n)}\Bigg|U^n=u^n(1)}\nonumber\\
  &+\sum_{{w_1^{p'} \neq w_1^p,w_2^{p'}\neq w_2^p}}\E[X_1^n(w_1^{p'},1,1),X_2^n(w_2^{p'},1,1)]{\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(w_1^{p'},1,1),X_2^n(w_2^{p'},1,1))}{Q_{Z}^{\otimes n}(z^n)}\Bigg|U^n=u^n(1)} \nonumber\\
  &\left.\left.+\sum_{{w_1^{p'} \neq w_1^p, w_2^{p'} \neq w_2^p, w_0' \neq w_0}} \E[U^n(w_0'),X_1^n(w_1^{p'},1,w_0'),X_2^n(w_2^{p'},1,w_0')]{\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|X_1^n(w_1^{p'},1,w_0'),X_2^n(w_2^{p'},1,w_0'))}{Q_{Z}^{\otimes n}(z^n)}}\right)\right]\\
  &= \log\left[\frac{1}{M_1^pM_2^pM_0}\left(\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^n(1,1,1),x_2(1,1,1))}{Q_{Z}^{\otimes n}(z^n)}\right.\right.\nonumber\\
  &\phantom{======}+\sum_{{w_1^{p'} \neq 1}}\frac{P_{Z|X_2U}^{\otimes n}(z^n|x_2^n(1,1,1),u^n(1))}{Q_{Z}^{\otimes n}(z^n)}+\sum_{{w_2^{p'} \neq 1}}\frac{P_{Z|X_1U}^{\otimes n}(z^n|x_1^n(1,1,1),u^n(1))}{Q_{Z}^{\otimes n}(z^n)}\nonumber\\
  &\phantom{==============}\left.\left.+\sum_{{w_1^{p'} \neq w_1^p, w_2^{p'} \neq w_2^p}}\frac{P_{Z|U}^{\otimes n}(z^n|u^n(1))}{Q_{Z}^{\otimes n}(z^n)}+\sum_{{w_1^{p'} \neq w_1^p, w_2^{p'} \neq w_2^p, w_0' \neq w_0}}1\right)\right].
\end{align}
Hence, recognizing that $x_1^n(1,1,1)$, $x_2^n(1,1,1)$ and $u^n(1)$ are merely indices, the inequality~(\ref{eq:concavity_bound}) takes the simplified form
\begin{align}
  &\E[C_n]{\D{P_{Z^n,W_1^s,W_2^s}}{Q_{Z}^{\otimes n}P_{W_1^s}P_{W_2^s}}}\nonumber\\
  &\leq \sum_{z^n}\sum_{u^n}\sum_{x_1^n}\sum_{x_2^n}W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^nx_2^n)P_{U}^{\otimes n}(u^n)P_{X_1|U}^{\otimes n}(x_1^n|u^n)P_{X_2|U}^{\otimes n}(x_2^n|u^n)\nonumber\\
  &\phantom{==}\times\log\left[\frac{1}{M_1^pM_2^pM_0}\frac{W^{\otimes n}_{Z|X_1,X_2}(z^n|x_1^n,x_2)}{Q_{Z}^{\otimes n}(z^n)}+\frac{1}{M_2^pM_0}\frac{P_{Z|X_2U}^{\otimes n}(z^n|x_2^n,u^n)}{Q_{Z}^{\otimes n}(z^n)}\right.\nonumber\\
    &\phantom{===============}\left.+\frac{1}{M_1^pM_0}\frac{P_{Z|X_1U}^{\otimes n}(z^n|x_1^n,u^n)}{Q_{Z}^{\otimes n}(z^n)}+\frac{1}{M_0}\frac{P_{Z|U}^{\otimes n}(z^n|u^n)}{Q_{Z}^{\otimes n}(z^n)}+1 \right].\label{eq:simplified_divergence_bound}
\end{align}
If $(u^n,x_1^n,x_2^n,z^n)\in\calB_{\mathbf{\tau}}^{(n)}$, the $\log$ term can be upper bounded by
\begin{multline}
  \log\left[\frac{e^{\tau_1}}{M_1^pM_2^pM_0}+\frac{e^{\tau_2}}{M_2^pM_0}+\frac{e^{\tau_3}}{M_1^pM_0}+\frac{e^{\tau_4}}{M_0}+1\right]\\ \leq \frac{e^{\tau_1}}{M_1^pM_2^pM_0}+\frac{e^{\tau_2}}{M_2^pM_0}+\frac{e^{\tau_3}}{M_1^pM_0}+\frac{e^{\tau_4}}{M_0}.\label{eq:bound_log_1}
\end{multline}
If $(u^n,x_1^n,x_2^n,z^n)\notin\calB_{\mathbf{\tau}}^{(n)}$, define $\nu_\textnormal{min}\eqdef\min_{z:Q_{00}(z)>0}Q_{00}(z)$ and upper bound the $\log$ term as
\begin{align}
