\end{align}
where $(a)$ follows from upper bounding the terms in the second $\log$ by 1 and using the definition of $\nu_\textnormal{min}$. Substituting~(\ref{eq:bound_log_1}) and~(\ref{eq:bound_log_1}) into~(\ref{eq:simplified_divergence_bound}), we obtain
\begin{align}
  &\E[C_n]{\D{P_{Z^n,W_1^s,W_2^s}}{Q_{Z}^{\otimes n}P_{W_1^s}P_{W_2^s}}}\nonumber\\
  &\leq \P{(\calB_{\mathbf{\tau}}^{(n)})^c} n\log\left(\frac{5}{(1-n^{-1}(q_1p_1+q_2p_2))\nu_\textnormal{min}}\right) + \frac{e^{\tau_1}}{M_1^pM_2^pM_0}+\frac{e^{\tau_2}}{M_2^pM_0}+\frac{e^{\tau_3}}{M_1^pM_0}+\frac{e^{\tau_4}}{M_0}.\label{eq:final_divergence_bound}
\end{align}
Based on the definition of $\bftau$, the last four terms of~(\ref{eq:final_divergence_bound}) vanish provided
\begin{align}
  \log M_1^pM_2^pM_0 &>(1+\mu)n\I{X_1,X_2}{Z},\\
  \log M_2^pM_0&>(1+\mu)n\I{X_2,U}{Z},\\
  \log M_1^pM_0 &>(1+\mu)n\I{X_1,U}{Z},\\
  \log M_0 &> (1+\mu)n\I{U}{Z}.
\end{align}
Using Lemma~\ref{lm:D_localTS2}, these conditions become
\begin{align}
    &\log M_1^pM_2^pM_0 > (1+\mu)n^{\frac{1}{2}}\left(q_1p_1\D{Q_{10}}{Q_{00}}+q_2p_2\D{Q_{01}}{Q_{00}}\right),\label{eq:res_r_cond1}\\
