  \P{(\calB^{(n)}_\tau)^c} &\leq \sum_{i=1}^4\P{(\calB^{(n)}_{\tau_i})^c}.\label{eq:res_bernstein_b}
\end{align} We define the random variables $V_1 = \log\frac{Q_{X_1X_2}(Z)}{Q_Z(Z)}-\I{X_1,X_2}{Z}$, $V_2 = \frac{P_{Z|X_1U}(Z|X_1,U)}{Q_Z(Z)}-\I{X_1,U}{Z}$, $V_3 = \log\frac{P_{Z|X_2U}(Z|X_2,U)}{Q_Z(Z)}-\I{X_2,U}{Z}$ and $V_4 = \frac{P_{Z|U}(Z|U)}{Q_Z(Z)}-\I{U}{Z}$. For the variance of $V_1$,
\begin{align}
    &\E{\log^2\frac{Q_{X_1X_2}(Z)}{Q_Z(Z)}} \\
    &=\sum_{u,x_1,x_2,z}P_U(u)P_{X_1|U}(x_1|u)P_{X_2|U}(x_2|u)Q_{x_1x_2}(z)\log^2\frac{Q_{x_1x_2}(z)}{Q_Z(z)}\\
    &=q_1n^{-\frac{1}{4}}\sum_{x_1,z}P_{X_1|U}(x_1|1)Q_{x_10}(z)\left(\log^2\frac{Q_{x_10}(z)}{Q_{00}(z)}-2\log\frac{Q_{x_10}(z)}{Q_{00}(z)}\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\nonumber\\
    &\phantom{==}+q_2n^{-\frac{1}{4}}\sum_{x_2,z}P_{X_2|U}(x_2|2)Q_{0x_2}(z)\left(\log^2\frac{Q_{0x_2}(z)}{Q_{00}(z)}-2\log\frac{Q_{0x_2}(z)}{Q_{00}(z)}\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\\
    &=\calO\left(n^{-\frac{1}{2}}\right),\label{eq:var_V1}
\end{align}
since the lowest order terms in two sums are the first terms. For the variance of $V_2$,
\begin{align}
    &\E{\log^2\frac{P_{Z|X_1U}(Z|X_1,U)}{Q_Z(Z)}} =\\ &\sum_{u,x_1,x_2,z}P_U(u)P_{X_1|U}(x_1|u)P_{X_2|U}(x_2|u)Q_{x_1x_2}(z)\log^2\left(\frac{\sum_{x_2'}P_{X_2|U}(x_2'|u)Q_{x_1x_2'}(z)}{Q_Z(z)}\right)\\
    &= q_1n^{-\frac{1}{4}}\sum_{x_1,z}P_{X_1|U}(x_1|1)Q_{x_10}(z)\left(\log^2\frac{Q_{x_10}(z)}{Q_{00}(z)}-2\log\frac{Q_{x_10}(z)}{Q_{00}(z)}\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\nonumber\\
    &\phantom{==}+q_2n^{-\frac{1}{4}}\sum_{x_2,z}P_{X_2|U}(x_2|2)Q_{0x_2}\left(\log^2\left(\frac{\sum_{x_2'}P_{X_2|U}(x_2'|2)Q_{0x_2'}(z)}{Q_{00}(z)}\right)\right.\\
    &\phantom{==}\left.-2\log\left(\frac{\sum_{x_2'}P_{X_2|U}(x_2'|2)Q_{0x_2'}(z)}{Q_{00}(z)}\right)\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\\
    &=\calO\left(n^{-\frac{1}{2}}\right),\label{eq:var_V2}
\end{align}
since lowest order term is first term in first summation. By symmetry of $X_1$ and $X_2$,
\begin{align}
    \E{\log^2\frac{P_{Z|X_2U}(Z|X_2,U)}{Q_Z(Z)}} = \calO\left(n^{-\frac{1}{2}}\right).\label{eq:var_V3}
\end{align}

For the variance of $V_4$,
\begin{align}
    &\E{\log^2\frac{P_{Z|U}(Z|U)}{Q_Z(Z)}} \\
    &=\sum_{u,x_1,x_2,z}P_U(u)P_{X_1|U}(x_1|u)P_{X_2|U}(x_2|u)Q_{x_1x_2}(z)\log^2\left(\frac{\sum_{x_1',x_2'}P_{X_1|U}(x_1'|u)P_{X_2|U}(x_2'|u)Q_{x_1'x_2'}(z)}{Q_Z(z)}\right)\\
    &= q_1n^{-\frac{1}{4}}\sum_{x_1,z}\left(Q_{00}(z)+p_1n^{-\frac{1}{4}}\left(Q_{10}(z)-Q_{00}(z)\right)\right)\left(\log^2\left(1+p_1n^{-\frac{1}{4}}\frac{Q_{10}(z)-Q_{00}(z)}{Q_{00}(z)}\right)\right.\nonumber\\
    &\phantom{==}\left.-2\log\left(1+p_1n^{-\frac{1}{4}}\frac{Q_{10}(z)-Q_{00}(z)}{Q_{00}(z)}\right)\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\nonumber\\
    &\phantom{==}+q_2n^{-\frac{1}{4}}\sum_{x_2,z}\left(Q_{00}(z)+p_2n^{-\frac{1}{4}}\left(Q_{01}(z)-Q_{00}(z)\right)\right)\left(\log^2\left(1+p_2n^{-\frac{1}{4}}\frac{Q_{01}(z)-Q_{00}(z)}{Q_{00}(z)}\right)\right.\nonumber\\
    &\phantom{==}\left.-2\log\left(1+p_2n^{-\frac{1}{4}}\frac{Q_{01}(z)-Q_{00}(z)}{Q_{00}(z)}\right)\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\\
    &= \calO\left(n^{-\frac{3}{4}}\right),\label{eq:var_V4}
\end{align}
since $\log^2\left(1+\calO\left(n^{-\frac{1}{4}}\right)\right)=\calO\left(n^{-\frac{1}{2}}\right)$, $\log\left(1+\calO\left(n^{-\frac{1}{4}}\right)\right)=\calO\left(n^{-\frac{1}{4}}\right)$, $\log^2\frac{Q_Z(z)}{Q_{00}(z)}=\calO\left(n^{-\frac{1}{2}}\right)$ and $\log\frac{Q_Z(z)}{Q_{00}(z)}=\calO\left(n^{-\frac{1}{2}}\right)$ by Lemma~\ref{lm:D_localTS2}.

Using \eqref{eq:var_V1}, \eqref{eq:var_V2}, \eqref{eq:var_V3}, \eqref{eq:var_V4}, Lemma~\ref{lm:D_localTS2}, and Bernstein's inequality, we upper bound~\eqref{eq:res_bernstein_b} as
\begin{align} &\exp\left(-\frac{\calO\left(n\right)}{\calO\left(n^{\frac{1}{2}}\right)}\right)+\exp\left(-\frac{\calO\left(n\right)}{\calO\left(n^{\frac{1}{2}}\right)}\right)+\exp\left(-\frac{\calO\left(n\right)}{\calO\left(n^{\frac{1}{2}}\right)}\right)+\exp\left(-\frac{\calO\left(n^{\frac{1}{2}}\right)}{\calO\left(n^{\frac{1}{4}}\right)}\right)\\
    &\leq \sum_{i=1}^3\exp\left(-\zeta_in^{-\frac{1}{2}}\right)+\exp\left(-\zeta_4n^{-\frac{1}{4}}\right)\\
    &\leq \exp\left(-\zeta n^{-\frac{1}{4}}\right),
\end{align}
for an appropriate constant $\zeta>0$. Hence, if \eqref{eq:res_r_cond1}-\eqref{eq:res_r_cond4} hold, we have
\begin{align}
    \E{\E[W_1^sW_2^s]{\D{P_{Z^n|W_1^sW_2^s}}{Q_Z^{\otimes n}}}}\leq \exp\left(-\xi n^{\frac{1}{4}}\right),
\end{align}
for an appropriate constant $\xi>0$ as desired.

\section{Proof of Lemma ~\ref{lm:resolv_concentration2}}\label{appendix:resolv_concent_proof}
Since $\D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}\leq \exp\left(-\zeta_2 n^\frac{1}{4}\right)$, from Pinsker's inequality we have $\V{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}\leq \frac{1}{2}\exp\left(-\frac{1}{2}\zeta_2 n^\frac{1}{4}\right)$. Then, we write
\begin{align}
  \D{\widehat{Q}^{nB}}{Q_{00}^{\otimes nB}} &= \D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}+\D{Q_{Z}^{\otimes nB}}{Q_{00}^{\otimes nB}}\nonumber\\
  &+\sum_{z^{nB}}\left(\widehat{Q}^{nB}(z^{nB})-Q_{Z}^{\otimes nB}(z^{nB})\right)\log\frac{Q_{Z}^{\otimes nB}(z^{nB})}{Q_{00}^{\otimes nB}(z^{nB})}.
\end{align}
By rearranging the terms and taking the absolute value we obtain
\begin{align}
  &\abs{\D{\widehat{Q}^{nB}}{Q_{00}^{\otimes nB}}-\D{Q_{Z}^{\otimes nB}}{Q_{00}^{\otimes nB}}}\nonumber\\
  &\leq \D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}+\abs{\sum_{z^{nB}}\left(\widehat{Q}^{nB}(z^{nB})-Q_{Z}^{\otimes nB}(z^{nB})\right)\frac{Q_{Z}^{\otimes nB}(z^{nB})}{Q_{00}^{\otimes nB}(z^{nB})}}\\
  &\overset{(a)}{\leq} \D{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}+\V{\widehat{Q}^{nB}}{Q_{Z}^{\otimes nB}}\sup_{z^{nB}}\log\frac{Q_{Z}^{\otimes nB}(z^{nB})}{Q_{00}^{\otimes nB}(z^{nB})}\\
  &\leq \exp\left(-\zeta_2n^\frac{1}{4}\right)+\frac{1}{\sqrt{2}}\exp\left(-\frac{1}{2}\zeta_2n^\frac{1}{4}\right)nB\nonumber\\
  &\times\sup_{z}\log\left(1+n^{-\frac{1}{2}}(q_1p_1+q_2p_2)\frac{\lambda Q_{10}(z)+\Bar{\lambda}Q_{01}(z)-Q_{00}(z)}{Q_{00}(z)}\right)\\
  &\leq \exp\left(-\zeta_2n^\frac{1}{4}\right)+\frac{1}{\sqrt{2}}\exp\left(-\frac{1}{2}\zeta_2n^\frac{1}{4}\right)nB\log\left(1+n^{-\frac{1}{2}}\frac{(q_1p_1+q_2p_2)}{\nu_\textnormal{min}}\right)\\
  &\leq \exp\left(-\zeta_2n^\frac{1}{4}\right)+\frac{1}{\sqrt{2}}\exp\left(-\frac{1}{2}\zeta_2n^\frac{1}{4}\right)n^\frac{1}{2}\frac{(q_1p_1+q_2p_2)}{\nu_\textnormal{min}}B\\
  &\leq \exp\left(-\zeta_3n^\frac{1}{4}\right),
\end{align}
where $(a)$ follows from Holder's Inequality and $\zeta_3>0$ is an appropriate constant.

\section{Proof of Lemma ~\ref{lm:D_conv}}\label{appendix:D_conv}
By the definition of relative entropy
\begin{align}
  \D{\sum_{ij}\mu^n_{ij}Q_{ij}}{Q_{00}} &= \sum_z \left(Q_{00}(z)+\sum_{ij}\mu^n_{ij}(Q_{ij}(z)-Q_{00}(z))\right)\nonumber\\
  &\times\log\left(1+\frac{\sum_{ij}\mu^n_{ij}(Q_{ij}(z)-Q_{00}(z))}{Q_{00}(z)}\right).
\end{align}

Since $\forall (i,j)\neq(0,0),\quad \lim_{n\to\infty}\mu_{ij}^n=0$, there exists $n$ large enough such that $\frac{\sum_{ij}\mu_{ij}^n(Q_{ij}(z)-Q_{00}(z))}{Q_{00}(z)}\geq-\frac{1}{2}$ for all $z\in\calZ$. By using the inequality $\log(1+x)>x-\frac{x^2}{2}\quad \forall x>0$ and $\log\left(1+x\right)\geq x-\frac{x^2}{2}+\frac{2x^3}{3}\quad \forall x\in\left[-\frac{1}{2},0\right]$, for $n$ large enough
\begin{align}
  \D{\sum_{ij}\mu^n_{ij}Q_{ij}}{Q_{00}}&\geq \sum_{z}\left(Q_{00}(z)+\sum_{ij}\mu_{ij}^n(Q_{ij}(z)-Q_{00}(z))\right)\nonumber\\
                                       &\phantom{==}\times\left[\frac{\sum_{kl}\mu_{kl}^n\left(Q_{kl}(z)-Q_{00}(z)\right)}{Q_{00}(z)}-\frac{1}{2}\frac{\left(\sum_{kl}\mu_{kl}^n\left(Q_{kl}(z)-Q_{00}(z)\right)\right)^2}{Q_{00}(z)^2}\right]\nonumber\\
                                       &\phantom{==}+\frac{2}{3}\sum_{z:\overline{Q}^n(z)\leq Q_{00}}\left(Q_{00}(z)+\sum_{ij}\mu_{ij}^n(Q_{ij}(z)-Q_{00}(z))\right)\nonumber\\
  &\phantom{==}\times\frac{\left(\sum_{kl}\mu_{kl}^nQ_{kl}(z)-Q_{00}(z)\right)^3}{Q_{00}(z)^3}\\
  &\approx \frac{1}{2}\chi_2\left(\sum_{ij}\mu_{ij}^nQ_{ij}\middle\Vert Q_{00}\right),\label{eq:D_local2}
\end{align}
where the higher order can be eliminated, since $\left(\mu^n_{ij}\right)^3$ terms go to $0$ faster than $\left(\mu^n_{ij}\right)^2$ terms $\forall (i,j)\neq(0,0)$. Thus, the bound on the weights for $n$ large enough becomes
\begin{align*}
  \frac{2\delta}{n} &\geq \chi_2\left(\sum_{ij}\mu^n_{ij}Q_{ij}\Biggl|\Biggl| Q_{00}\right) = \mu_n^2\chi_2\left(\sum_{ij}\rho^n_{ij}Q_{ij}\Biggl|\Biggl| Q_{00}\right),
\end{align*}
where $\rho_{ij}^n\geq0\quad\forall (i,j)\in[0,1]^2,\forall n\in\bbN^*$, $\rho_{00}^n=0,\forall n\in\bbN^*$ and $\sum_{ij}\rho_{ij}^n=1$. The average code distribution is then
\begin{align}
  P_{\Tilde{X}_1\Tilde{X}_2}(k,\ell) &= \left\{\begin{array}{cc}
                                                 1-\mu_n & (k,\ell)=(0,0) \\
                                                 \mu_n\rho_{k\ell}^n & \textnormal{otherwise}
                                               \end{array}\right.,
\end{align}
Then the constraint on the average weight of the code is
\begin{align}
  \mu_n \leq \sqrt{\frac{2\delta}{n\chi_2\left(\sum_{ij}\rho^n_{ij}Q_{ij}\Biggl|\Biggl| Q_{00}\right)}},
\end{align}
for $n$ large enough.

\section{Proof of Lemma ~\ref{lm:conv_r1r2}}\label{appendix:conv_r1r2}
\begin{align}
  \I{X_{1i}}{Y_{2i}|X_{2i}} &= \I{X_{1i},X_{2i}}{Y_{2i}}-\I{X_{2i}}{Y_{2i}}\label{eq:chain_rule}
\end{align}
Looking at the first term,
\begin{align}
    \I{X_{1i},X_{2i}}{Y_{2i}} &= \sum_{x_1,x_2}P_{X_{1i}X_{2i}}(x_1,x_2)\D{P^{(2)}_{x_1x_2}}{P^{(2)}_{\mu^{(n),i}}}\\
                              &= \sum_{x_1,x_2}P_{X_{1i}X_{2i}}(x_1,x_2)\D{P^{(2)}_{x_1x_2}}{P^{(2)}_{00}}-\D{P^{(2)}_{\mu^{(n),i}}}{P^{(2)}_{00}},\label{eq:IX1X2Y2}
\end{align}
where $P^{(2)}_{\mu^{(n),i}}=\sum_{k,\ell}\mu^{(n),i}_{k\ell}P^{(2)}_{k\ell}$. For the second term in \eqref{eq:chain_rule},
\begin{align}
    \I{X_{2i}}{Y_{2i}} &= \sum_{x_2,y_2}\sum_{x_1}P_{X_{1i}X_{2i}}(x_1,x_2)P^{(2)}_{x_1x_2}(y_2)\log\frac{\sum_{x_1'}P_{X_{1i}X_{2i}}(x_1',x_2)P^{(2)}_{x_1'x_2}(y_2)}{\sum_{\Bar{x}_1}P_{X_1iX_{2i}}(\overline{x_1},x_2)P^{(2)}_{\mu^{(n),i}}(y_2)}\\
                       &= \sum_{x_2,y_2}\sum_{x_1}P_{X_{1i}X_{2i}}(x_1,x_2)P^{(2)}_{x_1x_2}(y_2)\log\frac{\sum_{x_1'}P_{X_{1i}X_{2i}}(x_1',x_2)P^{(2)}_{x_1'x_2}(y_2)}{\sum_{\Bar{x}_1}P_{X_1iX_{2i}}(\overline{x_1},x_2)P^{(2)}_{00}(y_2)}\nonumber\\
                       &-\D{P^{(2)}_{\mu^{(n),i}}}{P^{(2)}_{00}}.\label{eq:IX2Y2}
\end{align}
For $x_2=0$,
\begin{align}
    &\sum_{y_2}\left(\left(1-\left(\mu^{(n),i}-\mu^{(n),i}_{10}\right)\right)P^{(2)}_{00}(y_2)+\mu^{(n),i}_{10}(P^{(2)}_{10}(y_2)-P^{(2)}_{00}(y_2)))\right)\nonumber\\
    &\phantom{==}\times\log\left(1+\frac{\mu^{(n),i}_{10}}{\left(1-\left(\mu^{(n),i}-\mu^{(n),i}_{10}\right)\right)}\frac{P^{(2)}_{10}(y_2)-P^{(2)}_{00}(y_2)}{P^{(2)}_{00}(y_2)}\right)\\
    &\overset{(a)}{=} \calO\left(\frac{\left(\mu^{(n),i}_{10}\right)^2}{1-\left(\mu^{(n),i}-\mu^{(n),i}_{10}\right)}\right)\label{eq:order1}\\
    &\overset{(b)}{=} \calO\left(\left(\mu^{(n),i}_{10}\right)^2\right),\label{eq:order2}
\end{align}
where $(a)$ follows from Lemma~\ref{lm:D_localTS1} and $(b)$ follows from Taylor series expansion of the denominator in \eqref{eq:order1}. For $x_2=1$,
\begin{align}
  \sum_{y_2}\left(\sum_{x_1}\mu_{x_11}^{(n),i}P^{(2)}_{x_11}(y_2)\right)\log\frac{\sum_{x_1'}\mu_{x_1'1}^{(n),i}P^{(2)}_{x_1'1}(y_2)}{\left(\sum_{\Bar{x}_1}\mu_{\Bar{x}_11}^{(n),i}\right)P^{(2)}_{00}(y_2)},\label{eq:IX2Y2_1}
\end{align}
when we push summation over $i$ in \eqref{eq:IX2Y2_1},
\begin{align}
&\sum_{i=1}^n\sum_{y_2}\left(\sum_{x_1}\mu_{x_11}^{(n),i}P^{(2)}_{x_11}(y_2)\right)\log\frac{\sum_{x_1'}\mu_{x_1'1}^{(n),i}P^{(2)}_{x_1'1}(y_2)}{\left(\sum_{\Bar{x}_1}\mu_{\Bar{x}_11}^{(n),i}\right)P^{(2)}_{00}(y_2)}\\
  &= \sum_{y_2}\sum_{i=1}^n\left(\sum_{x_1}\mu_{x_11}^{(n),i}P^{(2)}_{x_11}(y_2)\right)\log\frac{\sum_{x_1'}\mu_{x_1'1}^{(n),i}P^{(2)}_{x_1'1}(y_2)}{\left(\sum_{\Bar{x}_1}\mu_{\Bar{x}_11}^{(n),i}\right)P^{(2)}_{00}(y_2)}\\
  &\geq n\sum_{y_2}\left(\sum_{x_1}\mu_{x_11}^{n}P^{(2)}_{x_11}(y_2)\right)\log\frac{\sum_{x_1'}\mu_{x_1'1}^{n}P^{(2)}_{x_1'1}(y_2)}{\left(\sum_{\Bar{x}_1}\mu_{\Bar{x}_11}^{n}\right)P^{(2)}_{00}(y_2)}\\
  &= n\mu_n\left(\sum_i\rho^n_{i1}\right)\D{\frac{\sum_j\rho^n_{j1}P^{(2)}_{j1}}{\sum_k\rho^n_{k1}}}{P^{(2)}_{00}},\label{eq:log-sum}
\end{align}
by log-sum inequality. Hence, by combining \eqref{eq:IX1X2Y2}, \eqref{eq:IX2Y2}, \eqref{eq:order2} and \eqref{eq:log-sum},
\begin{align}
  \sum_{i=1}^n\I{X_{1i}}{Y_{2i}|X_{2i}}\leq& n\mu_n\left(\sum_{ij}\rho_{ij}^n\D{P^{(2)}_{ij}}{P^{(2)}_{00}}-\left(\sum_i\rho_{i1}^n\right)\D{\frac{\sum_j\rho^n_{j1}P^{(2)}_{j1}}{\sum_k\rho^n_{k1}}}{P^{(2)}_{00}}\right)\nonumber\\
  &+\calO\left(n\left(\mu_{10}^n\right)^2\right).\label{eq:I_bound}
\end{align}

\section{Analysis of Time-Sharing Scheme}\label{appendix:TS1}
Consider the random coding argument in Appendix~\ref{appendix:proof_resolvability2}, considering the same $V_4$ but now under Time-Sharing scheme with distrbution defined in Section~\ref{lm:D_localTS1}. By Lemma~\ref{lm:D_localTS1}, $\I{U}{Z}$ is $\calO\left(n^{-1}\right)$. For the variance of $V_4$,
\begin{align}
    \E{\log^2\frac{P_{Z|U}(Z|U)}{Q_Z(Z)}} &= \sum_{u,x_1,x_2,z}P_U(u)P_{X_1|U}(x_1|u)P_{X_2|U}(x_2|u)Q_{x_1x_2}(z)\nonumber\\
    &\times\left(\log^2\frac{\sum_{x_1',x_2'}P_{X_1|U}(x_1'|u)P_{X_2|U}(x_2'|u)Q_{x_1'x_2'}(z)}{Q_{00}(z)}\right.\nonumber\\
    &\left.-2\log\frac{\sum_{x_1',x_2'}P_{X_1|U}(x_1'|u)P_{X_2|U}(x_2'|u)Q_{x_1'x_2'}(z)}{Q_{00}(z)}\log\frac{Q_Z(z)}{Q_{00}(z)}+\log^2\frac{Q_Z(z)}{Q_{00}(z)}\right)\\
    &= p\sum_z\left(Q_{00}(z)+\calO\left(n^{-1}\right)\right)\left(\log^2\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)\right.\nonumber\\
    &\left.-2\log\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)\log\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)+\log^2\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right) \right)\nonumber\\
    &+(1-p)\sum_z\left(Q_{00}(z)+\calO\left(n^{-1}\right)\right)\left(\log^2\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)\right.\\
    &\left.-2\log\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)\log\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right)+\log^2\left(1+\calO\left(n^{-\frac{1}{2}}\right)\right) \right)\\
    &= \calO\left(n^{-1}\right).
\end{align}
Hence Bernstein's Inequality becomes,
\begin{align}
    \P{\sum_{i=1}^nV_{4,i}>n\mu\I{U}{Z}}&\leq \exp\left(-\frac{1}{2}\frac{n^2\mu^2\I{U}{Z}^2}{n\Var{V_4}+\frac{1}{3}cn\mu\I{U}{Z}}\right)\\
    &\leq\exp\left(-\calO(1)\right),
\end{align}
where $c$ is such that $\abs{V_{4}}\leq c<\infty$. We are not aware of a result that would allow the concentration of measure required here.

