\begin{restatable}{theorem}{dagenumerationtheorem}\label{thm:DAG_enumeration}
Given an $m$-skeleton DAG $G=(V,E)$, with $|V|=n$, after an $\O(n)$ time preprocessing, we can incrementally enumerate the $s-f$-paths in $D(G)$ with $\O(1)$ delay. 
\end{restatable}
