\begin{proof}
\noindent\emph{$\S $ Preliminaries.}
    Before constructing the skeleton graph $G$, we introduce for each position $i\in[n]$ of $w$ an ordered set $P_i = \{j_{i,1} < j_{i,2}< \ldots < j_{i,n_i}\}$, where $n_i = \abs{\text{alph}(w[1:i])}$, such that for each $\ell\in[n_i]$ holds that $j_{i,\ell}\in P_i$ if and only if $w[j_{i,\ell}]\in\text{alph}(w[j_{i,\ell}:i])$ and $w[j_{i,\ell}]\notin\text{alph}(w[j_{i,\ell}+1:i])$, i.e., $w[j_{i,\ell}:i]$ is the smallest substring ending in position $i$ that contains letter $w[j_{i,\ell}]$. 

\medskip

\noindent\emph{$\S $ Construction of the skeleton graph.}
    We will now define the skeleton graph $G = (V,E)$. We create a set of nodes $V = \{s,f\}\cup\{ V_i \mid i\in[n] \}$, with $ V_i = \{ v_{i}^{\ell} \mid \ell\in[n_i]\}$ corresponding to positions from $P_i$ ($ v_{i}^{\ell}$ corresponds to the pair $(i,j_{i,\ell})$). We construct the edges $(v,v') \in E$, as follows: 
    \begin{itemize}
        \item There is an edge $(s,v_{i}^{1})$, if $i = \nextpos[a,1]$. 
        \item For $i\in[n]$ and $\ell\in[n_i]$ there is an edge $(v_{i}^{\ell},v_{k}^{\ell^\prime})$, if $k = \nextpos[w[j_{i,\ell}],i+1] \leq n$ and $\ell^\prime = \arg\min_{t}\{j_{k,t}\in P_k \mid j_{k,t} > i\}$.
        \item For $i\in[n]$ and $\ell\in[n_i]$ we have an edge $(v_{i}^{\ell},f)$, if $w[j_{i,\ell}]\notin\al(w[i+1:n])$. 
        \item For all $i\in[n]$ and $\ell\in[n_i-1]$ there is an edge $(v_{i}^{\ell}, v_{i}^{\ell+1})$.
    \end{itemize}

    We define $\text{level}(s) = 0, \text{level}(f) = n+1$, and for all $i\in[n],\ \ell\in[n_i],$ we set $\text{level}( v_{i}^{\ell} ) = i$.
    The set $P_i = \{j_{i,1} < \ldots < j_{i,n_i}\}$ trivially induces an ordering $\rightedge{}{}{i}$ on the nodes $v_{i}^{\ell}$ such that $\rightedge{v_{i}^{1}}{v_{i}^{2}}{i}\rightedge{}{\ldots}{i}\rightedge{}{v_{i}^{n_i}}{i}$ for all $i\in[n]$. 

    By the definition of $V_i$ the number of nodes in each set $V_i$ is upper bounded by $\abs{V_i} \leq \sigma$. This bound on each of the sets yields the overall upper bound $\abs{V} \leq n\sigma + 2\in\O(n\sigma)$ on the full set of nodes. Further, every node, except for $s$ and $f$, has at most two outgoing edges and the number of edges originating in $s$ is also bounded by $\sigma$. Therefore, $\abs{E}\in\O(n\sigma)$ as well.  

\medskip

\noindent\emph{$\S $ Bijection.}
    We claim that the strings in $\mas(w)$ correspond bijectively to the $s-f$-paths in $D(G)$. %We assume that all edges reaching $v_{i}^{\ell}$ in $D(G)$ are labelled with $w[i]$. 

    Let $u$ be an MAS of $w$, with $\abs{u} = m+1$. We recall that by Theorem~\ref{thm:mas}, there exist positions $0 = i_0 < i_1 < \ldots < i_m < i_{m+1} = n+1$ such that the following four conditions are satisfied: \begin{enumerate}
        \item $u = w[i_1]\cdots w[i_m]u[m+1]$,
        \item $u[1] \notin \al(w[1:i_1-1])$,
        \item $u[k] \notin \al(w[i_{k-1}+1:i_k-1])$ for all $k\in[2:m+1]$,
        \item $u[k] \in \al(w[i_{k-2}+1:i_{k-1}])$ for all $k\in[2:m+1]$.
    \end{enumerate}

    We will show by induction that $u$ corresponds to a path $s, v_{i_1}^{\ell_1}, v_{i_2}^{\ell_2}, \ldots, v_{i_m}^{\ell_m}, f$. Since $i_1 = \nextpos[u[1], 1]$ and $w[i_2]\in w[1:i_1]$, there exists an $\ell_1\in [n_{i_1}]$ such that $w[j_{i_1,\ell_1}] = w[i_2]$, and thus there is an edge $(s, v_{i_1}^{\ell_1})$. 

    Assume now that the path $s, v_{i_1}^{\ell_1}, v_{i_2}^{\ell_2}, \ldots, v_{i_k}^{\ell_k}$ corresponds to the MAS-prefix $w[i_1]\cdots w[i_k]$ for $k\in [m-1]$ and $w[j_{i_k,\ell_k}] = w[i_{k+1}]=u[k+1]$, then the path $s, v_{i_1}^{\ell_1}, \ldots, v_{i_{k+1}}^{\ell_{k+1}}$ corresponds to the MAS-prefix $w[i_1]\cdots w[i_{k+1}]$ as follows. According to the induction hypothesis, $w[j_{i_k,\ell_k}] = w[i_{k+1}]$ and, according to the definition of $D(G)$, every edge originating in $v_{i_k}^{\ell_k}$ is of the form $(v_{i_k}^{\ell_k}, v_{i_{k+1}}^\ell)$, where $\ell\in\{t \in [n_{i_{k+1}}] \mid j_{i_{k+1}, t} > i_k\}$, since $i_{k+1} = \nextpos[w[i_{k+1}], i_k+1]$. By Theorem~\ref{thm:mas}, $u[k+2] \in w[i_k+1 : i_{k+1}]$, and, according to the definition of $P_{i_{k+1}}$, there exists an $\ell^\prime\in[n_{i_{k+1}}]$ such that $j_{i_{k+1},\ell^\prime} > i_{k}$ and $\al(w[i_k+1:i_{k+1}]) = \al(w[j_{i_{k+1,\ell^\prime}} : i_{k+1}])$. Therefore, we can extend the path $s, v_{i_1}^{\ell_1}, \ldots, v_{i_k}^{\ell_k}$ by node $v_{i_{k+1}}^{\ell_{k+1}}$ for $\ell_{k+1} \in [\ell^\prime : n_{i_{k+1}}]$ such that $w[j_{i_{k+1}, \ell_{k+1}}] = u[k+2]$. 

    Now, if the path $s, v_{i_1}^{\ell_1}, \ldots, v_{i_m}^{\ell_m}$ corresponds to the MAS-prefix $w[i_1]\cdots w[i_m]$ and $w[j_{i_m,\ell_m}] = u[m+1]$, then we can extend this path corresponding to the MAS $u$ by appending the sink $f$: since $u$ is an MAS, $\nextpos[w[j_{i_m,\ell_m}], i_m+1] = \nextpos[u[m+1], i_m+1] = n+1$ holds and thus, the only edge originating in $v_{i_m}^{\ell_m}$ is the edge $(v_{i_m}^{\ell_m}, f)$. We can therefore extend the path $s, v_{i_1}^{\ell_1}, \ldots, v_{i_m}^{\ell_m}$ using this edge, which yields a complete $s-f$-path in $D(G)$. Thus, every MAS has a corresponding $s-f$-path in $D(G)$. 

    For the reverse implication, consider a path from $s$ to $f$ in $D(G)$, namely $s, v_{i_1}^{\ell_1}, v_{i_2}^{\ell_2},\ldots, v_{i_m}^{\ell_m}, f$, where $w[j_{i_k,\ell_k}] = w[i_{k+1}]$ holds for all $k\in[m-1]$. We claim that this path corresponds to the MAS $u = w[i_1]w[i_2]\ldots w[i_m]b$, where $b = w[j_{i_m,\ell_m}]$. 
    According to the definition of $D(G)$, there is an edge $(s, v_{i_1}^{\ell_1})$ if and only if $i_1 = \nextpos[a, 1]$ for some $a=w[i_1]\in\Sigma$. Further, since $(v_{i_k}^{\ell_k}, v_{i_{k+1}}^{\ell_{k+1}})$ is a valid edge if and only if $i_{k+1} = \nextpos[w[j_{i_k,\ell_k}], i_k+1]$ and $j_{i_{k+1},\ell_{k+1}} > i_k$ for all $k\in[m-1]$, $w[i_{k+1}] = w[j_{i_k,\ell_k}] \in \al(w[j_{i_k,\ell_k}: i_k]) \subseteq \al(w[i_{k-1}+1 : i_k])$ and $w[i_{k+1}] \notin \al(w[i_k+1:i_{k+1}-1])$ hold and therefore, conditions 3 and 4 hold for all $k\in[m-1]$. By the same argument, conditions 3 and 4 also hold for $u[m+1] = b$, as $b\notin \al(w[i_m+1:n])$ (since there is an edge $(v_{i_m}^{\ell_m}, f)$) and $b = w[j_{i_m,\ell_m}] \in \al(w[j_{i_m,\ell_m}:i_m]) \subseteq \al(w[i_{m-1} : i_m])$ hold. Therefore, $u$ fulfills the four conditions 1 - 4 and every $s-f$-path in $D(G)$ corresponds to an MAS of $w$. 


\medskip

\noindent\emph{$\S $ Complexity.}
    We will first show that the sets $\{P_1, \dots, P_n\}$ can be precomputed in $\mathcal O(n\sigma)$ time and space. 

    An important initial observation is that the sets $P_i = \{j_{i,1},\dots, j_{i,n_i}\}$ and $P_{i+1} = \{j_{i+1,1}, \dots, j_{i+1, n_{i+1}}\}$ differ in at most two elements $j_{i,\ell}$ and $j_{i+1,\ell^\prime}$. Namely, $P_{i+1}$ must contain $i+1 = j_{i+1,n_{i+1}}$ (since $w[i+1:i+1]$ is the smallest interval containing $w[i+1]$) and $P_i$ can not contain $i+1$. 
    If position $i+1$ is the first occurrence of letter $w[i+1]$, then $n_i < n_{i+1}$ and $P_i \subsetneq P_{i+1} = P_i \cup \{i+1\}$. 
    Otherwise, $P_i$ contains an element $j_{i,\ell}$ such that $w[i+1] = w[j_{i,\ell}]$. Since $\text{alph}(w[j_{i,\ell} : i+1]) \supseteq \text{alph}(w[i+1:i+1]) = w[i+1]$, $w[j_{i,\ell}:i+1]$ is not the smallest interval ending in $i+1$ and containing $w[i+1]$, thus, $j_{i,\ell}\notin P_{i+1}$. 
    All other elements $j\in P_i$ are contained in $P_{i+1}$ as well. 

    As illustrated in Algorithm~\ref{MAS:algo:KM}, we can maintain a doubly linked list of the latest occurrence of each letter $a\in\Sigma$ up to position $i\in[n]$. In each step, we update letter $w[i]$ and copy the contents of the doubly linked list into row $i$ of an $n\times \sigma$ matrix $\KM$. 
    Since each update uses a constant number of steps and copying takes $\mathcal O(\sigma)$ time, we achieve an overall runtime of $\mathcal O(n\sigma)$ while using data structures of size $\mathcal O(n\sigma)$.  

    Using the sets $\{P_1,\dots,P_n\}$ we can now show that the computation of the edges $(v_i^\ell, v_k^{\ell^\prime})$ and $(v_i^\ell, f)$ for all $i\in[n]$ and $\ell\in[n_i]$, where $k = \nextpos[w[j_{i,\ell}],i+1]$ and $\ell^\prime = \min\{t\in[n_k]\mid j_{k,t} > i\}$ (if $k \leq n$), can be done in $\mathcal O(n\sigma)$ time as well. 

    We observe that, given two nodes $v_{x}^{y}$ and $v_{x^\prime}^{y^\prime}$, $j_{x,y}\in P_x, j_{x^\prime,y^\prime}\in P_{x^\prime}$, such that $w[j_{x,y}] = w[j_{x^\prime,y^\prime}]$, $x^\prime < x$, and $\nextpos[w[j_{x,y}],x+1] = \nextpos[w[j_{x^\prime,y^\prime}], x^\prime+1] = i$ (i.e., $v_x^y$ and $v_{x^\prime}^{y^\prime}$ both lead to a node on level $i$), then $j = \min\{p\in P_i\mid p > x\}$ is at least as large as $j^\prime = \min\{p\in P_i\mid p > x^\prime\}$. Thus, we can restrict the search for $j$ to the set $\{p\in P_i \mid p \geq j^\prime\} \subseteq P_i$. 

    We can therefore iteratively build the graph $G$ by computing all outgoing edges of each level $i\in[n]$, from the smallest to the largest level.
    To achieve this, we maintain information about the set restrictions mentioned above using an array $S$ of length $n$. Intuitively, $S[k]$ stores, for each value $k\in[n]$, the index $\ell^\prime$, such that $(v_i^\ell, v_k^{\ell^\prime})$ is the edge to level $k$ that was last added, or $1$, if no edge to level $k$ has been added to $G$ yet; note that $S[k] = 1$ is also possible if $i < j_{k,1}$.
    % We now compute the outgoing edges of all nodes $v_{i}^{\ell}$ for an increasing value $i\in[n]$ and $\ell\in[n_i]$ and maintain information about the set restrictions using an array $S$ of length $n$. 
    We initialize the values of $S$ to be $1$. 

    In each step, we obtain the outgoing edge of $v_{i}^{\ell}$ as follows.
    If $w[j_{i,\ell}]\notin \text{alph}(w[i+1:n])$, we simply add $(v_i^\ell, f)$ to the edge set. Assume now that $k = \nextpos[w[j_{i,\ell}], i+1] \leq n$ and set $s = S[k]$. 
    If $j_{k,s} > i$, we already found the smallest possible $j = j_{k,s} > i$ and add the resulting edge $(v_{i}^{\ell},v_{k}^{s})$.
    Otherwise, we iteratively search for $\ell^\prime\in[s+1:n_k]$ such that $j_{k,\ell^\prime} > i$ and $\ell^\prime$ is minimal,
    and add the resulting edge $(v_{i}^{\ell},v_{k}^{\ell^\prime})$. 
    We then set $S[k] = \ell^\prime$ and continue with the next node $v_i^{\ell+1}$ (or $v_{i+1}^1$, if $\ell=n_i$). 

    The value of $S[i]$, for $i\in[n]$, is updated at most $n_i-1 < \sigma$ times, where each update from value $s$ to $s^\prime$ takes $\mathcal O(\abs{s^\prime-s})$ time. 
    Therefore, updating all values $S[i]$ during the computation of the $\mathcal O(n\sigma)$ edges takes $\mathcal O(n\sigma)$ time. 
    Additionally, in each step we query the value of $S[i]$, which takes constant time, and use $\nextpos[a,i]$, which can be done in constant time after $\mathcal O(n\sigma)$ time preprocessing. 
    Thus, the computation of $(v_{i}^{\ell},v_{k}^{\ell^\prime})$ for all $i\in[n],~ \ell\in[n_i],~ k = \nextpos[w[j_{i,\ell}], i+1],~ \ell^\prime = \arg\min_{t}\{j_{k,t}\in P_k\mid j_{k,t} > i\}$, and therefore also the complete construction of the $(n+1)$-skeleton DAG $G$, can be done in $\mathcal O(n\sigma)$ time and space, which concludes the proof of our statement. %An implementation of the construction of $G$ can be seen in Algorithm~\ref{MAS:algo:main}.
\end{proof}



