\section{Figures and Pseudocodes}\label{sec:figures}

This section contains figures exemplifying the construction of skeleton-DAGs for $\mas(w)$ and $\sas(w)$ (Figures~\ref{fig:massas1} and \ref{fig:massas2}) as well as pseudocodes implementing the construction of these skeleton-DAGs (Algorithm~\ref{SAS:algo:main}, and Algorithms~\ref{MAS:algo:KM}~and~\ref{MAS:algo:main}, respectively). 

\begin{algorithm}[tbh]
    \caption{compute$\sas G$($w$)}\label{SAS:algo:main}
    \footnotesize
    \KwData{String $w$ with $\abs{w}=n$, alphabet $\Sigma=$ alph$(w)$ with $\abs{\Sigma}=\sigma$}
    \KwResult{Skeleton DAG $G$ consisting of $\mathcal O(n)$ nodes and edges representing all $\sas$ of $w$}
    compute arch factorisation of $w$, $\dist[\cdot]$, $\firstPosArch[\cdot][\cdot]$, and $\lastPosArch[\cdot][\cdot]$\;
    \For{$\ell=1$ \KwTo $k-1$}{
        \For{$i \in \text{ar}_w(\ell)$}{
            \lIf{$i = \firstPosArch[\ell][w[i]]$ $\wedge$ $\dist[i] = k - \ell + 2$}{add $i$ to $F_\ell$}
            \If{$i = \lastPosArch[\ell][w[i]] \wedge \dist[\firstPosArch[\ell+1][w[i]] = k - (\ell + 1) + 2$}{add $i$ to $G_\ell$\;}
            %\If{$i = \lastPosArch[\ell][w[i]]$}{
            %    \If{$\left(\ell < k \wedge \dist[\firstPosArch[\ell+1][w[i]] = k - (\ell + 1) + 2\right)\vee \left( \ell=k \wedge w[i] \notin \text{alph}(r(w))\right)$}{
            %    add $i$ to $G_\ell$\;}
            %}
            %\If{$i = \lastPosArch[\ell][w[i]] \wedge \left(\left(\ell < k \wedge \dist[\firstPosArch[\ell+1][w[i]] = k - (\ell + 1) + 2\right)\vee \left( \ell=k \wedge w[i] \notin \text{alph}(r(w))\right)\right)$}{add $i$ to $G_\ell$\;}
        }
    }
    \For{$i \in \text{ar}_w(k)$}{
        \lIf{$i = \firstPosArch[k][w[i]]$ $\wedge$ $\dist[i] = 2$}{add $i$ to $F_k$}
        \lIf{$i = \lastPosArch[k][w[i]] \wedge w[i] \notin \text{alph}(r(w))$}{add $i$ to $G_k$}
    }
    % \For{$\ell=1$ \KwTo $k$}{
    %     \lIf{$\ell < k$ $\wedge$ $\dist[\firstPosArch[\ell+1][w[i]] \neq k - (\ell + 1) + 2$}{
    %         remove $i$ from $G_\ell$
    %     }
    %     \lIf{$\ell = k$ $\wedge$ $w[i] \in \text{alph}(r(w))$}{
    %         remove $i$ from $G_\ell$
    %     }
    % }
    $V \gets \{s, f\} \cup \bigcup_{\ell=1}^k F_\ell \cup \{n+i \mid i \in [\sigma]\}$\;
    \For{$i = 1$ \KwTo $\abs{F_1}$}{
        \lIf{$i+1 < \abs{F_1}$}{add $(F[i+1], F[i])$ to $E$}
    }
    \For{$\ell = 2$ \KwTo $k$}{
        \For{$i = 1$ \KwTo $\abs{G_\ell}$}{
            \lIf{$i+1 < \abs{G_\ell}$}{add $(\firstPosArch[\ell][w[G_\ell[i]]], \firstPosArch[\ell][w[G_\ell[i+1]]])$ to $E$}
        }
    }
    \For{$i = 1$ \KwTo $\abs{G_k}$}{
        \lIf{$i+1 < \abs{G_k}$}{add $(n+w[G_k[i]], n+w[G_k[i+1]])$ to $E$}
    }
    \For{$\ell = 1$ \KwTo $k$}{
        $d \gets 1$\;
        \For{$i = 1$ \KwTo $\abs{F_\ell}$}{
            \lWhile{$G_\ell[d] < F_\ell[i]$}{
                $d \gets d+1$}
            \lIf{$\ell+1 \leq k$}{
                add $(F_\ell[i], \firstPosArch[\ell+1][w[G_\ell[d-1]]])$ to $E$}
            \lIf{$\ell+1 = k+1$}{
                add $(F_\ell[i], n+w[G_\ell[d-1]])$ to $E$}
        }
    }

    \Return{$(V, E)$.}
\end{algorithm}


\begin{algorithm}[tbh]
    \caption{computeP($w$)} \label{MAS:algo:KM}
    \footnotesize
    \KwData{String $w$ with $\abs{w}=n$, alphabet $\Sigma=$ alph$(w)$ with $\abs{\Sigma}=\sigma$}
    \KwResult{Matrix $\KM$ such that $\KM[i,\cdot]$ contains the set $P_{i}$ for $i \in [n]$, and $\KM[i,j]$ maintains the internal total order for increasing  $j \in [\sigma]$.} % not quite happy with this phrase.
    array \knp\  of length $\sigma$ with elements initially set to $0$\;
    array \knn\  of length $\sigma$ with elements initially set to $n+1$\;
    matrix \KM\  of size $n\times\sigma$ with elements initially set to $\infty$\;
    $last\gets 0$\;
    $first \gets n+1$\;
    \For{$i=1$ \KwTo $n$}{
        $x\gets w[i]$\;
        \If{$\knn[x]=n+1$}{
            \If{$\knp[x]=0$}{
                \If{$first=n+1 \vee w[first] = x$}{$first\gets i$\;}
                \Else{
                    $\knp[x]\gets last$\;
                    $\knn[w[last]]\gets i$\;
                }
                $last\gets i$\;
            }
            \Else{
                $\knn[w[\knp[x]]]\gets i$\;
                $last\gets i$\;
            }
        }
        \Else{
            \If{$x = w[first]$}{$first\gets \knn[x]$\;}
            \Else{
                $tmp \gets \knn[x]$\;
                $\knn[w[\knp[x]]]\gets tmp$\;
                $\knp[w[tmp]]\gets \knp[x]$\;
            }
            $\knp[x]\gets last$\;
            $\knn[x]\gets n+1$\;
            $\knn[w[last]]\gets i$\;
            $last\gets i$\;
        }

        $current\gets first$\;
        $row \gets 1$\;
        \While{$current\neq n+1$}{
            $\KM<row>[i]\gets current$\;
            $row\gets row+1$\;
            $current\gets \knn[w[current]]$\;
        }
    }
    \Return{\textup\KM.}
\end{algorithm}

\begin{algorithm}[tbh]
    \caption{compute$\mas G$($w$)}\label{MAS:algo:main}
    \footnotesize
    \KwData{String $w$ with $\abs{w}=n$, alphabet $\Sigma=$ alph$(w)$ with $\abs{\Sigma}=\sigma$}
    \KwResult{Skeleton DAG $G$ consisting of $\mathcal O(n\sigma)$ nodes and edges representing all $\mas$ of $w$}
    compute $\nextpos[\cdot,\cdot]$, and $\KM$\;
    array $S$ of length $n$ with elements initially set to $1$\;
    \For{$a=1$ \KwTo $\sigma$}{
        $i\gets\nextpos[1,a]$\;
        add $(s,v_{i}^{1})$ to the list of edges of $G$\;
    }
    \For{$i=1$ \KwTo $n$}{
        \For{$\ell=1$ \KwTo $\sigma$}{
            $j\gets \KM<\ell>[i]$\;
            \If{$j\neq \infty$}{
                $k \gets \nextpos[w[j],i+1]$\;
                \If{$k\leq n$}{
                    $s\gets S[k]$\;
                    \While{$\KM<s>[k]\leq i$}{$s\gets s+1$\;}
                    %$k\gets \KM<start>[\ell]$\;
                    add $(v_{i}^{\ell},v_{k}^{s})$ to the list of edges of $G$\;
                    $S[k]\gets s$\;
                }
                \Else{
                    add $(v_{i}^{\ell},f)$ to the list of edges of $G$\;
                }
                \If{$\ell>1$}{
                    %$j_{prev}\gets\KM<row-1>[i]$\;
                    add $(v_{i}^{\ell-1},v_{i}^{\ell})$ to the list of edges of $G$\;
                }
            }
        }
    }

    \Return{$G$.}
\end{algorithm}

