%Allocate memory for $B_{remote}$ combining the information contained in  $nonzerosPerRow$ and $rowsToReceive$\;\label{memAlloc}
%$B_{remote} \leftarrow MPI_{point-to-point}(B_{local})$\;\label{mpiP2P}
