\begin{center}
\includegraphics[width=0.48\textwidth]{FIGURES/SETUP.pdf}
\includegraphics[width=0.48\textwidth]{FIGURES/setupbreakdown.pdf}
\caption{Weak Scalability: Preconditioner Setup Time and Breakdown of Setup Time\label{fig-weak3}}
\end{center}
\end{figure*}
