  \caption{Benchmarks for % Algorithm
    \Cref{alg:genfglm}}
  \label{tbl:bench}
  \centering
  \begin{tabular}{l|r|r|r|}
    &\multicolumn{2}{c|}{\Cref{alg:genfglm}} & \msolve with $\targmord$\\[0pt]
    System & Timing (in s) & Memory & Timing (in s)\\[0pt]
    \hline
    ED(3,3) & 237.9 & 95.47 GB & 43521.43\\[0pt]
    R1 & 0.01 & 140.49 GB & 0.01\\[0pt]
    R2 & 0.01 & 251.95 MB & 0.01\\[0pt]
    R3 & 0.01 & 248.93 MB & 0.01\\[0pt]
    M2 & 2.75 & 1.56 GB & 0.03\\[0pt]
    M3 & 0.19 & 410.09 MB & 0.01\\[0pt]
    PS(2,10) & 0.8 & 417.63 MB & 0.3\\[0pt]
    PS(2,12) & 44.82 & 1.38 GB & 7.3\\[0pt]
    Sing(2,10) & 0.2 & 275.17 MB & 0.1\\[0pt]
    SOS(5,4) & 1.2 & 1.2 GB & 0.3\\[0pt]
    SOS(6,4) & 11.97 & 1.07 GB & 30.35\\[0pt]
    SOS(6,5) & 22.19 & 954.41 MB & 26.61\\[0pt]
