\subsubsection{Smooth graphons}\label{sec:smooth}


\begin{definition}
\label{definition: holder graphon}
Given $\alpha>0$, $H>0$, we say that $W : [0,1]^2 \rightarrow [0,1]$ is an $(H,\alpha)$-H\"{o}lder continuous graphon if
$$
\vert W(x',y')-P_{\lfloor \alpha\rfloor}((x,y), (x'-x,y'-y))   \vert \le H (\vert x'-x\vert^{\alpha-\lfloor \alpha\rfloor}+\vert y'-y\vert^{\alpha-\lfloor \alpha\rfloor})
$$
for all $(x',y'), (x,y) \in [0,1]^2$, where $\lfloor \alpha\rfloor$ is the maximal integer less than $\alpha$, and the function $(x',y')\mapsto P_{\lfloor \alpha\rfloor}((x,y), (x'-x,y'-y))$ is the Taylor expansion of $W$ of degree $\lfloor \alpha\rfloor$ at point $(x,y)$. 
%Let $H, \alpha$ be positive constants. We call a graphon $W$ $(H, \alpha)$-H\"older if there exist partial derivatives $\frac{\partial^{i + j}}{\partial x^i \partial y^j} W(x, y)$ and for all $x, y, x', y' \in [0,1]$ it holds
%	\begin{align*}
%		\sum_{ i , j, i + j = \lfloor \alpha \rfloor} \frac{1}{i! j!} \left | \frac{\partial^{i + j}}{\partial x^i \partial y^j} W(x, y) - \frac{\partial^{i + j}}{\partial x^i \partial y^j} W(x', y') \right | \le H \left (\left |x - x' \right |^{\alpha - \lfloor \alpha \rfloor} + \left |y - y' \right |^{\alpha - \lfloor \alpha \rfloor} \right ),
%	\end{align*}
%	where $\lfloor \alpha \rfloor$ is the maximal integer strictly less than $\alpha$.
\end{definition}
We denote the class of all $(H,\alpha)$-H\"{o}lder continuous graphons by $\Sigma(\alpha,H)$. 
\begin{remark}
It follows from the standard embedding theorems that, for any $W\in \Sigma(\alpha, L)$ and any $(x',y'), (x,y) \in [0,1]^2$,
\begin{equation}\label{lip}
\vert W(x',y') - W(x,y)\vert \le M (\vert x'-x\vert^{\alpha\wedge 1}+\vert y'-y\vert^{\alpha\wedge 1})
\end{equation}
where $M$ is a constant depending only on $\alpha$ and $H$. In the following, we will use only this last property of $W\in \Sigma(\alpha, L)$. For example, an $L$-Lipschitz function is $(L, 1)$-H\"older continuous.     
\end{remark}


Next we prove an upper bound on the error and the rank of our estimator in the case of  $(H, \alpha)$-H\"older continuous graphons.

\begin{theorem}
\label{theorem: holder convergence rate}
Consider a graphon $W\in \Sigma (\alpha, H)$. Let $\beta = \min(\alpha, 1)$. Assume that 
   $n \rho_n \ge \constantBandeira \log (2 n/\delta)$. Then, there exist constants $C$ and $C'$ depending on $\alpha, H$ such that for any $\delta \in (0,1]$, with probability at least $1 - \delta$, it holds that
	\begin{align*}
		i)&\ \opnorm{\rho_n \bbW - \bbW_{\bQhat_\lambda}} \le \rho_n  C \cdot \left ( \frac{\log (4 n/\delta)}{n} \right )^{\beta/2} + 11 \sqrt{\frac{\rho_n}{n}}, \\
		ii)&\  \rank (\bQhat_{\lambda})  \le C' \left ( n \rho_n \right )^{\frac{1}{1 + 2 \alpha}}. 
	\end{align*}
\end{theorem}
%
%It is well-known that H\"older conditions control the smoothness of a function. Hence, one may suppose that smooth graphons admit similar rates of convergence of $\delta_{\op}(\rho_n W, W_{\bQhat_{\lambda}})$ but $\bQhat_\lambda$ has the logarithmic rank in $n \rho_n$.
The proof of this result can be found in Appendix \ref{appendix: proof of Holder convergence rate}. 

An important property of H\"older graphons is that they can be well approximated by piecewise polynomial functions of degree at most $\lfloor \alpha \rfloor $. More generally, we can consider a class of function that can be approximated  by polynomials with arbitrary precision. 

\begin{definition}
\label{condition: M-r analiticity}
    Given $M > 0$, $r > 0$,  we say that $W : [0,1]^2 \rightarrow [0,1]$ is $(M,r)$-analytic if there exist functions $c_k : [0, 1]^2 \to [-Mr^{-k}, Mr^{-k}]$ for each $k \in \bbN$ such that
    \begin{enumerate}
        \item $	W(x, y) = \sum_{k = 0}^{\infty} c_k(x_0, y) (x - x_0)^k $ for any $x_0, y$ and $x, |x - x_0| < r$, 
        \item $	W(x, y) = \sum_{k = 0}^{\infty} c_k(x, y_0) (y - y_0)^k $ for any $y_0, x$ and $y, |y - y_0| < r$.
    \end{enumerate}
% {\color{red} Note that the second bullet is implied by the first for symmetric graphons. CHECK} \magenta{(Also requires $c_k$ to be symmetric: $W(x,y) = W(y,x) = \sum_{k = 0}^{\infty} c_k(y_0, x) (y - y_0)^k  = \sum_{k = 0}^{\infty} c_k(x, y_0) (y - y_0)^k $ only if $c_k$ is symmetric)}

\end{definition}

Roughly speaking, a graphon $W$ is $(M,r)$-analytic if it is analytic on $x$ uniformly with respect to $y$, its Taylor series has radius of convergence $r$, and the coefficients are bounded by $M$. Since the functions $c_k$ are bounded, $W$ satisfies the $(H, 1)$-H\"older condition for some $H$.\footnote{This is shown in Appendix \ref{appendix: proof of analytic convergence rate}.} Consequently, using Theorem \ref{theorem: holder convergence rate}, we derive the following result.

\begin{theorem}
\label{theorem: analityc convergence rate}
Consider a graphon $W$ that is $(M,r)$-analytic. Assume that $n \rho_n \ge \constantBandeira \log (2 n/\delta)$. Then, there are constants $C$ and $C'$ depending on $M$, $r$ such that for any $\delta \in (0,1]$, with probability at least $1 - \delta$, it holds that
    \begin{align*}
        i)&\ \opnorm{\rho_n \bbW - \bbW_{\bQhat_\lambda}}  \le \rho_n  C \cdot \left ( \frac{\log \frac{4 n}{\delta}}{n} \right )^{1/2} + 11 \sqrt{\frac{\rho_n}{n}}, \\
        ii)&\ \rank (\bQhat_{\lambda})  \le C' \log (n \rho_n).
    \end{align*}
\end{theorem}

The proof of this result can be found in Appendix \ref{appendix: proof of analytic convergence rate}. 

\begin{remark}
    Theorems \ref{theorem: holder convergence rate} and \ref{theorem: analityc convergence rate} can be easily extended to the case when $W$ is piecewise H\"older and piecewise analytic respectively.
\end{remark}




\begin{remark}
    Note that our estimator $\widehat{\bQ}_{\lambda}$ is not guaranteed to be symmetric or to take values in $[0,1]$. We can symmetrize it taking $\widetilde {\bQ}_{\lambda}=(\widehat{\bQ}_{\lambda}+\widehat{\bQ}^{T}_{\lambda})/2$. Then, $\rank (\widetilde {\bQ}_{\lambda})\leq 2 \rank (\widehat{\bQ}_{\lambda})$ and, if $W$ is symmetric, using $W(x,y)=(W(x,y)+W(y,x))/2$, we get 
    $\opnorm{\rho_n W - W_{\widetilde \bQ_\lambda}}\leq \opnorm{\rho_n W - W_{\bQhat_\lambda}}$.
\end{remark}
\section{Back to Targeted Interventions}\label{section:simulations}
 In this section, we integrate our results to demonstrate how optimal interventions in the network \( \mathbf{A} \) can be estimated using a smaller network \( \mathbf{A}' \) sampled from the same underlying graphon. Notably, \( \mathbf{A}' \) can potentially be obtained by subsampling \( \mathbf{A} \).  
By combining the stability analysis from Theorem~\ref{theorem: graphon perturbed welfare problem} with the convergence results from Theorems~\ref{theorem: SBM convergence rate}, \ref{theorem: holder convergence rate}, and \ref{theorem: analityc convergence rate} , we obtain the following corollary.  
\begin{corollary}
\label{corollary: convergene rate targeted interventions}
   Fix a positive integer $N$. Consider an LQ network game $G(\bA,\btheta)$ with the budget $B \cdot N$ and the peer-effect parameter $\gamma$, $\gamma \Vert \bA \Vert_{\op} < N$, where $\bA$ is a network of size $N$ sampled from a sparse graphon $\rho_N W$.
    Let $T_{(\bA,\btheta)}(\cdot)$ be the objective function of the social welfare problem \eqref{eq: graphon social welfare problem} associated with $G(\bA,\btheta)$. Fix $n$, and consider an estimator $\widehat{W} = W_{\bQ_\lambda}$ of the graphon $\rho_n W$ based on a network $\bA'$ of size $n$ sampled from the graphon $\rho_n W$. Assume that $\gamma \Vert \bA' \Vert_{\op} < \rho_N / \rho_n \cdot n$.
    Let $\hat{t}'$ be the optimal solutions of the social welfare problem associated with graphon game $G(\rho_N / \rho_n \cdot \widehat{W},\tilde \theta)$ with
    \begin{align*}
        \tilde \theta(x) = \sum_{i = 1}^N \btheta_i \cdot \indicator{x \in [(i-1)/N, i/N)}
    \end{align*}
    and budget $B$.
    Define a vector $\widehat{\btheta}' \in \bbR^N$ as
    \begin{align*} 
        \widehat{\btheta}'_i = N \cdot \int_{(i - 1)/N}^{i/N} \hat{t}'(x) dx.
    \end{align*}
    Let $\widehat{\btheta}$ be the optimal solution of the network game $G(\bA,\btheta)$.
    Then, given any $\delta \in (0, 1)$, with probability at least $1 - \delta$, provided $\rho_N N^2 \ge n \rho_n \constantBandeira^2 \log^2(4N/\delta)$ and $n \rho_n \ge \constantBandeira \log (16 n/\delta)$, we have
    \begin{align*}
        T_{(\bA,\btheta)}(\hat{\btheta}) - T_{(\bA,\btheta)}(\hat{\btheta}') \leq \tau \cdot \begin{cases}
           \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + 2 \rho_N \left ( \frac{32k \sum_{a = 1}^{k - 1}e_a}{n} \log \left ( \frac{16k}{\delta} \right) \right )^{1/4} \right ), & \quad \text{if $W$ is $k$-SBM}, \\
            \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + C_1(H, \alpha) \rho_N \left ( \frac{\log(16n/\delta)}{n} \right)^{\beta/2}  \right ), & \quad \text{if $W$ is $(H,\alpha)$-\holder}, \\
          \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + C_1(M, r) \rho_N \left ( \frac{\log(16n/\delta)}{n} \right)^{1/2}  \right ), &\quad \text{if $W$ is $(M,r)$-analytic},
        \end{cases}
     \end{align*}
     where 
     \begin{align*}
         \tau = \frac{2 \gamma (1 + \gamma \Vert \bA\Vert_{\op}/N)^2 (\Vert \btheta \Vert/\sqrt{N} + \sqrt{B})^2}{\left (1 - \gamma \cdot \max \{\Vert \bA \Vert_{\op}/N, \rho_N \Vert \bA' \Vert_{\op}/n\rho_n\} \right )^5},
     \end{align*}
     $\beta = \min(\gamma, 1)$, the constant $C_1(H, \gamma)$ depends on $H$ and $\gamma$ only, and the constant $C_2(M, r)$ depends on $M$ and $r$ only.
     % \begin{align}
    %     C_1 = \frac{(\Theta + \sqrt{B})(1 + \alpha \rho_n \Vert \bbW \Vert_{\op} )^2}{\left(1 - \alpha [\rho_n \Vert \bbW \Vert_{\op} \vee \Vert \bbW_{\bQhat} \Vert_{\op}]\right)^4}, \ \blue{C_2 = 4L}, \ C_3 = \frac{2 \alpha \left (\Theta + \sqrt{B} \right )}{1 - \alpha [\rho_n \Vert \bbW \Vert_{\op} \vee \Vert \bbW_{\bQhat} \Vert_{\op}]}, \ \beta = \min(\alpha, 1). 
    % \end{align}
     Moreover, $\hat\btheta'$ can be computed by solving an SDP with 2 variables and an LMI constraint involving a matrix of dimension $r_n + 2$, where
     \begin{align*}
         r_n \leq 
        \begin{cases}
            k, & \quad \text{if $W$ is $k$-SBM}, \\
             C'_1(H, \alpha) \left ( n \rho_n \right )^{\frac{1}{1 + 2 \alpha}}, & \quad \text{if $W$ is $(H,\alpha)$-\holder}, \\
           C'_2(M, r)\log (n \rho_n), & \quad \text{if $W$ is $(M,r)$-analytic}. 
        \end{cases}
    \end{align*}
 \end{corollary}

 The proof is provided in Appendix~\ref{section: convergence rate targeted interventions}.


 \subsection{Numerical experiments}

 We start by illustrating our theory by the following example. Consider a graphon $W_1$ defined as follows:
 \begin{align*}
     W_1(x, y) = \sqrt{|x - y|}.
 \end{align*}
 This graphon is $(1, 1/2)$-H\"older, since for any $x_1, x_2, y_1, y_2$, we have
 \begin{align*}
     W_1(x_1, y_1) - W_1(x_2, y_2) & = \sqrt{|x_1 - y_1|} - \sqrt{|x_2 - y_2|} \\
     & \le \sqrt{|x_2 - y_2| + |x_1 - x_2| + |y_1 - y_2|} - \sqrt{|x_2 - y_2|} \\
     & \le |x_1 - x_2|^{1/2} + |y_1 - y_2|^{1/2},
 \end{align*}
 where we used the triangle inequality and the fact that $\sqrt{a + b} \le \sqrt{a} + \sqrt{b}$ for any non-negative $a, b$. For each $n \in \{20, 120, \ldots, 4920\}$, we sample a network $\bA$ and heterogeneity parameters $\btheta$ as follows:
 \begin{align}
 \label{eq: experiment sample scheme}
 \begin{cases}
     \bA_{ij} & = Bern(\rho_n W(\xi_{(i)}, \xi_{(j)})), \quad i < j,\\
     \btheta_i & = \xi_{(i)}^2,
 \end{cases}
 \end{align}
 where $\rho_n = n^{-0.25}$ and $\xi_1, \ldots,\xi_n$ are samples from the uniform distribution on $[0, 1]$. For each $\bA$, we compute optimal interventions $\widehat{\btheta}$ with budget $B = n / 2$ and the peer-effect parameter $\gamma = 0.8$ using the representation~\eqref{eq: hat theta equation} and the algorithm suggested in~\cite{gander1989constrained}. Then, we compute optimal interventions $\widehat{\btheta}'$ for the same $\btheta$ and the empirical graphon of $\widehat{\bQ}_\lambda$ for $\lambda = 2 \sqrt{n \rho_n}$. We choose $\lambda$ smaller than suggested by our theory since otherwise the rank of $\widehat\bQ_{\lambda}$ will be either $0$ or $1$ for those values of $n$ which we study. In the upper-left picture of Figure~\ref{fig:experiments}, we plot the dependence of difference between target functions $T(\widehat{\btheta})$ and $T(\widehat{\btheta}')$ computed for interventions on the network $\bA$. In the lower-left picture of Figure~\ref{fig:experiments}, we plot the rank of $\widehat{\bQ}_\lambda$.  To construct empirical $0.9$-confidence intervals, we repeat the experiment 100 times. As one can see, the network can be efficiently approximated by a low-rank matrix, despite the fact that the underlying graphon is not low-rank.


 Then, we consider the case when a network is sampled from an SBM graphon with $K = 4$ communities, i.e.
 \begin{align*}
     W_2(x, y) = \bB_{\lceil 4x \rceil, \lceil 4y \rceil}
 \end{align*}
 and $\bB$ is a symmetric matrix which entries are generated as follows. Let $\{u_{ij}\}_{1 \le i \le j \le K}$ be independent samples from the uniform distribution on $[0, 1]$, then
 \begin{align*}
     \bB_{ij} = \begin{cases}
         u_{ij} / 2, \text{ if } i < j, \\
         (1 + u_{ij}) / 2, \text{ if } i = j.
     \end{cases}
 \end{align*}
 We generated the matrix $\bB$ once, and keep it fixed during all experiments. For each $n \in \{20, 40, \ldots, 980\}$, we sample 100 different pairs of a network $\bA$ and a heterogeneity vector $\btheta$ using the procedure~\eqref{eq: experiment sample scheme}. For each pair, we compute the optimal interventions $\widehat{\btheta}$ with budget $n/2$ and the peer-effect parameter $\gamma = 0.8$ as before. Then, we compute an estimator $\widehat{\btheta}'$ of optimal interventions based on truncated SVD with $4$ components and the true graphon $W_2$. We plot the difference between the target functions for the optimal intervention vector and its estimator in Figure~\ref{fig:experiments}, middle. As can be seen, truncated SVD outperforms graphon-based interventions. 

 Finally, we run the following experiment. We generate a network $\bA$ and the heterogeneity vector $\btheta$ of size $N = 10000$ from $W_2$. Then, for each $n \in \{100, 200, \ldots, 1500\}$, we generate a network $\bA'$ of size $n$, construct an estimator $\widehat{W}$ of the sparse graphon $\rho_n W_2$ based on the truncated SVD, and estimate optimal interventions in $\bA$ using $\widehat{W}$. We estimate the ratio of sparsities $\rho_N / \rho_n$ using the ratio between average degrees. We plot the result in Figure~\ref{fig:experiments}, right. The dashed line corresponds to interventions based on the true graphon $W_2$. We average the result over $600$ generations of matrix $\bA'$ for each $n$.

