\section{Proof of Theorem~\ref{theorem: graphon perturbed welfare problem}}\label {proof_graphon_perturbed_welfare_problem}

The problem of optimal interventions in graphon can be restated as follows:
\begin{align*}
    \max_{\hat{\theta}} T(\hat{\theta}) = \frac{1}{2} \left \Vert  \left ( \bI - \gamma \bbW \right )^{-1} (\theta + \hat \theta) \right \Vert_{L_2}^2 \\
    \text{subject to } \Vert \hat \theta\Vert^2_{L_2} \le B,
\end{align*}
see the proof of Proposition 1 in~\cite{Parise_Ozdaglar_Econometrica}. From the self-adjointness of the opertator $\bbW$, we have
\begin{align*}
    T_i(\hat{\theta}) = \frac{1}{2} \left \langle (\bI - \gamma \bbW_i)^{-2} [\theta + \hat{\theta}], \theta + \hat \theta \right \rangle, \quad i = 1, 2.
\end{align*}

Given a Hilbert-Schmidt operator $\bbW$, we claim that the squared resolvent $\cR^2(\gamma, \bbW) = (\bI - \gamma \bbW)^{-2}$ is $\beta$-strongly monotone for $\beta = (1 + \gamma \Vert \bbW \Vert_{\op})^{-2}$. Indeed, for any $f$ we have
\begin{align*}
	\< (\bI - \gamma \bbW) [f], (\bI - \gamma \bbW) [f] \> \le \Vert \bI - \gamma \bbW_1 \Vert^2_{\op} \Vert f \Vert_{L_2}^2 \le (1 + \gamma \Vert \bbW_1 \Vert_{\op})^2 \Vert f \Vert_{L_2}^2
\end{align*}
from the Cauchy-Shwartz inequality. For arbitrary $f'$ consider $f = \cR(\gamma, \bbW)[f']$. Then
\begin{align*}
	(\bI - \gamma \bbW) [f] = f',
\end{align*}
so
\begin{align*}
	\< \cR^2(\gamma, \bbW) [f'], [f'] \> = \< \cR(\gamma, \bbW) [f'], \cR(\gamma, \bbW) [f'] \> \ge \frac{1}{(1 + \gamma \Vert \bbW \Vert_{\op})^2} \Vert f' \Vert_{L_2}.
\end{align*}
Since $\cR^2(\gamma, \bbW)$ is linear, the $\beta$-monotonicity is proven.


Next, due to Proposition~\ref{proposition: VI statement}, problems of maximization of $T_1$ and $T_2$ can be reformulated as \newline $VI(\cR^2(\gamma, \bbW_1)[\theta + \cdot], \cB_B(0))$ and $VI(\cR^2(\gamma, \bbW_2)[\theta + \cdot], \cB_B(0))$ where $\cB_B(0)$ stands for the ball with radius $B$ and center $0$. Thus, using Proposition~\ref{prop: stability of VI} we get
\begin{align}
	{\Vert \hat \theta_1 - \hat \theta_2 \Vert_{L_2}} & \le (1 + \gamma \Vert \bbW_1 \Vert_{\op} )^2 \Vert \cR^2(\gamma, \bbW_1) [\theta + \hat \theta_1] -  \cR^2(\gamma, \bbW_2) [\theta + \hat \theta_1] \Vert_{L_2} \nonumber \\
	& \le (1 + \gamma \Vert \bbW_1 \Vert_{\op} )^2  \cdot \Vert \cR^2(\gamma, \bbW_1)-  \cR^2(\gamma, \bbW_2) \Vert_{\op} \cdot \Vert \theta + \hat \theta_1 \Vert_{L_2}. \label{eq: theta difference bound proof}
\end{align}
 To bound the operator norm of the difference, we use decomposition
\begin{align*}
	\cR^2(\gamma, \bbW) = \sum_{i = 0}^\infty (i + 1) \gamma^i \bbW^i.
\end{align*}
The right-hand side converges because $\gamma \Vert \bbW_i \Vert <1$ for $i = 1, 2$.
Hence, we have
\begin{align*}
	\cR^2(\gamma, \bbW_1) - \cR^2(\gamma, \bbW_2) = \sum_{i = 1}^\infty (i + 1) \gamma^i (\bbW_1^i - \bbW_2^i).
\end{align*}
Finally, we bound $\Vert \bbW_1^i - \bbW_2^i \Vert_{\op}$ by induction on $i$ as follows:
\begin{align*}
	\Vert \bbW_1^i - \bbW_2^i \Vert_{\op} \le i \cdot \Vert \bbW_1 - \bbW_2 \Vert_{\op} \cdot (\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op})^{i - 1}.
\end{align*}
The base $i = 1$ is trivial. Next, we obtain 
\begin{align*}
	{\Vert \bbW_1^i - \bbW_2^i \Vert}_{\op} & = \Vert \bbW^{i - 1}_1 (\bbW_1 - \bbW_2) + \bbW_2 (\bbW^{i - 1}_1 - \bbW_2^{i - 1}) \Vert_{\op} \\
	& \le \Vert \bbW_1 \Vert_{\op}^{i - 1}  \Vert \bbW_1 - \bbW_2 \Vert_{\op} + \Vert \bbW_2 \Vert_{\op} \Vert \bbW^{i - 1}_1 - \bbW_2^{i - 1} \Vert_{\op} \\
	& \overset{\text{I.H.}}{\le} \Vert \bbW_1 \Vert_{\op}^{i - 1} \Vert \bbW_1 - \bbW_2 \Vert_{\op} + (i - 1) \Vert \bbW_2 \Vert_{\op} \Vert \bbW_1 - \bbW_2 \Vert_{\op} (\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op})^{i - 2} \\
	& \le i \cdot \Vert \bbW_1 - \bbW_2 \Vert_{\op} \cdot (\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op})^{i - 1}.
\end{align*}
Hence, we have
\begin{align*}
	\Vert \cR^2(\gamma, \bbW_1) - \cR^2(\gamma, \bbW_2) \Vert_{\op} & \le \Vert \bbW_1 - \bbW_2 \Vert_{\op} \sum_{i = 0}^{\infty} (i + 1)(i + 2) \gamma^{i + 1} (\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op})^{i} \\
	& = \frac{2 \gamma \Vert \bbW_1 - \bbW_2 \Vert_{\op}}{(1 - \gamma [\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op}])^3}.
\end{align*}
Substituting the above into~\eqref{eq: theta difference bound proof}, we get
\begin{align}
	{\Vert \hat \theta_1 - \hat \theta_2 \Vert_{L_2}} & \le \frac{2 \gamma \cdot (1 + \gamma \Vert \bbW_1 \Vert_{\op} )^2}{(1 - \gamma [\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op}])^3} \Vert \bbW_1 - \bbW_2 \Vert_{\op} \Vert \theta +  \hat \theta_1 \Vert_{L_2} \nonumber \\
	& \le \frac{2 \gamma \cdot (1 + \gamma \Vert \bbW_1 \Vert_{\op} )^2}{(1 - \gamma [\Vert \bbW_1 \Vert_{\op} \vee \Vert \bbW_2 \Vert_{\op}])^3} \Vert \bbW_1 - \bbW_2 \Vert_{\op} \cdot \left (\Vert \theta \Vert_{L_2} + \sqrt{B} \right ). \label{eq: theta difference bound}
\end{align}
To establish a bound on \(T_1(\hat{\theta}_1) - T_1(\hat{\theta}_2)\), we use a formula that holds for any vectors \(\ba\) and \(\bc\):
\begin{align*}
	\< \ba, \ba \> - \< \bc, \bc \> = \<\ba + \bc, \ba - \bc \>.
\end{align*}
Hence, taking $\ba=\cR(\gamma, \bbW_1) [ \theta + \hat \theta_1]$ and $\bc=\cR(\gamma, \bbW_1) [ \theta + \hat \theta_2]$ we derive
\begin{align*}
	T_1(\hat \theta_1) - T_1 (\hat \theta_2) & = \frac{1}{2} \< \cR^2(\gamma, \bbW_1) [2 \theta + \hat \theta_1 + \hat \theta_2], \hat \theta_1 - \hat \theta_2 \> \\
	& \le \Vert \cR^2(\gamma, \bbW_1) \Vert_{\op} (\Vert \theta \Vert_{L_2} + \sqrt{B}) \Vert \hat \theta_1 - \hat \theta_2 \Vert_{L_2}.
\end{align*}
Now, using $\cR(\gamma, \bbW_1) - \gamma \bbW_1 \cR(\gamma, \bbW_1)  = \bI$ and
\begin{align*}
	\Vert \cR(\gamma, \bbW_1) \Vert_{\op}  \le 1 + \gamma \Vert \bbW_1 \Vert_{\op} \Vert \cR(\gamma, \bbW_1) \Vert_{\op}, \quad
	\Vert \cR(\gamma, \bbW_1) \Vert_{\op}  \le (1 - \gamma \Vert \bbW_1 \Vert_{\op})^{-1},
\end{align*}
we get
\begin{align}
\label{eq: T-difference via theta-difference}
	T_1(\hat \theta_1) - T_1 (\hat \theta_2) \le \frac{ (\Vert \theta \Vert_{L_2} + \sqrt{B})}{(1 - \gamma \Vert \bbW_1 \Vert_{\op})^2} \cdot \Vert \hat \theta_1 - \hat \theta_2 \Vert_{L_2}.
\end{align}
By applying the bound in ~\eqref{eq: theta difference bound} and the inequality $1 + \gamma \Vert \bbW_1 \Vert_{\op} \le (1 - \gamma \Vert \bbW_1 \Vert_{\op})^{-1}$,
we conclude the proof.


 \section{Proof of Theorem~\ref{theorem: UHTE performance}}
\label{appendix: proof of HTE estimator error}

Define $\tilde{\bQ} = \bQ - \bD_{\bQ}$, where $\bD_{\bQ}$ consists of diagonal entries of $\bQ$. Now, $\Vert \bD_{\bQ} \Vert_{\op} = \max_i |(\bD_{\bQ})_{ii}| = \max_i \rho_n |W(\xi_i, \xi_j)| \le \rho_n$. 
We apply the triangle inequality, and derive
\begin{align*}
	\Vert \bQ - \widehat{\bQ}_\lambda \Vert_{\op} \le \Vert \bQ - \bA \Vert_{\op}+\Vert  \bA - \widehat{\bQ}_\lambda\Vert_{\op} =  \Vert \bD_{\bQ} \Vert_{op}+ \Vert \tilde{\bQ}  - \bA \Vert_{\op} + \lambda \le \rho_n + \lambda + \Vert \tilde{\bQ} - \bA \Vert_{\op}.
\end{align*}
Conditioned on $\xi_1, \ldots, \xi_n$, we bound the difference $\Vert \tilde{\bQ} - \bA \Vert_{\op}$ in probability by Proposition~\ref{theorem: matrix concentration} in Appendix \ref{appendix: tools}. For $\bX=\tilde{\bQ} - \bA$, we have $\sigma \leq \sqrt{n \rho_n}$ since
\begin{align*}
    \sigma &= \max_i \sqrt{\sum_{j} \Var(\bA_{ij})} = \max_i \sqrt{\sum_j \left(\bbE(\bA_{ij}^2) - \bbE(\bA_{ij})^2\right)} = \max_i \sqrt{\sum_j \left(\rho_n W(\xi_i, \xi_j) - \rho_n^2 W(\xi_i, \xi_j)^2\right)} \\
    &= \max_i \sqrt{\sum_j \rho_n W(\xi_i, \xi_j)\left(1 - \rho_n W(\xi_i, \xi_j)\right)} \leq \max_i \sqrt{\sum_j \rho_n W(\xi_i, \xi_j)} \leq \max_i \sqrt{\sum_j \rho_n} = \sqrt{n \rho_n}. 
\end{align*}
and $\sigma_* \le 1$ since $\tilde{\bQ}_{ij}, \bA_{ij} \in [0,1]$ for all $(i,j)$. Selecting $t=\sqrt{\constantBandeira \log \frac{n}{\delta}}$, we obtain $\Vert \tilde{\bQ} - \bA \Vert_{\op} \le 3 \sqrt{n \rho_n} + \sqrt{\constantBandeira \log \frac{n}{\delta}}$ with probability at least $1 -\delta$. Since the bound does not depend on $\xi_1, \ldots, \xi_n$, the conditioning can be removed. Finally, we have $\rho_n \le \sqrt{n \rho_n}$, and, thus, the result follows.


\section{Proof of Theorem~\ref{theorem: SBM convergence rate}}
\label{appendix: proof of SBM convergence rate}


{\textbf{i) Upper bound on the convergence rate.} 
We build the proof on that of Proposition 3.2 in~\cite{klopp2017}. However, we provide bounds in probability instead of bounds in expectation and we use the operator norm.
%Let $\xi_{(i)}$ be the reordering of the $\xi_{i}$ in increasing order.
Define a function $\phi: [0, 1] \to [k]$, such that $\phi(x) = a$ iff $x \in P_a$ and a function $\psi: [0, 1] \to [k]$ such that for any $x\in \left(\frac{i-1}{n},\frac{i}{n}\right), \psi(x)=\phi(\xi_{i})$. 
Thus,
\begin{align*}
	\left\Vert  \rho_n \bbW - {\bbW}_{\bQ} \right\Vert_{\op}& \le \Vert  \rho_n \bbW - {\bbW}_{\bQ} \Vert_{F} \\
 & \le \rho_n \sqrt{\int_{[0,1]^2} (\bS_{\phi(x)\phi(y)} - \bS_{\psi(x)\psi(y)})^2 dx dy} \\
	& \le \rho_n \sqrt{\mu \bigl (\psi(x) \neq \phi(x) \text{ or } \psi(y) \neq \phi(y) \bigr )} \\
	& \le \rho_n \sqrt{2 \mu \bigl (\psi(x) \neq \phi(x) \bigr )}.
\end{align*}
%Now, Lemma \ref{lem:uniform} implies that, for all $i$, with probability at least $1-\frac{\delta}{2}$
%$$\left|\xi_{i}-\frac{i}{n}\right|\le \sqrt{ \frac{\log(4n/\delta)}{n}}.$$
%Since the SBM has at most $k-1$ discontinuities, the functions $\psi(x)$ and $\phi(x)$ differ at most over $k-1$ intervals centered at the discontinuity points of length $2\sqrt{ \frac{\log(4n/\delta)}{n}}.$ Hence  
%$\mu \bigl (\psi(x) \neq \phi(x) \bigr )\le 2k\sqrt{ \frac{\log(4n/\delta)}{n}} $
%and $\Vert  \rho_n \bbW - {\bbW}_{\bQ} \Vert_{\op} \le 2\rho_n \sqrt{k\sqrt{ \frac{\log(4n/\delta)}{n}}}.$


%As before,
%\begin{align*}
  %  \Vert \rho_n \bbW - \bbW_Q \Vert_{\op} \le \rho_n \sqrt{2 \mu(\psi(x)) \neq \rho(x))}.
%\end{align*}
%We supposed that communities form consequent segments $[0, e_1], (e_1, e_2], \ldots, (e_{k - 1}, 1]$.
Define $\widehat{e}_a = \frac{1}{n} \sum_{i = 1}^n \indicator{\xi_i \le e_a}.$
Note that $\{x \mid \phi(x) = \psi(x)\} \subseteq \bigcup_{a = 1}^{k - 1} [\max(e_{a - 1},\hat{e}_{a - 1}), \min(e_{a},\hat{e}_a)]$, where we assume that the segment \newline $[\max(e_{a - 1},\hat{e}_{a - 1}), \min(e_{a},\hat{e}_a)]$ is empty if $\min(e_{a}, \hat{e}_a) < \max(e_{a - 1}, \hat{e}_{a - 1})$. Hence, we have
\begin{align*}
    \mu\{\phi(x) \neq \psi(x)\} \le \sum_{a = 1}^{k - 1} |\widehat{e}_a - e_a|.
\end{align*}
We are left to bound $|e_a - \widehat{e}_a|$ for each $a \in [k-1]$. Fix any $a \in [k-1]$. Applying the Bernstein inequality, we obtain
\begin{align*}
        \P \left (\left |\widehat e_a - e_a \right| \ge t \right ) = \P \left( \left| \sum_{i = 1}^n (\indicator{\xi_i \le e_a} - e_a) \right| \ge n t\right) \le 2 \exp \left( - \frac{n^2 t^2 / 2}{\sum_{i = 1}^n  \Var(\indicator{\xi_i \le e_a})  + n t/3}\right ). 
\end{align*}
Since $\Var(\indicator{\xi_i \le e_a}) =  e_a(1 - e_a) \leq e_a$, we have
\begin{align*}
    \P \left(|e_a - \widehat e_a | \ge t \right ) \le 2 \exp \left( - \frac{n t^2}{2(e_a + t/3)}\right )
\end{align*}
for each $a = [k - 1]$. We choose $t = t_a$ to ensure that the right-hand side is at most $\delta/(2 k)$. For our purposes, it is sufficient to set
\begin{align*}
    t_a = \frac{2}{3n} \log \left( \frac{4k}{\delta} \right) + \sqrt{\frac{2 e_a}{n} \log \left ( \frac{4 k}{\delta}\right )}.
\end{align*}
Hence, by the union bound, with probability at least $1 - \delta/2$, it holds
\begin{align}
\label{eq: mu psi minus phi bound}
    \mu \{ \psi(x) \neq \phi(x)\} \le \sum_{a = 1}^{k-1} t_a \leq \frac{2k}{n} \log \frac{4k}{\delta} + \sum_{a = 1}^{k - 1} \sqrt{\frac{2e_a}{n} \log \frac{4k}{\delta}}.
\end{align}
The second term in the right-hand side can be bounded using the Cauchy-Schwartz inequality to obtain
\begin{align*}
    \sum_{a = 1}^{k - 1} \sqrt{\frac{2e_a}{n} \log \frac{4k}{\delta}} \leq \sqrt{\frac{2k }{n} \sum_{a = 1}^{k-1} e_a \log \frac{4k}{\delta}}.
\end{align*}
Assumption $n \ge 2 k \log \frac{4k}{\delta}$ implies
\begin{align*}
    \frac{2k}{n} \log \frac{4k}{\delta} \leq \sqrt{\frac{2 k}{n} \log \frac{4k}{\delta}}. 
\end{align*}
Substituting the above two displays into~\eqref{eq: mu psi minus phi bound}, we get
\begin{align*}
    \mu \{ \psi(x) \neq \phi(x)\} \leq \sqrt{\frac{8k \sum_{a = 1}^{k - 1} e_a}{n} \log \frac{4k}{\delta}}. 
\end{align*}
Hence,  
\begin{align}
\label{eq: error of connection probabilities graphon}
    \Vert \rho_n \bbW - \bbW_{\bQ} \Vert_{\op} \le \rho_n \sqrt{2 \mu(\psi(x)) \neq \rho(x))} \leq \rho_n \left (\frac{32 k \sum_{a = 1}^{k - 1} e_a}{n} \log \frac{4k}{\delta}\right )^{1/4}
\end{align}
with probability at least $1 - \delta/2$.
Bounding $\Vert \bQ - \widehat{\bQ}_\lambda \Vert$ via Theorem~\ref{theorem: UHTE performance} with probability at least $1 - \delta/2$ and applying Lemma \ref{lemma: empirical graphon norm} we obtain the result.


\textbf{ii) Upper bound on the rank.} For arbitrary matrix of connection probabilites $\bQ$, we claim that the rank of $\widehat{\bQ}_\lambda$ can be bounded as follows.
\begin{prop}
\label{proposition: singular value rank}
	Let $\sigma_1 \ge \ldots \ge \sigma_n$ be singular values of $\bQ$. Then with probability at least $1 - \delta$
	\begin{align*}
		\rank(\widehat{\bQ}_\lambda) & \le \max \{i \mid \sigma_i \ge \lambda - w_\delta\}, \\
		w_\delta & := 4 \sqrt{n \rho_n} + \sqrt{\constantBandeira \log \frac{n}{\delta}}.
	\end{align*}	

\end{prop}

\begin{proof}
	Let $\bE=\bA-\bQ$. Then, by Proposition \ref{proposition: eckart-yang theorem}, for all $i$, we have $\sigma_i(\bA) \le \sigma_{i}(\bQ) +\sigma_{1}(\bE)$. It follows from Proposition~\ref{theorem: matrix concentration} that  with probability at least $1 - \delta$, $\sigma_{1}(\bE) \le w_{\delta}$ (see also Proof of Theorem 3). If $i \le \rank(\widehat{\bQ}_\lambda)$, then $\sigma_i(\bA) \ge \lambda$. Consequently, $\lambda \le \sigma_i(\bQ) + w_{\delta}$ for such $i$, and $\rank(\widehat{\bQ}_\lambda) \le \max \{ i \mid \sigma_i(\bQ) \ge \lambda - w_\delta \}$. 
\end{proof}

For $\lambda= 6\sqrt{n \rho_n}$, we have $\lambda - w_\delta \ge \sqrt{n \rho_n}>0$. Since $\sigma_{i} = 0$ for $i > k$, Proposition~\ref{proposition: singular value rank} implies that $\rank(\widehat{\bQ}_\lambda)\le k$.




\section{Proof of Theorem~\ref{theorem: SBM lower bound}}
\label{appendix: proof of SBM lower bound}

We use the standard framework based on hypotheses testing and adapt the proof technique from \cite{klopp2017}. As discussed in Section~\ref{sec:minimax bounds}, we should construct two SBM graphons $U$ and $V$ such that
\begin{enumerate}
    \item $\opnorm{\rho_n U - \rho_n V} \ge \rho_n n^{-1/4} / 8$;
    \item the corresponding distributions $\P_U$ and $\P_V$ satisfy $\KL{\P_V}{\P_U} \le 1/2$.
\end{enumerate}
We introduce a family of graphons parametrized by some real number $m \in (-1/2; 1/2)$ as follows:
\begin{align*}
    W_{m}(x, y) = \begin{cases}
        3/4, & \text{either $x, y \le 1/2 + m$ or $x, y \ge 1/2 + m$}, \\
        1/4, & \text{otherwise}.
    \end{cases}
\end{align*}
We choose $U$ to be $W_0$ and $V$ to be $W_{\Delta}$ for $\Delta$ specified in the sequel. First, we bound the difference between $W_0$ and $W_{\Delta}$ in the operator norm.
\begin{prop}
    \label{prop:risk lower bound}
    We have
    \begin{align*}
        \opnorm{W_0 - W_{\Delta}} = \frac{1}{2} \sqrt{\Delta (1 - \Delta)}.
    \end{align*}
\end{prop}

\begin{proof}
    Due to symmetry, we may assume that $\Delta > 0$. Note that a graphon $W' = W_{\Delta} - W_0$ is an SMB with three communities:
    \begin{align*}
        W'(x, y) & = \frac{1}{2} \indicator{x \in (1/2; 1/2 + \Delta)} \indicator{y \in (0; 1/2)} + \frac{1}{2} \indicator{x \in (0; 1/2)} \indicator{y \in (1/2; 1/2 + \Delta)} \\ 
         & \quad - \frac{1}{2} \indicator{x \in (1/2 + \Delta; 1)} \indicator{y \in (1/2; 1/2 + \Delta)} - \frac{1}{2} \indicator{x \in (1/2; 1/2 + \Delta)} \indicator{y \in (1/2 + \Delta; 1)}.
    \end{align*}
    Since for any function $f$, $\bbW' f$ can be represented as
    \begin{align*}
        (\bbW' f)(x) = f_1 \indicator{x \in (0; 1/2)} + f_2 \indicator{x \in (1/2; \Delta)} + f_2 \indicator{x \in (1/2 + \Delta; 1)}
    \end{align*}
    for some numbers $f_1, f_2, f_3$,
    any eigenfunction $\bv$ of $\bbW'$ has the form:
    \begin{align*}
        \bv(x) = v_1 \indicator{x \in (0; 1/2)} + v_2 \indicator{x \in (1/2; {1/2 +}\Delta)} + v_3 \indicator{x \in (1/2 + \Delta; 1)}.
    \end{align*}
    Note that, the matrix of connection probabilities between communities of the SBM $W'$ has rank $2$  and $\bbW'$ has zero trace, so the graphon $W'$ has two different non-zero eigenvalues $\lambda$ and $-\lambda$, $\lambda > 0$. We find $\lambda$ from the system $\bbW' \bv = \lambda \bv$. We have
    \begin{align*}
        \begin{cases}
            \frac{\Delta}{2} v_2 & = \lambda v_1 \\
            \frac{1}{2} v_1 \cdot \frac{1}{2}- \frac{1}{2} v_3  \left ( \frac{1}{2} - \Delta \right )& = \lambda v_2 \\
            - \frac{\Delta}{2} v_2 & = \lambda v_3.
        \end{cases}
    \end{align*}
    From the first and the third equations, we deduce $v_1 =  - v_3$. Thus, we have
    \begin{align*}
        \begin{cases}
            \frac{\Delta}{2} v_2 & = \lambda v_1 \\
            \frac{1}{2} v_1 (1 - \Delta) & = \lambda v_2.
        \end{cases}
    \end{align*}
We multiply these equations, and get $\lambda^2 = \Delta (1 - \Delta) / 4$. Therefore, the proposition follows.
\end{proof}

Next, we bound the KL-divergence between distributions $\P_0$ and $\P_{\Delta}$ corresponding to graphons models $\rho_n W_0$ and $\rho_n W_{\Delta}$ respectively.
\begin{prop}
    \label{prop:KL bound}
    We have that $\KL{\P_{\Delta}}{\P_0} \le 16 n \Delta^2$.
\end{prop}
\begin{proof}
By the definition, we have
\begin{align*}
    \KL{\P_{\Delta}}{\P_0} = \sum_{A} \P_{\Delta}(\bA = A) \log \frac{\P_{\Delta}(\bA = A)}{\P_0(\bA = A)},
\end{align*}
where the sum is taken over all adjacency matrix $A$.
We introduce a new random variable $\theta = \max \{ k \mid \xi_{k} \text{ belongs to the first comminity}  \}$, with the convention that $\theta=0$ if $\xi_{k}$ belongs to the second community.  Subject to $\theta$, the distributions $\P_{\Delta} (\cdot \mid \theta)$ and $\P_0 (\cdot \mid \theta)$ are identical, since both of them are random graph models with the same matrix of connection probabilities $\bQ$:
\begin{align*}
    \bQ_{ij} = 
    \begin{cases}
        3\rho_n/4 , & \text{if $i, j \le \theta$ or $i, j > \theta$,} \\
        \rho_n/4 , & \text{otherwise.}
    \end{cases}
\end{align*}
For brevity, we define $p_{\bA | \theta}(A \mid t) = \P_0 (\bA = A \mid \theta = t) = \P_{\Delta} (\bA = A \mid \theta = t)$, $q(t) = \P_{\Delta}(\theta = t)$ and $p(t) = \P_{0}(\theta = t)$. Then, we get
\begin{align*}
    \KL{\P_{\Delta}}{\P_0} = \sum_{A} \sum_t p_{\bA \mid \theta}(A \mid t) q(t) \log \frac{\sum_{t} p_{\bA \mid \theta}(A \mid t) q(t)}{\sum_t p_{\bA \mid \theta} (A \mid t) p(t)}.
\end{align*}
Since the function $(x, y) \to x \log (x / y)$ is convex, due to the Jensen inequality, we have
\begin{align*}
    \KL {\P_{\Delta}}{\P_0} \le \sum_{t} q(t) \log \frac{q(t)}{p(t)}.
\end{align*}
The latter is the KL-divergence between two binomial distributions $Binom(n, 1/2 + \Delta)$ and $Binom(n, 1/2)$. We have
\begin{align*}
    \sum_{t} q(t) \log \frac{q(t)}{p(t)} & = \sum_{t = 0}^n \binom{n}{t}(1/2 + \Delta)^t (1/2 - \Delta)^{n - t} \log \frac{(1/2 + \Delta)^t (1/2 - \Delta)^{n - t}}{2^{-n}}  \\
    & = \KL{Bern^{\otimes n}(1/2 + \Delta)}{Bern^{\otimes n}(1/2)} \\
    & = n \KL{Bern(1/2 + \Delta)}{Bern(1/2)} \le {4} n \Delta^2,
\end{align*}
where we use the fact that KL-divergence does not exceed chi-square divergence.
\end{proof}

We choose $\Delta = ({2} \sqrt{2n})^{-1}$, so $\KL{\P_{\Delta}}{\P_0} \le 1/2$ and $\opnorm{\rho_n W_0 - \rho_n W_{\Delta}} \ge \rho_n n^{-1/4} / 8$. Application of Theorem~\ref{theorem:minimax bounds} finishes the proof.


\section{Proof of Theorem~\ref{theorem: holder convergence rate}}
\label{appendix: proof of Holder convergence rate}



i) \textbf{Upper bound on the convergence rate.} We build the proof on that of Proposition~3.5 in~\cite{klopp2017}. The difference is that we bound the error in probability instead of bounding in expectation. We first bound the difference in the Frobenius norm and then, using that, bound the difference in the spectral norm. 

% In what follows, we omit the apex $\phi$ that fixes H\"older version of graphon $W$, and assume that $W(\cdot, \cdot)$ satisfies H\"older conditions itself.

By the definition of the empirical graphon 
\begin{align*}
	W_{\bQ}(x,y) = \rho_n\sum_{i j} W(\xi_{(i)}, \xi_{(j)}) \cdot I\{x \in [(i - 1)/n, i/n]\} \cdot I\{y \in [(j - 1)/n, j/n)\}.
\end{align*}
%where $\xi_{(i)}$ is the $i$-th smallest element of $\{\xi_1, \ldots, \xi_n\}$.
Define $\Delta_{ij} = [(i-1)/n, i/n) \times [(j - 1)/n, j/n)$. Then for any $(x, y) \in \Delta_{ij}$ we have
\begin{align*}
	|W(x, y) - W(\xi_{(i)}, \xi_{(j)})| \le \left |W(x, y) - W \left ( i/n, j/n \right ) \right | + \left |  W \left ( i/n, j/n \right ) - W(\xi_{(i)}, \xi_{(j)})\right |.
\end{align*}
Since the graphon $W$ is $(H, \alpha)$-H\"older there exists a constant $C(H, \alpha)$ such that
\begin{align*}
	\left |W(x, y) - W \left ( i/n, j/n \right ) \right | & \le C(H, \alpha) \left ( |x - i/n|^{\alpha \land 1} + |y - j/n|^{\alpha \land 1} \right ) \\
	& \le 2 C(H, \alpha) n^{-(\alpha \land 1)},
\end{align*}
where $\alpha \land 1=\min\{\alpha,1\}.$



Analogously, we have
\begin{align*}
	\left |  W \left ( i/n, j/n \right ) - W(\xi_{(i)}, \xi_{(j)})\right | \le C(H, \alpha) \left (|\xi_{(i)} - i/n|^{\alpha \land 1} +  |\xi_{(j)} - j/n|^{\alpha \land 1}\right ).
\end{align*}
Thus, we obtain
\begin{align}
    \|\rho_n \bbW - \bbW_{\bQ}\|_F^2 &= \int_{[0, 1]^2} (\rho_n W(x, y) - W_{\bQ}(x, y))^2 dx dy \nonumber \\
    & \le 2\rho_n^2 \left(4 C^2(H, \alpha) n^{-2 (\alpha \land 1)} \nonumber\right. \\
	&\left. \quad \quad + C^2(H, \alpha) \sum_{i j} \mu(\Delta_{ij}) \left (|\xi_{(i)} - i/n|^{\alpha \land 1} +  |\xi_{(j)} - j/n|^{\alpha \land 1}\right )^2\right) \nonumber \\
	& \le 2\rho_n^2 \left(4 C^2(H, \alpha) n^{-2 (\alpha \wedge 1)} + \frac{4 C^2(H, \alpha)}{n} \sum_{i = 1}^n |\xi_{(i)} - i/n|^{2 (\alpha \wedge 1)}\right). \label{eq: L2 decomposition for Holder graphon}
\end{align}
Next, for any $t$ such that $t/n \in [0,1]$, we have
\begin{align*}
	\bbP \left ( \left|\xi_{(i)} - \frac{i}{n}\right| \ge \frac{t}{n} \right ) \le \bbP \left ( \sum_{j = 1}^n I\left\{\xi_j \le \frac{i - t}{n}\right\} \ge i \right ) + \bbP \left (\sum_{j = 1}^n I\left\{\xi_j \leq \frac{i + t}{n}\right\} \le i -1 \right ).
\end{align*}
We bound the first term, the second term can be bounded analogously. From the Bernstein inequality, we have
\begin{align*}
	\bbP \left ( \sum_{j = 0}^n I\left\{\xi_j \le \frac{i - t}{n}\right\} \ge i \right ) \le \exp \left ( - \frac{t^2}{0 \lor (i - t) + t/3}\right ).
\end{align*}
We require $\exp \left ( - \frac{t^2}{0 \lor (i - t) + t/3}\right ) \leq \delta/(4 n)$. For this, it is enough to choose $t \geq \sqrt{n \log(4n/\delta)}$. 
 Then, we get that with probability at least $1 - \delta/2$
\begin{align*}
	\frac{1}{n} \sum_{i = 1}^n \left | \xi_{(i)} - i/n \right |^{2 (\alpha \wedge 1)}  \le 4 \left ( \frac{\log (4n/\delta)}{n} \right )^{(\alpha \wedge 1)}.
\end{align*}
Substituting the above into~\eqref{eq: L2 decomposition for Holder graphon}, we get
\begin{align*}
    \Vert \rho_nW - W_{\bQ} \Vert_{F}^2 & \le 2\rho_n^2 \left(4 C^2(H, \alpha) n^{-2 (\alpha \wedge 1)} + 16 C^2(H, \alpha) \left ( \frac{\log (4n/\delta)}{n} \right )^{(\alpha \wedge 1)}\right)  \\
    & \le 32\rho_n^2 C^2(H, \alpha) \left ( \frac{\log \frac{4n}{\delta}}{n} \right )^{(\alpha \wedge 1)},
\end{align*}
which implies
\begin{align*} 
    \Vert \rho_n\bbW - \bbW_{\bQ} \Vert_{F} &\leq 4 \sqrt{2}\rho_n C(H, \alpha) \left ( \frac{\log \frac{4n}{\delta}}{n} \right )^{\frac{(\alpha \wedge 1)}{2}}
\end{align*}
% \red{(Minor: I got an additional factor of $\sqrt{2}$.Please check if that is correct.)}
with probability at least $1 - \delta/2$. Since the Frobenius norm bounds the spectral norm, the above implies
\begin{align}
	\opnorm{\rho_n \bbW - \bbW_{\bQ}} \le 4 \sqrt{2} \rho_n C(H, \alpha) \left ( \frac{\log (4n/\delta)}{n} \right )^{\frac{(\alpha \wedge 1)}{2}}. \label{eq: holder matrix of connection probabilities difference}
\end{align}
Bounding $\Vert \bQ - \widehat{\bQ}_\lambda \Vert$ via Theorem~\ref{theorem: UHTE performance} with probability at least $1 - \delta/2$ and applying Lemma \ref{lemma: empirical graphon norm} we obtain the result.
% \red{(With the reasoning above, I believe the power in the bound above should be $\frac{\alpha - \lfloor \alpha \rfloor}{2}$.)}

ii) \textbf{Upper bound on the rank.} We start by recalling the following result from approximation theory. 
\begin{lemma}
\label{lemma: Holder function approximation}
	Fix $k \in \mathbb{N}$. Define $\Delta_{ij} = [(i - 1)/k, i/k) \times [(j - 1)/k, j/k)$ for $1 \le i, j \le k$. Define $\ell = \lfloor \alpha \rfloor$. Then for any $(H, \alpha)$-H\"older graphon $W$ there exists a function $P_k: [0, 1]^2 \to \bbR$ such that
	\begin{enumerate}
		\item for any $\Delta_{i j}$, the function $P_k|_{\Delta_{ij}}$ is polynomial of degree at most $\ell$,
		\item the error of approximation satisfies
		\begin{align*}
			\sup_{x, y} |W(x, y) - P_k(x, y)| \le 2 H k^{-\alpha}.
		\end{align*}
	\end{enumerate}
\end{lemma}
For the proof, see, for example, Lemma 3 in~\cite{xu2017}.

First, we claim that $P_k(x, y)$ has rank at most $k \cdot (\ell + 1)^2$. Indeed, it can be represented as a sum of functions
\begin{align*}
	P_k(x, y) = \sum_{a, b, a + b \le \ell} W_{\bS^{ab}}(x,y) x^a y^b,
\end{align*}
where functions $W_{\bS^{ab}}$ are constants on each $\Delta_{ij}$, i.e. $W_{\bS^{ab}}|_{\Delta_{ij}} = \bS^{ab}_{ij}$ for some matrix $\bS^{ab} \in \bbR^{k \times k}$. Thus, each $W_{\bS^{ab}}$ has rank at most $k$, and, consequently, $P_k$ has rank at most $k \cdot (\ell + 1)^2$ (see Appendix \ref{sec:rank_function}). \\
% \red{Is it true that a graphon $W(x,y) = \sum_{i = 1}^r f_i(x) g_i(y)$ has rank at most $r$, i.e., at most $r$ non-zero eigenvalues?}

Second, we state that $\bP_k = \{P_k(\xi_{(i)}, \xi_{(j)})\}_{ij}$ has the same rank as $P_k$. Indeed, if $P_k(x, y)$ can be represented as a sum $\sum_{r = 1}^{k (\ell + 1)^2} \phi_r(x) \psi_r(y)$ of functions of rank $1$, then $\bP_k$ has decomposition $\sum_{r = 1}^{k (\ell + 1)^2} \bv_r \bg_r^T$, where $\bv_r = (\phi_r(\xi_{(i)}))_{i = 1}^n$, $\bg_r = (\psi_r(\xi_{(i)}))_{i = 1}^n$.

We aim to show that for some constant $C(H,\alpha)$, we have $\sigma_k(\bQ) \le C(H, \alpha) n \rho_n k^{-(\alpha + 1/2)}$ for all $k \in \bbN$. First, we bound $\sigma_{k} (\bQ)$ for each $k \ge (\ell + 1)^3$. Define $k_1 = \left \lceil \frac{k}{(\ell + 1)^3} \right \rceil$ and $k_2 = k - k_1 (\ell + 1)^2$.
%Note that $k \ge (\ell + 1)^3$ implies $k \geq (\ell + 1)^3/\ell$, which implies $k_1 < k/(\ell+1)^3 + 1 \leq k/(\ell + 1)^2$. Hence, $k_2 > 0$. 
Eckart - Young - Mirsky theorem (see Proposition~\ref{proposition: eckart-yang theorem}) for $\bA=\bQ$, $r=k_1 (\ell+1)^2$, $\bB=\rho_n \bP_{k_1}$  and
Lemma~\ref{lemma: Holder function approximation}, imply
\begin{align*}
	k_2 \sigma^2_k(\bQ) \le \sum_{r = k_1 (l + 1)^2 + 1}^n \sigma_r^2(\bQ) \le  \Vert \bQ - \rho_n \bP_{k_1} \Vert_{\mathrm{F}}^2 \le (2 H n \rho_n k_1^{-\alpha})^2 ,
\end{align*}
and, consequently, $\sigma_k(\bQ) \le 2 H n \rho_n k_2^{-1/2} k_1^{-\alpha}\leq C'(H, \alpha) n \rho_n k^{-(\alpha + 1/2)}$ where $C'(H, \alpha)$ is a constant depending only on $H$ and $\alpha$. 
On the other hand, as $\Vert \bQ \Vert_{\op} \le n \rho_n$ taking $C'(H, \alpha)$ large enough the bound holds also for  $k<(l+1)$.




Finally, we apply Proposition~\ref{proposition: singular value rank}. Choose $k$ such that $\sigma_k(\bQ) \le \lambda - w_\delta$. We get
\begin{align*}
	\rank(\widehat{\bQ}_\lambda) \le \left ( \frac{C(H, \alpha) n \rho_n}{\lambda - w_\delta} \right )^{\frac{2}{1 + 2 \alpha}} \le \left (C^2(H, \alpha) n \rho_n \right )^{\frac{1}{1 + 2 \alpha}}
\end{align*}
with probability at least $1 - \delta$.


\section{Proof of Theorem~\ref{theorem: analityc convergence rate}}
\label{appendix: proof of analytic convergence rate}


i) \textbf{Upper bound on the convergence rate.} We claim that Definition~\ref{condition: M-r analiticity} guarantees that $W(x, y)$ is $(H, 1)$-H\"older ($H$-Lipshitz) for some $H$. If $|x_2 - x_1| > r/2$ or $|y_1 - y_2| > r/2$, we can bound
\begin{align*}
	|W(x_1, y_1) - W(x_2, y_2)| \le 2 \le \frac{2}{r} (|x_2 - x_1| + |y_2 - y_1|).
\end{align*}
Otherwise, we have
\begin{align*}
	|W(x_1, y_1) - W(x_2, y_2)| & \le |W(x_1, y_1) - W(x_2, y_1)| + |W(x_2, y_1) - W(x_2, y_2)| \\
	& \le \sum_{i = 1}^{\infty} |c_i(x_1, y_1)| |x_2 - x_1|^i + \sum_{i = 1}^{\infty} |c_i(x_2, y_1)| |y_2 - y_1|^i.
\end{align*}
Since $\sup_{x, y} |c_k(x, y)| \le M r^{-k}$, we obtain
\begin{align*}
	|W(x_1, y_1) - W(x_2, y_2)| & \le M \left ( \sum_{i = 1}^\infty \frac{|x_2 - x_1|^i}{r^i} + \sum_{i = 1}^\infty  \frac{|y_2 - y_1|^i}{r^i} \right ) \\
	& \le M \left ( \frac{r^{-1}|x_2 - x_1|}{1 - r^{-1} |x_2 - x_1|} + \frac{r^{-1}|y_2 - y_1|}{1 - r^{-1}|y_2 - y_1|} \right ) \\
	& \le 4 r^{-1} M (|x_2 - x_1| + |y_2 - y_1|).
\end{align*}
Consequently, graphon $W$ is indeed $(H, 1)$-H\"older for $H = \max(4 M r^{-1}, 2r^{-1})$. Applying Theorem~\ref{theorem: holder convergence rate}, we obtain the rate of convergence.

ii) \textbf{Upper bound on the rank.} Choose some integer $\ell$ such that $\ell \ge 2 / r$. For $a,b\in \{1,\dots,l\}$ consider $\Delta_{a b} = [(a - 1)/\ell, a/\ell) \times [(b - 1)/\ell, b/\ell)$.  Let  $ p\geq 1$ be an integer.  For each $\Delta_{ab}$  define function
\begin{align*}
	P_p^{ab}(x, y) = \sum_{i = 0}^{p - 1} c_i \left ( \frac{a - 1/2}{\ell}, y \right ) \left (x - \frac{a - 1/2}{\ell} \right )^i.
\end{align*}
The function $P_p^{ab}$ has rank at most $p$.
%(see Appendix \ref{sec:rank_function}). 
Define   function $P_p: [0, 1]^2 \to \bbR$ as $P_{p}|_{\Delta_{ab}} = P^{ab}_{p}$.
%Then $P_p(x,y) = W_{\bS^{ab}}(x,y) P^{ab}_p(x,y)$, where $(\bS^{ab})_{ij} = 1$ if and only if $(i,j) = (a,b)$. 
Then $P_p$ has rank at most $\ell^2 p$. Moreover, we have  
%(see Appendix \ref{sec:rank_function}). Meanwhile,
\begin{align*}
	\sup_{x, y} |W(x, y) - P_p(x, y)| = \sup_{a, b} \sup_{(x, y) \in \Delta_{ab}} |W(x, y) - P_p^{ab}(x, y)| \le M \sum_{i = p}^{\infty} r^{-i} l^{-i} \le M \sum_{i = p}^{\infty} 2^{-i}  \le M 2^{1-p}.
\end{align*}
Next, define $\bP_p = (P_p(\xi_i, \xi_j))_{1 \le i, j \le n}$ and recall that $\bQ = \rho_n(W(\xi_i, \xi_j))_{1 \le i, j \le n}$. Then $\bP_p$ has the same rank as $P_p$. Indeed, if $P_p(x, y)$ can be represented as a sum $\sum_{r = 1}^{\ell^2 p} \phi_r(x) \psi_r(y)$ of functions of rank $1$, then $\bP_k$ has decomposition $\sum_{r = 1}^{\ell^2 p} \bv_r \bg_r^T$, where $\bv_r = (\phi_r(\xi_i))_{i = 1}^n$, $\bg_r = (\psi_r(\xi_i))_{i = 1}^n$. %Thus, by Proposition~\ref{proposition: eckart-yang theorem} (for $\bA=\bQ$, $r=\ell^2p+1$, $\bB=\rho_n \bP_p$), we have 
We have, 
\begin{align*}
   \sigma_{\ell^2 p}(\bQ) \le \Vert \bQ - \rho_n \bP_p \Vert_{op}\le \Vert \bQ - \rho_n \bP_p \Vert_{F} \le M n \rho_n 2^{1-p}.
\end{align*}
For any $k \ge \ell^2$, by choosing $p = \left \lfloor \frac{k}{\ell^2} \right \rfloor$ we can conclude that 
\begin{align*}
	\sigma_k(\bQ) \le M n \rho_n 2^{1 - p} \leq 4 M n \rho_n 2^{-\frac{k}{\ell^2}.} 
\end{align*}
Since $\Vert \bQ \Vert_{\op} \le n \rho_n$, there exists constant $C(M, r)$ such that $\sigma_k(\bQ) \le C(M, r) n \rho_n 2^{- k}$ for all positive $k$. 
In the notation of Proposition~\ref{proposition: singular value rank}, if $\sigma_k(\bQ) \geq \lambda - \omega_\delta$, we have
\begin{align*}
    C(M, r) n \rho_n 2^{- k / \ell^2} \geq \lambda - \omega_\delta \geq \sqrt{n \rho_n},
\end{align*}
which implies
$C(M,r) \sqrt{n \rho_n} 2^{- k / \ell^2} \geq 1$
and $  k \leq \ell^2 \log_2\left(C(M,r) \sqrt{n \rho_n}\right)$.
Applying Proposition~\ref{proposition: singular value rank}, we get with probability at least $1 - \delta$.
\begin{align*}
	\rank(\widehat{\bQ}_\lambda) &\leq \ell^2 \log_2\left(C(M,r) \sqrt{n \rho_n}\right) \leq C' \log (n \rho_n).
\end{align*}


\section{Proof of Corollary~\ref{corollary: convergene rate targeted interventions}}
\label{section: convergence rate targeted interventions}

Instead of the network game $G(\bA, \btheta)$, we consider the corresponding graphon game $G(W_{\bA}, \tilde{\theta})$, where $W_{\bA}$ is the empirical graphon of the network $\bA$. Define function $\hat{t}^\circ, \hat{t}$ as follows:
\begin{align*}
    \hat{t}(x) & = \sum_{i = 1}^N \hat{\btheta}_i \cdot \indicator{x \in [(i- 1)/N; i/N)}, \\
    \hat{t}^\circ(x) &= \sum_{i = 1}^N \hat{\btheta}'_i \cdot \indicator{x \in [(i- 1)/N; i/N)}.
\end{align*}
Then, we have
\begin{align*}
    T_{(\bA, \btheta)}(\hat{\btheta}) - T_{(\bA, \btheta)}(\hat{\btheta}') = T_{(W_{\bA}, \tilde{\theta})}(\hat{t}) - T_{(W_{\bA}, \tilde{\theta})}(\hat{t}^\circ),
\end{align*}
where $T_{(W_{\bA}, \tilde{\theta}})$ is the target function of the corresponding graphon game $G(W_{\bA}, \tilde{\theta})$ with budget $B$. By the lines of the proof of Theorem~\ref{theorem: graphon perturbed welfare problem}, we have
\begin{align*}
    T_{(W_{\bA}, \tilde{\theta})}(\hat{t}) - T_{(W_{\bA}, \tilde{\theta})}(\hat{t}^\circ) \le \frac{(\Vert \tilde{\theta} \Vert_{L_2} + \sqrt{B})}{(1 - \alpha \Vert \bbW_{\bA} \Vert_{\op})^{2}} \cdot \Vert \hat{t} - \hat{t}^\circ \Vert_{L_2} = \frac{(\Vert \btheta\Vert / \sqrt{N} + \sqrt{B})}{(1 - \alpha \Vert \bA \Vert / N)^2} \cdot \Vert \hat{t} - \hat{t}^\circ \Vert_{L_2},
\end{align*}
see~\eqref{eq: T-difference via theta-difference}. Then, we bound $\Vert \hat{t} - \hat{t}^\circ \Vert_{L_2}$ as follows:
\begin{align*}
    \Vert \hat{t} - \hat{t}^\circ \Vert^2_{L_2} & = \sum_{i = 1}^N \int_{(i - 1)/N}^{i/N} \left (\hat{\btheta}_i - N \int_{(i - 1)/N}^{i/N} \hat{t}'(x) dx\right )^2 dx \le \frac{1}{N}\sum_{i = 1}^N \left ( \hat\btheta_i - N \int_{(i - 1)/N}^{i/N} \hat{t}'(x) dx \right )^2 \\
    & \le \sum_{i = 1}^N \int_{(i - 1)/N}^{i/N} (\btheta_i - \hat{t}'(x))^2 dx = \Vert \hat{t} - \hat{t}' \Vert_{L_2}^2,
\end{align*}
where the last inequality holds due to the Jensen inequality, and $t'(x)$ is defined in the statement of the corollary. To bound the latter quantity, we use the first part of Theorem~\ref{theorem: graphon perturbed welfare problem}, which yields
\begin{align*}
    \Vert \hat{t} - \hat{t}' \Vert_{L_2} \le \frac{2 \alpha \cdot (1 + \alpha \Vert \bbW_{\bA} \Vert_{\op})^2}{\left ( 1- \alpha [\Vert \bbW_{\bA} \Vert_{\op} \vee (\rho_N \Vert \widehat{\bbW} \Vert/\rho_n)] \right )^3} \cdot \Vert \bbW_{\bA} - \rho_N \widehat{\bbW} / \rho_n \Vert_{\op} \cdot (\Vert \tilde{\theta} \Vert_{L_2} + \sqrt{B}).
\end{align*}
Note that $\Vert \bbW_{\bA} \Vert_{\op} = \Vert \bA \Vert / N$ and $\Vert \widehat{W} \Vert_{\op} \le \Vert \bA' \Vert_{\op}/n$ by the construction of the hard-thresholding estimator. Therefore, we have
\begin{align}
\label{eq: T difference for graphon estimator}
    T_{(\bA, \btheta)}(\hat{\btheta}) - T_{(\bA, \btheta)}(\hat\btheta') \le \frac{2 \alpha (1 + \alpha \Vert \bA\Vert_{\op}/N)^2 (\Vert \btheta \Vert/\sqrt{N} + \sqrt{B})^2}{\left (1 - \alpha \cdot \max \{\Vert \bA \Vert_{\op}/N, \rho_N \Vert \bA' \Vert_{\op}/n\rho_n\} \right )^5} \cdot \Vert \bbW_{\bA} - \rho_N \widehat{\bbW} / \rho_n \Vert_{\op}
\end{align}

It remains to bound $\Vert \bbW_{\bA} - \rho_N \widehat{\bbW} / \rho_n \Vert_{\op}$. We have
\begin{align}
    \Vert \bbW_{\bA} - \rho_N \widehat{\bbW} / \rho_n \Vert_{\op} & \le \Vert \bbW_{\bA} - \rho_N \bbW \Vert_{\op} + \Vert \rho_N \bbW - \rho_N \widehat{\bbW}/\rho_n \Vert_{\op} \nonumber \\
    & = \Vert \bbW_{\bA} - \rho_N \bbW \Vert + \frac{\rho_N}{\rho_n} \Vert \rho_n \bbW - \widehat{\bbW} \Vert_{\op}. \label{eq: empirical graphon difference - i}
\end{align}
To bound the first term of the rightmost side, we use the triangle inequality and Proposition~\ref{theorem: matrix concentration}, and deduce, that with probability at least $1 - \delta/4$, we have
\begin{align}
\label{eq: empirical graaphon difference - ii}
    \Vert \bbW_{\bA} - \rho_N \bbW \Vert_{\op} \le \frac{1}{N} \Vert \bA - \bQ \Vert_{\op} + \Vert \bbW_{\bQ} - \rho_N \bbW \Vert_{\op} \le 3 \sqrt\frac{\rho_N}{N} + \frac{\constantBandeira \log(4N/\delta)}{N} + \Vert \bbW_{\bQ} - \rho_N \bbW \Vert_{\op},
\end{align}
where $\bQ$ is the matrix of connection probabilities for the network $\bA$. It remains to bound $\Vert \bbW_{\bQ} - \rho_N \bbW\Vert_{\op}$ and $\Vert \rho_n \bbW - \widehat{\bbW} \Vert_{\op}$. Consider several cases.

\noindent \textbf{Case 1. The graphon $W$ is an SBM with $k$ communities.} By the lines of the proof of Theorem~\ref{theorem: SBM convergence rate}, we have
\begin{align*}
    \Vert \rho_N \bbW - \bbW_{\bQ} \Vert_{\op} \le \rho_N \left ( \frac{32k \sum_{a = 1}^{k - 1}e_a}{N} \log \frac{4k}{\delta} \right )^{1/4}
\end{align*}
with probability at least $1 - \delta/2$, see~\eqref{eq: error of connection probabilities graphon}. By conclusion of this theorem, we have
\begin{align*}
    \frac{\rho_N}{\rho_n} \Vert \rho_n \bbW - \widehat{\bbW} \Vert_{\op} \le \rho_N \left ( \frac{32k \sum_{a = 1}^{k - 1}e_a}{n} \log \left ( \frac{16k}{\delta} \right) \right )^{1/4} + 11 \sqrt{\frac{\rho_N}{n \rho_n}}
\end{align*}
and $\rank(\widehat{W}) \le k$ with probability at least $1 - \delta/4$, provided $n \rho_n \ge \constantBandeira \log (16 n/\delta)$. Combining~\eqref{eq: T difference for graphon estimator}, \eqref{eq: empirical graphon difference - i}, \eqref{eq: empirical graaphon difference - ii} and the inequalities above, we get
\begin{align*}
    T_{(\bA, \btheta)}(\hat{\btheta}) - T_{(\bA, \btheta)}(\hat\btheta') & \le \frac{2 \alpha (1 + \alpha \Vert \bA\Vert_{\op}/N)^2 (\Vert \btheta \Vert/\sqrt{N} + \sqrt{B})^2}{\left (1 - \alpha \cdot \max \{\Vert \bA \Vert_{\op}/N, \rho_N \Vert \bA' \Vert_{\op}/n\rho_n\} \right )^5} \\
    & \quad  \times \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + 2 \rho_N \left ( \frac{32k \sum_{a = 1}^{k - 1}e_a}{n} \log \left ( \frac{16k}{\delta} \right) \right )^{1/4} \right ).
\end{align*}

\noindent \textbf{Case 2. The graphon $W$ is $(H, \alpha)$-H\"older.} By the lines of the proof of Theorem~\ref{theorem: holder convergence rate}, we have
\begin{align*}
    \Vert \rho_N \bbW - \bbW_{\bQ} \Vert_{\op} \le  \rho_N C_1(H, \alpha) \left (  \frac{\log(4N/\delta)}{N}\right )^{\beta/2},
\end{align*}
see~\eqref{eq: holder matrix of connection probabilities difference}. By the conclusion of this theorem, we have
\begin{align*}
    \Vert \rho_n \bbW - \widehat{\bbW} \Vert_{\op} \le \tilde C_1(H, \alpha) \rho_n \cdot \left ( \frac{\log(16n/\delta)}{n} \right)^{\beta/2} + 11 \sqrt{\frac{\rho_n}{n}},
\end{align*}
and $\rank(\widehat{W}) \le C'(H, \alpha) (n \rho_n)^{\frac{1}{1 + 2 \alpha}}$ with probability at least $1 - \delta/4$, provided $n \rho_n \ge \constantBandeira \log(8n/\delta)$. Combining~\eqref{eq: T difference for graphon estimator}, \eqref{eq: empirical graphon difference - i}, \eqref{eq: empirical graaphon difference - ii} and the inequalities above, we get
\begin{align}
    T_{(\bA, \btheta)}(\hat{\btheta}) - T_{(\bA, \btheta)}(\hat\btheta') & \le \frac{2 \alpha (1 + \alpha \Vert \bA\Vert_{\op}/N)^2 (\Vert \btheta \Vert/\sqrt{N} + \sqrt{B})^2}{\left (1 - \alpha \cdot \max \{\Vert \bA \Vert_{\op}/N, \rho_N \Vert \bA' \Vert_{\op}/n\rho_n\} \right )^5} \nonumber \\
    & \quad  \times \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + C''_1(H, \alpha) \rho_N \left ( \frac{\log(16n/\delta)}{n} \right)^{\beta/2}  \right ) \label{eq: holder final bound}
\end{align}
for some constant $C''_1(H, \alpha)$ which depends only on $H$ and $\alpha$, with probability at least $1 - \delta$, provided $\rho_N N^2 \ge n \rho_n \constantBandeira^2 \log^2(4N/\delta)$.

\noindent \textbf{Case 3. The graphon $W$ is $(M, r)$-analytic.} By the lines of the proof of Theorem~\ref{theorem: analityc convergence rate}, part i), the graphon $W$ is $(H, 1)$-H\"older for $H = \max \{4 M r^{-1}, 2 r^{-1}\}$, so, repeating the proof of Case 2, we conclude that, with probability at least $1 - \delta$, we have
\begin{align*}
    T_{(\bA, \btheta)}(\hat{\btheta}) - T_{(\bA, \btheta)}(\hat\btheta') & \le \frac{2 \alpha (1 + \alpha \Vert \bA\Vert_{\op}/N)^2 (\Vert \btheta \Vert/\sqrt{N} + \sqrt{B})^2}{\left (1 - \alpha \cdot \max \{\Vert \bA \Vert_{\op}/N, \rho_N \Vert \bA' \Vert_{\op}/n\rho_n\} \right )^5} \\
    & \quad  \times \left ( 15 \sqrt{\frac{\rho_N}{n \rho_n}} + C_2(M, r) \rho_N \left ( \frac{\log(16n/\delta)}{n} \right)^{1/2}  \right ),
\end{align*}
and $\rank(\widehat{W}) \le C_2(M, r) \log (n \rho_n)$ by the conclusion of Theorem~\ref{theorem: analityc convergence rate}.



\section{Computational aspects of LQ games}
\label{section: computational aspects}

\begin{lemma}
\label{lemma: computational aspects}
For a network $\bA$ of size $n$ and heterogeneities $\btheta$, let $G(\bA, \btheta)$ be a network LQ game with peer-effect parameter $\gamma$ and budget $B$. Suppose that $\btheta$ has non-zero projection on the eigenspace of the largest eigenvalue $\lambda_1(\bA)$ of $\bA$. Then, there exists a number $L \in \left (-\infty; (1 - \gamma \Vert \bA \Vert_{\op} / n)^{-2} \right )$, such that the optimal interventions can be computed as follows:
\begin{align*}
    \widehat{\btheta} = - \left [\bI + L (\bI - \gamma \bA / n)^2 \right ]^{-1} \btheta, 
\end{align*}
and $\Vert \widehat{\btheta} \Vert^2 = B$.
\end{lemma}

\begin{proof}
    The optimal intevetion problem can be restated as follows:
    \begin{align*}
        \max \Vert (\bI - \gamma \bA / n)^{-1} (\btheta + \widehat{\btheta}) \Vert^2 \\
        \text{subject to } \Vert \widehat{\btheta} \Vert^2 \le B,
    \end{align*}
    see the proof of Proposition 1 in~\cite{Parise_Ozdaglar_Econometrica}. Expanding the squared norm, we obtain the following equivalent problem
    \begin{align*}
        \min_{\widehat{\btheta}} \quad \widehat{\btheta}^T \left [ - (\bI - \gamma \bA / n)^{-2}\right ] \widehat{\btheta} - 2 \widehat{\btheta}^T (\bI - \gamma \bA/n)^{-2} \btheta, \\
        \text{ subject to } \Vert \widehat{\btheta} \Vert^2_2 \le B.
    \end{align*}
    A problem of the form
    \begin{align*}
        \min_{x} x^T \bC x - 2 \bb^T x,  \quad \text{subject to } \Vert x \Vert^2_2 \le \beta,
    \end{align*}
    where $\bC$, $\bb$ and $\beta$ are arbitrary matrix, vector and positive scalar respectively,
    was widely studied in optimization literature, see, for example, papers~\cite{opt_forsythe1965stationary, gander1989constrained, opt_more2006levenberg}. It admits solution in the following form:
    \begin{align*}
        x = (\bC - L \bI)^{-1} \bb, \quad \Vert x \Vert^2_2 = \beta,
    \end{align*}
    where $L \in (-\infty; \lambda_{\min}(\bC))$, assuming $\bb$ has non-zero projection on the eigenspace of $\lambda_{\min}(\bC)$. In our case, $\bC = - (\bI - \gamma \bA / n)^{-2}$ and $\bb = (\bI - \gamma \bA/n)^{-2} \btheta$. Symplifying, we obtain
    \begin{align*}
        \widehat{\btheta} = - \left [ (\bI + L(\bI - \gamma \bA /n)^2 \right ]^{-1} \btheta, \quad \Vert \widehat{\btheta} \Vert^2_2 = B,
    \end{align*}
    where $L \in \left (-\infty; (1 - \gamma \Vert \bA \Vert_{\op} / n)^{-2} \right)$.
\end{proof}





\section{Proof of Lemma \ref{lemma: empirical graphon norm}}
\label{appendix: proof of empirical graphon lemma}



For $f, g \in [0, 1]$ such that $\Vert f \Vert_{L_2} = \Vert g \Vert_2 = 1$ consider
\begin{align*}
	\langle g, \bbW_{\bT}[f] \rangle & = \sum_{i, j} \bT_{ij} \int_{[(i - 1)/n, i/n)} g(y) dy \cdot \int_{[(j - 1)/n, j/n)} f(x) dx \\ 
	& = \bv^T_g \bT \bv_f \\
	& \le \Vert \bv_g \Vert_2 \cdot \Vert \bT \Vert_{\op} \cdot \Vert \bv_f \Vert_2.
\end{align*}
where $\bv_f$ and $\bv_g$ are vectors defined as
\begin{align*}
	(\bv_f)_i & = \int_{[(i - 1)/n, i/n)} f(x) dx, \\
	(\bv_g)_i & = \int_{[(i - 1)/n, i/n)} g(x) dx.
\end{align*}
Next we bound $\Vert \bv_f \Vert_2$, the norm $\Vert \bv_g \Vert$ can be bounded analogously. Define a Hilbert space $L_2^i := L_2 ([(i - 1)/n, i/n))$. Then
\begin{align*}
	|(\bv_f)_i| = |\langle 1, f \rangle_{L_2^i} | \le \Vert 1 \Vert_{L_2^i} \cdot \Vert f \Vert_{L_2^i}.
\end{align*}
Meanwhile, we have
\begin{align*}
	\sum_{i = 1}^n \Vert f \Vert_{L_2^i}^2 = \int_0^1 f^2(x) dx = 1.
\end{align*}
Since $\Vert 1 \Vert_{L_2^i} = \sqrt{\mu ([(i - 1)/n, i/n))} = 1/\sqrt{n}$, we obtain 
\begin{align*}
    \Vert \bv_f \Vert_2 \leq \sqrt{\sum_{i = 1}^n |(\bv_f)_i|^2} \leq \sqrt{ \frac{1}{n} \sum_{i = 1}^n \|f\|^2_{L_2^i}} \le \frac{1}{\sqrt{n}}
\end{align*}
Thus,
\begin{align*}
	\langle g, \bbW_{\bT}[f] \rangle \le \frac{1}{n} \Vert \bT \Vert_{\op}.
\end{align*}
The dual of $L_2[0, 1]$ coincides with $L_2[0, 1]$, so 
\begin{align*}
	\opnorm{\bbW_{\bT}} = \sup_{f, g, \Vert f \Vert_{L_2} = \Vert g \Vert_{L_2} = 1} 
	\langle g, \bbW_{\bT} [f] \rangle \le \frac{1}{n} \Vert \bT \Vert_{\op}.
\end{align*}
The upper bound can be attained by taking $f, g$ equal to
\begin{align*}
	f & = \sum_{i = 1}^n \bu_i I{[(i - 1)/n, i/n)}, \\
	g & = \sum_{i = 1}^n \bv_i I{[(i - 1)/n, i/n)},
\end{align*} 
where $\bu$ and $\bv$ are the right and left singular vectors, respectively, corresponding to the largest singular value of $\bT$.



\section{Tools}\label{appendix: tools}

In this section, we review established results from the literature that are utilized in the proofs.

\subsection{Concentration inequalities}

\begin{prop}[Bernstein's inequality, see Equation (2.10) in \cite{boucheron_concentration_inequalities}]
    Let $X_1, \ldots, X_n$ be independent random variables such that $\max_i |X_i| \le M$. Then
    \begin{align*}
    	\bbP \left (\sum_{i = 1}^n X_i - \sum_{i = 1}^n \bbE (X_i) \ge  t
    	\right )
    	\le \exp \left (
    		- \frac{t^2/2}{\left(\sum_{i = 1}^n \Var (X_i)\right) + M t/3}
    	\right ), 
    \end{align*}
    and
    \begin{align*}
    	\bbP \left (
    		\left|\sum_{i = 1}^n X_i - \sum_{i = 1}^n \bbE (X_i) \right|\ge  t
    	\right )
    	\le 2\exp \left (
    		- \frac{t^2/2}{\left(\sum_{i = 1}^n \Var (X_i)\right) + M t/3}
    	\right ).
    \end{align*}
\end{prop}

\begin{prop}[Matrix concentration inequality, see Corollary 3.12, Remark 3.13 in~\cite{bandeira2016}]
\label{theorem: matrix concentration}
	Let $\bX$ be an $n \times n$ matrix whose entries $\bX_{i j}$ are independent, centered and bounded random variables. Then there exists for any $0 < \epsilon \le 1/2$ a universal constant $c_\epsilon$ such that for every $t > 0$
	\begin{align*}
		\bbP \left ( \Vert \bX \Vert_{\op} \ge (1 + \epsilon) 2 \sqrt{2} \sigma + t \right ) \le n e^{-t^2 / c_\epsilon \sigma_*^2},
	\end{align*}
	where we have defined
	\begin{align*}
		\sigma : = \max_i \sqrt{\sum_j \bbE (\bX_{i j}^2}), \quad \sigma_* : = \max_{i j}  |\bX_{i j}|.
	\end{align*}
\end{prop}

% {\color{red}($\esssup$ is not stated in the cited result, should we remove it?)}
In our paper, we choose $\epsilon = \frac{3 \sqrt{2}}{4} - 1 \approx 0.06$. Then, $(1 + \epsilon) 2 \sqrt{2} = 3$. We denote the corresponding $c_\epsilon$ by $\constantBandeira$.



\subsection{Stability of variational inequality problem}
Let $H$ be a Hilbert space. 
\begin{definition}
    We say that a function $F : H \to H$ admits the strong monotonicity property with constant $\alpha > 0$ if for each $x_1, x_2$ we have
    \begin{align*}
        \langle F(x_1) - F(x_2) , x_1 - x_2 \rangle \ge \alpha \Vert x_1 - x_2 \Vert^2.
    \end{align*}
\end{definition}

The following statements are obvious generalizations of finite-dimensional ones from~\cite{nagurney_VIs}.

\begin{prop}[see Proposition 1.2, 1.3 in~\cite{nagurney_VIs}]
\label{proposition: VI statement}
    Let $T$ be an integral operator. Then if $v$ maximizes the quadratic form $\langle T (v_0 + v), T (v_0 + v) \rangle$ subject to a convex set $K \subseteq H$, then for any $v' \in K$
    \begin{align*}
        \langle  T^* T (v_0 + v), v' - v\rangle \le 0.
    \end{align*}
\end{prop}

\begin{definition}
	We say that $v$ is a solution of the variational inequality problem $VI(F, K)$ with function $F$ and convex set $K$ if
	\begin{align*}
		\langle F(v), v' - v \rangle \le 0 \text{ for any } v' \in K.
	\end{align*}
\end{definition}

\begin{prop}[Theorem 1.14 in~\cite{nagurney_VIs}]
\label{prop: stability of VI}
	Let $F_1$ be a strongly monotone function with constant $\alpha$. Let $v_1$ be a solution of $VI(F_1, K)$ and $v_2$ be a solution of $VI(F_2, K)$. Then
	\begin{align*}
		\Vert v_1 - v_2 \Vert \le \frac{1}{\alpha} \Vert F_2(v_1) - F_1(v_1) \Vert.
	\end{align*}
\end{prop}



\subsection{Norms and singular values of matrices}

\begin{prop}[Weyl's inequality, see \cite{bisgard2020}]
\label{proposition: weyl inequality}
	Let $\bA, \bB \in \bbR^{n \times n}$ be arbitrary matrices, and let $\sigma_k(\bA)$ and $\sigma_k(\bB)$, $k \in [n]$  be their singular values in descending order. Then
	\begin{align*}
		\sigma_{i + j - 1}(\bA + \bB) \le \sigma_{i}(\bA) + \sigma_j(\bB)
	\end{align*}
	for $1 \le i, j, i+ j - 1 \le  n$.
\end{prop}

\begin{prop}[Eckart-Young-Mirsky theorem, see \cite{bisgard2020}]
\label{proposition: eckart-yang theorem}
	Let $\bA$ be an arbitrary matrix and $\sigma_1 \ge \ldots \ge \sigma_n$ be its singular values. Then, we have
	\begin{align*}
		\min_{\rank(\bB) \le r} \Vert \bA - \bB \Vert_{F} = \sqrt{\sum_{i > r} \sigma_i^2},
	\end{align*}
	and the minimizer is unique.
\end{prop}


\subsection{Norms of matrices and graphons}
The cut norm of a matrix $\bA \in [0,1]^{n \times n}$ is defined by
\begin{align}
    \|\bA\|_\square := \frac{1}{n^2} \max_{S, T \subseteq [n]} \left|\sum_{i \in S, j \in T} A_{ij}\right|. 
\end{align} 
We have that  $\Vert \bA \Vert_{\op} \ge n \Vert \bA \Vert_{\square}.$
\begin{proof}
    Let $S^*, T^*$ be the sets that provide the maximum  in  the definition of $\|\bA\|_\square$, i.e., 
    \begin{align*}
        \|\bA\|_\square = \frac{1}{n^2} \left|\sum_{i \in S^*, j \in T^*} A_{ij}\right|.
    \end{align*}
    Define $\bu^{S^*} \in \bbR^n$ such that $\bu^{S^*}_i = 1$ if $i \in S^*$, $\bu^{S^*}_i = 0$ if $i \notin S^*$.  Similarly, define $\bu^{T^*}$. Then,
    \begin{align*}
        \|\bA\|_\square = \frac{1}{n^2} \langle \bA \bu^{T^*}, \bu^{S^*} \rangle \leq \frac{1}{n^2} \| \bA \bu^{T^*} \| \| \bu^{S^*} \| \leq \frac{1}{n^2} \| \bA \|_{\op} \| \bu^{T^*} \| \| \bu^{S^*} \| \leq \frac{1}{n^2} \| \bA \|_{\op} \sqrt{n} \sqrt{n} = \frac{\|\bA\|_{\op}}{n},  
    \end{align*}
    where the first inequality is the Cauchy-Schwartz inequality and the second inequality is due to submultiplicativity of the $2$-norm. 
\end{proof}
