	\noindent\textbf{Matching construction.} Suppose that $\tilde{d}_F(\tau, \sigma)\le \delta$. We use the following lemma to compute a matching $\+M$ between $\tau$ and $\sigma$ satisfying $d_{\+M}(\tau, \sigma)\le \delta$ explicitly. Note that $\+{M}$ matches each vertex of $\tau$ to a vertex of $\sigma$ and vice verse. We can construct such a matching by backtracking the output of {\sc DisWave}$(\tau, \sigma, \delta, \+S, \+S')$, where $\+S=\{v_1\}$ and $\+S'=\{w_1\}$. For a vertex $p$ of $\tau$ or $\sigma$, let $\+M(p)$ be a vertex matched to $p$ by $\+M$.

	\begin{lemma}~\label{lem: discrete matching}
		Given two polygonal curves $\tau, \sigma$ in $\mathbb{R}^d$, suppose $\tilde{d}_F(\tau, \sigma) \leq \delta$. There is an $O(nm)$-time algorithm for computing a matching $\+M$ between $\tau, \sigma$ such that $d_{\+M}(\tau, \sigma) \leq \delta$. $\+M$ can be stored in $O(n+m)$ space such that for any vertex $p$ of $ \tau $ or $ \sigma$, we can retrieve a vertex $\+{M}(p)$ in $O(1)$ time.
	\end{lemma}

	\begin{proof}	
		We can backtrack the output $\bigl(\+{DW}^{v_i}\bigr)_{i\in[n]}$ of {\sc DisWave}$(\tau, \sigma, \delta, \+S, \+S')$ to construct $\+M$, where $\+S=\{v_1\}$ and $\+S'=\{w_1\}$. For every vertex $p$ of $\tau$ or $\sigma$, we compute $\+{M}(p)$ and store it. Let $\+{L}$ be an empty sequence.
		Since $\tilde{d}_F(\tau, \sigma) \leq \delta$, we have $w_m\in \+{DW}^{v_n}$, we add $(v_n, w_m)$ to $\+{L}$. According to the procedure of {\sc DisWave}, it must be true that $w_m\in \+{DW}^{v_{n-1}}$ or $w_{m-1}\in \+{DR}^{v_n}$ or $w_{m-1}\in \+{DW}^{v_{n-1}}$. Suppose $w_m\in \+{DW}^{v_{n-1}}$, we add $(v_{n-1}, w_m)$ to $\+{L}$. Then it must happen that $w_m\in \+{DW}^{v_{n-2}}$ or $w_{m-1}\in \+{DW}^{v_{n-1}}$ or $w_{m-1}\in \+{DW}^{v_{n-2}}$. We repeat this process until we add $(v_1, w_1)$ to $\+{L}$. Finally, we get a sequences for pairs of vertices from $(v_n, w_m)$ to $(v_1, w_1)$.

		Traverse $\+L$ in order, for each pair $(v_i, w_j)$, if $\+{M}(v_i)$ doesn't exist, we set $\+{M}(v_i) = w_j$; if $\+{M}(w_j)$ doesn't exist, we set $\+{M}(w_j) = v_i$; if neither $\+{M}(v_i)$ nor $\+{M}(w_j)$ exists, we set $\+{M}(v_i) = w_j$ and $\+{M}(w_j) = v_i$. According to the procedure of {\sc DisWave}$(\tau, \sigma, \delta,\+S, \+S')$, we have $d(v_i, w_j) \leq \delta$ for all pairs $(v_i, w_j) \in \+L$. So, the matching $\+M$ satisfies $d_{\+{M}}(\tau, \sigma) \leq \delta$. We store $\+M$ in a linear space, then for any vertex $p \in \tau \cup \sigma$, we can retrieve a vertex $\+{M}(p)$ in $O(1)$ time.
	\end{proof}

	\noindent\textbf{Curve simplification.} We will need to simplify a curve $\tau$ under the discrete Fr\'echet distance. We employ an approximate algorithm developed in \cite[Lemma 23]{filtser2023approximate}

	\begin{lemma}[Lemma 23~\cite{filtser2023approximate}]~\label{lem: discrete simplification}
		Let $\tau$ be a curve of $n$ vertices in $\mathbb{R}^d$. Given $\delta > 0$, and $\epsilon \in (0, 1)$, there is an algorithm that returns a curve $\tau'$ of size at most $k^*$ in $O(\frac{d \cdot n \log n}{\epsilon} + n \cdot \epsilon^{-4.5} \log \frac{1}{\epsilon})$ time such that 
		$\tilde{d}_{F}(\tau, \tau') \leq (1+\epsilon)\delta$, where $k^*=\min\{|\tau''|:\tilde{d}_F(\tau, \tau'')\le \delta\}$. %Furthermore, for every curve $\tau'$ with $|\tau'| < |\tau^*|$, it holds that $\tilde{d}_{F}(\tau, \tau') > \delta$.
	\end{lemma}	

	As with the Fr\'echet distance, we divide $\tau$ and $\sigma$ into short subcurves and implement a discrete counterpart of {\sc Reach} called {\sc DisReach}. Let $\mu_1$ and $\mu_2$ be two integers with $\mu_1>\mu_2$. Define $a_k=(k-1)\mu_1+1$ for $k\in [(n-1)/\mu_1]$. We divide $\tau$ into a collection $(\tau_1, \tau_2,\ldots, \tau_{(n-1)/\mu_1})$ of $(n-1)/\mu_1$ subsequences such that $\tau_k=\tau[v_{a_k}, v_{a_{k+1}}]$. Note that every subsequence $\tau_k$ contains $\mu_1+1$ vertices, and $\tau_{k-1}\cap \tau_k=v_{a_k}$. 

	We divide $\sigma$ into shorter subsequences. Define $b_l=(l-1)\mu_2+1$ for $l\in [(m-1)/\mu_2]$. We divide $\sigma$ into a collection $(\sigma_1, \sigma_2,\ldots, \sigma_{(m-1)/\mu_2})$ of $(m-1)/\mu_2$ subsequences such that $\sigma_l=\sigma[w_{b_l}, w_{b_{l+1}}]$. Every subsequence $\sigma_l$ contains $\mu_2+1$ vertices, and $\sigma_{l-1}\cap \sigma_l=w_{b_l}$.

