	\noindent\textbf{Lemma~\ref{lem: wave}.}~~\emph{Given two polygonal curves $\tau$ and $\sigma$ in $\mathbb{R}^d$, a value $\delta>0$, an array $\+S$ induced by $\tau$, and an array $\+S'$ induced by $\sigma$, calling {\sc WaveFront}$(\tau, \sigma, \delta, \+S, \+S')$ returns $(\+{W}^{v_i})_{i\in [n]}$ and $(\+{W}^{w_j})_{j\in[m]}$:} 

