	\section{Proof of Lemma~\ref{lem: I_3}}\label{sec:proof_I_3}

	\noindent\textbf{Lemma~\ref{lem: I_3}.}~\emph{We can construct $\+I^3$ in $O(\mu_1+\mu_2^2)$ time. For any $i\in [n-1]$, if $\reachWJ{b_{l+1}}{i}$ is of type 3, then $\reachWJ{b_{l+1}}{i}\subset \+I^3_{v_i}$, and every point covered by $\+I^3$ forms a $((7+\varepsilon)\delta)$-reachable pair with $w_{b_{l+1}}$.  }

	\begin{proof}
		The running time follows the construction procedure directly. We focus on proving the property of $\+I^3$.

	Suppose that there is a reachability interval $\reachWJ{b_{l+1}}{i}$ of type 3 in $v_iv_{i+1}$. By definition, $i$ must belong to $[a_k, i_{\text{pre}}]$. According to the construction procedure,  $\+I^3_{v_i}$ is determined by $\+{W}^{w_{b_{l+1}}}$ instead of being set to $\emptyset$ directly. We first claim that for any point $x\in \reachWJ{b_{l+1}}{i}$, there is a point $p$ covered by $\appReachVIArray{a_k}{l}$ with $d_F(\tau[v_{a_k}, x], \sigma[p, w_{b_{l+1}}])\le \delta$. By the definition of type 3 reachability interval, for the start $\ell^{b_{l+1}}_{v_i}$ of $\reachWJ{b_l}{i}$, there is a point $p$ covered by $\appReachVIArray{a_k}{l}$ with $d_F(\tau[v_{a_k}, \ell^{b_{l+1}}_{v_i}], \sigma[p, w_{b_{l+1}}])\le \delta$. Since $\ell^{b_{l+1}}_{v_i}\le_{\tau} x$ and both $\ell^{b_{l+1}}_{v_i}$ and $x$ are within a distance $\delta$ to $w_{b_{l+1}}$, we can extend the Fr\'echet matching between $\tau[v_{a_k}, \ell^{b_{l+1}}_{v_i}]$ and $\sigma[p, w_{b_{l+1}}]$ to a matching between $\tau[v_{a_k},x]$ and $\sigma[p, w_{b_{l+1}}]$ by matching the line segment $\ell^{b_{l+1}}_{v_i}x$ to $w_{b_{l+1}}$. The matching realizes a distance at most $\delta$. We finish proving the claim.

	We then reveal the connection between $\reachWJ{b_{l+1}}{i}$ and $\pre$, $\+{W}^{w_{b_{l+1}}}$. Specifically, we prove that for any point $x\in \reachWJ{b_{l+1}}{i}$, $\Mpre(x)$ is covered by $\+{W}^{w_{b_{l+1}}}$. Given that $d_{\Mpre}(\tau[v_{a_k}, v_{i_{\text{pre}}}], \pre)\le (1+\epsilon)\delta$, the subcurve $\tau[v_{a_k}, x]$ can be matched to $\pre[v''_1, \Mpre(x)]$ within a distance of $(1+\epsilon)\delta$, which implies that $d_F(\tau[v_{a_k}, x], \pre[v''_1, \Mpre(x)])\le(1+\epsilon)\delta$. Hence, $d_F(\pre[v''_1, \Mpre(x)], \sigma[p, w_{b_{l+1}}])\le(2+\epsilon)\delta$ by the triangle inequality. Provided that $p$ is covered by $\appReachVIArray{a_k}{l}$, and $\+{W}^{w_{b_{l+1}}}$ is returned by the invocation of {\sc WaveFront}$(\pre, \sigma_l, (2+\epsilon)\delta, \+S, \appReachVIArray{a_k}{l})$, $\Mpre(x)$ must belong to some line segment in $\+{W}^{w_{b_{l+1}}}$ by Lemma~\ref{lem: wave}.

	Given that $\Mpre(x)$ is covered by $\+{W}^{w_{b_{l+1}}}$, $\+I^3_{v_i}$ is not empty by the construction. In addition, the start $x'$ and end $y'$ of $\+I^3_{v_i}$ satisfies that $x'\le_{\tau} x\le_{\tau} y'$. Hence, $\reachWJ{b_{l+1}}{i}\subset \+I^3_{v_i}$.

	Next, suppose that $\+I^3_{v_i}=x'y'$ is not empty for some $i\in [n-1]$. By construction, $i$ belongs to $[a_k, i_{\text{pre}}-1]$, and both $\Mpre(x')$ and $\Mpre(y')$ are covered by $\+{W}^{w_{b_{l+1}}}$. By Lemma~\ref{lem: wave}, $\Mpre(x')$ satisfies that there is some point $p$ in some $\appReachVIArray{a_k}{l}$ such that $d_F(\pre[v''_1, \Mpre(x')], \sigma[p, w_{b_{l+1}}])\le (2+\epsilon)\delta$. So does $\Mpre(y')$. It implies that $d(w_{b_{l+1}}, \Mpre(x'))\le (2+\epsilon)\delta$ and $d(w_{b_{l+1}}, \Mpre(y'))\le (2+\epsilon)\delta$. Provided that $d(x', \Mpre(x'))\le (1+\epsilon)\delta$ and $d(y', \Mpre(y'))\le (1+\epsilon)\delta$, both $d(x', w_{b_{l+1}})$ and $d(y', w_{b_{l+1}})$ are at most $(3+2\epsilon)\delta$ by the triangle inequality. Hence, $\+I^3_{v_i}$ is within the ball $\+B(w_{b_{l+1}}, (3+2\epsilon)\delta)$.

	We proceed to prove that $(x', w_{b_{l+1}})$ is $((7+\varepsilon)\delta)$-reachable. Since $d_F(\pre[v''_1, \Mpre(x'), \sigma[p, w_{b_{l+1}}]])\le(2+\epsilon)\delta$ for a point $p$ covered by $\appReachVIArray{a_k}{l}$, and $d_F(\tau[v_{a_k}, x'], \pre[v''_1, \Mpre(x')])\le (1+\epsilon)\delta$, we have $d_F(\tau[v_{a_k}, x'], \sigma[p, w_{b_{l+1}}])\le (3+2\epsilon)\delta$ by the triangle inequality. Note that $\epsilon=\varepsilon/10$. Given that $\appReachVIArray{a_k}{l}$ is $(7+\varepsilon)$-approximate reachable for $v_{a_k}$, it holds that $d_F(\tau[v_1, v_{a_k}], \sigma[w_1, p])\le (7+\varepsilon)\delta$. Hence, we can construct a matching between $\tau[v_1, x']$ and $\sigma[w_1, w_{b_{l+1}}]$ by concatenating the Fr\'echet matching between $\tau[v_{a_k}, x']$ and $\sigma[p, w_{b_{l+1}}]$ and the Fr\'echet matching between $\tau[v_1, v_{a_k}]$ and $\sigma[w_1, p]$. The matching realizes a distance at most $(7+\varepsilon)\delta$. Therefore, $d_F(\tau[v_1, x'], \sigma[w_1, w_{b_{l+1}}])\le (7+\varepsilon)\delta$, it means that $(x', w_{b_{l+1}})$ is $((7+\varepsilon)\delta)$-reachable.

	For any point $x''\in \+I^3_{v_i}$, we can extend the Fr\'echet matching between $\tau[v_1, x']$ and $\sigma[w_1, w_{b_{l+1}}]$ to a matching between $\tau[v_1, x'']$ and $\sigma[w_1, w_{b_{l+1}}]$ by matching the line segment $x'x''$ to $w_{b_{l+1}}$. The matching realizes a distance at most $(7+\varepsilon)\delta$. Therefore, $d_F(\tau[v_1, x''], \sigma[w_1, w_{b_{l+1}}])\le (7+\varepsilon)\delta$, it means that $(x'', w_{b_{l+1}})$ is $((7+\varepsilon)\delta)$-reachable.

\end{proof}


