\noindent To make sure that the presentation is as neat as possible, we formulate all key results (including both simple and more complicated ones) as lemmas or theorems.







\vspace{.1in}

\noindent \underline{1) \textbf{\emph{Algebraic spectral initializers characterization:}}} We start by noting that $ \x^{(spec)} $ defined in (\ref{eq:speceq1}) can alternatively be obtained as
\begin{equation}
 \x^{(spec)} =\mbox{max eigenvector} \lp A^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   A\rp = \mbox{arg} \max_{\|\x\|_2=1} \x^T\lp A^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   A\rp \x.
\label{eq:rdteq0a0a0}
\end{equation}
For the completeness, we also define the corresponding maximum eigenvalue
\begin{equation}
 \lambda^{(spec)} =\mbox{max eigenvalue} \lp A^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   A\rp = \max_{\|\x\|_2=1} \x^T\lp A^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   A\rp \x.
\label{eq:rdteq0a0a0a0}
\end{equation}
From (\ref{eq:rdteq0a0a0}), we further have
\begin{eqnarray}
 \x^{(spec)} = \mbox{arg}\max_{\|\x\|_2=1,\z}  & &  \z^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   \z \nonumber \\
 \mbox{subject to } & & A\x=\z.
\label{eq:rdteq0a0a1}
\end{eqnarray}
One then also observes that rotational invariance of $A$ allows any ($A$ independent) rotation of $\bar{\x}$. Following into the footsteps of \cite{Stojnicphretreal24}, we choose the rotation that transform $\bar{\x}$ into  $\bar{\x}=[\|\bar{\x}\|_2,0,\dots,0 ]^T$. This immediately implies
\begin{eqnarray}
 \bar{\y}=A\bar{\x}=A_{:,1}\|\bar{\x}\|_2
\label{eq:rdteq0a0a2}
\end{eqnarray}
and allows to rewrite (\ref{eq:rdteq0a0a1}) as
\begin{eqnarray}
 \x^{(spec)} = \mbox{arg}\max_{\|\x\|_2=1,\z}  & &  \z^T \mbox{diag} \lp  {\mathcal T}(A_{:,1}\|\bar{\x}\|_2)  \rp   \z \nonumber \\
 \mbox{subject to } & & A\x=\z,
\label{eq:rdteq0a0a3}
\end{eqnarray}
where $A_{:,i}$ stands for the $i$-th column of $A$. Analogously to (\ref{eq:ex1a4a0}), we find it convenient to introduce the following \emph{fundamental spectral initializer}
\begin{eqnarray}
\hspace{-.2in}\bl{\mbox{\emph{\textbf{(f-spin) optimization:}}}} \qquad  \xi_s(x) \triangleq \max_{\|\x\|_2=1,\z}  & &  \z^T \mbox{diag} \lp  {\mathcal T}(A_{:,1}\|\bar{\x}\|_2)  \rp   \z \nonumber \\
 \mbox{subject to } & & A\x=\z \nonumber \\
  & & \x^T\bar{\x}=\x_1\|\bar{\x}\|_2=x.
\label{eq:rdteq0a0a3a0}
\end{eqnarray}
After setting $r\triangleq \sqrt{1-x^2}$ and noting that restriction to $\|\bar{\x}\|_2=1$ brings no loss of generality, we further have
 \begin{eqnarray}
 - \xi_s(x) = \min_{\x,\z} & & -\z^T \mbox{diag} \lp  {\mathcal T}(A_{:,1})  \rp   \z \nonumber \\
  \mbox{subject to} & &  A\x=A_{:,1}x + A_{:,2:n}\x_{2:n} = \z \nonumber \\
   & & \sum_{i=2}^{n}\x_i^2=1-x^2=r^2, \label{eq:rdteq0a1}
\end{eqnarray}
Writing Lagrangian then gives
 \begin{eqnarray}
 - \xi_s(x) = \min_{\x,\z} \max_{\y}   & &
 -\z^T \mbox{diag} \lp  {\mathcal T}(A_{:,1})  \rp   \z
  +\y^TA_{:,1}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \nonumber \\
  \mbox{subject to}
     & & \sum_{i=2}^{n}\x_i=c-x^2=r^2. \label{eq:rdteq0a2}
\end{eqnarray}
We also set $\g^{(0)}=A_{:,1}$ and rewrite (\ref{eq:rdteq0a2}) in a more compact way
 \begin{eqnarray}
 - \xi_s(x) = \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}( \g^{(0)} )  \rp   \z
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp. \label{eq:rdteq0a3}
\end{eqnarray}
Since the above  is a fairly useful characterization of the spectral initializers, it is summarized in the following lemma.

\begin{lemma} Consider real phase retrieval (PR) problem and, for a general componentwise-wise preprocessing function ${\mathcal T}(\cdot):\mR^m\rightarrow \mR^m$, let the associated general spectral initializer, $\x^{(spec)}$, be as in (\ref{eq:speceq1}). Assume a high-dimensional linear/proportional regime
with $\alpha=\lim_{n\rightarrow\infty}\frac{m}{n}$ and let $A\in\mR^{m\times n}$ and $\g^{(0)}\triangleq A_{:,1}$.  Set $r\triangleq \sqrt{1-x^2}$. Let
$\lambda^{(spec)}$ and $\x^{(spec)}$ be the maximum eigenvalue and the associated maximum eigenvector of $A^T \mbox{diag} \lp  {\mathcal T}(\bar{\y})  \rp   A$, i.e., let $\lambda^{(spec)}$ and $\x^{(spec)}$  be as defined in  (\ref{eq:rdteq0a0a0}) and (\ref{eq:rdteq0a0a0a0}), respectively. Moreover, let $x^{(spec)}$ be as in (\ref{eq:speceq3}).  Then
 \begin{eqnarray}\label{eq:ta10}
 \frac{\lambda^{(spec)}}{n} & = & \max_{x} \frac{\xi_s(x)}{n}  =   -\min_{x} f^{(s)}_{rp}(x;A) \nonumber \\
 x^{(spec)} = \x_1^{(spec)} & = & \arg \min_{x} f^{(s)}_{rp}(x;A) \nonumber \\
\x_{2:n}^{(spec)}  & = & \arg \min_{\|\x_{2:n}\|_2=r} \lp \min_{\z} \max_{\y}  \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp \rp, \nonumber \\
\end{eqnarray}
 where
\begin{equation}\label{eq:ta11}
f^{(s)}_{rp}(x;A)\triangleq \frac{1}{n}  \min_{\|\x_{2:n}\|_2=r,\z} \max_{\y}  \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\y^T \g^{(0)}x + \y^TA_{:,2:n}\x_{2:n} -\y^T \z \rp.
\end{equation}
    \label{lemma:lemma1}
\end{lemma}
\begin{proof}
Follows automatically from the above discussion after recognizing that (\ref{eq:ta11}) is cosmetically  scaled (\ref{eq:rdteq0a3}).
\end{proof}

The optimization program on the right hand side of (\ref{eq:ta11}) constitutes the so-called \emph{random primal}. The corresponding \emph{random dual} is discussed next.


\vspace{.1in}
\noindent \underline{2) \textbf{\emph{Determining the random dual:}}} Following the typical practice within the RDT, the concentration of measure is utilized as well. This basically means that for any fixed $\epsilon >0$,  one has (see, e.g. \cite{StojnicCSetam09,StojnicRegRndDlt10,StojnicICASSP10var})
\begin{equation*}
\lim_{n\rightarrow\infty}\mP_{A}\left (\frac{|f^{(s)}_{rp}(x;A)-\mE_{A}(f^{(s)}_{rp}(x;A)|}{\mE_{A}(f^{(s)}_{rp}(x;A)}>\epsilon\right )\longrightarrow 0.\label{eq:ta15}
\end{equation*}
The so-called random dual theorem that we state below is another fundamentally important ingredient of the RDT machinery.
\begin{theorem} Assume the setup of Lemma \ref{lemma:lemma1} with the elements of $A\in\mR^{m\times n}$ ($\g^{(0)}\in\mR^{m\times 1}$ and $A_{:,2:n}\in\mR^{m\times (n-1)}$), $\g^{(1)}\in\mR^{m\times 1}$, and  $\h^{(1)}\in\mR^{(n-1)\times 1}$  being iid standard normals. Let $x$ be a nonnegative  scalar ($0\leq x \leq 1$) and set $r\triangleq \sqrt{1-x^2}$. Let
\vspace{-.0in}
\begin{eqnarray}
\cG & \triangleq & \lp A,\g^{(1)},\h^{(1)}\rp = \lp\g^{(0)},A_{:,2:n},\g^{(1)},\h^{(1)}\rp  \nonumber \\
\phi^{(s)}(\x,\z,\y) & \triangleq &
 \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\y^T \g^{(0)}x   +  \y^T \g^{(1)}\|\x_{2:n}\|_2 + \lp \x_{2:n}  \rp^T\h^{(1)}\|\y\|_2  -\y^T  \z  \rp
\nonumber \\
 f^{(s)}_{rd}(x;\cG) & \triangleq &
\frac{1}{n}  \min_{\|\x_{2:n}\|_2=r,\z} \max_{\|\y\|_2=r_y,r_y>0}  \phi^{(s)}(\x,\z,\y)
  \nonumber \\
 \phi^{(s)}_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f^{(s)}_{rd}(x;\cG).\label{eq:ta16}
\vspace{-.0in}\end{eqnarray}
One then has \vspace{-.02in}
\begin{eqnarray}
  \lim_{n\rightarrow\infty}\mP_{ A } (f^{(s)}_{rp} (x; A )   >  \phi^{(s)}_0)\longrightarrow 1.\label{eq:ta17a0}
\end{eqnarray}
  \label{thm:thm1}
\end{theorem}\vspace{-.17in}
\begin{proof}
Follows automatically after applying the Gordon's comparison theorem (see, e.g., Theorem B in \cite{Gordon88}) and  conditioning on $\g^{(0)}$. Gordon's theorem can be deduced as a special case of a series of results Stojnic obtained in \cite{Stojnicgscomp16,Stojnicgscompyx16} (see Theorem 1, Corollary 1, and Section 2.7.2 in \cite{Stojnicgscomp16} as well as Theorem 1, Corollary 1, and Section 2.3.2 in \cite{Stojnicgscompyx16}).
\end{proof}




\vspace{.1in}
\noindent \underline{3) \textbf{\emph{Handling the random dual:}}} To handle the above random dual, we rely on a series of techniques introduced in \cite{StojnicCSetam09,StojnicICASSP10var,StojnicISIT2010binary,StojnicICASSP10block,StojnicRegRndDlt10}. We first note that the optimizations over $\x$ and $\y$ in  (\ref{eq:ta16}) are relatively simple and allow to write
\begin{equation}
 f^{(s)}_{rd}(x;\cG) =
\frac{1}{n}  \min_{\z} \max_{r_y>0}
 \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2 r_y - \|\h^{(1)} \|_2 r r_y \rp.
\label{eq:hrd1}
 \end{equation}
One then also has
\begin{eqnarray}
 f^{(s)}_{rd}(x;\cG)
  &  =  &
\frac{1}{n}  \min_{\z} \max_{r_y>0}
 \lp
   -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp \nonumber \\
  &  \geq   &
\frac{1}{n}  \max_{r_y>0} \min_{\z}
 \lp
  -\z^T \mbox{diag} \lp  {\mathcal T}(\g^{(0)} )  \rp   \z
  +\|\g^{(0)}x   +  \g^{(1)}r -\z\|_2^2 r_y - \|\h^{(1)} \|_2^2 r^2 r_y \rp
  \nonumber \\
  &  =   &
\frac{1}{n}  \max_{r_y>0} \min_{\z_i}
 \lp
\sum_{i=1}^{m}
\lp
-\tau_i\z_i^2  +\|\g_i^{(0)}x   +  \g_i^{(1)}r -\z_i\|_2^2 r_y \rp
  - \|\h^{(1)} \|_2^2 r^2 r_y \rp,
\label{eq:hrd2}
 \end{eqnarray}
 where we set
\begin{eqnarray}
\tau =  {\mathcal T}(\g^{(0)} ) .
\label{eq:hrd2a0}
 \end{eqnarray}
Statistical identicalness over $i$ together with concentrations then gives
\begin{eqnarray}
 \phi^{(s)}_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f^{(s)}_{rd}(\cG)
\geq
  \max_{r_y>0} \mE_{\cG}  \min_{\z_i} \cL_1(r_y),
\label{eq:hrd6}
 \end{eqnarray}
where
\begin{eqnarray}
\cL_1(r_y)
  &  = &
\alpha  \lp
 -\tau_i \z_i^2
  + \lp \g_i^{(0)}x   +  \g_i^{(1)}r -\z_i \rp^2 r_y \rp
  -  r^2 r_y.
\label{eq:hrd7}
 \end{eqnarray}
When  $\r_y> \tau_i$ finding the following derivative turns out to be useful
\begin{eqnarray}
\frac{d\cL_1(r_y)}{d\z_i}
  &  = &
\alpha \lp -2\tau_i\z_i
  -2\lp \g_i^{(0)}x   +  \g_i^{(1)}r -\z_i \rp  r_y\rp.
\label{eq:hrd7a0}
 \end{eqnarray}
One can then equal the above derivative to zero while keeping in mind the condition $\r_y\geq \tau_i$ and determine the optimal $\z_i$ as
\begin{eqnarray}
\hat{\z}_i= \begin{cases}
              \frac{r_y}{-\tau_i+r_y} \lp \g_i^{(0)}x   +  \g_i^{(1)}r\rp
, & \mbox{if } r_y> \tau_i \\
              0, & \mbox{otherwise}.
            \end{cases}
\label{eq:hrd7a1}
 \end{eqnarray}
A combination of  (\ref{eq:hrd7}) and  (\ref{eq:hrd7a1}) further gives
\begin{eqnarray}
\min_{\z_i} \cL_1(r_y)
     &  = &
     \begin{cases}
       -\alpha
\frac{\tau_i r_y}{-\tau_i+r_y} \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2
  -  r^2 r_y, & \mbox{if } r_y>\tau_i \\
              \alpha
r_y \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2
  -  r^2 r_y, & \mbox{otherwise}.
     \end{cases}
\label{eq:hrd7a2}
 \end{eqnarray}
 For the time being we assume $r_y>\tau_i$ and after setting
\begin{eqnarray}
f_q & \triangleq & - \mE_{\cG} \frac{\tau_i r_y}{-\tau_i+r_y}   \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2,
\label{eq:hrd7a2a0}
 \end{eqnarray}
 easily write
\begin{eqnarray}
 \mE_{\cG} \min_{\z_i} \cL_1(r_y)
       &  = &
\alpha
   f_q  -  r^2 r_y.
\label{eq:hrd7a3}
 \end{eqnarray}
After plugging this back in (\ref{eq:hrd6}) one has
\begin{eqnarray}
 \phi^{(s)}_0 & \triangleq & \lim_{n\rightarrow\infty} \mE_{\cG} f^{(s)}_{rd}(\cG)
    \geq
  \max_{r_y>0}
  \lp
  \alpha
\ f_q
  -  r^2 r_y \rp.
\label{eq:hrd7a4}
 \end{eqnarray}
To further analyze the optimization problem on the right hand side
one computes the derivative of the expression under $\max$
\begin{equation}
 \frac{d  \lp
  \alpha
 f_q
  -  r^2 r_y \rp}{dr_y} =   \alpha
 \frac{df_q}{dr_y}
  -  r^2
  =   -\alpha
 \frac{d\lp \mE_{\cG} \frac{\tau_i r_y}{-\tau_i+r_y}   \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2 \rp}{dr_y}
  -  r^2
    =   \alpha
 \mE_{\cG} \frac{\tau_i^2   \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2 }{(-\tau_i+r_y)^2}
  -  r^2.
\label{eq:hrd7a5}
 \end{equation}
Keeping in mind that $\tau_i$ depends only on $\g_i^{(0)}$ (and not on $\g_i^{(1)}$), one can integrate out $\g_i^{(1)}$ and rewrite (\ref{eq:hrd7a5}) as
\begin{equation}
 \frac{d  \lp
  \alpha
 f_q
  -  r^2 r_y \rp}{dr_y}     =   \alpha
 \mE_{\cG} \frac{\tau_i^2   \lp \lp \g_i^{(0)}\rp^2(1-r^2)   + r^2  \rp }{(-\tau_i+r_y)^2}
  -  r^2.
\label{eq:hrd7a5a0}
 \end{equation}
As (\ref{eq:ta10}) and (\ref{eq:ta17a0}) state, an additional minimization over $r$ of the righthand side of (\ref{eq:hrd7a4}) is ultimately needed as well. To that end we find it useful to complement the above $r_y$ derivative with its $r$-derivative analogue. Since $r^2$ appears as a variable rather than $r$, formally speaking,  we find it more convenient to compute the $r^2$-derivative
\begin{equation}
 \frac{d  \lp
  \alpha
 f_q
  -  r^2 r_y \rp}{dr^2} =   \alpha
 \frac{df_q}{dr^2}
  -  r_y
  =   -\alpha
 \frac{d\lp \mE_{\cG}\lp \frac{\tau_i r_y}{-\tau_i+r_y}   \lp \g_i^{(0)}x   +  \g_i^{(1)}r  \rp^2 \rp\rp}{dr^2}
  -  r_y
    =   \alpha
 \mE_{\cG} \frac{\tau_i r_y  \lp  \lp \g_i^{(0)} \rp^2  -  1  \rp }{-\tau_i+r_y}
  -  r_y,
\label{eq:hrd7a5a0a0}
 \end{equation}
where the second equality follows after recognizing once again that $\g_i^{(1)}$ can be integrated out. Equalling (\ref{eq:hrd7a5a0}) and (\ref{eq:hrd7a5a0a0}) to zero is then sufficient to determine optimal $\hat{r}_y$ and $\hat{r}$ and provided that $\hat{r}_y>\tau_i$ it is also sufficient to determine the tightest (with respect to $r$) right hand side of (\ref{eq:hrd7a4}). Assuming that all of this indeed happens for a choice of $\tau_i$, one still needs to determine the optimal choice of $\tau_i$ that makes $\hat{r}$ as small as possible (that would automatically make $x^{(spec)}$ as large as possible and effectively determine $\hat{x}^{(spec)}$ in (\ref{eq:speceq5})). We now show how this is done. Let $\tau_i$, $\hat{r}_y$, and $\hat{r}$ be such that the derivatives in (\ref{eq:hrd7a5a0}) and (\ref{eq:hrd7a5a0a0}) are indeed zero.  From (\ref{eq:hrd7a5a0}) we have
\begin{equation}
\frac{1}{\hat{r}^2}   =
\frac{\frac{1}{\alpha} + \mE_{\cG} \lp \frac{\tau_i^2   \lp \lp \g_i^{(0)}\rp^2   -1  \rp } {(-\tau_i+r_y)^2} \rp }  { \mE_{\cG} \lp  \frac{\tau_i^2  \lp \g_i^{(0)}\rp^2  }{(-\tau_i+r_y)^2}   \rp} =
1+\frac{\frac{1}{\alpha} - \mE_{\cG} \lp \frac{\tau_i^2  } {(-\tau_i+\hat{r}_y)^2} \rp }  { \mE_{\cG} \lp  \frac{\tau_i^2  \lp \g_i^{(0)}\rp^2  }{(-\tau_i+\hat{r}_y)^2}   \rp}.
\label{eq:hrd7a5a0a1}
 \end{equation}
and from (\ref{eq:hrd7a5a0a0})
\begin{equation}
 \mE_{\cG} \lp \frac{\tau_i  \lp  \lp \g_i^{(0)} \rp^2  -  1  \rp }{-\tau_i+\hat{r}_y} \rp
  = \frac{1}{\alpha}.
\label{eq:hrd7a5a0a2}
 \end{equation}
After setting
\begin{equation}
\zeta = \frac{\tau_i  }{-\tau_i+\hat{r}_y}, \quad  b=  \lp \g_i^{(0)} \rp^2  -  1, \quad a= \lp \g_i^{(0)} \rp^2,
\label{eq:hrd7a5a0a3}
 \end{equation}
 minimal $\hat{r}$ will be obtained as
\begin{equation}
\hat{r}=\frac{1}{\sqrt{1+\hat{d}}},
\label{eq:hrd7a5a0a3a0}
 \end{equation}
 where
\begin{eqnarray}
\hat{d} =\max_{\zeta}  & &  \frac{\frac{1}{\alpha}  - \mE_{\cG} \lp \zeta^2 \rp } {\mE_{\cG} \lp \zeta^2 a \rp} \nonumber \\
\mbox{subject to} & & \mE_{\cG} \lp \zeta b \rp =\frac{1}{\alpha},
  \label{eq:hrd7a5a0a4}
 \end{eqnarray}
 The above is a simple linearly constrained quasi-convex program that can be solved in a closed form. One can proceed by keeping integral notation. However, to be more aligned with a common optimization practice we set
\begin{eqnarray}
\theta= \frac{e^{-\frac{\lp \g_i^{(0)}\rp^2}{2}}d\g_i^{(0)}}{\sqrt{2\pi}},
  \label{eq:hrd7a5a0a4a0}
 \end{eqnarray}
assume $d\g_i^{(0)}\rightarrow 0$ and write a discretized analogue of (\ref{eq:hrd7a5a0a4})
\begin{eqnarray}
\hat{d} = \lim_{l\rightarrow\infty}\max_{\zeta}  & &  \frac{\frac{1}{\alpha}  - \sum_{j=1}^{l} \zeta_j^2\theta_j } {\sum_{j=1}^{l} \zeta_j^2 a_j\theta_j} \nonumber \\
\mbox{subject to} & & \sum_{j=1}^{l}\zeta_j b_j\theta_j =\frac{1}{\alpha}.
  \label{eq:hrd7a5a0a4a1}
 \end{eqnarray}
 A cosmetic change gives
\begin{eqnarray}
\hat{d} = \lim_{l\rightarrow\infty}\max_{\zeta}  & & d \nonumber \\
\mbox{subject to}  & &
 \frac{1}{\alpha}  - \sum_{j=1}^{l} \zeta_j^2\theta_j  \geq d \sum_{j=1}^{l} \zeta_j^2 a_j\theta_j \nonumber \\
& & \sum_{j=1}^{l}\zeta_j b_j\theta_j =\frac{1}{\alpha}.
  \label{eq:hrd7a5a0a4a2}
 \end{eqnarray}
 Clearly, optimal $d$ (i.e., $\hat{d}$) will be obtained if
\begin{eqnarray}
 \frac{1}{\alpha}  = \lim_{l\rightarrow\infty}\min_{\zeta}  & &
  \sum_{j=1}^{l} \zeta_j^2 (\hat{d}a_j+1)\theta_j
  \nonumber \\
\mbox{subject to} & & \sum_{j=1}^{l}\zeta_j b_j\theta_j =\frac{1}{\alpha}.
  \label{eq:hrd7a5a0a4a2}
 \end{eqnarray}
The above is a simple linearly constrained quadratic program. To solve it, we write the Lagrangian
\begin{eqnarray}
\cL_s(\nu) =    \sum_{j=1}^{l} \zeta_j^2 (\hat{d}a_j+1)\theta_j -\nu\sum_{j=1}^{l}\zeta_j b_j\theta_j +\nu\frac{1}{\alpha}.
 \label{eq:hrd7a5a0a4a3}
 \end{eqnarray}
Strong duality then gives
\begin{equation}
 \frac{1}{\alpha}  = \lim_{l\rightarrow\infty}\min_{\zeta} \max_{\nu}  \cL_s(\nu)= \lim_{l\rightarrow\infty}  \max_{\nu}\min_{\zeta}  \cL_s(\nu)= \lim_{l\rightarrow\infty}  \max_{\nu}\min_{\zeta}
  \lp \sum_{j=1}^{l} \zeta_j^2 (\hat{d}a_j+1)\theta_j -\nu\sum_{j=1}^{l}\zeta_j b_j\theta_j +\nu\frac{1}{\alpha}\rp.
  \label{eq:hrd7a5a0a4a4}
 \end{equation}
Taking derivative with respect to $\zeta_j$ gives
\begin{eqnarray}
 \frac{d\cL_s(\nu)}{\d\zeta_j} = 2\zeta_j (\hat{d}a_j+1)\theta_j -\nu b_j\theta_j.
  \label{eq:hrd7a5a0a4a5}
 \end{eqnarray}
Equaling the derivative to zero and keeping in mind that $\theta_j\geq 0$, one finds for the optimal $\zeta_j$
\begin{eqnarray}
\hat{\zeta}_j = \frac{\nu b_j}{2(\hat{d}a_j+1)}.
  \label{eq:hrd7a5a0a4a6}
 \end{eqnarray}
Plugging the above $\hat{\zeta}$ in (\ref{eq:hrd7a5a0a4a4}) further gives
\begin{equation}
 \frac{1}{\alpha}    = \lim_{l\rightarrow\infty}  \max_{\nu} \lp -\nu^2\sum_{j=1}^{l} \frac{b_j^2\theta_j}{4(\hat{d}a_j+1)} +\nu\frac{1}{\alpha}\rp.
  \label{eq:hrd7a5a0a4a7}
 \end{equation}
After solving the residual maximization, one obtains for the optimal $\nu$
\begin{equation}
\hat{\nu} = \frac{1}{2}\frac{\frac{1}{\alpha}}{ \lim_{l\rightarrow\infty} \sum_{j=1}^{l} \frac{b_j^2\theta_j}{4(\hat{d}a_j+1)} }.
  \label{eq:hrd7a5a0a4a8}
 \end{equation}
Plugging the above $\hat{\nu}$ in (\ref{eq:hrd7a5a0a4a7}) then gives
\begin{equation}
 \frac{1}{\alpha}
 =
 \frac{1}{4}\frac{\frac{1}{\alpha^2}}{ \lim_{l\rightarrow\infty} \sum_{j=1}^{l} \frac{b_j^2\theta_j}{4(\hat{d}a_j+1)} },
  \label{eq:hrd7a5a0a4a9}
 \end{equation}
which, after returning to integral representation, means that optimal $d$, i.e., $\hat{d}$ is such that
\begin{equation}
 \lim_{l\rightarrow\infty}  \sum_{j=1}^{l} \frac{b_j^2\theta_j}{(\hat{d}a_j+1)}
 =
\frac{1}{\alpha} \quad  \Longleftrightarrow \quad  \mE_{\cG} \frac{\lp\lp \g_i^{(0)} \rp^2  -  1\rp^2}{\hat{d}\lp \g_i^{(0)} \rp^2  +  1}
 =
\frac{1}{\alpha}.
  \label{eq:hrd7a5a0a4a10}
 \end{equation}
Moreover, a combination of (\ref{eq:hrd7a5a0a4a7}) and (\ref{eq:hrd7a5a0a4a9}) gives
\begin{equation}
\hat{\nu} =2.  \label{eq:hrd7a5a0a4a11}
 \end{equation}
Plugging this value for optimal $\nu$ in (\ref{eq:hrd7a5a0a4a7}) we also find the optimal form of $\zeta$ (without the residual dependence on $\nu$)
\begin{eqnarray}
\hat{\zeta}_j = \frac{b_j}{(\hat{d}a_j+1)}.
  \label{eq:hrd7a5a0a4a12}
 \end{eqnarray}
Combining (\ref{eq:hrd7a5a0a4a12}) and (\ref{eq:hrd7a5a0a3}) and switching back to integral form one has that optimal $\tau_i$, $\hat{\tau}_i$ satisfies
\begin{equation}
 \frac{\hat{\tau}_i  }{-\hat{\tau}_i+\hat{r}_y} = \frac{\lp \g_i^{(0)} \rp^2  -  1}{(\hat{d}\lp \g_i^{(0)} \rp^2+1)},
\label{eq:hrd7a5a0a4a13}
 \end{equation}
or alternatively
\begin{equation}
\hat{\tau}_i = \frac{\hat{r}_y}{\hat{d}+1}\frac{\lp \g_i^{(0)} \rp^2  -  1}{\lp \g_i^{(0)} \rp^2},
\label{eq:hrd7a5a0a4a14}
 \end{equation}
Recalling on (\ref{eq:hrd2a0}) we obtain for the optimal preprocessing function ${\mathcal T}(\cdot)$
\begin{eqnarray}
 \hat{{\mathcal T}}(\g^{(0)} ) =\frac{\hat{r}_y}{\hat{d}+1}\frac{\lp \g_i^{(0)} \rp^2  -  1}{\lp \g_i^{(0)} \rp^2}.
\label{eq:hrd7a5a0a4a15}
 \end{eqnarray}
 One should note that since  $\hat{{\mathcal T}}(\cdot)$ is applied on $\bar{\y}$ (only measurements $\bar{\y}$ are available in phase retrieval problem) and since $\bar{\y}=0$ with probability 1 in the context that we consider here, potential singularities have no effect on any of the above calculations and associated algorithmic implementations. Also, as stated earlier (right after (\ref{eq:hrd7a2})), the above holds assuming $\hat{r}_y>\hat{\tau}_i$. Since scaling $ \hat{{\mathcal T}}(\g^{(0)} ) $ by any constant does not affect the optimal $\hat{x}^{(spec)}$, one can choose $r_y=\hat{d}+1$, where $\hat{d}$ is the solution of   (\ref{eq:hrd7a5a0a4a10}), which then gives
\begin{eqnarray}
 \hat{{\mathcal T}}(\g^{(0)} ) = \frac{\lp \g_i^{(0)} \rp^2  -  1}{\lp \g_i^{(0)} \rp^2}
 = 1 - \frac{ 1}{\lp \g_i^{(0)} \rp^2}\leq 1+ \hat{d} =\hat{r}_y,
\label{eq:hrd7a5a0a4a16}
 \end{eqnarray}
 which ensures that all of the above is indeed correct. Moreover, after introducing $\hat{\gamma}=\hat{d}+1$, one from (\ref{eq:hrd7a5a0a3a0}) and  (\ref{eq:hrd7a5a0a4a10}) finds the optimal overlap
\begin{eqnarray}
\hat{x}^{(spec)}=\sqrt{1-\frac{1}{\hat{\gamma}}},
\label{eq:hrd7a5a0a4a17}
 \end{eqnarray}
where $\hat{\gamma}$ is the solution of
\begin{eqnarray}
 \frac{\hat{\gamma}}{(\hat{\gamma}-1)^3}\left (\frac{\hat{\gamma}}{2} e^{\frac{1}{2(\hat{\gamma}-1)}}\sqrt{2(\hat{\gamma}-1)\pi}\mbox{erfc}\left ( \frac{1}{\sqrt{2(\hat{\gamma}-1)}} \right ) -(\hat{\gamma}-1) \right)=\frac{1}{\alpha}.
\label{eq:hrd7a5a0a4a18}
 \end{eqnarray}

It is not that difficult to check that $ \hat{{\mathcal T}}(\cdot)$  from (\ref{eq:hrd7a5a0a4a16})  precisely matches the optimal choice  suggested in \cite{MondelliM19} and proven for any $\alpha$ in \cite{LuoAL19} (optimality of $\hat{{\mathcal T}}(\cdot)$ was proven for $\alpha=\frac{1}{2}$ in the limiting scenario corresponding to the so-called \emph{weak threshold} of spectral methods in \cite{MondelliM19} as well). It should be noted that the methodology that we presented above is very generic. It can be used to incorporate various forms of further structuring of unknown signal $\x$. This is done by following line by line practice developed within compressed sensing context in \cite{StojnicCSetam09,StojnicICASSP10block,StojnicICASSP10knownsupp,StojnicICASSP10var,Stojnicbinary16asym,StojnicISIT2010binary}. Among others, examples of structuring include sparse, block-sparse, binary, partially observed and many other signals. Spectral methods, on the other hand, rely on  powerful tools from random matrix or free probability theory and as such are often restricted to eigenvalues/eigenvectors related considerations.





  \vspace{.1in}
\noindent \underline{4) \textbf{\emph{Double checking the strong random duality:}}} As just stated, the above results match the optimal ones from \cite{LuoAL19} and one has that the strong random duality is in place as well (i.e., no further RDT lifting is needed).

The above spectral initializers are overlap optimal, i.e., they produce the smallest $r$ and the largest $x^{(spec)}$.
